comms.text:
@1 וְאִלֵין דִינַיָא דִי תַסְדַר קֳדָמֵיהוֹן:
@2 אֲרֵי תִזְבַּן עַבְדָא בַר יִשְׂרָאֵל שִׁתְּ שְׁנִין יִפְלָח וּבַשְׁבִיעֵתָא יִפּוֹק לְבַר חוֹרִין מַגָן:
@3 אִם בִּלְחוֹדוֹהִי יֵיעוֹל בִּלְחוֹדוֹהִי יִפּוֹק אִם בְּעֵל אִתְּתָא הוּא וְתִפּוֹק אִתְּתֵהּ עִמֵהּ:
@4 אִם רִבּוֹנֵהּ יִתֶּן לֵהּ אִתְּתָא וּתְלִיד לֵהּ בְּנִין אוֹ בְנָן אִתְּתָא וּבְנָהָא תְּהֵי לְרִבּוֹנָהָא וְהוּא יִפּוֹק בִּלְחוֹדוֹהִי:
@5 וְאִם מֵימַר יֵימַר עַבְדָא רָחֵימְנָא יָת רִבּוֹנִי יָת אִתְּתִי וְיָת בְּנָי לָא אֶפּוֹק לְבַר חוֹרִין:
@6 וִיקָרְבִנֵהּ רִבּוֹנֵהּ לִקֳדָם דַיָנַיָא וִיקָרְבִנֵהּ לְוָת דָשָׁא אוֹ לְוָת (נ''א דִילְוָת) מְזְזֶתָּא וְיַרְצַע רִבּוֹנֵהּ יָת אוּדְנֵהּ בְּמַרְצְעָא וִיהֵי לֵהּ עֲבַד פָּלַח לְעָלָם:
@7 וַאֲרֵי יְזַבֵּן גְבַר יָת בְּרַתֵּהּ לְאַמְהוּ לָא תִפּוֹק כְּמַפְקָנוּת עַבְדַיָא:
@8 אִם בִּישָׁא בְּעֵינֵי רִבּוֹנַהּ דִיקַיְמַהּ לֵהּ וְיִפְרְקִנַהּ לִגְבַר אָחֳרָן לֵית לֵהּ רְשׁוּ לְזַבּוֹנַהּ בְּמִשְׁלְטֵהּ בַהּ:
@9 וְאִם לִבְרֵהּ יְקַיְמִנַהּ כְּהִלְכַת בְּנַת יִשְׂרָאֵל יַעְבֵּד לַהּ:
@10 אִם אָחֳרַנְתָּא יִסַב לֵהּ זִיוּנַהּ כְּסוּתַהּ וְעוֹנָתַהּ לָא יִתְמְנָע:
@11 וְאִם תְּלָת אִלֵין לָא יַעְבֵּד לַהּ וְתִפּוֹק מַגָן בְּלָא כְסַף:
@12 דְיִמְחֵי לֶאֱנַשׁ וְיִקְטְלִנֵהּ אִתְקְטָלָא יִתְקְטֵל:
@13 וּדְלָא כְמַן לֵהּ וּמִן קֳדָם יְיָ אִתִּמְסַר לִידֵהּ וֶאֱשַׁוִי לָךְ אֲתַר דִי יֵעִרוֹק לְתַמָן:
@14 וַאֲרֵי יַרְשַׁע גְבַר עַל חַבְרֵהּ לְמִקְטְלֵהּ בִנְכִילוּ מִן מַדְבְּחִי תִּדְבְּרִנֵהּ לִמְמָת:
@15 וּדְיִמְחֵי אֲבוּהִי וְאִמֵהּ אִתְקְטָלָא יִתְקְטֵל:
@16 וְדִיִגְנוּב נַפְשָׁא מִן בְּנֵי יִשְׂרָאֵל וִיזַבְּנִנֵהּ וְיִשְׁתְּכַח בִּידֵהּ אִתְקְטָלָא יִתְקְטֵל:
@17 וְדִיְלוּט אֲבוּהִי וְאִמֵהּ אִתְקְטָלָא יִתְקְטֵל:
@18 וַאֲרֵי יִנְצוּן גֻבְרִין וְיִמְחֵי גְבַר יָת חַבְרֵהּ בְּאַבְנָא אוֹ בְכוּרְמֵיזָא וְלָא יְמוּת וְיִפּוֹל לְבוּטְלָן:
@19 אִם יְקוּם וִיהַלִיךְ בְּבָרָא עַל בּוּרְיֵהּ וִיהֵי זַכָּאָה מָחַיָא לְחוֹד בּוּטְּלָנֵהּ יִתֵּן וַאֲגַר אַסְיָא יְשַׁלֵם:
@20 וַאֲרֵי יִמְחֵי גְבַר יָת עַבְדֵהּ אוֹ יָת אַמְתֵהּ בְּשָׁלְטָּן וִימוּת תְּחוֹת יְדֵהּ אִתְדָנָא יִתְּדָן:
@21 בְּרַם אִם יוֹמָא אוֹ תְרֵין יוֹמִין יִתְקַיָם לָא יִתְּדָן אֲרֵי כַסְפֵּהּ הוּא:
@22 וַאֲרֵי יִנְצוּן גֻבְרִין וְיִמְחוּן אִתְּתָא מַעַדְיָא וְיִפְּקוּן וַלְדָהָא וְלָא יְהֵי מוֹתָא אִתְגְבָאָה יִתְגְבֵי כְּמָא דִי יְשַׁוִי עֲלוֹהִי בַּעֲלַהּ דְאִתְּתָא וְיִתֵּן עַל מֵימַר דַיָנַיָא:
@23 וְאִם מוֹתָא יְהֵא וְתִתֵּן נַפְשָׁא חֳלָף נַפְשָׁא:
@24 עֵינָא חֳלָף עֵינָא שִׁנָא חֳלָף שִׁנָא יְדָא חֳלָף יְדָא רַגְלָא חֳלָף רַגְלָא:
@25 כְּוָאָה חֳלָף כְּוָאָה פִּדְעָא חֳלָף פִּדְעָא מַשְׁקוֹפֵי חֳלָף מַשְׁקוֹפֵי:
@26 וַאֲרֵי יִמְחֵי גְבַר יָת עֵינָא דְעַבְדֵהּ אוֹ יָת עֵינָא דְאַמְתֵהּ וִיחַבְּלִנַהּ לְבַר חוֹרִין יִפְטְּרִנֵהּ חֳלָף עֵינֵהּ:
@27 וְאִם שִׁנָא דְעַבְדֵהּ אוֹ שִּׁנָא דְאַמְתֵהּ יַפֵּל לְבַר חוֹרִין יִפְטְרִנֵהּ חֳלָף שִׁנֵהּ:
@28 וַאֲרֵי יַגַח תּוֹרָא יָת גַבְרָא אוֹ יָת אִתְּתָא וִימוּת אִתְרְגְמָא יִתְרְגֵם תּוֹרָא וְלָא יִתְאָכֵל יָת בִּסְרֵהּ וּמָרֵהּ דְתוֹרָא יְהֵי זַכָּאָה:
@29 וְאִם תּוֹר נַגַח הוּא מֵאִתְּמַלֵי וּמִדְקַמוֹהִי וְיִתַּסְהֵד בְּמָרֵהּ וְלָא נַטְרֵהּ וְיִקְטוֹל גַבְרָא אוֹ אִתְּתָא תּוֹרָא יִתְרְגֵם וְאַף מָרֵהּ יִתְקְטֵל:
@30 אִם מָמוֹן יְשַׁווּן עֲלוֹהִי וְיִתֵּן פּוּרְקַן נַפְשֵׁהּ כְּכֹל דִי יְשַׁווּן עֲלוֹהִי:
@31 אוֹ לְבַר יִשְׂרָאֵל יַגַח תּוֹרָא אוֹ לְבַת יִשְׂרָאֵל יַגָח כְּדִינָא הָדֵין יִתְעֲבֵד לֵהּ:
@32 אִם לְעַבְדָא יַגַח תּוֹרָא אוֹ לְאַמְתָא כְּסַף תְּלָתִין סִלְעִין יִתֵּן לְרִבּוֹנֵהּ וְתוֹרָא יִתְרְגֵם:
@33 וַאֲרֵי יִפְתַּח גְבַר גוֹב אוֹ אֲרֵי יִכְרֶה גְבַר גוֹב וְלָא יְכַסִנֵהּ וְיִפֵּל תַּמָן תּוֹרָא אוֹ חֲמָרָא:
@34 מָרֵי דְגֻבָּא יְשַׁלֵם כַּסְפָּא יָתִיב לְמָרוֹהִי וּמֵיתָא יְהֵי דִילֵהּ:
@35 וַאֲרֵי יִגוֹף תּוֹר דִגְבַר יָת תּוֹרָא דְחַבְרֵהּ וִימוּת וִזַבְּנוּן יָת תּוֹרָא חַיָא וִיפַלְגוּן יָת כַּסְפֵּהּ וְאַף יָת דְמֵי מֵיתָא יְפַלְגוּן:
@36 אוֹ אִתְיְדַע אֲרֵי תוֹר נַגַח הוּא מֵאִתְּמַלֵי וּמִדְקַמוֹהִי וְלָא נָטְרֵהּ מָרֵהּ שַׁלָמָא יְשַׁלֵם תּוֹרָא חֲלַף תּוֹרָא וּמֵיתָא יְהֵא דִילֵהּ:
@37 אֲרֵי יִגְנוּב גְבַר תּוֹר אוֹ אִמָר וְיִכְּסִנֵהּ אוֹ זַבְּנִנֵהּ חַמְשָׁא תוֹרִין יְשַׁלֵם חָלָף תּוֹרָא וְאַרְבַּע עָנָא חֳלָף אִמְרָא:
@38 אִם בְּמַחְתַּרְתָּא יִשְׁתְּכַח גַנָבָא וְיִתְמְחֵי וִימוּת לֵית לֵהּ דָם:
@39 אִם עֵינָא דְסַהֲדַיָא נְפָלַת עֲלוֹהִי דְמָא לֵהּ שַׁלָמָא יְשַׁלֵם אִם לֵית לֵהּ וְיִזְדַבַּן בִּגְנֻבְתֵּהּ:
@40 אִם אִשְׁתְּכָחָא יִשְׁתְּכַח בִּידֵהּ גְנֻבְתָּא מִתּוֹר עַד חֲמַר עַד אִמַר דְאִנוּן חַיִין עַל חַד תְּרֵין יְשַׁלֵם:
@41 אֲרֵי יאכִיל גְבַר חֲקַל אוֹ כְרָם וִישַׁלַח יָת בְּעִירֵהּ וְיֵיכוּל בַּחֲקַל אָחֳרָן שְׁפַר חַקְלֵהּ וּשְׁפַר כַּרְמֵהּ יְשַׁלֵם:
@42 אֲרֵי תִתַּפַּק נוּר וְיַשְׁכַּח כּוּבִין וְיֵיכוּל גְדִישִׁין אוֹ קֳמָא אוֹ חַקְלָא שַׁלָמָא יְשַׁלֵם דְאַדְלֵק יָת דְלֶקְתָּא:
@43 אֲרֵי יִתֵּן גְבַר לְחַבְרֵהּ כְּסַף אוֹ מָנִין לְמִטַר וְיִתְגַנְבוּן מִבֵּית גַבְרָא אִם יִשְׁתְּכַח גַנָבָא יְשַׁלֵם עַל חַד תְּרֵין:
@44 אִם לָא יִשְׁתְּכַח גַנָבָא וְיִתְקָרֵב מָרֵי דְבֵיתָא לִקֳדָם דַיָנַיָא אִם לָא אוֹשִׁיט יְדֵהּ בְּמָא דִמְסַר לֵהּ חַבְרֵהּ:
@45 עַל כָּל פִּתְגַם דְחוֹב עַל תּוֹר עַל חֲמַר עַל אִמָר עַל כְּסוּ עַל כָּל אֲבֶדְתָּא דִי יֵימַר אֲרֵי הוּא דֵין לִקֳדָם דַיָנַיָא יֵיעוֹל דִין תַּרְוֵיהוֹן דִי יְחַיְבוּן דַיָנַיָא יְשַׁלֵם עַל חַד תְּרֵין לְחַבְרֵהּ:
@46 אֲרֵי יִתֵּן גְבַר לְחַבְרֵהּ חֲמַר אוֹ תוֹר אוֹ אִמָר וְכָל בְּעִירָא לְמִטָּר וּמִית אוֹ אִתְּבַר אוֹ אִשְׁתְּבִי לֵית דְחָזֵי:
@47 מוֹמָתָא דַיְיָ תְּהֵי בֵּין תַּרְוֵיהוֹן אִם לָא אוֹשִׁיט יְדֵהּ בְּמָא דִמְסַר לֵהּ חַבְרֵהּ וִיקַבֵּל מָרֵהּ מִנֵהּ מוֹמָתָא וְלָא יְשַׁלֵם:
@48 וְאִם אִתְגְנָבָא יִתְגְנֵב מֵעִמֵהּ יְשַׁלֵם לְמָרוֹהִי:
@49 אִם אִתְּבָרָא יִתְּבַר יַיְתִי סַהֲדִין דִתְבִירָא לָא יְשַׁלֵם:
@50 וַאֲרֵי יִשְׁאַל גְבַר מִן חַבְרֵהּ וְיִתְּבַר אוֹ מִית מָרֵהּ לֵית עִמֵהּ שַׁלָמָא יְשַׁלֵם:
@51 אִם מָרֵהּ עִמֵהּ לָא יְשַׁלֵם אִם אֲגִירָא הוּא עַל בְּאַגְרֵהּ:
@52 וַאֲרֵי יְשַׁדֵל גְבַר בְּתֻלְתָּא דִּי לָא מְאַרְסָא וְיִשְׁכּוּב עִמַהּ קַיָמָא יְקַיְמִנַהּ לֵהּ לְאִנְתּוּ:
@53 אִם מִצְבָּא לָא יִצְבֵּי אֲבוּהָא לְמִתְּנַהּ לֵהּ כַּסְפָּא יִתְקוֹל כְּמוֹהֲרֵי בְּתֻלְתָּא:
@54 חָרָשָׁא לָא תָחֵי:
@55 כָּל דְיִשְׁכּוּב עִם בְּעִירָא אִתְקְטָלָא יִתְקְטֵל:
@56 דְדַבַּח לְטַעְוַת עַמְמַיָא יִתְקְטֵל אֶלָהֵן לִשְׁמָא דַיְיָ בִּלְחוֹדוֹהִי:
@57 וְגִיוֹרָא לָא תוֹנוּן וְלָא תְעִיקוּן לֵהּ אֲרֵי דַיָרִין הֱוֵיתוּן בְּאַרְעָא דְמִצְרָיִם:
@58 כָּל אַרְמְלָא וְיִתָּם לָא תְעַנוּן:
@59 אִם עַנָאָה תְעַנֵי יָתֵהּ אֲרֵי אִם מִקְבַל יִקְבֵל קֳדָמַי קַבָּלָא אֱקַבֵּל קְבִלְתֵּהּ:
@60 וְיִתְקֵף רוּגְזִי וְאֶקְטוֹל יָתְכוֹן בְּחַרְבָּא וִיהֶוְיָן נְשֵׁיכוֹן אַרְמְלִין וּבְנֵיכוֹן יַתְמִין:
@61 אִם כַּסְפָּא תּוֹזֵף בְּעַמִי לְּעַנְיָא דִי עִמָךְ לָא תְהֵי לֵהּ כְּרַשְׁיָא לָא תְשַׁוּוֹן עֲלוֹהִי חִבּוּלְיָא:
@62 אִם מַשְׁכּוֹנָא תִסַב כְּסוּתָא דְחַבְרָךְ עַד מֵעַל שִׁמְשָׁא תְּתִיבִנֵהּ לֵהּ:
@63 אֲרֵי הִיא כְסוּתֵהּ בִּלְחוֹדַהּ הִיא תוֹתְבֵהּ לְמַשְׁכֵּיהּ בְּמָא יִשְׁכּוּב וִיהֵי אֲרֵי יִקְבֵל קֳדָמַי וֶאֱקַבֵּל קְבִלְתֵּהּ אֲרֵי חַנָנָא אֲנָא:
@64 דַיָנָא לָא תְקִיל וְרַבָּא בְעַמָךְ לָא תְלוּט:
@65 בִּכּוּרָךְ וְדִמְעָךְ לָא תְאַחֵר בּוּכְרָא דִבְנָיךְ תַּפְרֵשׁ קֳדָמָי:
@66 כֵּן תַּעְבֵּד לְתוֹרָךְ לְעָנָךְ שִׁבְעָא יוֹמִין יְהֵי עִם אִמֵהּ בְּיוֹמָא תְמִינָאָה תִּפְרְשִׁנֵהּ קֳדָמָי:
@67 וֶאֱנָשִׁין קַדִישִׁין תְּהוֹן קֳדָמָי וּבְשַׂר תְּלִישׁ מִן חֵיוָא חַיְתָא לָא תֵיכְלוּן לְכַלְבָּא תִּרְמוּן יָתֵהּ:
@68 לָא תְקַבֵּל שְׁמַע דִשְׁקָר לָא תְשַׁוִי יְדָךְ עִם חַיָבָא לְמֶהֱוֵי לֵהּ סָהִיד שְׁקָר:
@69 לָא תְהֵי בָּתַר סַגִיאִין לְאַבְאָשָׁא וְלָא תִתִּמְנַע מִלְאַלָפָא מָא דִבְעֵינָךְ עַל דִינָא בָּתַר סַגִיאֵי שְׁלַם דִינָא:
@70 וְעַל מִסְכֵּינָא לָא תְרַחֵם בְּדִינֵהּ:
@71 אֲרֵי תִפְגַע תּוֹרָא דְסָנְאָךְ אוֹ חֲמָרֵהּ דְטָּעֵי אָתָבָא תְּתִיבִנֵהּ לֵהּ:
@72 אֲרֵי תֶחֱזֵי חֲמָרָא דְסָנְאָךְ רְבִיעַ תְּחוֹת טוֹעֲנֵיהּ וְתִתִּמְנַע מִלְמִשְׁבַּק לֵהּ מִשְׁבַּק תִּשְׁבּוֹק מָא דִבְלִבָּךְ עֲלוֹהִי וּתְפָרֵק עִמֵהּ:
@73 לָא תַצְלֵי דִין מִסְכֵּינָךְ בְּדִינֵהּ:
@74 מִפִּתְגָמָא דְשִׁקְרָא הֱוֵי רָחִיק וְדִזְכֵי וְדִי נְפַק (דְכֵי) מִן דִינָא לָא תִקְטוֹל אֲרֵי לָא אֱזַכֵּי חַיָבָא:
@75 וְשׁוֹחֲדָא לָא תְקַבֵּל אֲרֵי שׁוֹחֲדָא מְעַוֵר עֵינֵי חַכִּימִין וּמְקַלְקֵל פִּתְגָמִין תְּרִיצִין:
@76 וְגִיוֹרָא לָא תְעִיקוּן וְאַתּוּן יְדַעְתּוּן יָת נַפְשָׁא דְגִיוֹרָא אֲרֵי דַיָרִין הֲוֵיתוּן בְּאַרְעָא דְמִצְרָיִם:
@77 וְשִׁית שְׁנִין תִּזְרַע יָת אַרְעָךְ וְתִכְנוֹשׁ יָת עֲלַלְתַּהּ:
@78 וּשְׁבִעֵתָא תַּשְׁמְטִּנַהּ וְתַרְטְשִׁנַהּ וְיֵיכְלוּן מִסְכְּנֵי עַמָךְ וּשְׁאָרְהוֹן תֵּיכוּל חֵיוַת בָּרָא כֵּן תַּעְבֵּד לְכַרְמָךְ לְזֵיתָךְ:
@79 שִׁתָּא יוֹמִין תַּעְבֵּד עוֹבָדָיךְ וּבְיוֹמָא שְׁבִיעָאָה תָּנוּחַ בְּדִיל דִינוּחַ תּוֹרָךְ וְחַמָרָךְ וְיִשְּׁקוֹט בַּר אַמְתָךְ וְגִיוֹרָא:
@80 וּבְכֹל דִי אֲמָרִית לְכוֹן תִּסְתַּמְרוּן וְשׁוּם טַעֲוַת עַמְמַיָא לָא תִדְכְּרוּן לָא יִשְׁתְּמַע עַל פּוּמְכוֹן:
@81 תְּלַת זִמְנִין תֵּחוֹג קֳדָמַי בְּשַׁתָּא:
@82 יָת חַגָא דְפַטִירַיָא תִּטַר שִׁבְעָא יוֹמִין תֵּיכוּל פַּטִירָא כְּמָא דִפַקֵידִתָּךְ לִזְמַן יַרְחָא דַאֲבִיבָא אֲרֵי בֵהּ נְפַקְתָּ מִמִצְרָיִם וְלָא יִתְחֲזוּן קֳדָמַי רֵיקָנוּן:
@83 וְחַגָא דַחֲצָדָא בִּכּוּרֵי עוֹבָדָיךְ דִי תִזְרַע בְּחַקְלָא וְחַגָא דִכְנָשָׁא בְּמִפְּקָא דְשַׁתָּא בְּמִכְנְשָׁךְ יָת עוֹבָדָיךְ מִן חַקְלָא:
@84 תְּלַת זִמְנִין בְּשַׁתָּא יִתְחֲזוּן כָּל דְכוּרָךְ קֳדָם רִבּוֹן עָלְמָא יְיָ:
@85 לָא תִכּוֹס עַל חֲמִיעַ דַם פִּסְחִי וְלָא יְבִיתוּן בַּר מִן מַדְבְּחָא תַּרְבֵּי נִכְסַת חַגָא עַד צַפְרָא:
@86 רֵישׁ בִּכּוּרֵי אַרְעָךְ תַּיְתִי לְבֵית מִקְדְשָׁא דַיְיָ אֱלָהָךְ לָא תֵיכְלוּן בְּשַׂר בַּחֲלָב:
@87 הָא אֲנָא שָׁלַח מַלְאָכָא קֳדָמָךְ לְמִטְרָךְ בְּאָרְחָא וּלְאָעֳלוּתָךְ לְאַתְרָא דִאַתְקֵנִית:
@88 אִסְתַּמַּר מִן קֳדָמוֹהִי וְקַבֵּל לְמֵימְרֵהּ לָא תְסָרֵב לְקִבְלֵהּ אֲרֵי לָא יִשְׁבּוֹק לְחוֹבֵיכוֹן אֲרֵי בִשְׁמִי מֵימְרֵהּ:
@89 אֲרֵי אִם קַבָּלָא תְקַבֵּל לְמֵימְרֵהּ וְתַעְבֵּד כֹּל דִאֱמַלֵל וְאֶסְנֵי יָת סָנְאָךְ וְאָעִיק לְדִמְעִיקִין לָךְ:
@90 אֲרֵי יְהַךְ מַלְאָכִי קֳדָמָךְ וְיָעֵלִנָךְ לְוָת אֱמוֹרָאֵי וְחִתָּאֵי וּפְרִיזָאֵי וּכְנַעֲנָאֵי חִוָאֵי וִיבוּסָאֵי וֶאֱשֵׁצִנוּן:
@91 לָא תִסְגוּד לְטַעֲוָתְהוֹן וְלָא תִפְלְחִנוּן וְלָא תַעְבֵּד כְּעוֹבָדֵיהוֹן אֲרֵי פַגָרָא תְּפַגְרִנוּן וְתַבָּרָא תְתַבַּר קָמָתְהוֹן:
@92 וְתִפְלְחוּן קֳדָם יְיָ אֱלָהֲכוֹן וִיבָרֵךְ יָת מֵיכְלָךְ וְיָת מִשְׁתְּיָךְ וְאַעְדִי מַרְעִין בִּישִׁין מִבֵּינָךְ:
@93 לָא תְהֵי מְתַכְּלָא וְעַקְרָא בְּאַרְעָךְ יָת מִנְיַן יוֹמָיךְ אַשְׁלִים:
@94 יָת אֵימְתִי אֲשַׁלַח קֳדָמָךְ ואֶתְּפַר (נ''א וֶאֱשַׁגֵשׁ) יָת כָּל עַמָא דְאַתְּ אָתֵי לַאֲגָחָא בְּהוֹן וְאֶמְסַר יָת כָּל בַּעֲלֵי דְבָבָךְ קֳדָמָךְ מְחַזְרֵי קְדָל:
@95 וְאֶשְׁלַח יָת עֲרָעִיתָא קֳדָמָךְ וּתְתָרֵךְ יָת חִוָאֵי יָת כְּנַעֲנָאֵי וְיָת חִתָּאֵי מִן קֳדָמָךְ:
@96 לָא אֱתָרֵכִנוּן מִן קֳדָמָךְ בְּשַׁתָּא חֲדָא דִילְמָא תְהֵי אַרְעָא צַדְיָא וְתִסְגֵי עֲלָךְ חֵיוַת בָּרָא:
@97 זְעֵיר זְעֵיר אֱתָרֵכִנוּן מִן קֳדָמָךְ עַד דְתִסְגֵי וְתַחְסֵן יָת אַרְעָא:
@98 וֶאֱשַׁוֵי יָת תְּחוּמָךְ מִיַמָא דְסוּף וְעַד יַמָא דִפְלִשְׁתָּאֵי וּמִמַדְבְּרָא עַד פְּרָת אֲרֵי אֶמְסַר בִּידֵיכוֹן יָת יָתְבֵי אַרְעָא וּתְתָרֵכִנוּן מִן קֳדָמָךְ:
@99 לָא תִגְזַר לְהוֹן וּלְּטַעֲוָתְהוֹן קְיָם:
@100 לָא יֵתְבוּן בְּאַרְעָךְ דִילְמָא יְחַיְבוּן יָתָךְ קֳדָמָי אֲרֵי תִפְלַח יָת טַעֲוָתְהוֹן אֲרֵי יְהוֹן לָךְ לְתַקְלָא:
@101 וּלְמשֶׁה אֲמַר סַק לִקֳדָם יְיָ אַתְּ וְאַהֲרֹן נָדָב וַאֲבִיהוּא וְשִׁבְעִין מִסָבֵי יִשְׂרָאֵל וְתִסְגְדוּן מֵרָחִיק:
@102 וְיִתְקְרֵב משֶׁה בִלְחוֹדוֹהִי לִקֳדָם יְיָ וְאִנוּן לָא יִתְקָרְבוּן וְעַמָא לָא יִסְקוּן עִמֵהּ:
@103 וַאֲתָא משֶׁה וְאִשְׁתָּעִי לְעַמָא יָת כָּל פִּתְגָמַיָא דַיְיָ וְיָת כָּל דִינַיָא וַאֲתֵיב כָּל עַמָא קָלָא חַד וַאֲמָרוּ כָּל פִּתְגָמַיָא דִי מַלִיל יְיָ נַעְבֵּד:
@104 וּכְתַב משֶׁה יָת כָּל פִּתְגָמַיָא דַיְיָ וְאַקְדֵם בְּצַפְרָא וּבְנָא מַדְבְּחָא בְּשִׁפּוֹלֵי טוּרָא וְתַרְתָּא עֶשְׂרֵי קָמָן לִתְרֵי עֲסַר שִׁבְטַיָא דְיִשְׂרָאֵל:
@105 וּשְׁלַח יָת בּוּכְרֵי בְּנֵי יִשְׂרָאֵל וְאַסִיקוּ עֲלָוָן וְקָרִיבוּ נִכְסַת קוּדְשִׁין קֳדָם יְיָ תּוֹרִין:
@106 וּנְסִיב משֶׁה פַּלְגוּת דְמָא וְשַׁוִי בְּמִזְרְקַיָא וּפַלְגוּת דְמָא זְרַק עַל מַדְבְּחָא:
@107 וּנְסִיב סִפְרָא דִקְיָמָא וּקְרָא קֳדָם עַמָא וַאֲמָרוּ כֹּל דִי מַלִיל יְיָ נַעְבֵּד וּנְקַבֵּל:
@108 וּנְסִיב משֶׁה יָת דְמָא וּזְרַק עַל מַדְבְּחָא לְכַפָּרָא עַל עַמָא וַאֲמַר הָא דֵין דָם קְיָמָא דִגְזַר יְיָ עִמְכוֹן עַל כָּל פִּתְגָמַיָא הָאִלֵין:
@109 וּסְלֵיק משֶׁה וְאַהֲרֹן נָדָב וַאֲבִיהוּא וְשִׁבְעִין מִסָבֵי יִשְׂרָאֵל:
@110 וַחֲזוֹ יָת יְקַר אֱלָהָא דְיִשְׂרָאֵל וּתְחוֹת כָּרְסָא יְקָרֵהּ כְּעוֹבַד אֶבֶן טָבָא וּכְמֶחֱזֵי שְׁמַיָא לְבָרִירוּ:
@111 וּלְרַבְרְבֵי בְּנֵי יִשְׂרָאֵל לָא הֲוָה נִזְקָא וַחֲזוֹ יָת יְקָרָא דַיְיָ וַהֲווֹ חָדָן בְּקָרְבָּנֵיהוֹן דְאִתְקַבָּלוּ בְּרַעֲוָא כְּאִלוּ אָכְלִין וְשָׁתָן:
@112 וַאֲמַר יְיָ לְמשֶׁה סַק לִקֳדָמַי לְטוּרָא וֶהֱוֵי תַמָן וְאֶתֵּן לָךְ יָת לוּחֵי אַבְנָא וְאוֹרַיְתָא וְתַפְקֶדְתָּא דִכְתָבִית לְאַלוּפֵיהוֹן:
@113 וְקָם משֶׁה וִיהוֹשֻׁעַ מְשֻׁמְשָׁנֵהּ וּסְלֵיק משֶׁה לְטוּרָא דְאִתְגְלִי עֲלוֹהִי יְקָרָא דַיְיָ:
@114 וּלְםָבַיָא אֲמַר אוֹרִיכוּ לָנָא הָכָא עַד דִנְתוּב לְוָתְכוֹן וְהָא אַהֲרֹן וְחוּר עִמְכוֹן מָן דְאִית לֵהּ דִינָא יִתְקְרֵב לִקֳדָמֵיהוֹן:
@115 וּסְלֵק משֶׁה לְטוּרָא וַחֲפָא עֲנָנָא יָת טוּרָא:
@116 וּשְׁרָא יְקָרָא דַיְיָ עַל טוּרָא דְסִינַי וַחֲפָהִי עֲנָנָא שִׁתָּא יוֹמִין וּקְרָא לְמשֶׁה בְּיוֹמָא שְׁבִיעָאָה מִגוֹ עֲנָנָא:
@117 וְחֵיזוּ יְקָרָא דַיְיָ כְּחֵיזוּ אֶשָׁא אָכְלָא בְּרֵישׁ טוּרָא לְעֵינֵי בְּנֵי יִשְׂרָאֵל:
@118 וְעַל משֶׁה בְּגוֹ עֲנָנָא וּסְלֵיק לְטוּרָא וַהֲוָה משֶׁה בְּטּוּרָא אַרְבְּעִין יְמָמִין וְאַרְבְּעִין לֵילָוָן: פפפ:

@1 **ואלה המשפטים.** כל מקום שנאמר אלה פסל את הראשונים, ואלה מוסיף על הראשונים, מה הראשונים מסיני, אף אלו מסיני. ולמה נסמכה פרשת דינין לפרשת מזבח, לומר לך שתשים סנהדרין אצל המקדש [המזבח] : **אשר תשים לפניהם.** אמר לו הקדוש ברוך הוא למשה לא תעלה על דעתך לומר אשנה להם הפרק וההלכה ב' או ג' פעמים עד שתהא סדורה בפיהם כמשנתה, ואיני מטריח עצמי להבינם טעמי הדבר ופירושו, לכך נאמר אשר תשים לפניהם, כשלחן הערוך ומוכן לאכול לפני האדם: **לפניהם.** ולא לפני גוים, ואפילו ידעת בדין אחד שהם דנין אותו כדיני ישראל, אל תביאהו בערכאות שלהם, שהמביא דיני ישראל לפני גוים מחלל את השם ומיקר שם עבודה זרה להחשיבה, שנאמר (דברים לב לא) כי לא כצורנו צורם ואויבינו פלילים, כשאויבינו פלילים זהו עדות לעלוי יראתם:
@2 **כי תקנה עבד עברי.** עבד שהוא עברי, או אינו אלא עבדו של עברי, עבד כנעני שלקחתו מישראל, ועליו הוא אומר שש שנים יעבד, ומה אני מקים (ויקרא כה מו) והתנחלתם אתם, בלקוח מן הגוי, אבל בלקוח מישראל יצא בשש, תלמוד לומר (דברים טו יב) כי ימכר לך אחיך העברי, לא אמרתי אלא באחיך: **כי תקנה.** מיד בית דין שמכרוהו בגנבתו כמו שנאמר (שמות כב ב) אם אין לו ונמכר בגנבתו. או אינו אלא במוכר עצמו מפני דחקו, אבל מכרוהו בית דין לא יצא בשש, כשהוא אומר (ויקרא כה לט) וכי ימוך אחיך עמך ונמכר לך, הרי מוכר עצמו מפני דחקו אמור, ומה אני מקים כי תקנה, בנמכר בבית דין: **לחפשי.** לחרות:
@3 **אם בגפו יבא.** שלא היה נשוי אשה כתרגומו אם בלחודוהי. ולשון בגפו בכנפו, שלא בא אלא כמות שהוא, יחידי, בתוך לבושו בכנף בגדו: **בגפו יצא.** מגיד שאם לא היה נשוי מתחלה, אין רבו מוסר לו שפחה כנענית להוליד ממנה עבדים: **אם בעל אשה הוא.** ישראלית: **ויצאה אשתו עמו.** וכי מי הכניסה שתצא, אלא מגיד הכתוב, שהקונה עבד עברי חיב במזונות אשתו ובניו:
@4 **אם אדניו יתן לו אשה.** מכאן שהרשות ביד רבו למסור לו שפחה כנענית להוליד ממנה עבדים. או אינו אלא בישראלית, תלמוד לומר האשה וילדיה תהיה לאדוניה, הא אינו מדבר אלא בכנענית, שהרי העבריה אף היא יוצאה בשש, ואפילו לפני שש אם הביאה סימנין יוצאה, שנאמר (דברים טו יב) אחיך העברי או העבריה, מלמד, שאף העבריה יוצאה בשש:
@5 **את אשתי.** השפחה:
@6 **אל האלהים.** לבית דין, צריך שימלך במוכריו שמכרוהו לו: **אל הדלת או אל המזוזה.** יכול שתהא המזוזה כשרה לרצוע עליה, תלמוד לומר (דברים טו יז) ונתתה באזנו ובדלת, בדלת ולא במזוזה, הא מה תלמוד לומר או אל המזוזה, הקיש דלת למזוזה מה מזוזה מעומד אף דלת מעומד: **ורצע אדניו את אזנו במרצע.** הימנית. או אינו אלא של שמאל, תלמוד לומר אזן, אזן לגזרה שוה נאמר כאן ורצע אדניו את אזנו, ונאמר במצורע (ויקרא יד יד) תנוך אזן המטהר הימנית, מה להלן הימנית, אף כאן הימנית. ומה ראה אזן להרצע מכל שאר אברים שבגוף, אמר רבי יוחנן בן זכאי (קידושין כב ע''ב) אזן זאת ששמעה על הר סיני לא תגנוב, והלך וגנב, תרצע. ואם מוכר עצמו, אזן ששמעה על הר סיני (ויקרא כה נה) כי לי בני ישראל עבדים, והלך וקנה אדון לעצמו, תרצע. ר' שמעון היה דורש מקרא זה כמין חמר מה נשתנו דלת ומזוזה מכל כלים שבבית, אמר הקדוש ברוך הוא דלת ומזוזה שהיו עדים במצרים כשפסחתי על המשקוף ועל שתי המזוזות ואמרתי כי לי בני ישראל עבדים, עבדי הם ולא עבדים לעבדים, והלך זה וקנה אדון לעצמו, ירצע בפניהם: **ועבדו לעלם.** עד היובל. או אינו אלא לעולם כמשמעו, תלמוד לומר (ויקרא כה י) ואיש אל משפחתו תשובו, מגיד שחמשים שנה קרויים עולם, ולא שיהא עובדו כל חמשים שנה, אלא עובדו עד היובל בין סמוך בין מפלג:
@7 **וכי ימכר איש את בתו לאמה.** בקטנה הכתוב מדבר. יכול אפלו הביאה סימנים. אמרת קל וחמר ומה מכורה קדם לכן יוצאה בסימנין, כמו שנאמר (פסוק יא) ויצאה חנם אין כסף, שאנו דורשים אותן לסימני נערות, שאינה מכורה אינו דין שלא תמכר: **לא תצא כצאת העבדים.** כיציאת עבדים כנענים שיוצאים בשן ועין, אבל זו לא תצא בשן ועין, אלא עובדת שש או עד היובל, או עד שתביא סימנין, וכל הקודם קדם לחירותה ונותן לה דמי עינה או דמי שנה, או אינו אלא לא תצא כצאת העבדים בשש וביובל, תלמוד לומר (דברים טו יב) כי ימכר לך אחיך העברי או העבריה. מקיש עבריה לעברי לכל יציאותיו מה עברי יוצא בשש וביובל, אף עבריה יוצאה בשש וביובל, ומהו לא תצא כצאת העבדים, לא תצא בראשי אברים כעבדים כנענים. יכול העברי יוצא בראשי אברים, תלמוד לומר העברי או העבריה, מקיש עברי לעבריה מה העבריה אינה יוצאה בראשי אברים, אף הוא אינו יוצא בראשי אברים:
@8 **אם רעה בעיני אדניה.** שלא נשאה חן בעיניו לכנסה: **אשר לא יעדה.** שהיה לו ליעדה ולהכניסה לו לאשה, וכסף קניתה הוא כסף קדושיה. כאן רמז לך הכתוב שמצוה ביעוד ורמז לך שאינה צריכה קדושין אחרים: **והפדה.** יתן לה מקום להפדות ולצאת, שאף הוא מסיע בפדיונה ומה הוא מקום שנותן לה, שמגרע מפדיונה כמספר השנים שעשתה אצלו, כאלו היא שכורה אצלו. כיצד, הרי שקנאה במנה ועשתה אצלו שתי שנים אומרים לו יודע היית שעתידה לצאת לסוף שש, נמצא שקנית עבודת כל שנה ושנה בששית המנה, ועשתה אצלך שתי שנים, הרי שלישית המנה, טול שתי שלישיות המנה ותצא מאצלך: **לעם נכרי לא ימשל למכרה.** אינו רשאי למכרה לאחר, לא האדון ולא האב: **בבגדו בה.** אם בא לבגד בה, שלא לקים בה מצות ייעוד, וכן אביה, מאחר שבגד בה ומכרה לזה:
@9 **ואם לבנו ייעדנה.** האדון. מלמד, שאף בנו קם תחתיו ליעדה, אם ירצה אביו, ואינו צריך לקדשה קדושין אחרים. אלא אומר לה הרי את מיועדת לי בכסף שקבל אביך בדמיך: **כמשפט הבנות.** שאר, כסות ועונה:
@10 **אם אחרת יקח לו.** עליה: **שארה כסותה וענתה לא יגרע.** מן האמה שיעד לו כבר: **שארה.** מזונות: **כסותה.** כמשמעו: **ענתה.** תשמיש:
@11 **ואם שלש אלה לא יעשה לה.** אם אחת משלש אלה לא יעשה לה, ומה הן השלש, ייעדנה לו, או לבנו, או יגרע מפדיונה ותצא, וזה לא יעדה לא לו ולא לבנו, והיא לא היה בידה לפדות את עצמה: **ויצאה חנם.** רבה לה יציאה לזו יותר ממה שרבה לעבדים, ומה היא היציאה, ללמדך שתצא בסימנין ותשהה עמו עד שתביא סימנין. ואם הגיעו שש שנים קודם סימנין, כבר למדנו שתצא, שנאמר (דברים טו יב) העברי או העבריה ועבדך שש שנים, ומהו האמור כאן ויצאה חנם, שאם קדמו סימנים לשש שנים תצא בהן, או אינו אומר שתצא אלא בבגרות תלמוד לומר אין כסף לרבות יציאת בגרות ואם לא נאמרו שניהם הייתי אומר ויצאה חנם זו בגרות, לכך נאמרו שניהם, שלא לתן פתחון פה לבעל הדין לחלוק:
@12 **מכה איש ומת.** כמה כתובים נאמרו בפרשת רוצחין, ומה שבידי לפרש למה באו כלם, אפרש: **מכה איש ומת.** למה נאמר, לפי שנאמר (ויקרא כד יז) ואיש כי יכה כל נפש אדם מות יומת, שומע אני בהכאה בלא מיתה, תלמוד לומר מכה איש ומת, אינו חיב אלא בהכאה של מיתה. ואם נאמר מכה איש, ולא נאמר ואיש כי יכה, הייתי אומר אינו חיב עד שיכה איש, הכה את האשה ואת הקטן מנין, תלמוד לומר כי יכה כל נפש אדם, אפלו קטן ואפילו אשה. ועוד אלו נאמר מכה איש, שומע אני, אפלו קטן שהכה והרג יהא חיב, תלמוד לומר ואיש כי יכה, ולא קטן שהכה. ועוד, כי יכה כל נפש אדם, אפלו נפלים במשמע, תלמוד לומר מכה איש, אינו חיב עד שיכה בן קימא ראוי להיות איש:
@13 **ואשר לא צדה.** לא ארב לו ולא נתכון: **צדה.** לשון ארב, וכן הוא אומר (שמואל א כד יא) ואתה צודה את נפשי לקחתה, ולא יתכן לומר צדה לשון הצד ציד (בראשית כז לג) , שצידת חיות אין נופל ה''א בפועל שלה, ושם דבר בה ציד, וזה שם דבר בו צדיה ופועל שלו צודה, וזה פועל שלו צד. ואומר אני פתרונו כתרגומו ודלא כמן ליה. ומנחם חברו בחלק צד ציד, ואין אני מודה לו. ואם יש לחברו באחת ממחלוקת של צד, נחברנו בחלק (ישעיה סו יב) על צד תנשאו, (שמואל א' כ כ) צדה אורה, (דניאל ז כה) ומלין לצד עלאה ימלל. אף כאן אשר לא צדה לא צדד למצוא לו שום צד מיתה, ואף זה יש להרהר עליו, סוף דבר לשון אורב הוא: **והאלהים אנה לידו.** זמן לידו, לשון (תהלים צא י) לא תאנה אליך רעה, (משלי יב כא) לא יאנה לצדיק כל און, (מלכים ב' ה ז) מתאנה הוא לי, מזדמן למצא לי עלה: **והאלהים אנה לידו.** ולמה תצא זאת מלפניו, הוא שאמר דוד (שמואל א' כד יג) כאשר יאמר משל הקדמוני מרשעים יצא רשע, ומשל הקדמוני היא התורה, שהיא משל הקדוש ברוך הוא שהוא קדמונו של עולם. והיכן אמרה תורה מרשעים יצא רשע, והאלהים אנה לידו. במה הכתוב מדבר, בשני בני אדם, אחד הרג שוגג ואחד הרג מזיד, ולא היו עדים בדבר שיעידו, זה לא נהרג וזה לא גלה, והקדוש ברוך הוא מזמנן לפנדק אחד, זה שהרג במזיד יושב תחת הסלם, וזה שהרג שוגג עולה בסלם ונופל על זה שהרג במזיד והורגו, ועדים מעידים עליו ומחייבים אותו לגלות, נמצא זה שהרג בשוגג גולה, וזה שהרג במזיד נהרג: **ושמתי לך מקום.** אף במדבר, שינוס שמה, ואיזה מקום קולטו, זה מחנה לויה:
@14 **וכי יזיד.** למה נאמר, לפי שנאמר מכה איש וגו' שומע אני אפילו גוי, והרופא שהרג ושליח בית דין שהמית במלקות ארבעים, והאב המכה את בנו, והרב הרודה את תלמידו, והשוגג, תלמוד לומר וכי יזיד ולא שוגג על רעהו ולא על גוי. להרגו בערמה. ולא שליח בית דין והרופא והרודה את בנו ותלמידו, שאף על פי שהם מזידין אין מערימין: **מעם מזבחי.** אם היה כהן ורוצה לעבוד עבודה, תקחנו למות:
@15 **ומכה אביו ואמו.** לפי שלמדנו על החובל בחברו שהוא בתשלומין ולא במיתה, הצרך לומר על החובל באביו שהוא במיתה, ואינו חיב אלא בהכאה שיש בה חבורה: **אביו ואמו.** או זה או זה: **מות יומת.** בחנק:
@16 **וגנב איש ומכרו.** למה נאמר, לפי שנאמר (דברים כד ז) כי ימצא איש גונב נפש מאחיו, אין לי אלא איש שגנב נפש, אשה או טומטום או אנדרוגינוס שגנבו מנין, תלמוד לומר וגונב איש ומכרו. ולפי שנאמר כאן וגונב איש, אין לי אלא גונב איש, גונב אשה מנין, תלמוד לומר (שם) גונב נפש, לכך הצרכו שניהם, מה שחסר זה גלה זה: **ונמצא בידו.** שראוהו עדים שגנבו ומכרו ונמצא בידו כבר קדם מכירה: **מות יומת.** בחנק, כל מיתה האמורה בתורה סתם חנק היא. והפסיק הענין וכתב וגונב איש, בין מכה אביו ואמו למקלל אביו ואמו, ונראה לי הינו פלוגתא, דמר סבר מקשנן הכאה לקללה, ומר סבר לא מקשנן:
@17 **ומקלל אביו ואמו.** למה נאמר, לפי שהוא אומר (ויקרא כ ט) איש איש אשר יקלל את אביו, אין לי אלא איש שקלל את אביו, אשה שקללה את אביה מנין, תלמוד לומר ומקלל אביו ואמו סתם בין איש ובין אשה. אם כן למה נאמר איש אשר יקלל, להוציא את הקטן: **מות יומת.** בסקילה, וכל מקום שנאמר דמיו בו, בסקילה ובנין אב לכלם (ויקרא כ כז) באבן ירגמו אותם דמיהם בם, ובמקלל אביו ואמו נאמר (ויקרא כ ט) דמיו בו:
@18 **וכי יריבן אנשים.** למה נאמר, לפי שנאמר (פסוק כד) עין תחת עין, לא למדנו אלא דמי אבריו, אבל שבת ורפוי לא למדנו, לכך נאמרה פרשה זו: **ונפל למשכב.** כתרגומו ויפל לבוטלן, לחולי שמבטלו ממלאכתו:
@19 **על משענתו.** על בוריו וכחו: **ונקה המכה.** וכי תעלה על דעתך שיהרג זה שלא הרג, אלא למדך כאן שחובשים אותו, עד שנראה אם יתרפא זה, וכן משמעו כשקם זה והולך על משענתו אז נקה המכה, אבל עד שלא יקום זה לא נקה המכה: **רק שבתו.** בטול מלאכתו מחמת החולי, אם קטע ידו או רגלו, רואין בטול מלאכתו מחמת החולי כאלו הוא שומר קשואין, שהרי אף לאחר החולי אינו ראוי למלאכת יד ורגל, והוא כבר נתן לו מחמת נזקו דמי ידו ורגלו, שנאמר (פסוק כד) יד תחת יד רגל תחת רגל: **ורפא ירפא.** כתרגומו, ישלם שכר הרופא:
@20 **וכי יכה איש את עבדו או את אמתו.** בעבד כנעני הכתוב מדבר. או אינו אלא בעברי, תלמוד לומר כי כספו הוא, מה כספו קנוי לו עולמית, אף עבד הקנוי לו עולמית. והרי היה בכלל (פסוק יב) מכה איש ומת, אלא בא הכתוב והוציאו מן הכלל, להיות נדון בדין יום או יומים, שאם לא מת תחת ידו ושהה מעת לעת פטור: **בשבט.** כשיש בו כדי להמית הכתוב מדבר. או אינו אלא אפלו אין בו כדי להמית, תלמוד לומר בישראל (במדבר לה יז) ואם באבן יד אשר ימות בה הכהו, והלא דברים קל וחמר מה ישראל חמור אין חיב עליו, אלא אם כן הכהו בדבר שיש בו כדי להמית, ועל אבר שהוא כדי למות בהכאה זו, עבד הקל לא כל שכן: **נקם ינקם.** מיתת סייף, וכן הוא אומר (ויקרא כו כה) חרב נוקמת נקם ברית:
@21 **אך אם יום או יומים יעמד לא יקם.** אם על יום אחד הוא פטור, על יומים לא כל שכן, אלא יום שהוא כיומים, ואיזה, זה מעת לעת: **לא יקם כי כספו הוא.** הא אחר שהכהו, אף על פי ששהה מעת לעת קדם שמת, חיב:
@22 **וכי ינצו אנשים.** זה עם זה, ונתכון להכות את חברו והכה את האשה: **ונגפו.** אין נגיפה אלא לשון דחיפה והכאה, כמו (תהלים צא יב) פן תגוף באבן רגלך, (ירמיה יג טז) ובטרם יתנגפו רגליכם, (ישעיה ח יד) ולאבן נגף: **ולא יהיה אסון.** באשה: **ענוש יענש.** לשלם דמי ולדות לבעל שמין אותה, כמה היתה ראויה למכר בשוק להעלות בדמיה בשביל הריונה: **ענוש יענש.** יגבו ממון ממנו, כמו (דברים כב יט) וענשו אותו מאה כסף: **כאשר ישית עליו** וגו' **.** כשיתבענו הבעל בבית דין להשית עליו עונש על כך: **ונתן.** המכה דמי ולדות: **בפללים.** על פי הדינים:
@23 **ואם אסון יהיה.** באשה: **ונתתה נפש תחת נפש.** רבותינו חולקין בדבר. יש אומרים נפש ממש, ויש אומרים ממון, אבל לא נפש ממש, שהמתכון להרג את זה והרג את זה פטור ממיתה ומשלם ליורשיו דמיו, כמו שהיה נמכר בשוק:
@24 **עין תחת עין.** סמא עין חברו נותן לו דמי עינו, כמה שפחתו דמיו למכר בשוק, וכן כלם, ולא נטילת אבר ממש, כמו שדרשו רבותינו בפרק החובל (בבא קמא פד א) :
@25 **כויה תחת כויה.** מכות אש, ועד עכשיו דבר בחבלה שיש בה פחת דמים, ועכשיו בשאין בה פחת דמים, אלא צער, כגון כואו בשפוד על צפרנו אומדים כמה אדם כיוצא בזה רוצה לטל להיות מצטער כך: **פצע.** היא מכה המוציאה דם, שפצע את בשרו, נברדור''א בלעז , הכל לפי מה שהוא אם יש בו פחת דמים נותן נזק, ואם נפל למשכב נותן שבת ורפוי ובשת וצער. ומקרא זה יתר הוא, ובהחובל דרשוהו רבותינו לחייב על הצער אפלו במקום נזק, שאף על פי שנותן לו דמי ידו, אין פוטרין אותו מן הצער לומר הואיל וקנה ידו יש עליו לחתכה בכל מה שירצה, אלא אומרים יש לו לחתכה בסם, שאינו מצטער כל כך, וזה חתכה בברזל וצערו: **חבורה.** היא מכה שהדם נצרר בה ואינו יוצא, אלא שמאדים הבשר כנגדו ולשון חבורה [ טי''א ] בלעז [כתם] , כמו (ירמיה יג כג) ונמר חברברתיו ותרגומו משקופי, לשון חבטה בטדור''א בלעז , וכן ושדופת קדים (בראשית מא ו) שקיפן קדום, חבוטות ברוח, וכן על המשקוף (לעיל יב כג) על שם שהדלת נושק עליו:
@26 **את עין עבדו.** כנעני, אבל עברי אינו יוצא בשן ועין, כמו שאמרנו אצל לא תצא כצאת העבדים (פסוק ז) : **תחת עינו.** וכן בעשרים וארבעה ראשי אברים אצבעות הידים והרגלים. ושתי אזנים והחוטם וראש הגויה, שהוא גיד האמה. ולמה נאמר שן ועין, שאם נאמר עין ולא נאמר שן, הייתי אומר מה עין שנברא עמו אף כל שנברא עמו, והרי שן לא נברא עמו, ואם נאמר שן ולא נאמר עין, הייתי אומר אפלו שן תינוק שיש לה חליפין, לכך נאמר עין:
@28 **וכי יגח שור.** אחד שור ואחד כל בהמה וחיה ועוף אלא שדבר הכתוב בהוה: **ולא יאכל את בשרו.** ממשמע שנאמר סקול יסקל השור, איני יודע שהוא נבלה, ונבלה אסורה באכילה, אלא מה תלמוד לומר ולא יאכל את בשרו, שאפלו שחטו לאחר שנגמר דינו, אסור באכילה. בהנאה מנין, תלמוד לומר: **ובעל השור נקי.** כאדם האומר לחברו יצא פלוני נקי מנכסיו ואין לו בהם הנאה של כלום, זהו מדרשו. ופשוטו כמשמעו לפי שנאמר במועד וגם בעליו יומת, הצרך לומר בתם ובעל השור נקי:
@29 **מתמל שלשם.** הרי שלש נגיחות: **והועד בבעליו.** לשון התראה בעדים, כמו (בראשית מג ג) העד העיד בנו האיש: **והמית איש** וגו' **.** לפי שנאמר וכי יגח, אין לי אלא שהמיתו בנגיחה, המיתו בנשיכה, דחיפה, רביצה, בעיטה מנין, תלמוד לומר והמית [מכל מקום] : **וגם בעליו יומת.** בידי שמים. יכול בידי אדם, תלמוד לומר (במדבר לה כא) מות יומת המכה רוצח הוא, על רציחתו אתה הורגו, ואי אתה הורגו על רציחת שורו:
@30 **אם כפר יושת עליו.** ''אם'' זה אינו תלוי, והרי הוא כמו (לקמן כב כד) אם כסף תלוה, לשון אשר זה משפטו, שישיתו עליו בית דין כופר: **ונתן פדיון נפשו.** דמי נזק, דברי רבי ישמעאל, רבי עקיבא אומר דמי מזיק:
@31 **או בן יגח.** בן שהוא קטן: **או בת.** שהיא קטנה. לפי שנאמר והמית איש או אשה, יכול אינו חיב אלא על הגדולים, תלמוד לומר או בן יגח וגו' , לחייב על הקטנים כגדולים:
@32 **אם עבד' או אמה.** כנעניים: **שלשים שקלים יתן.** גזרת הכתוב הוא, בין שהוא שוה אלף זוז, בין שאינו שוה אלא דינר. והשקל משקלו ארבעה זהובים שהם חצי אונקיא למשקל הישר של קולוניי''א :
@33 **וכי יפתח איש בור.** שהיה מכסה וגלהו: **או כי יכרה.** למה נאמר, אם על הפתיחה חיב, על הכריה לא כל שכן, אלא להביא כורה אחר כורה שהוא חיב: **ולא יכסנו.** הא אם כסהו, פטור, ובחופר ברשות הרבים דבר הכתוב: **שור או חמור.** הוא הדין לכל בהמה וחיה, שבכל מקום שנאמר שור וחמור, אנו למדין אותו שור שור משבת, שנאמר למען ינוח שורך וחמורך (שמות כג יב) , מה להלן כל בהמה וחיה כשור. שהרי נאמר במקום אחר וכל בהמתך (דברים ה יג) אף כאן, כל בהמה וחיה כשור, ולא נאמר שור וחמור אלא שור, ולא אדם, חמור, ולא כלים:
@34 **בעל הבור.** בעל התקלה, אף על פי שאין הבור שלו, שעשאו ברשות הרבים, עשאו הכתוב בעליו להתחיב עליו בנזקיו: **כסף ישיב לבעליו.** ישיב, לרבות שוה כסף, ואפלו סבין: **והמת יהיה לו.** לנזק, שמין את הנבלה ונוטלה בדמים ומשלם לו המזיק עליה תשלומי נזקו:
@35 **וכי יגף.** ידחוף, בין בקרניו, בין בגופו, בין ברגליו, בין שנשכו בשניו, כלן בכלל נגיפה הם, שאין נגיפה אלא לשון מכה: **שור איש.** שור של איש: **ומכרו את השור** וגו' **.** בשוים הכתוב מדבר, שור שוה מאתים שהמית שור שוה מאתים, בין שהנבלה שוה הרבה, בין שהיא שוה מעט, כשנוטל זה חצי החי וחצי המת, וזה חצי החי וחצי המת, נמצא כל אחד מפסיד חצי נזק שהזיקה המיתה, למדנו שהתם משלם חצי נזק, שמן השוין אתה למד לשאינן שוין, כי דין התם לשלם חצי נזק לא פחות ולא יותר. או יכול אף בשאינן שוין בדמיהן כשהן חיים, אמר הכתוב וחצו את שניהם, אם אמרת כן, פעמים שמזיק משתכר הרבה, כשהנבלה שוה למכר לנכרים הרבה יותר מדמי שור המזיק, ואי אפשר שיאמר הכתוב, שיהא המזיק נשכר. או פעמים שהנזק נוטל הרבה יותר מדמי נזק שלם, שחצי דמי שור המזיק שוין יותר מכל דמי שור הנזק, ואם אמרת כן, הרי תם חמור ממועד, על כרחך לא דבר הכתוב אלא בשוין. ולמדך שהתם משלם חצי נזק, ומן השוין תלמד לשאינן שוין, שהמשתלם חצי נזקו שמין לו את הנבלה, ומה שפחתו דמיו בשביל המיתה, נוטל חצי הפחת והולך, ולמה אמר הכתוב בלשון הזה ולא אמר ישלם חציו, ללמד שאין התם משלם אלא מגופו, ואם נגח ומת, אין הנזק נוטל אלא הנבלה, ואם אינה מגעת לחצי נזקו, יפסיד. או שור שוה מנה שנגח שור שוה חמש מאות זוז, אינו נוטל אלא את השור, שלא נתחיב התם לחיב את בעליו לשלם מן העליה:
@36 **או נודע.** או לא היה תם, אלא נודע כי שור נגח הוא היום, ומתמול שלשום, הרי שלש נגיחות: **שלם ישלם שור.** נזק שלם: **והמת יהיה לו.** לנזק, ועליו ישלים המזיק עד שישתלם נזק כל נזקו:
@37 **חמשה בקר** וגו' **.** אמר רבן יוחנן בן זכאי חס המקום על כבודן של בריות, שור שהולך ברגליו ולא נתבזה בו הגנב לנשאו על כתפו, משלם חמשה, שה שנשאו על כתפו, משלם ארבעה הואיל ונתבזה בו. אמר רבי מאיר בא וראה כמה גדולה כחה של מלאכה, שור שבטלו ממלאכתו משלם חמשה, שה שלא בטלו ממלאכתו ארבעה: **תחת השור' תחת השה.** שנאן הכתוב לומר, שאין מדת תשלומי ארבעה וחמשה נוהגת אלא בשור ושה בלבד:
@38 **אם במחתרת.** כשהיה חותר את הבית: **אין לו דמים.** אין זו רציחה, הרי הוא כמת מעיקרו. כאן למדתך תורה אם בא להרגך, השכם להרגו, וזה להרגך בא שהרי יודע הוא, שאין אדם מעמיד עצמו ורואה שנוטלין ממונו בפניו ושותק, לפיכך על מנת כן בא, שאם יעמוד בעל הממון כנגדו יהרגנו:
@39 **אם זרחה השמש עליו.** אין זה אלא כמן משל אם ברור לך הדבר שיש לו שלום עמך, כשמש הזה שהוא שלום בעולם, כך פשוט לך שאינו בא להרוג, אפילו יעמוד בעל הממון כנגדו, כגון אב החותר לגנוב ממון הבן, בידוע שרחמי האב על הבן, ואינו בא על עסקי נפשות: **דמים לו.** כחי הוא חשוב ורציחה היא, אם יהרגהו בעל הבית: **שלם ישלם.** הגנב ממון שגנב, ואינו חיב מיתה. ואונקלוס שתרגם אם עינא דסהדיא נפלת עלוהי, לקח לו שטה אחרת, לומר שאם מצאוהו עדים קדם שבא בעל הבית, וכשבא בעל הבית נגדו, התרו בו, שלא יהרגהו, דמים לו, חיב עליו אם הרגו, שאחר שיש רואים לו, אין הגנב הזה בא על עסקי נפשות, ולא יהרוג את בעל הממון:
@40 **אם המצא תמצא בידו.** ברשותו, שלא טבח ולא מכר: **משור עד חמור.** כל דבר בכלל תשלומי כפל בין שיש בו רוח חיים בין שאין בו רוח חיים, שהרי נאמר במקום אחר (פסוק ח) על שה על שלמה על כל אבדה וגו' ישלם שנים לרעהו: **חיים שנים ישלם.** ולא ישלם לו מתים, אלא חיים או דמי חיים:
@41 **כי יבער. את בעירה ובער.** כלם לשון בהמה, כמו (במדבר כ ד) אנחנו ובעירנו: **כי יבער.** יוליך בהמותיו בשדה וכרם של חברו ויזיק אתו באחת משתי אלה או בשלוח בעירה, או בבעור. ופירשו רבותינו שלוח הוא נזקי מדרך כף רגל, ובער הוא נזקי השן האוכלת ומבערת: **בשדה אחר.** בשדה של איש אחר: **מיטב שדהו ישלם.** שמין את הנזק, ואם בא לשלם לו קרקע דמי נזקו, ישלם לו ממיטב שדותיו אם היה נזקו סלע יתן לו שוה סלע מעדית שיש לו. למדך הכתוב, שהנזקין שמין להם בעדית:
@42 **כי תצא אש.** אפילו מעצמה: **ומצאה קוצים.** קרדונ''ש בלעז : **ונאכל גדיש.** שליחכה בקוצים עד שהגיעה לגדיש או לקמה המחברת לקרקע: **או השדה.** שליחכה את נירו וצריך לניר אותה פעם שניה: **שלם ישלם המבעיר.** אף על פי שהדליק בתוך שלו והיא יצאה מעצמה על ידי קוצים שמצאה, חיב לשלם, לפי שלא שמר את גחלתו שלא תצא ותזיק:
@43 **וגנב מבית האיש.** לפי דבריו: **אם ימצא הגנב.** ישלם הגנב שנים לבעלים:
@44 **אם לא ימצא הגנב.** ובא השומר הזה שהוא בעל הבית: **ונקרב.** אל הדינין לדון עם זה ולשבע לו שלא שלח ידו בשלו:
@45 **על כל דבר פשע.** שימצא שקרן בשבועתו, שיעידו עדים שהוא עצמו גנבו, וירשיעוהו אלהים על פי העדים: **ישלם שנים לרעהו.** למדך הכתוב, שהטוען בפקדון לומר נגנב המנו, ונמצא שהוא עצמו גנבו, משלם תשלומי כפל. ואימתי בזמן שנשבע ואחר כך באו עדים, שכך דרשו רבותינו זכרונם לברכה ונקרב בעל הבית אל האלהים, קריבה זו שבועה היא. אתה אומר לשבועה, או אינו אלא לדין, שכיון שבא לדין וכפר לומר נגנבה, מיד יתחיב כפל, אם באו עדים שהוא בידו. נאמר כאן שליחות יד, ונאמר למטה שליחות יד (פסוק י) שבועת ה' תהיה בין שניהם אם לא שלח ידו, מה להלן שבועה אף כאן שבועה: **אשר יאמר כי הוא זה.** לפי פשוטו אשר יאמר העד כי הוא זה שנשבעת עליו הרי הוא אצלך. עד הדינין יבא דבר שניהם ויחקרו את העדים, ואם כשרים הם וירשיעוהו לשומר זה, ישלם שנים, ואם ירשיעו את העדים, שנמצאו זוממין, ישלמו הם שנים לשומר. ורבותינו זכרונם לברכה דרשו כי הוא זה, ללמד שאין מחייבין אותו שבועה אלא אם כן הודה במקצת לומר כך וכך אני חיב לך, והמותר נגנב ממני:
@46 **כי יתן איש אל רעהו חמור או שור.** פרשה ראשונה נאמרה בשומר חנם, לפיכך פטר בו את הגנבה, כמו שנאמר (פסוק ו) וגנב מבית האיש, אם לא ימצא הגנב ונקרב בעל הבית לשבועה, למדת שפוטר עצמו בשבועה זו. ופרשה זו אמורה בשומר שכר, לפיכך אינו פטור אם נגנבה, כמו שכתוב (פסוק יא) אם גנב יגנב מעמו ישלם, אבל על האונס, כגון מת מעצמו, או נשבר או נשבה בחזקה על ידי לסטים, ואין רואה שיעיד בדבר:
@47 **שבועת ה' תהיה.** ישבע שכן הא כדבריו, והוא לא שלח בה יד להשתמש בה לעצמו, שאם שלח בה יד, ואחר כך נאנסה, חיב באנסים: **ולקח בעליו.** השבועה: **ולא ישלם.** לו השומר כלום:
@49 **אם טרף יטרף.** על ידי חיה רעה: **יבאהו עד.** יביא עדים שנטרפה באונס, ופטור: **הטרפה לא ישלם.** אינו אומר טרפה לא ישלם, אלא הטרפה, יש טרפה שהוא משלם ויש טרפה שאינו משלם. טרפת חתול ושועל ונמיה משלם. טרפת זאב, ארי ודב ונחש אינו משלם. ומי לחשך לדון כן, שהרי כתיב ומת או נשבר או נשבה, מה מיתה שאין יכול להציל, אף שבר ושביה שאין יכול להציל:
@50 **וכי ישאל.** בא ללמדך על השואל שחיב באונסין: **בעליו אין עמו.** אם בעליו שלשור אינו עם השואל במלאכתו:
@51 **אם בעליו עמו.** בין שהוא באותה מלאכה, בין שהוא במלאכה אחרת, היה עמו בשעת שאלה, אינו צריך להיות עמו בשעת שבירה ומיתה: **אם שכיר הוא.** אם השור אינו שאול אלא שכור, **בא בשכרו.** ליד השוכר הזה ולא בשאלה, ואין כל הנאה שלו, שהרי על ידי שכרו נשתמש, ואין לו משפט שואל להתחיב באנסין. ולא פרש מה דינו, אם כשומר חנם או כשומר שכר, לפיכך נחלקו בו חכמי ישראל, שוכר כיצד משלם, רבי מאיר אומר כשומר חנם. רבי יוחנן אומר כשומר שכר:
@52 **וכי יפתה.** מדבר על לבה עד ששומעת לו, וכן תרגומו וארי ישדל. שדול בלשון ארמי כפתוי בלשון עברי: **מהר ימהרנה.** יפסוק לה מהר כמשפט איש לאשתו, שכותב לה כתבה וישאנה:
@53 **כמהר הבתולות.** שהוא קצוב חמשים כסף אצל התופס את הבתולה ושוכב עמה באונס שנאמר (דברים כב כט) ונתן האיש השוכב עמה לאבי הנער חמשים כסף:
@54 **מכשפה לא תחיה.** אלא תומת בבית דין, ואחד זכרים ואחד נקבות, אלא שדבר הכתוב בהוה שהנשים מצויות מכשפות:
@55 **כל שוכב עם בהמה מות יומת.** בסקילה, רובע כנרבעת, שכתוב בהן (ויקרא כ טז) דמיהם בם:
@56 **לאלהים.** לעבודה זרה. אלו היה נקוד לאלהים היה צריך לפרש ולכתב אחרים, עכשיו שאמר לאלהים, אין צריך לפרש אחרים, שכל למד ובית המשמשות בראש התבה אם נקודה בחטף, כגון למלך, למדבר, לעיר, צריך לפרש לאיזה מלך, לאיזה מדבר, לאיזה עיר, וכן למלכים, לרגלים צריך לפרש לאיזה, ואם אינו מפרש, כל מלכים במשמע, וכן לאלהים כל אלהים משמע, אפלו קדש, אבל כשהיא נקודה פת''ח, כמו למלך, למדבר, לעיר נודע באיזה מלך, באיזו מדבר ובאיזה עיר מדבר, וכן לאלהים, לאותן שהזהרתם עליהם במקום אחר, כיוצא בו (תהלים פו ח) אין כמוך באלהים, לפי שלא פרש הצרך לנקד פתח: **יחרם.** יומת. ולמה נאמר יחרם, והלא כבר נאמר בו מיתה במקום אחר (דברים יז ה) והוצאת את האיש ההוא או את האשה ההיא וגו' , אלא לפי שלא פרש על איזו עבודה חיב מיתה, שלא תאמר כל עבודות במיתה, בא ופרש לך כאן זובח לאלהים יחרם, לומר לך, מה זביחה עבודה הנעשית בפנים לשמים, אף אני מרבה המקטיר והמנסך והמשתחוה, שהן עבודת בפנים וחיבים עליהם לכל עבודה זרה בין שדרכה לעבדה בכך, בין שאין דרכה לעבדה בכך, אבל שאר עבודות, כגון המכבד והמרבץ והמגפף והמנשק, אינו במיתה, אלא באזהרה:
@57 **וגר לא תונה.** אונאת דברים, קונטרליי''ר בלעז [לקנטר] , כמו (ישעיה מט כו) והאכלתי את מוניך את בשרם: **ולא תלחצנו.** בגזלת ממון: **כי גרים הייתם.** אם הוניתו, אף הוא יכול להונותך ולומר לך אף אתה מגרים באת, מום שבך אל תאמר לחברך. כל לשון גר, אדם שלא נולד באותה מדינה, אלא בא ממדינה אחרת לגור שם:
@58 **כל אלמנה ויתום לא תענון.** הוא הדין לכל אדם, אלא שדבר הכתוב בהווה, לפי שהם תשושי כח ודבר מצוי לענותם:
@59 **אם ענה תענה אתו.** הרי זה מקרא קצר, גזם ולא פרש ענשו, כמו (בראשית ד טו) לכן כל הרג קין גזם ולא פרש ענשו אף כאן אם ענה תענה אתו, לשון גזום, כלומר סופך לטול את שלך, למה, כי אם צעק יצעק אלי וגו' :
@60 **והיו נשיכם אלמנות.** ממשמע שנאמר והרגתי אתכם, איני יודע שנשיכם אלמנות ובניכם יתומים, אלא הרי זו קללה אחרת, שיהיו הנשים צרורות כאלמנות חיות, שלא יהיו עדים למיתת בעליהן ותהיינה אסורות להנשא והבנים יהיו יתומים, שלא יניחום בית דין לירד לנכסי אביהם לפי שאין יודעים אם מתו אם נשבו:
@61 **אם כסף תלוה את עמי.** רבי ישמעאל אומר כל אם ואם שבתורה רשות, חוץ משלשה וזה אחד מהן: **את עמי.** עמי וגוי, עמי קדם. עני ועשיר, עני קדם. עניי עירך ועניי עיר אחרת, עניי עירך קודמין. וזה משמעו אם כסף תלוה, את עמי תלוהו, ולא לגוי ולאיזה מעמי, את העני, ולאיזה עני לאותו שעמך. דבר אחר את העני, שלא תנהג בו מנהג בזיון בהלואה, שהוא עמי: **את העני עמך.** הוי מסתכל בעצמך כאלו אתה העני: **לא תהיה לו כנשה.** לא תתבענו בחזקה, אם אתה יודע שאין לו, אל תהי דומה עליו כאלו הלויתו, אלא כאלו לא הלויתו, כלומר לא תכלימהו: **נשך.** רבית שהוא כנשיכת נחש, שנושך חבורה קטנה ברגלו ואינו מרגיש, ופתאום הוא מבצבץ ונופח עד קדקדו, כך רבית, אינו מרגיש ואינו נכר עד שהרבית עולה ומחסרו ממון הרבה:
@62 **אם חבל תחבל.** כל לשון חבלה אינו משכון בשעת הלואה, אלא שממשכנין את הלוה, כשמגיע הזמן ואינו פורע. חבל תחבול כפל לך בחבלה, עד כמה פעמים, אמר הקדוש ברוך הוא כמה אתה חיב לי, והרי נפשך עולה אצלי כל אמש ואמש ונותנת דין וחשבון ומתחיבת לפני, ואני מחזירה לך, אף אתה טול והשב טול והשב: **עד בא השמש תשיבנו לו.** כל היום תשיבנו לו עד בא השמש, וכבוא השמש תחזור ותטלנו, עד שיבא בקר של מחר, ובכסות יום הכתוב מדבר, שאין צריך לה בלילה:
@63 **כי הוא כסותה.** זו טלית: **שמלתו.** זו חלוק: **במה ישכב.** לרבות את המצע:
@64 **אלהים לא תקלל.** הרי זו אזהרה לברכת השם, ואזהרה לקללת דין:
@65 **מלאתך.** חובה המטלת עליך כשתתמלא תבואתך להתבשל, והם בכורים: **ודמעך.** התרומה, ואיני יודע מהו לשון דמע: **לא תאחר.** לא תשנה סדר הפרשתן, לאחר את המקדם ולהקדים את המאחר, שלא יקדים תרומה לבכורים ומעשר לתרומה: **בכור בניך תתן לי.** לפדותו בחמש סלעים מן הכהן. והלא כבר צוה עליו במקום אחר, אלא כדי לסמוך לו כט **כן תעשה לשורך.** מה בכור אדם לאחר שלשים יום פודהו שנאמר (במדבר יח טז) ופדויו מבן חדש תפדה, אף בכור בהמה דקה [גסה] מטפל בו שלשים יום ואחר כך נותנו לכהן: **שבעת ימים יהיה עם אמו.** זו אזהרה לכהן, שאם בא למהר את הקרבתו, לא ימהר קדם שמונה, לפי שהוא מחסר זמן: **ביום השמיני תתנו לי.** יכול יהא חובה לבו ביום, נאמר כאן שמיני, ונאמר להלן (ויקרא כב כז) ומיום השמיני והלאה ירצה, מה שמיני האמור להלן להכשיר משמיני ולהלן, אף שמיני האמור כאן להכשיר משמיני ולהלן, וכן משמעו וביום השמיני אתה רשאי לתנו לי:
@67 **ואנשי קדש תהיון לי.** אם אתם קדושים ופרושים משקוצי נבלות וטרפות הרי אתם שלי, ואם לאו אינכם שלי: **ובשר בשדה טרפה.** אף בבית כן, אלא שדבר הכתוב בהוה, מקום שדרך בהמות לטרף, וכן (דבר' כב כז) כי בשדה מצאה, וכן (שם כג יא) אשר לא יהיה טהור מקרה לילה, הוא הדין מקרה יום, אלא שדבר הכתוב בהוה. ואונקלוס תרגם ובשר תליש מן חיוא חיא, בשר שנתלש על ידי טרפת זאב או ארי, מן חיה כשרה או מבהמה כשרה בחייה: **לכלב תשלכון אתו.** אף הגוי ככלב, או אינו אלא כלב כמשמעו, תלמוד לומר בנבלה (דב' יד כא) או מכר לנכרי, קל וחמר לטרפה שמתרת בכל הנאות. אם כן מה תלמוד לומר לכלב, למדך הכתוב שאין הקדוש ברוך הוא מקפח שכר כל בריה, שנאמר (שמות יא ז) ולכל בני ישראל לא יחרץ כלב לשונו, אמר הקדוש ברוך הוא תנו לו שכרו:
@68 **לא תשא שמע שוא.** כתרגומו לא תקבל שמע דשקר, אזהרה למקבל לשון הרע, ולדין, שלא ישמע דברי בעל דין עד שיבא בעל דין חברו: **אל תשת ידך עם רשע.** הטוען את חברו תביעת שקר, שהבטיחהו להיות לו עד חמס:
@69 **לא תהיה אחרי רבים לרעת.** יש במקרא זה מדרשי חכמי ישראל, אבל אין לשון המקרא מישב בהן על אפניו. מכאן דרשו שאין מטין לחובה בהכרעת דין אחד, וסוף המקרא דרשו אחרי רבים להטות, שאם יש שנים במחיבין יותר על המזכין, הטה הדין על פיהם לחובה ובדיני נפשות הכתוב מדבר, ואמצע המקרא דרשו ולא תענה על רב, על רב, שאין חולקין על מפלא שבבית דין, לפיכך מתחילין בדיני נפשות מן הצד, לקטנים שבהן שואלין תחלה, שיאמרו את דעתם. לפי דברי רבותינו כך פתרון המקרא לא תהיה אחרי רבים לרעות לחייב מיתה בשביל דין אחד, שירבו המחיבין על המזכין ולא תענה על הרב לנטות מדבריו, ולפי שהוא חסר יו''ד דרשו בו כן. אחרי רבים להטת ויש רבים שאתה נוטה אחריהם, ואימתי, בזמן שהן שנים המכריעין במחיבין יותר מן המזכין, וממשמע שנאמר לא תהיה אחרי רבים לרעות שומע אני אבל היה עמהם לטובה, מכאן אמרו דיני נפשות מטין על פי אחד לזכות ועל פי שנים לחובה. ואונקלוס תרגם לא תתמנע מלאלפא מה דבעינך על דינא, ולשון העברי, לפי התרגום, כך הוא נדרש לא תענה על ריב לנטת אם ישאלך דבר למשפט, לא תענה לנטות לצד אחד ולסלק עצמך מן הריב, אלא הוי דן אותו לאמתו. ואני אומר לישבו על אפניו כפשוטו, כך פתרונו: **לא תהיה אחרי רבים לרעת.** אם ראית רשעים מטין משפט, לא תאמר הואיל ורבים הם, הנני נוטה אחריהם: **ולא תענה על רב לנטת** וגו' **.** ואם ישאל הנדון על אותו המשפט אל תעננו על הריב דבר הנוטה אחרי אותן רבים להטות את המשפט מאמתו אלא אמור את המשפט כאשר הוא, וקלר יהא תלוי בצואר הרבים:
@70 **לא תהדר.** לא תחלוק לו כבוד לזכותו בדין ולומר דל הוא, אזכנו ואכבדנו:
@72 **כי תראה חמור שנאך** וגו' **.** הרי כי משמש בלשון דלמא, שהוא מארבע לשונות של שמושי כי וכה פתרונו שמא תראה חמורו רובץ תחת משאו: **וחדלת מעזב לו.** בתמיהה: **עזב תעזב עמו.** עזיבה זו לשון עזרה, וכן (דברים לב לו) עצור ועזוב, וכן (נחמיה ג ח) ויעזבו ירושל ם עד החומה, מלאוה עפר לעזוב ולסיע את חוזק החומה. כיוצא בו (דברים ז יז) כי תאמר בלבבך רבים הגוים האלה ממני וגו' , שמא תאמר כן, בתמיהה, לא תירא מהם. ומדרשו, כך דרשו רבותינו כי תראה וחדלת פעמים שאתה חדל ופעמים שאתה עוזר. הא כיצד, זקן ואינו לפי כבודו, וחדלת, או בהמת נכרי ומשאוי ישראל, וחדלת: **עזב תעזב עמו.** לפרק המשא. מלמשקל ליה, מלטול משאוי ממנו:
@73 **אבינך.** לשון אובה, שהוא מדולדל ותאב לכל טובה:
@74 **ונקי וצדיק אל תהרג.** מנין ליוצא מבית דין חיב ואמר אחד יש לי ללמד עליו זכות, שמחזירין אותו, תלמוד לומר ונקי אל תהרג וזה אף על פי שאינו צדיק, שלא נצטדק בבית דין, מכל מקום נקי הוא מדין מיתה, שהרי יש לך לזכותו. ומנין ליוצא מבית דין זכאי ואמר אחד יש לי ללמד עליו חובה, שאין מחזירין אותו לבית דין לחיבו תלמוד לומר וצדיק אל תהרוג, וזה צדיק הוא, שנצטדק בבית דין: **כי לא אצדיק רשע.** אין עליך להחזירו, כי אני לא אצדיקנו בדיני, אם יצא מידך זכאי, יש לי שלוחים הרבה להמיתו במיתה שנתחייב בה:
@75 **ושחד לא תקח.** אפלו לשפוט אמת, וכל שכן כדי להטות הדין, שהרי כדי להטות את הדין נאמר כבר לעיל לא תטה משפט: **יעור פקחים.** אפלו חכם בתורה ונוטל שחד, סוף שתטרף דעתו עליו, וישתכח תלמודו, ויכהה מאור עיניו: **ויסלף.** כתרגומו ומקלקל: **דברי צדיקים.** דברים המצדקים, משפטי אמת, וכן תרגומו פתגמין תריצין. ישרים:
@76 **וגר לא תלחץ.** בהרבה מקומות הזהירה תורה על הגר מפני שסורו רע: **את נפש הגר.** כמה קשה לו כשלוחצים אותו:
@77 **ואספת את תבואתה.** לשון הכנסה לבית, כמו (דברים כב ב) ואספתו אל תוך ביתך:
@78 **תשמטנה.** מעבודה: **ונטשתה.** מאכילה אחר זמן הבעור. דבר אחר תשמטנה מעבודה גמורה, כגון חרישה וזריעה. ונטשתה מלזבל ומלקשקש: **ויתרם תאכל חית השדה.** להקיש מאכל אביון למאכל חיה מה חיה אוכלת בלא מעשר, אף אביונים אוכלים בלא מעשר, מכאן אמרו אין מעשר בשביעית: **כן תעשה לכרמך.** ותחלת המקרא בשדה הלבן, כמו שאמר למעלה המנו תזרע את ארצך:
@79 **וביום השביעי תשבת.** אף בשנה השביעית לא תעקר שבת בראשית ממקומה, שלא תאמר הואיל וכל השנה קרויה שבת, לא תנהג בה שבת בראשית: **למען ינוח שורך וחמרך.** תן לו ניח להתיר שיהא תולש ואוכל עשבים מן הקרקע. או אינו אלא יחבשנו בתוך הבית, אמרת אין זה ניח אלא צער: **בן אמתך.** בעבד הערל הכתוב מדבר: **והגר.** גר תושב:
@80 **ובכל אשר אמרתי אליכם תשמרו.** לעשות כל מצות עשה באזהרה, שכל שמירה שבתורה אזהרה היא במקום לאו: **לא תזכירו.** שלא יאמר לו שמור לי בצד עבודה זרה פלונית או תעמוד עמי ביום עבודה זרה פלונית. דבר אחר ובכל אשר אמרתי אליכם תשמרו ושם אלהים אחרים לא תזכירו ללמדך ששקולה עבודה זרה כנגד כל המצות כלן, והנזהר בה כשומר את כלן: **לא ישמע.** מן הגוי: **על פיך.** שלא תעשה שתפות עם נכרי וישבע לך בעבודה זרה שלו נמצאת שאתה גורם שיזכר על ידך:
@81 **רגלים.** פעמים וכן (במדבר כב כח) כי הכיתני זה שלש רגלים:
@82 **חדש האביב.** שהתבואה מתמלאת בו באביה. לשון אחר אביב, לשון אב, בכור וראשון לבשל פרות: **ולא יראו פני ריקם.** כשתבאו לראות פני ברגלים, הביאו לי עולות:
@83 **וחג הקציר.** הוא חג שבועות: **בכורי מעשיך.** שהוא זמן הבאת בכורים, ששתי הלחם הבאים בעצרת היו מתירין החדש למנחות ולהביא בכורים למקדש, שנאמר (במדבר כח כו) וביום הבכורים וגו' : **וחג האסיף.** הוא חג הסכות: **באספך את מעשיך.** שכל ימות החמה התבואה מתיבשת בשדות ובחג אוספים אותה אל הבית מפני הגשמים:
@84 **שלש פעמים** וגו' **.** לפי שהענין מדבר בשביעית הצרך לומר שלא יסתרסו רגלים ממקומן: **כל זכורך.** הזכרים שבך:
@85 **לא תזבח על חמץ** וגו' **.** לא תשחט את הפסח בארבעה עשר בניסן עד שתבער החמץ: **ולא ילין חלב חגי** וגו' **.** חוץ למזבח: **עד בקר.** יכול אף על המערכה יפסל בלינה, תלמוד לומר (ויקרא ו ב) על מוקדה על המזבח כל הלילה: **ולא ילין.** אין לינה אלא בעמוד השחר שנאמר עד בקר, אבל כל הלילה יכול להעלותו מן הרצפה למזבח:
@86 **ראשית בכורי אדמתך.** אף השביעית חיבת בבכורים, לכך נאמר אף כאן בכורי אדמתך. כיצד, אדם נכנס לתוך שדהו, וראה תאנה שבכרה, כורך עליה גמי לסימן ומקדישה. ואין בכורים אלא משבעת המינין האמורין במקרא (דברים ח ח) ארץ חטה ושעורה וגו' : **לא תבשל גדי.** אף עגל וכבש בכלל גדי, שאין גדי אלא לשון ולד רך, ממה שאתה מוצא בכמה מקומות בתורה שכתוב גדי, והוצרך לפרש אחריו עזים, כגון (בראשית לח יז) אנכי אשלח גדי עזים, (שם שם כ) את גדי העזים, (שם כז ט) שני גדיי עזים, ללמדך, שכל מקום שנאמר גדי סתם, אף עגל וכבש במשמע. ובשלושה מקומות נכתב בתורה אחד לאסור אכילה, ואחד לאסור הנאה, ואחד לאסור בשול:
@87 **הנה אנכי שלח מלאך.** כאן נתבשרו שעתידין לחטוא, ושכינה אומרת להם (שמות לג ג) כי לא אעלה בקרבך: **אשר הכנתי.** אשר זמנתי לתת לכם, זהו פשוטו ומדרשו אל המקום אשר הכינותי כבר מקומי נכר כנגדו, וזה אחד מן המקראות שאומרים, שבית המקדש של מעלה מכון כנגד בית המקדש של מטה:
@88 **אל תמר בו.** לשון המראה, כמו (יהושע א יח) אשר ימרה את פיך: **כי לא ישא לפשעכם.** אינו מלמד בכך, שהוא מן הכת שאין חוטאין, ועוד שהוא שליח ואינו עושה אלא שליחותו: **כי שמי בקרבו.** מחבר לראש המקרא, השמר מפניו כי שמי משתף בו, ורבותינו אמרו זה מטטרו''ן ששמו כשם רבו. מטטרו''ן בגימטריא שדי:
@89 **וצרתי.** כתרגומו ואעיק:
@91 **הרס תהרסם.** לאותם אלהות: **מצבותיהם.** אבנים שהם מציבין להשתחוות להם:
@93 **לא תהיה משכלה.** אם תעשה רצוני: **משכלה.** מפלת נפלים או קוברת את בניה, קרויה משכלה:
@94 **והמתי.** כמו והממתי ותרגומו ואשגש. וכן כל תבה שפעל שלה בכפל האות האחרונה, כשתהפוך לדבר בלשון פעלתי, יש מקומות שנוטל אות הכפולה ומדגיש את האות ונוקדו במלאפום, כגון והמותי, מגזרת (ישעיה כח כח) והמם גלגל עגלתו, (קהלת ב כ) וסבותי, מגזרת (שמו''א ז טז) וסבב בית אל, (תהלים קטז ו) דלותי, מגזרת (ישעיה יט ו) דללו וחרבו, (שם מט טז) על כפים חקותיך, מגזרת (שופטים ה טו) חקקי לב, (שמו''א יב ג) את מי רצותי, מגזרת (איוב כ יט) רצץ עזב דלים. והמתרגם והמותי ואקטל, טועה הוא, שאלו מגזרת מיתה היה, אין ה''א שלה בפת''ח, ולא מ''ם שלו מדגשת, ולא נקודה מלאפום, אלא והמתי, כגון (במד' יד טו) והמתה את העם הזה, והתי''ו מדגשת, לפי שתבא במקום ב' תוי''ן, האחת נשרשת, לפי שאין מיתה בלא ת''ו, והאחרת משמשת, כמו אמרתי, חטאתי, עשיתי, וכן ונתתי, הת''ו מדגשת, שהיא באה במקום שתים, לפי שהיה צריך שלש תוי''ן, שתים ליסוד, כמו (יהושע י יב) ביום תת ה', (קהלת ג יג) מתת אלהים היא, והשלישית לשמוש: **ערף.** שינוסו מפניך ויהפכו לך ערפם:
@95 **הצרעה.** מן שרץ העוף, והיתה מכה אותם בעיניהם ומטילה בהם ארס והם מתים, והצרעה לא עברה את הירדן, והחתי והכנעני הם ארץ סיחון ועוג, לפיכך מכל שבע אמות לא מנה כאן אלא אלו. וחוי אף על פי שהוא מעבר הירדן והלאה, שנו רבותינו במסכת סוטה (סוטה לו א) על שפת הירדן עמדה וזרקה בהם מרה:
@96 **שממה.** ריקנית מבני אדם, לפי שאתם מעט ואין בכם כדי למלאות אותה: **ורבה עליך.** ותרבה עליך:
@97 **עד אשר תפרה.** תרבה, לשון פרי, כמו פרו ורבו:
@98 **ושתי.** לשון השתה, והת''ו מדגשת מפני שבאה תחת שתים, שאין שיתה בלא ת''ו, והאחת לשמוש: **עד הנהר.** פרת: **וגרשתמו.** ותגרשם:
@100 **כי תעבד וגו' כי יהיה לך למקש.** הרי אלו כי משמשין במקום אשר, וכן בכמה מקומות, וזהו לשון אי, שהוא אחד מארבע לשונות שהכי משמש. וגם מצינו בהרבה מקומות אם משמש בלשון אשר, כמו (ויקרא ב יד) ואם תקריב מנחת בכורים, שהיא חובה:
@101 **ואל משה אמר עלה.** פרשה זו נאמרה קדם עשרת הדברות, ובארבעה בסיון נאמר לו עלה:
@102 **ונגש משה לבדו.** אל הערפל:
@103 **ויבא משה ויספר לעם.** בו ביום: **את כל דברי ה'.** מצות פרישה והגבלה: **ואת כל המשפטים.** שבע מצות שנצטוו בני נח. ושבת וכבוד אב ואם ופרה אדמה ודינין שנתנו להם במרה:
@104 **ויכתב משה.** מבראשית ועד מתן תורה, וכתב מצות שנצטוו במרה: **וישכם בבקר.** בחמשה בסיון:
@105 **את נערי.** הבכורות:
@106 **ויקח משה חצי הדם.** מי חלקו, מלאך בא וחלקו: **באגנות.** שני אגנות אחד לחצי דם עולה ואחד לחצי דם שלמים להזות אותם על העם. ומכאן למדו רבותינו שנכנסו אבותינו לברית במילה וטבילה והרצאת דמים שאין הזאה בלא טבילה:
@107 **ספר הברית.** מבראשית ועד מתן תורה ומצות שנצטוו במרה:
@108 **ויזרק.** ענין הזאה, ותרגומו וזרק על מדבחא לכפרא על עמא:
@110 **ויראו את אלהי ישראל.** נסתכלו והציצו ונתחייבו מיתה, אלא שלא רצה הקדוש ברוך הוא לערבב שמחת התורה, והמתין לנדב ואביהוא עד יום חנכת המשכן, ולזקנים עד, (במדבר יא א) ויהי העם כמתאוננים וגו' ותבער בם אש ה' ותאכל בקצה המחנה, בקצינים שבמחנה: **כמעשה לבנת הספיר.** היא היתה לפניו בשעת השעבוד לזכור צרתן של ישראל, שהיו משעבדים במעשה לבנים: **וכעצם השמים לטהר.** משנגאלו היה אור וחדוה לפניו: **וכעצם.** כתרגומו, לשון מראה: **לטהר.** לשון ברור וצלול:
@111 **ואל אצילי.** הם נדב ואביהוא והזקנים: **לא שלח ידו.** מכלל שהיו ראוים להשתלח בהם יד: **ויחזו את האלהים.** היו מסתכלין בו בלב גס מתוך אכילה ושתיה, כך מדרש תנחומא. ואונקלוס לא תרגם כן. אצילי לשון גדולים, כמו (ישעיה מא ט) ומאציליה קראתיך, (במדבר יא כה) ויאצל מן הרוח, (יחזקאל מא ח) שש אמות אצילה:
@112 **ויאמר ה' אל משה.** לאחר מתן תורה: **עלה אלי ההרה והיה שם.** ארבעים יום: **את לחת האבן והתורה והמצוה אשר כתבתי להורתם.** כל שש מאות ושלש עשרה מצות בכלל עשרת הדברות הן, ורבנו סעדיה פרש באזהרות שיסד לכל דבור ודבור מצוות התלויות בו:
@113 **ויקם משה ויהושע משרתו.** לא ידעתי מה טיבו של יהושע כאן. ואומר אני, שהיה התלמיד מלוה לרב עד מקום הגבלת תחומי ההר, שאינו רשאי לילך משם והלאה, ומשם ויעל משה לבדו אל הר האלהים, ויהושע נטה שם אהלו ונתעכב שם כל ארבעים יום, שכן מצינו, כשירד משה (לקמן לב יז) וישמע יהושע את קול העם ברעה, למדנו שלא היה יהושע עמהם:
@114 **ואל הזקנים אמר.** בצאתו מן המחנה: **שבו לנו בזה.** והתעכבו כאן עם שאר העם במחנה להיות נכונים לשפוט לכל איש ריבו: **חור.** בנה של מרים היה, ואביו כלב בן יפנה, שנאמר ויקח לו כלב את אפרת ותלד לו את חור (דברי הימים א' ב יט) . אפרת זו מרים, כדאיתא בסוטה (יא ב) : **מי בעל דברים.** מי שיש לו דין:
@116 **ויכסהו הענן.** רבותינו חולקין בדבר. יש מהם אומרים אלו ששה ימים שמראש חדש עד עצרת יום מתן תורה: **ויכסהו הענן.** להר: **ויקרא אל משה ביום השביעי.** לומר עשרת הדברות, ומשה וכל בני ישראל עומדים, אלא שחלק הכתוב כבוד למשה, ויש אומרים ויכסהו הענן למשה ששה ימים לאחר עשרת הדברות, והם היו בתחלת ארבעים יום שעלה משה לקבל הלוחות, ולמדך, שכל הנכנס למחנה שכינה טעון פרישה ששה ימים:
@118 **בתוך הענן.** ענן זה כמין עשן הוא, ועשה לו הקדוש ברוך הוא למשה שביל [ נ''א : חפה] בתוכו:
@119 **אחרי כרות המלך.** בשנה השביעית למלכו כך שנינו בסדר עולם ויהי בשנה השביעית באו אנשים מזקני יהודה לדרוש את ה' אמרו ליחזקאל עבד כהן שמכרו רבו מהו שיאכל בתרומה כלומר לפי שהיו רוצין לומר לא נענש על המצות על שהחזירו את העבדי':
@128 **הנני קורא לכם דרור.** מאתי שאינו אדון לכם להציל ותהיו הפקר אל החרב ואל הרעב:
@129 **העגל אשר כרתו לשנים.** כשחזרו וכבשום כרתו כולם ברית למרוד במקום וכרתו העגל לשנים ועברו בין בתריו למרוד בו והיא היתה ברית חזקה וגמורה לאמר ככה יבתר ויחלק העובר עליה:
@132 **העולים מעליכם.** מפני חיל פרעה שיצא ממצרים כמו שמפורש בספר זה ( ל"ז ):
@133 **הנני מצוה.** ושב חיל פרעה לארצו והכשדים ישובו עליכם:
@134 **אם לא בריתי וגו'.** אי אפשר שלא יתקיים הברית שכרתי ליום ולילה להיות בעתם ואי אפשר לחוקות שמים וארץ ליבטל כאלו לא שמתים גם זרע יעקב וגו' ורבותינו דרשוהו לענין ברית התורה ללמוד מכאן שבשביל התורה נבראו שמים וארץ אך אין המדרש מיושב על סדר המקראות:

@3 **בגפו.** ר"ל בגפו שבא יחיד או יהיה בכנפו. והרצון בו כנף כסותו כאלו יאמר שבא יחידי לא הביא עמו דבר זולת כסותו בטעם כי במקלי שעברתי את הירדן:
@4 **אם אדוניו יתן לו אשה.** ר"ל שפחה כנענית ולה אמ' האשה וילדיה תהיה לאדניה וזה לא יתכן שיהיה בבת ישראל:
@6 **אל האלהים.** ר"ל אל השופטים:
@6 **והגישו אדניו אל הדלת או אל המזוזה.** ר"ל שיעמוד העבד אצל הדלת או אצל המזוזה הסמוכה לו באופן שיתכן לרצוע אזנו בדלת:
@8 **לו יעדה.** ר"ל ליעדה לו לנשואין:
@8 **לעם נכרי.** הנה עם הוא שם נופל על הקבוץ. ור"ל בעם נכרי קבוץ נכרי ר"ל שלא ימכרנה לבית אחר כי בבית יתקבצו אנשי הבית וכאלו אמר שלא יוכל למכרה לאיש אחר:
@10 **שארה כסותה ועונתה. שארה.** מזונה. כטעם וימטר עליהם כעפר שאר:
@10 **ועונתה.** רוצה לומר חקה הראוי לה למשגל:
@13 **צדה.** הוא מענין הצדיה להשתדל להמיתו במזיד כמו ואתה צודה את נפשי לקחתה:
@13 **והאלהים אנה לידו.** ר"ל הכין והזמין וראוי שתדע כי מה שבקרי יוחם אל השם יתע' כמו שזכר חרב המורה אמר ותהי אשה לבן אדוניך כאשר דבר יי' או יהיה הרצון באמרו והאלהי' אנה לידו שהש"י סבב שיגיע הרע לאיש הנהרג לאחת מהסבות שיתכן שיביא הש"י בעבורם הרע לרעי' לפי מה שביארנו ברביעי ממ"י ובבאורנו לספר איוב. שבתו' הוא מה ששבת ממלאכתו בסבת ההכאה:
@20 **נקום ינקם.** ר"ל שיקחו ב"ד נקמתו ממנו והנקמה היא נפש תחת נפש והוא בסייף כמו שביארה התורה באמרה שופך דם האדם באדם דמו ישפך ושפיכת הדם הו' בחרב לפי הנהוג ומצאנו ג"כ שם הנקמה נופלת בחרב שנ' חרב נוקמת נקם ברית נקום נקמת בני ישר':
@22 **בפלילים.** הוא כמו ואויבנו לפלילים. והרצון בו דיינים בטעם ופללו אלהים:
@32 **שקלים.** הם סלעי' והסלע הוא מכסף נקי משקל שלש מאות ושמונים וארבע מגרגירי השעורה לפי מה שהתבאר לקודמים מגדרו:
@33 **וכי יפתח איש בור.** שהיה מכוסה כראוי או כי יכרה איש בור ולא יכסנו כראוי ונפל שמה שור או חמור או אחד משאר ב"ח:
@34 **בעל הבור ישלם.** ההיזק שבא בב"ח ההוא בסבת הבור כסף ישיב לבעליו כשעור היזק ההוא:
@34 **והמת יהיה לו.** ר"ל לניזק כי זה מן הראוי רצוני שלא ישלם בעל הבור אלא היזק שנתחדש בסבת הבור ולזה יהיה אמרו והמת יהיה לו שב אל הניזק ולא אל המזיק. וראוי היה להיות כן שאם אתה אומר שתהיה הנבלה למזיק הנה יקרה מזה שתפסד הנבלה כי המזיק לא ירצה להחזיק בה כדי שלא יחייב עצמו בתשלומי הנזק ההוא עד יוברר הדבר על פי עדים ויחתך הדין על יד ב"ד והבעלים לא יחזיקו בה ולפי שאינה שלהם ולזה היה מהיושר התוריי שתהיה הנבלה לניזק והוא ישתדל למכרה באופן שלא תפסד אלא שבעל הבור חייב להוציא לו משם הנבלה ר"ל שהוא יפרע שכר ההוצאה ההיא. כי היא גרם לו זה הנזק ג"כ והוא מבואר שהאיש והאשה שוין בזה הדין שנ' בעל הבור. ואולם דבר הכתוב בהווה כי הכונה היתה לסלק ההיזקים באופן שלא יבא נזק מהאדם לחברו ואמנם הקן והשוטה והחרש לא ינהג בהם זה הדין כי אינם בני דעת ולזה כוונה התורה באמרה וכי יפתח איש בור להוציא הקטן ומי שידמה לו שאינם בני דעת וראוי שתדע שזה הדין לא ינהג אלא במקום שהיה רשות לב"ח ההוא להלך כמו רשות בעליו ורשות הרבים ומה שידמה לו שנ' ונפל שמה שור או חמור שיפול בדרך נפילה ואין דרך שיכנסו השור והחמור של אדם בביתו של חברו ועוד שאין לו אשם על זה והנה יתחייב על הבור שהוא ברה"ר אע"פ שאינו שלו לפי שלא היה לו רשות להמציא שם ההיזקים והנה אם חפר ברשותו והפקיר אחר זה רשותו ולא הפקיר בורו חייב בנזקים ההם לפי שהוא בעל הבור ובכלל איך שהיה הוא בעל הבור הנה הוא חייב בנזקי הבור שנאמר בעל הבור ישלם אמנם אם הפקיר רשותו ובורו לא ישאר בכאן צד יתחייב בעבורו בנזקי הבור לפי שלא יתחייב על החפירה שכבר חפר בשלו ואינו ג"כ בעל הבור וכבר יתבאר לך שהוא יתחייב על חפירתו בור ברשות הרבים ואע"פ שאינו שלו שנא' וכי יפתח איש בור מגיד לך שאל פתיחתו אותו הוא חייב ומפני זה יקרא בעל הבור כי הוא המציא התקלה ההיא ואינו חייב על נזקי הבור שאינו שלו אלא אם המציא התקלה ההיא מדעתו כאלו תאמר שפתח הבור או חפר אותו אבל אם היה אנוס בהמצאותו אותו פטו' כמו שנתקל ונשברה בורו ברה"ר. וראוי שתדע שאחד הבור ואחד שאר התקלות הדומות לה כאלו תאמר שהניח אבן בר"ה ונתקל בה הב"ח בהליכתו ואחד שור וחמור ואחד שאר הב"ח ואמנם דבר הכתו' בהווה וראוי שתדע שלא יתחייב על מיתת שור וחמור אם לא היתה נפילתם לפי הנהוג רצוני שאם היו קטנים או שוטים או שומי' יתחייב על נפילתם לפי שאין דרכם להתכונן בדרך אם יש שם מכשול אם לא ואולם אם היו גדולים ופקחים הנה הוא פטור לפי שדרכם להתבונן בדרכים אלא אם נפלה הבהמה בלילה או שדחפה ב"ח אחר שם או שהיתה אבן אצל הבור שנתקל בה ונפל או שנשפכו אם מים אצל הבור והוחלקה שם ונפלה כי כשחיה העני' על זה התואר יתחייב בעל הבור כי הבהמה היא כמו אנוסה בזאת הנפילה ואם היתה תקלה אחרת בעלים ישלמו יחד בעל הבור ובעל התקלה ההיא הנזק כי לכל אחד מהם מבוא בהמצאת זה הנזק וראוי שתדע כי בהמתו של אדם אם המציא תקלה ברה"ר הנה בעל הבהמה פטור מלשלם הנזקין שיתחדשו מפני התקלה ההיא שנ' כי יפתח איש בור ולא שיפתח שור בור. וראוי שתדע שמי שימסור בורו לבן דעת שישמר אותו פטור מנזקי הבור שנאמר ולא יכנסנו והוא הדין לשמירתה שתשוה כמו הכסוי כי כוונת התור המבוארת בזה הענין והנה אם כסהו בכליו של חברו ובא חברו ונטלו הנה לא יפטרהו זה הכסוי כי לא היה לו רשות לכסותו בו וחברו כשנטלו נטלו ברשות והנה אמרה התור הבור שיש בו כדי שמית אף כל שיש בו כדי להמית ולה אם לא היה בתקלה כדי להמית פטור מהמיתה אבל הוא חייב על הנזקי' לפי שכבר יש בו כדי להזיק. וראוי שתדע שאם נפל בבור אדם ומת שבעל הבור פטור כי התורה ביארה דין המתת האדם בשור המועד מפני שיש לו בעצמו התחלה ללכת ולהזיק ואולם הבור אין לו התחלה בעצמו ללכת ולהזיק ולזה לא נלמד זה הדין. בור ממה שנ' בזה בשור ואולם אם נזק אדם בנפילתו בור הנה יתחייב בנזקי בעל הבור ואפילו אם היה פקח ונפל שם ביום כי אין דרך בני אדם להתבונן בדרכים כי ההיקש אחד ר"ל כי הוא ישלם לו הממון שחסר אותו אם נפלה שם בהמתו ולזה ישלם לו מה שחסרו מהממון כשנפל שם הוא בעצמו וכמו שלא ישלם לו מבהמתו כי אם הנזק כן לא ישלם לו מגופו כי אם הנזק ואולם שאר הדברים לא ישלם לו וכבר יתבאר זה באופן אחר וזה כי הוא זכר שור וחמור להוציא אדם שאינו מסוגם הקרוב וכבר נתמעט האדם לענין המיתה שנזכרה בשור וחמור ולפי שהוא מבואר שבעל הבור חייב על נזקי בהמה כמו שהוא חייב על מיתתה כי ההיקש הוא אחד ולא נתמעט האדם כי אם מענין המיתה הנה יתחייב בעל הבור על נזקי אדם אם לא היה האד' פושע בנפילתו בו והוא מבואר שאם נפלו כלי' בבור ונשברו או נטנפו שבעל הבור פטור שנ' ונפל שם שור או חמור שדרכן לילך וליפול בבור יצאו הכלי' שאין דרכם לילך ואינם ג"כ מסוג השור והחמור ולזה יהיה פטור גם על הלכים שנפלו שם עם השור והחמור כי התורה לא לחייבתהו לשלם כי אם השור והחמור ומה שידמה להם מהב"ח והוא מבואר כי שוה כסף הו' ככסף וראוי שתדע שאם היתה הבהמה שמתה מפסולי המוקדשי' הנה בעל הבור פטור שנ' והמת יהיה לו מי שאפשר בו להיות לו יצאו פסולי המוקדשין שהם אסורי הנאה כשמתו כמו שיתבאר במה שיב' ובכלל אינו מן היושר שישלם רק מה שפוחתו הביתה לפי הנהוג כשישומו הנבלה. ואולם זאת הנבלה אין לה שומ' כי אינ' שוה כלל ואין ראוי לו שיוסיף על ענשו מה שיש מדין הקדשי' מזאת הבהמה ולפי שאי אפשר בזאת הנבלה שומא הנה לא ינהגו בה אלו התשלומין:
@35 **וכי יגוף שור איש את שור רעהו.** באופן שימות:
@35 **ומכרו את השור וחצו את כספו.** בינים וגם את המת יחצון. וראוי שתדע שאין כוונת התורה שימכר השוה החי על האופן שיראה מפשט הכתוב שאם היה הענין כן היה לפעמים המזיק נשכר כשהיתה הנבלה יותר שוה מהשור החי ולפעמים היה משלם יותר ממה שהזיק ויהיה אם כן תם חמור במועד ולזה הוא מבואר שהדין הזה יהיה כשהיו השורים שוים כמו שאמר אחר זה שלם ישלם שור תחת השור שהרצון בו שהיו שוי' ולפי מה שנזכר במה שקדם יתבאר כי אמרו וגם את המת יחצון. אין הרצון בו שיטפלו שניהם בנבלה ההיא כי בעל השור המזיק לא ירצה להטפל בה עד יתברר הדבר לפני ב"ד כדי שלא יתחייב עצמו בתשלומי זה הנזק ויקרה מזה שתפסד הנבלה ולזה היה מן היושר שיהיו שמין כמה היתה הנבלה יפה בשעת מיתה ואם נפסדה אחר זה יהיה ההפסד לניזק כי הוא פושע בזה ואם נתיקרה קודם השומא יהיה השבח לשניהם כי לא בא זה היוקר בה מצד הניזק שיהיה היוקר שלו יתבאר מזה שנזק השור התם הוא משתלם בגופו ולזה אם נגנב או נאבד הבעלים פטורין והנה הדין בזה כמו הדין בשור תם שהרג האדם שלא יוכלו הבעלים להפסיד כי אם השור ההוא ואם נודע לבעלים כי שור נגח הוא מתמול שלשום ולא ישמרנו בעליו כראוי ויצא והזיק שלם ישלם שור תחת השור הזיק והמת יהיה לו ר"ל לניזק שאם היה הרצון שיהיה למזיק לא היתה התורה צריכה לבאר שיהיה המת למזיק אחר שאמרה שלם ישלם שור תחת השור כי אין מן הדין שישלמו הבעלים יותר ממה שהזיקו ולזה הוא מבואר שרצון בזה שיהיה המת לניזק ושישלמו לו הבעלים בשיעור מה שהגיע לו מהנזק בסבת המיתה והנה שתקה התורה מהנזקים אשר תעשה בהמתו של אדם וזברה בהמתה לבד לפי שאפילו המתה יהיה הענש עליה ממון ולזה לא יהיה הבדל בין ההמתה לנזקין ואולם באדם לבדו היה הבדל בין המתתו לזולתו ובין חבלו בזולתו ולה ביארה התורה הדין במיתה ובניזקין וכבר יתבאר לך שכוונת התורה שאם הזיק השור בזולתו ישלם הנזק אע"פ שלא המיתו ממה שבאר בשן ורגל ובאש שיתחייבו בעלים על נזקיהם אפילו במה שאין בו רוח חיים שלא יתכן שיאמר בו מיתה ובכלל הנה כוונת התורה להסיר ההיזקים מבין בני אדם ולזה יהיה דין המיתה ודין ההיזקי' בזה אחד ולזה זכרה התורה ההמתה לבאר שלא יתחייב השור מיתה על המתת השור כי אין שם מה שחוייב בו מיתה כי אם על המתת האדם וכן אמרה התורה ומכה נפש בהמה ישלמנה ומכה אדם יומת. ובהיות הענין כן הנה יתחייב השור ג"כ על נזקי הכלים ועל נזקי אדם אם חבל בו אלא שלא יתחייב עליו כי אם נזק לבד כי שאר הארבעה דברים לא חייבה התורה בהם זולתי האדם והנה יהיה הדבר שהוזק לניזק והמזיק ישלם לו מה שהניעהו מההפסד בסבת הנזק אם היה תם חצי נזק גופו ואם היה מועד נזק שלם משל מזיק כי לא הקפידה התורה שישתלמו נזקי הבהמה מגופה אלא כשהיתה תמה. וראוי שתדע שדין הנגיפה והגניחה והרביצה והבעיטה והנשיכה הוא אחד והנה הבהמה היא תמה לאלו הנזקים עד שהועדה אלא אם היה מועד מתחלתו כמו הארי והדוב והזאב והנמר והברדלס ושאר מה שידמה להם ולזה אם רבצה הבהמה על כלים גדולים ושברה אותם הרי זה שנוי ומשלם חצי נזק בגופה. ואולם אם רבצה הבהמה על כלים קטנים אין זה שנוי ודינו דין היזקי הרגל והנה יתבאר דינם אחר זה. וראוי שתדע שלא ינהג זה הדין אלא בשור של ישראל שנגח שור של ישראל שנאמר כי יגוף שור איש את שור רעהו ואולם בשור של הקדש ובשור של נכרי לא ינהג זה הדין והוא מבואר שזה הענין לא ימצא באופן שתשלם שם העדה כ"א ברה"ר כי שם תלכנה הבהמות כלן וימצאו קצתם קצתם ויתכן שיזיקום והוא מבואר שאם נזקה הבהמה ברשות הניזק שבעל השור חייב בנזקיה אם היה תם חצי נזק ואם היה מועד נזק שלם ודין זה נלמד אותו מרגל שפטור בו ברה"ר לפי שלשניהם רשות להוליך בו וחייב ברשות הניזק לפי שאין לו רשו' להלך שם כמו שיתבאר אחר זה ולזאת הסבה חייבה התורה בהיזקים שהזיק הבהמה בעצמה ובמה שידמה לה ברה"ר לפי שאע"פ שיש לה רשות להלך שם אין לה רשות ליגח או לנגוף ובהיות הענין כן הנה תתחייב גם כן על הנגיפה ברשות הניזק לפי שאין לה רשות שם לנגוף אבל הוא יותר ראוי שתתחייב שם וזה מבואר מאד ואולם אם נכנס הניזק ברשות המזיק פטור לפי שאין לו רשות להלך שם ולכתו שם גרם לו הנזק ואולם אם נכנס שם ברשות הנה המזיק חייב כמו הענין ברה"ר וזה כלו מבואר כמעט עיון. וראוי שתדע שהעדת השור תהיה בג' ימים רצופים כשהעידו העדי' בב"ד בכל יום ויום שכבר נגח לא שיעידו יחד שנגח ג' ימים שנ' או נודע כי שור נגח הוא מתמול שלשום שיהיה נודע לו מתמול שלשום שהוא שור נגח ואולם יתבאר שהו' נודע לו כשהעידו זה בב"ד וכן הענין אם הועד לשבתות או לראשי חדשים או משני ימים לשני ימי' ויהיה מועד לימים ההם ולשאר הימים הוא תם ואולם אם נגח ביום אחד ג' נגיחות אין זה מועד שנאמר מתמול שלשו' ואם נגח בג' ימים והעידו העדים יחד בשלשה הנגיחות הנה לא יקרא מועד ואם העידו זה ביום אחד שלשה כתי עדים והעידו שנגח בג' ימים הרי זה ספק אם דינו דין מועד אם לא והמוציא מחבירו עליו הראיה והנה אין העדה אלא בפני הבעלים שנאמר בשור שגנח האדם והועד בבעליו וכ"ש שראוי זה הדין בשור שנגח השור ומפני זה אם הועד שור אחד ומכרו בעלי או נתנו חזר לתמותו עד שיהיה מועד בפני הבעלים השניים וכן אם חזר בו זה השור מהיותו נגח באופן שיתבאר זה לאנשים כאלו תאמר שיהיו התינוקות ממשמשין בו ואינו נוגח הנה חזר לתמותו שנאמר או נודע כי שור נגח הוא שיהיה שור נגח בע שנגח והנה השור המועד אם ישמרו בעליו כראוי פטור שנאמר ולא ישמרנו בעליו ואולם השור התם יתחייב עליו אפילו שמרו כראוי כי לא תלה הכתוב הענין בשמירה והנה אם לא היו לשור בעלים והזיק בין תם בין מועד פטור מן התשלומין והקודם בו זכה כדין ההפקר שנאמ' כי יגח שור איש וזה איננו שור איש וכן היו לו בעלים ולא היו בני דעת כמו שהיה חרש שוטה וקטן אם שנאמר כי יגח שור איש שהוא בן דעת ובכלל מי שהוא פטור על נזקי עצמו לא כל שכן שהוא פטור על נזקי ממונו ולפי שנזק שור תם משתלם מגופו שנאמר ומכרו אש השור החי וחצו את כספו הנה נעשה הנזק שותף בו ואם חזר ונגף יהיה הניזק חייב בנזקיו לפי החלק אשר לו בו. והנה העבד שהזיק הבעלים פטורין שלא חייבה התורה האדם על נזקי ממונו אלא כגון שור וכיוצא בו לא על עסקי אדם שיש לו דעת ועוד שא' היה הענין כן היה ביד העבד להפסיד לרבו כל קניניו וזה אינו מיוש' התוריי ולה לא יתחייב האד' במה שתזיק אשתו והעבד והאשה משלימין כאשר יהיה להם קנין ימשלו בו כאלו תאמר שנשתחרר העבד ונתגרשה האשה והנה דין הנזקין שיגבו מן המטלטלין שנאמר שלם ישלם שור תחת השור כסף ישיב לבעליו ואם אין שם מטלטלין הנה יהיו נפרעין מהקרקע היותר נבחר כדי שישוה למטלטלין ר"ל שיקפצו בו בני אדם לקנותו מצד שבח הקרקע ההוא כי יגנוב איש שור או שה וטבחו או מכרו חמשה בקר ישלם תחת השור וארבע צאן תחת השה והנה החמירה התורה בשור ושה יותר משאר הגנבות לקלות העשות הגנבה הזאת כי אלו הבהמות דרכן שיעמידון בשדות וביערים לרעות ויקל לגנבם מפני זה ולטבחם ולאכלם וכן יקל למכרם לרב התועלת אשר בענינם מה שאין כן בבהמה טמאה והנה הבקר שיש בו בטול מהמלאכה היה ענשו יותר גדול והנה לא יתחייב בזה העונש אם לא מכרו כלו אבל אם שייר בו אבר מן איבריו פטור שנא' וטבחו ומכרו לא שימכר קצו ובכלל הנה הטביחה והמכירה הם בנושא אחד ואם שייר בו מה שאיננו נכלל בטביחה כמו גזותיו הנה הוא חייב ואחד האיש ואחת האשה ואולם חרש שוטה וקטן פטורין מתשלומי ארבעה וחמשה כי אינם בני עונשין שנאמר כי יגנוב איש פרט לקטן לפי שאינו בן דעת וכן הענין בחרש שוטה וקטן והנה הגנבה תאמר על מה שיצא מרשות הבעלים כי מה שהוא ברשותם לא נגנב ולזה אם גנב שור או שה והוא עדיין ברשות הבעלים שלא הגביה אותם באופן שיקנה אותם הנה אם טבח או מכר פטור מתשלומי ד' וה' כי לא גנב אותם בעת שטבח או מכר ואם גנב עגל ונעשה שור או טלה ונעשה איל ואח"כ טבח ומכר פטור מתשלומי ד' וה' שנ' וטבחו או מכרו שיהיה מה שטבח או מכר הוא מה שנגנב בעינו ואולם זה אינו מה שגנב כי כבר נשתנה ונתחדש לו שם אחר טבחו או מכרו על ידי שליח הרי הוא כאלו טבחו או מכרו הוא בעצמו כי כבר יאמר שעשה האדם דבר מה כאשר עשה אותו על ידי שלוחו וכן אם נתנו או פרעו בחובו הרי הוא כאלו מכר כי הנותן נותן לתקות גמול הונה אם חתך אבר מאבריה ואח"כ מכרה הרי זה ספק אם הוא שיור או אינו שיור וזה כי מפני שבטביחה לא יותר זולת מה שמכר ידמה שאין זה שיור ולפי שלפי הנהוג תהיה הטביחה כוללת כל האיברים הנה ידמה שיהיה זה שיור והנה המוציא מחבירו עליו הראיה וכן אם מכרו חוץ ממלאכתו או חוץ משלשים יום שתהיה מלאכתו גם זה ספק אם הוא שיור כי אינו שיור בגוף הבהמה אבל הוא שיור ביחס אל הטביחה כי אחר הטביחה לא תהיה בו מלאכה ולזה יהיה המוציא מחבירו עליו הראיה ואם גנב האדם מבית הגנב פטור מתשלומי כפל ומתשלומי ד' וה' שנ' וגונב מבית האיש ולא מבית הגנב כי אין איש ואדון לזה הדבר הנגנב ומזה יתבאר גם כן שהגונב להקדש פטור מאלו העונשין שנאמר וגונב מבית האיש ולא מבית הקדש וכן הגונב לנכרי שנאמר ישלם לרעהו. וכבר נלמד זה גם כן מדין נגיפת השור הסמוך לזה הדין שאינו נוהג כי אם ברעהו וראוי שתדע כי האדון יקנה הדבר שאינו שלו כשנתיאשו הבעלים ממנו כמו שיתבאר במה שיבא אצל דיני האבדה והנה מפני זה לא תועיל המכירה שימכר לפני יאוש הבעלים ועם כל זה חייבהו התורה עליה שנאמר וטבחו או מכרו בעת שיתחייבו בו על הטביחה יתחייבו על המכירה וכל שכן שיתחייב על המכירה אם מכרו אחר יאוש הבעלים כי אז תקרא מכירה על דרך האמת ואם לקח אדם מהגנב קודם יאוש בעלים ונגנב ממנו הנה איננו איש לזה הדבר הנגנב ולזה לא יתחייב הגנב בגנבה ההיא תשלומי כפל ולא תשלומי ארבעה וחמשה שנאמר וגונב מבית האיש:
@38 **אם במחתרת ימצא הגנב.** שהיה משתדל לגנוב והכהו הבעל הבית או איפה שיהיה ומת לא יתחייב הורגו מיתה ואם זרחה השמש עליו דמים לו ראוי שתדע כי הגנבה תעשה על הרוב בלילה לפי שאז יבטח הגנב שלא יראוהו האנשים ולזה אמר איוב ובלילה יהי כגנב ואמר עוד כי יחדו בבקר למו צלמות ר"ל שהרוצחים והגנבים ידאגו מאד בהיות הבקר עד שהוא צלם כמו צלמות ולזה אמרה התורה אם זרחה עליו השמש ולפי שלא אמר הכתוב אם זרחה השמש דמים לו מגיד שתהיה הזריחה עליו כאלו תאמר שיתחדש שם מה שיתפרסם שהוא עושה מה שיעשה שם כאלו תאמר שראהו נכנס לשם כי אז יירא מעשות שם דבר לחשבו שכבר יודע שהוא עשה זה כמו שיירא הגנב מלגנוב כשזרחה השמש לחשבו שכבר יראוהו האנשים. וראוי שתדע שלא אמרה שאין דמים לזה הגנב מפני רצותו לגנוב הממון שאין ראוי שישלם נפש תחת ממון. ואמנם ירדה תורה לסוף דעתו כי הוא נכנס שם לגנוב ושאם יעמוד עליו בעל הבית או אחד מבני ביתו יהרגם כדי שתשלם לו הגנבה ולזה התירה התורה להורגו לכל מי שימצאהו ואמנם כשזרחה השמש עליו ר"ל שראוהו שם הנה אז ישמר מההריג' לחשובו שכבר יודע מי עשה הדבר הזה ואז לא יותר להרגו ומזה המקום יתבאר שהרודף אחר חברו לרגו מותר להצילו בנפשו של רודף:
@39 **שלם ישלם.** מה שגנב על האופן שיתבאר אחר זה ואם אין לו דבר שישלם הגנבה ממנו ונמכר בגנבתו על יד ב"ד וזאת המכירה היא לשש שנים כמו שהתבאר במה שקדם:
@40 **ואם המצא תמצא ביד הגנב הגנבה משור ועד חמור ועד שה חיים שנים ישלם.** אולם אם טבחם יתחייב על השור חמשה ועל השה ארבעה ולזה אמר חיים. וראוי שתדע שלא תקרא הזביחה הנהירה והעקור ודומיהם וזה מבואר בנפשו אלא אם היתה שחיטתו לכלבי' או לרפואה כי אז יהיה דין הנבול ודין הטביחה אחד והוא כמו טביחה לזה התכלית אשר כוון בה והוא מבואר שדין תשלומי כפל נוהג בכל הדברים המטלטלים שהם ממון שנאמר כי יתן איש אל רעהו כסף או כלים וגו'. אם ימצא הגנב ישלם שנים למדנו שדין תשלומי כפל נוהג גם במה שאינו ב"ח כשהיה ממון ויתבאר מזה שמי שגנב עבד כנעני לא ינהג בו דין תשלומי כפל כי אינו דומה לאלו הפרטים אשר זכרה התורה בענין הגנבה כי הוא אדם ועוד שכבר הוקשו עבדים לקרקעות אמר והתנחלתם אותם לבניכם אחריכם ולא ינהג זה הדין בקרקעות כי אינן מטלטלין ולא תתכן בהם הגניבה גם כן כי הקרקע הוא ברשות בעליו איך שיהיה ולא ינהג זה הדין בגנבת השטרות לפי שאין גופו ממון והוא מבואר שתשלומי ד' וה' אינו נוהג אלא בשור ושה ושור יקרא אפילו בן יומו שנאמר שור או כשב או עז כי יולד ושה יקרא מן הכבשים ומן העזים אחד זכר ואחד נקבה כמו שהתבאר במה שקדם והוא מבואר שנקרא שה אפי' אחר שנה מפני שאמרה תורה שה תמים זכר בן שנה וראוי שתדע כי הגנבה בעינה חוזרת לבעלים אפילו לאחר יאוש שנאמר אם המצא תמצא בידו הגנבה וגו'. ר"ל שהוא משלם הגנבה ההיא בעצמה ובעינה ויענש לתת כפל כשעור מה שרצה לגנוב מחברו וזה גם כן יתבאר ממה שהקפידה תורה בנזקי שור ובור שיהיה המת לנזק וכן ראוי שתשוב הגנבה לבעליה ואם השביחה הגנבה מאליה לפי יאוש הוא לבעלים ולאחר יאוש הוא לגנב כי כבר קנאה ביאוש הבעלים ואולם אם השביחה בשהוציא הגנב בה הוצאה הנה השבח לגנב אפילו לפני יאוש ואם נשנית בידו הגנבה משלם תשלומי כפל בשעת הגנבה שנאמר אם המצא בידו הגנבה וגו'. שנים ישלם ר"ל שישלם שנים כמו הגנבה לזה אם גנב טלה ונעשה איל משלם שני טלאים כעין שגנב וכן אם גנב כי ושברו אינו משיב לו הכלי אבל משיב לו שנים כעין שגנב כי הוא מחוייב לשלם שנים כמו הגנבה. וראוי שתדע כי הבא במחתרת נהרג מפני חשבנו שהיה רודף להרוג בעל הבית אם יעמוד להציל ממונו ולזה לא יהיה נהרג אם נתברר לנו שהוא אינו רודף כמו שראוהו עדים שנכנס שם כי יירא מעשות דבר לדעתו כי יודע הדבר וכן אם היה יוצא משם ונמצא במחתרת יש לו דמים גנב או לא גנב כי כבר נתבאר שאינו רודף וכן אם נתבאר מעניינו ביאור שלם שאין כונתו להמית כמו הצב שנכנס בבית הבן יש לו דמים ואין הבדל בין נמצא גנב במחתרת או שנמצא בתוך גנו של אדם או לתוך חצר או בתוך קרפיפו הנה אם נהרג אין לו דמים כי הוא נכנס שם לגנוב ואם יעמוד אדם לפניו יהרגנו ולא אמרה התורה במחתרת אלא בהווה כי הכונה כלה למנוע המכוין להרוג שלא יהרוג ואין הבדל בין שנמצא שם ביום או בלילה כי התורה לא אמרה אם זרחה השמש דמים לא אבל אמרה אם זרחה השמש עליו כמו שקדם והוא מבואר בעצמו כי ביום ישתדל יותר להרוג כדי שלא יתפרסם ענינו כי לא יוכל לברוח שלא יראוהו האנשים ואין הבדל בין נמצא במחתר' או בין שיהי' איש או אשה או גדול או קטון שנא' אם המחתרת יצא הגנב אי זה שיהיה. וראוי היה להיות כן כדי לשמור שלא יהרג הלא תראה כי השור נסקל לשמירה שלא יהרג ואע"פ שאין לו דעת ולא היה ראוי שיענש והנה הבא במחתרת לתוך שדה או גנה או דיר או סהר וכיוצא בהם יש לו דמים כי לא עלה בדעתו שימצא שם אדם ולזה לא היתה כונתו כי אם לגנוב. וראוי שתדע שאין האשה נמכרת בגנבתה שנאמר ונמכר בגנבתו האיש ולא השה ולזה תמצא שבארה התורה זה הדין בעבד עברי לבד ואולם האשה לא תמצא שיהיה אחר שליט למכרה כי אם אביה בהיותה קטנה שנאמר וכי ימכור איש את בתו לאמה וראוי היה להיות כן כי באשה אם תמכר יהיה לחוש לעבירה מה שאין כן באיש הנמכר ולזה צותה התורה בבת הנמכרת שיעדה האדון לו לאשה או לבנו והוא מבואר שאינו נמכר בגנבתו אם לא היה גדול כי אינו בן עונשיו והנה הואר נמכר בגנבתו ואם היה שוה יותר מגנבתו אינו נמכר שנאמר ונמכר בגניבתו שיהיה כלו נמכר בגנבתו אבל אם היה שוה פחות מגנבתו הרי הוא נמכר כי כבר תוכלל מכירתו בגניבתו והשאר יהיה חוב עליו עד שתמצא ידו:
@41 **כי יבער איש שדה או כרם.** ר"ל שיאכילהו לבהמתו ושלח את בהמתו וירעה בשד' אחר הנה ישלם מיטב שדהו שהשחית או מיטב כרמו ואו' ההשחתה כבר תהיה אם באכילה אם ברגלי הבהמה כי הוא ישלם לו גם כן מה שתשחית הבהמה ברגליה כי בזה הגיע לו ג"כ נזק וכבר רמז אל זה הנזק במה שאמר ושלח את בעירה ר"ל שכבר עזבם ללכת שם כאמרו משלחי רגל השור והחמור ולא יתחייב על אלו הנזקין וכמה שידמה להם כי אם ברשו' הניזק שנאמר וביער בשדה אחר ואולם ברשו' הרבים פטור על השן והרגל וכ"ש ברשות המזיק וראוי שתדע שמה שידמה לשן דינו כשן ומה שידמ' לרגל דינו כרגל והנה מה שידמה לשן הוא כל נזק שיגיע מהבהמה שתתכוין בו להנאתו כמו שנתחככה בכותל להנאתו והזיקה או טנפה פירות להנאתה ומה שידמה לזה ממה שיהיה להנאת הבהמה שיהיה דרכה בכך ומה שידמה לרגל הוא מה שדרך הבהמה להזיק בו דרך הליכה כמו שהזיקה בגופה דרך הלוכה או במה שמחובר לגופה וכמו משואה ופרומביא שבפיה ועגלה המושכת בקרון כי כמו שדרכה ללכת ולהזיק כך דרכה להניע הדברים המחוברים לה עמה ולהזיק במה שיפגשו אותו' וראוי שתדע שאם אכלה הבהמה מה שאין דרכה לאכול על דרך הטרף או על דרך השחתה הנה הוא מתולדות נגיחה או נגיפה שחייב עליהם ברשו' הרבים אם תם חצי נזק מגופו ואם מועד נזק שלם כמו הכלב שאכל טלאים וחתול שאכל תרנגולים גדלים או שאכלה כסות אוכלים כי התורה אמרה שדה או כרם שהוא דבר שדרך הבהמה לאכול ממנו וראוי שלא יעלם ממנו כי אע"פ שהוא פטור ברשות הרבים מנזקי שן ורגל הנה אם נהנת הבהמה משלמת מה שנהנת אע"פ שאינה משלמת מה שהזיקה כי אין ראוי שיהנה האדם מחברו שלא ברצונו ולא ישלם לו. וראוי שתדע שאם נכנסה הבהמה לרשות הניזק באונס בזולת פשיעת השומר הנה בעליה פטור מלשלם מה שהזיקה שנאמר כי יבער איש שדה או כרם ושלח את בעירה שיהיה הוא המבעיר או המשלח וזה אמנ' יהיה כשלא שמר' כראוי כי מטבע הבהמה שתלך לאכול באשר תמצא כשלא ישמרוה הבעלים ולה אם לא שמרה הנה הוא כאלו היה הוא המשלח אותה שם ובהיות הענין כן הנה אם באה הבהמה שם באונס כמו שהוחלקה ונפלה לגנה ואכלה שם אין הבעלים משלמין מה שהזיקה ואמנם ישלמו מה שנהנת כמו שביארנו וכן אם כנס צאנו לדיר ונעל בפניה כראוי ויצאת והזיקה הנה הוא פטור כי הוא אינו המבעיר או המשלח וכן אם שלחה איש אחר והביאה שם הבעלים פטורין כי הם אינם המשלחים וזה ששולח אותם שם היא משלם מה שהזיקה יותר ממה שנהנת והבעלים משלמין מה שנהנת והנה יראה מפשטי הכתוב שהבהמה תהיה ברשו' הניזק ואכלה פירות הניזק שתקחם מרשות הניזק ואז יתחייב לשלם מה שהזיקה שנאסר ושלח את בעירה ובער בשדה אחר שתהיה הבהמה אוכלת בשדה אחר ותקח משם מה שתאכל הי התורה בארה שהוא משלם מה שהזיק בשדה ההוא. ואולם אם אכלה פירות הניזק ברשות הניזק ולקחת אותם מרשות הרבים הנהנה ספק נסתפק לחכמי התלמוד וזה כי הוא אוכלת בשדה אחר ויתכן שיאמר בכמו זה ובער בשדה אחר ואפשר גם כן שלא יאמר בכמו זה וביער בשדה אחר מפני שלא לקחה הפירות מרשות הניזק ולזה יהיה על המוציא מחבירו עליו הראיה ואולם אם לקחה הפירות ברשות הניזק ואכלה אותם ברשות הרבים הנה לא יאמר בכמו זה וביער בשדה אחר שהרי לא אכלה אותם בשדה אחר ולזה לא ישלם אלא מה שנהנת. וראוי שתדע שאם הזיקה הבהמה פירות תלושין ומה שידמה להם כמו כלים משלמין הבעלים מה שהזיקה הבהמה כשישומו הפירות ההם או הכלים ההם כמה הם שוין ואם הזיקה פירות המחוברים לקרקע הנה ישומו הפירות ההם בששים בקרקע ההוא ר"ל שאם אכלה בית סאה משערי' כמה ישוו ששים בית סאו' באותה שדה עם כמו אלו הפירות וכמה הם שוין כשנאכל מהם בית סאה ומשלם הפירות ולמדנו זה ממה שאמרה התורה מיטב שדהו ר"ל ששמין המיטב עם השדה אע"פ שלא אכל כל השדה ובזה הקל מה למזיק ור"ל שאם היו שמין הפירות ההם לבדם היה הפחות יותר וזה הדין נבנה על שרשים מהם שהמחובר למה שיצמח בו דינו כדין מה שיצמח בו ולזה היה עובר ירך אמו ופירות המחוברים לקרקע כקרקע ומהם כי ששים הוא המספר התכליתיי אשר יהיה בו למתדמה החלקים בטול במינו ולמדנו זה בענין זרוע בשלה ומהסכי בדיני ממונות נשפט להקל על מי שנוציא הממון ממנו לפי מה שאפשר ובהיותצ הענין כן וכבר בארה לנו התורה שזאת השומא תהיה על גב שדה אע"פ שלא אכלה כלה הנה נקח זאת השומא בתכלית מה שאפשר מן ההיקל באופן שלא יבטל יחס זה הדבר אל הכלל שנחברהו אליו וזה יהיה בששי' פחות ממנו מעט ולפי שהמעט ההו' לא ימצא באופן שלא ימצא יותר מעט ממנו הנה לא נחסר מהם דבר כי מה שזה דרכו לא יעלה ולא יוריד בזאת השומא כלל עד שאם נחסר מהם דבר מה הנה כבר אפשר שיחוכר ממנו יותר מעט מזה ונכביד על המזיק שלא כדין ומזה יתבאר שאם שכרה הבהמה לק מה מכלי יתכן שיתוקן הנה לא נשים החלק ההוא הנשבר אבל נשים הכלי כמה שהיה שוה קודם הנזק וכמה הוא שוה עתה כמו הענין בשדה ובכרם:
@42 **כי תצא אש.** לפי הנהוג שימשך יציאתה ומצאת קוצים אשר המשיכו האש והביאוה אל הגדיש או אל הקמה ונאכל הגדיש או הקמה או נפסד השדה ונשרף כמו שלחכה נירו וסככה אבניו שלם ישלם הנזק מי שהבעיר הבערה והוא מבואר שאם עבר האש שם באונס כמו שהביאתה לשם רוח שאינה מצויה. או שעברה נהר שאין דרך האש ההוא לעברה והזיקה אחר זה או שהכניס הניזק כליו לשם פטור כי התורה אמרה המבעיר את הבערה והו' לא הבעיר אותה ולזה הוא מבואר שהמבעיר את הבערה והרחיק משד' חברו באופן שלא היה ראוי לאותה האש שתגיע שם והגיעה שם והזיקה טור וכן אם שמר אשו ומסרה לבן דעת לשמר' פטור מנזקיה כי הוא אינו המבעיר הבערה ואם מסרה למי שאינו בן דעת חייב ואם היה מדרך האש ההוא שתמשך ותזיק ולזה הוא מבואר שאם מסר אש בעל שלהבת לחרש שוטה וקטן שהוא חייב ואם מסר להם נחלת ולהכוה טור לפי שאין דרך הנחלת שתמשך ותזיק והנה אם כן זה הנזק לא עשתה אשו אבל עשתה זה האש שהדליקו אליו שאינם בני דעת והנה המבעיר והוא המתחייב ולזה אם הביא אחד האש והביא השני עצים הנה המביא עצים הוא המבעיר ואם הביא אחד עצים והביא השני האש' הנה המביא האש הנה הוא המבעיר וכן אם הביא האחד אש והשני עצים ובא השלישי וליבה כדי להבעיר האש הנה המלבה הוא המבעיר והנה יתחייב לבדו בנזקי האש ואם לבתו רוח שאינה מצויה כלן פטורין כי זאת ההבערה היתה באונס וראוי שתדע כי האדם יתחייב באשו משום חציו וזה כי כמו שהחץ מזיק מזולת מי שיגע מי שירה אותו בנזק כן הענין באש וכמו שהחץ יתנועע מההנעה אשר הניע אותה מי שירה אותו אם לא ימנעהו מונע כן האש ימשך ויתנועע מצד הטבע שחדש בו המדליק אותו במקום הראוי שימשך שם מצד טבעו ואין לאש התחלה אל שלא יתנועע אחר שהובער כמו שאין לחץ התחלה אל שלא יתנועע אחר שיורוהו ולפי שאשו הו' משו' חציו הנה יתחייב בו בעל האש אם הזיק באדם בה' דברים כמו שיתחייב בזה אם חבל בו בחציו כי אין הבדל בין חבלו' האד' בין מתכוין לשאין מתכוין כמו שהתבאר בענין דמי ולדות והנה יתחייב על אשו ג"כ משום ממונו שנאמר כי תצא אש ומצאה קוצים ונאכל גדיש או הקמה. ולזה כשהיתה אש בחצרו של אדם ולא שמרה כראוי ויצתה והזיקה חייב ולזה סמך הכתוב גם כן נזקי אשו לנזקי שן ורגל ללמד שהוא חייב על אשו משום ממונו וראוי שתדע כי האש שיצאה מרשותו של אדם והזיקה הנה בעל האש פטור על הטמון שנאמר ונאכל גדיש או הקמה או השדה שהם דברים גלוים ואולם על הטמון פטור ואם הבעיר בתו של חברו חייב אף על הטמון שנודע בלי ספק שהוא שם שהרי לא הבעיר ברשות והרי הוא כאלו הזיקו בידים ומתקנת חכמים שאם לא היו שם לדים על הטמון ישבע ויטול מה שדרך בני ארסל הניח בו אבל מה שאין דרך בני אדם להניח בו אפילו ישבע אינו נוטל. והמשל שאם היה ארנקי מלא מעו' בגדיש אפי' נשבע אינו נוטל אם אין שם עדים כי אין דרך בני אדם להניח ארנקי בגדיש וראוי שתדע כי מה שידמה לאש דינו כדין האש כמו אבנו וסכינו ומשא' שהניחן בראש גגו באופן שרוח מצויה תפילם ונפלו והזיקו בעת נפלם. הנה דין זה הנזק כדין האש בשוה וכן הענין במה שידמה לזה ואמנם אחר נפלם יהיה דינם דין הבור וזה מבואר ממה שקדם
@43 **כי יתן איש אל רעהו כסף או כלים שמור.** ר"ל שיגיעו ביד רעהו באחד מהדרכים אשר ישובו בהם להיות ברשותו וקבל עליו לשמור אותם וגונב אחרי כן הדבר שהוא שומר אותו מבית האיש השומר אם ימצא הגנב ישלם שנים לבעלים לפי שהוא גונב אותו להם כי זה השומר פטור מגניבה ואם לא ימצא הגנב והיה זזה וען שנגנב מנו לפטרו מן התשלומין ונקרב בעל הבית שנגנב זה מרשותו אל הדיינין וישבע ויפטר כי לזאת הסבה יבא לפניהם כמו שאמר בתמורת זה המקום בפרשה השנית שבועת יי' תהיה בין שניהם אם לא שלח ידו וגו'. והנה יפטר בזאת השבועה אם לא שלח ידו במה שנתן בידו חבירו קודם שנגנב ממנו שאם שלח ידו בו באופן שיקנה אותו לעצמו כאלו תאמר שהגביהו להשתמש בו ולהחזיק בו כשלו הרי הוא באחריותו ומשלו נגנב לא משל בעלים ואם טענו הבעלי' שהוא פשע בשמירתו שלא שמר כראוי לפי מה שהפקיד לו שהיה שור או חמור או שה או שלמה ומה שידמה להם או שהיה מחלוקת ביניהם:
@45 **על כל אבדה.** שהיא באופן שאפשר שיאמר בעל האבדה כי הוא זה ר"ל שאפשר לו להכיר האבידה ולתת סימניה והנה טוען שאין האבידה שלו עד הדינין יבא דבר שניהם להכיר אם פשע אם לא פשע או אם האבדה שלו או אינה שלו ואפשר שיהיה הרצון בזה על כל אבדה שיטעון השומר שנאבד ממנו באיזה אופן שיהיה עם כשנגנב כמו שקדם או בזולת זה האופן שזה יאמר כך וכך היה מה שהפקדתי בידך והשומר טוען כי הוא זה ואינו כמו שאתה אומ' או יהיה הרצון בזה על כל אבדה שיטעון השומר שיאמר בעל הפקדון כי מה שאתה שואל שנגנב או אבד הוא זה והוא בידך הנה מכל אלו הטענות יבא על הדיינין דבר שניהם לראות מי הוא הטוען אמת וישבע בפניהם השומר שהוא דבריו ויפטר במה שהודה אם הודה דבר. והנה מי שירשיעו אותו הדיינין מפני שנשבע על שקר ישלם שנים לרעהו ר"ל בזה שטען טענ' גנבה ואבדה ונשבע שאם באו עדים אחר זה שנשבע על שקר באופן שירשיעוהו הדיינים ולא ירשיע הוא עצמו הנה הוא משלם שני כי הוא כמו גנב ואין ספק שלא יהיה זה הדין כי אם אחר שנשבע כי המה שטען שנגנב או נאבד קודם שנשבע לא הועיל להפטר מתשלומי הפקדון וענין תשלומי כפל הוא לחייבו מדה כנגד מדה וכן אם נשבע והודה אחר זה אינו משלם תשלומי כפל כי אין מרשיעין אותו דיינים אבל הוא מרשיע את עצמו והוא מבואר שזה הדין בזה הענין שוה היה הפקדון כסף או כלים או שור או חמור או שה ומה שידמה להם. כי כבר זה באר זה בביאור בזאת הפרשה ולא אמר הכתוב כסף או כלים אלא שדבר בהווה:
@45 **אשר יאמר כי הוא זה.** ר"ל שאם תהיה טענתם בשור וחמור או שה או שלמה שנתן בידו בכל אבדה שמצא שיאמר השומר כי הוא זה ואיננו כמו שאתה טוען עד האלהים יבא דבר שניהם לאמת זה הענין בשבועה והנה השומר ישבע ולא ישלם כמו הענין בשבועות השומרים שהוא על השומר לפי מה שהתבאר מדברי התורה ומהענין בעצמו וכבר יתבאר שזה הענין הוא הודאה במקצת הטענה מפני מה שאמר אשר יאמר כי הוא זה ולא אמר אשר יאמר כי הוא אינו ואם טענו חטים והודה לו בשעורים הנה הוא אומר לו כי הוא אינו לא כי הוא זה. ובכלל הנה אמרו כי הוא זה מודה שהטענה וההודאה הם בדבר אחד וזה מבואר למי שיבין במלאכת ההגיון וכבר ביארו זה במכילתא בזה האופן והנה חכמים תקנו שהמוצא מציאה לא נחייבהו שבועה מפני תקון העולם ומתקנת חכמים שלא ישבע מודה מקצת אם לא היתה הכפירה שתי כסף או יותר וההודאה בשוה פרוטה או יותר והוא מבואר שאינו מודה מקצת אם לא הודה לו במקצת הכמו' שטען. ולזה יחוייב שיהיה הטוען טוען דבר מוגבל במדה או במשקל או במנין שאם לא היה מוגבל לא היה לזאת הטענ' קצת שתהיה בו הודאה במקצת והנה אם טען דבר שבמדה והודה לו במנין או במשקל פטור כי הם מינים מתחלפים מהכמה ולא יפול ביניהם היחס כאלו תאמר שטען מדה מלאה מעות והוא מודה לו בחמשים זוז ומזה המקום יתבאר שהמודה בקנס פטור שנא' אשר ירשיעון האלהים ישלם שנים ואולם אם היה מרשיע עצמו ר"ל שיורה שנשבע על שקר הנה הוא פטור מן הכפל וכבר נשפט שהענין הוא כן בשאר הקנסות וראוי שתדע כי מה שנאמר בשומר שכר ומת או נשכח הוא כשהיה זה באונס גדול שאינו יכול להציל ראיה לדבר זה שהרי הוא חייב על הגנב' ואע"פ שהוא אונס ולזה הוא מבוא' שלא יפטר מהמתה והשבורה והשבויה אלא מפני שהו' אונס יותר גדול מאונס הגנבה והנה הרצון במתה שתמות כדרכה שאין לך אונס יותר גדול מזה והשבור' שנשברה ע"י לסטים שאין לו כח לעמוד מפניהם בשום פנים וכן העניין בשאר האונסים הגדולים הדומים לזה וראוי שתדע כי מ"ש אין רואה שבועת ה' תהיה וגו'. אין הרצון בו שאם לא ראו עדים זה הענין ישבע ויפטר כי לא יפול ספק בזה שאם יביא עדי' יפטר אבל הרצון בזה שאם לא היה מדרך המקום ההוא שיהיה שם רואה אז יפטר בשבועה ואם היה מדרך המקום ההוא שיהיה שם רואה לא יפטר בשבועה אלא יביא ראיה או ישלם וכן מה שפטרה התורה שומר שכר מהטרפה הוא כשנטרפ' באונס גדול וזה יתבאר בביאור בעינו אשר ביארנו זה בשבויה ושבורה ומתה וראוי שתדע שאם פשע בשמירתו כמו שהביא הבהמה למקום גדודי חיות ולסטי' ומה שידמה לזה הנה הוא חייב לשלם כמו העניין בשומר חנם שהוא חייב בפשיעה והנה מה שאמר בטרפה יביאהו עד אין הרצון בו שלא יפטר אלא בעדם כי הטרפה דינה כדין המתה והשבויה והשבורה אלא שהרצון בו שיביא עדים במקו שיש רואה או שישבע במקום שאין רואה כי אין שם סבה תחייב שיהיה ההבדל בין הטרפה ושאר האונסים הגדלים וראוי שתדע שהעד הנאמר בכאן הוא שני עדים וזה יתבאר מצד הגדר כי ההעדה יחויב שתהיה בבית דין כי בזולת זה לא יהיה כי אם ספור. וראוי שיהיה משני עדים כי בזולת זה לא יגמר הדין על פיהן ולא תהיה העדה בצד שיהיה פטור מלשלם בה העדות כי התורה אמרה על פי שנים עדים יקום דבר וראוי שתדע כי השואל ששאל בהמה או כלי למלאכה מה ומחמת המלאכה ההיא שהיה לו רשות עליה מאת הבעלים מתה הבהמה או נשבר הכלי בשעת מלאכה הנה הוא פטור כי על זה הרשוהו הבעלים ואולם אם בא הפסד שלא בשעת מלאכה או שלא מחמת המלאכה שהרשוהו עליה אבל מחמת מלאכה אחרת הנה השואל חייב והוא חייב בכל האונסין כמו שהתבאר בתורה. וראוי שתדע שהשומרים לא יתחייבו בדבר אם לא היו בני דעת וזה מבואר מהשרשים הכוללים ואולם הבעלים אע"פ שלא היו בני דעת יתחייבו השומרים להם כל אחד בדינו ולא נאמר כי יתן איש אל רעהו אלא בהווה:
@46 **כי יתן איש אל רעהו חמור או שור או שה וכל בהמה.** באופן שיהיה ביד רעו ויקבל עליו לשמור ומת הב"ח ההוא או נשבר ששברתו חיה רעה או נשבה ששבוהו לסטים הנה אם אין רואה שיבא ויעיד בזה שבועה השם תהיה בין שניהם בפני ב"ד כמו הענין בפרשה הקודמת וישבע השומ' שכן הוא ויפטר אם לא שלח ידו קודם זה במלאכת רעהו שאם שלח ידו בה שלא מת או נשבר חייב לשלם ולקח בעליו השבועה ממנו ויפטר השומר מלשלם ההפסד שהגיע בסב' המיתה והשבירה או יהיה הרצון באמרו ולקח בעליו שיקח הנבלה או השבור' ויפטר השומר מלשלם אפילו פחת נכלה כי אל היה לו רשות להטפל בה וכן פירשו במכילתא ואם גנוב יגנוב מעמו וגו'. כי אונס הגנבה איננו גדול כאונס המיתה והשבורה והבזוזה ולזה לא יתחייב על המיתה והשבירה והשבי ואם טרוף יטרף. שטרפו חיה רעה יביא אל הבעלים עד בפני ב"ד שהענין כי הוא ויפטר מלשלם הטרפה ר"ל ההיזק שהגיע בסבת הטרפה ויתכן שירצה בזה כי גם הנזק שתגיע בטרפה אחר שנטרפה לא ישלם כי לא היה לו רשות להטפל בזה:
@50 **וכי ישאל איש מעם רעהו ונשבר.** באונס או מת הנה אם לא היה בעליו עמו במלאכתו בשעת שאלה שלם ישלם אע"פ שאלו האונסין הם אונסים גדולים אם בעליו עמו בשעת שאלה לא ישלם דבר כי מפני שבעליו הם תחת ידו בשעת שאלה הנה לא יתכן שישתעבד לו זה אז בשמירת הבהמה כי מן השקר שיהיה האדם עבד ואדון יחד לאיש ועוד כי האדם כשהיה עושה מלאכת אחר ייטב בעיניו ליהנות בעל המלאכה כדי שיתן לו שכר מהמלאכות אשר לו ולזה לא יחוש אז אם יקח בהמתו או כליו אע"פ שלא יקבל עליו שמירתו הנה אם הוא שכיר לבעלים בא בעניין זאת השאלה בעבור שכרו ואם איננו שכרו הכל הולך אל מקום אחד כי האדם יעשה חסד לחברו לתקות גמול ולזה הוא מבואר שאם היה בעליו עמו פטור מלשלם ולמדנו מזה כי בכאן ג' דינין מתחלפין לשומרים האחד הוא פטור מגנבה ואבדה וחייב בשפיעה והב' חייב בגנבה ופטור בשבורה ומתה. והשלישי חייב בכל האונסין והנה השלישי הוא שואל כמו שביאר הכתוב והשנים הראשונים הם שומרין ואין התחלפו' דיניהם מפני חלוף מה שישמרו אותו כי כל אחד מהם כבר יחוייב בשמירת הבהמ' כמו שביאר הכתוב ולזה הוא מבואר שהתחלפות דיניהם הוא מפני התחלפותם בענין השמירה והוא מבואר שאשר ישמור בשכר הוא יותר משועבד לשמור מאשר ישמור בחנם ולזה תהיה הפרשה הראשונה בשומ' חנם ומפני זה אמר בה כסף או כלים כי לא תמצא שיבקש האנשים שכר בשמירת הכסף והכלים והפרשה השנייה היא בשומר שכר ולזה אמר בה חמור או שור או שה וכל בהמה כי על הרוב לא תמצא שיקבלו האנשים לשמור הבהמה אם לא בשכר והנה הענין כן הולך בהדרגה שומר חנם שכל ההנאה היא לבעלי' פטור מכל אונס ושואל שכל ההנאה היא שלו חייב בכל אונס ושומר שכר שההנאה היא לשניהם חייב באונסין קטנים כמו גניבה ואבידה ופטור באונסין גדולים וממזה יתבא' שכן הענין בשוכר כי ההנאה היא גם כן לשניהם. וראוי שתדע כי כל אחד מהשומרים יפטר מכל דבר אם היה בעליו עמו בשעה שהגיע לידו הפקדון ככי התורה ביארה זה הענין בשואל וכ"ש בשאר השומרים וכבר יתבאר לך מדברינו כי כשהיה בעליו עמו פטור גם על פשיעה כי לא נשתעבד בשמירתו כלל כמו שביארנו וראוי שתדע שדין השומרים הנזכ' בכאן אינו נוהג בהקדש ולא בשל נכרי שנאמר כי יתן איש אל רעהו וכי ישאל איש מעם רעהו אינו נוהג בקרקעות ולא בעבדים ולא בשטרות והטעם בעינו שנתבאר זה בענייני הגנבה ולא יתחייבו עד שהגיע לידם שנאמר כי יתן איש אל רעהו שיגיע לידו ובשואל נאמר וכי ישאל איש מעם רעהו שיהיה שואל מעם רעהו להוציא מה שהוא עדין עם רעהו ולא יתחייבו שומר חנם ושומר שכר עד שיקבלו לשמור שנאמר לשמור והנה שומר חנם שפשע ולא שמר כראוי לדבר ההוא הנשמר הנה הוא חייב שנאמר על כל דבר פשע על שור על חמור על שה על שלמה שיהיה פושע ביחס שמירת השור או החמור או השה או השלמה ושומר חנם ושומר שכר ששלח יד בפקדון נתחייב בכל האונסין הרי הדבר עומד באחריותן שנאמר אם לא שלח ידו במלאכת רעהו הא אם שלח ידו במלאכה לא יפטר מתשלומין מפני אלו האונסין וסבת זה כי כבר שב הדבר ההוא להיות להם ונתחייבו לשלם כמוהו לבעלים מעת ששלח בו ידו והוא מבואר שהדיינין שיבואו לפניהם הם יותר מאחד שנאמר אשר ירשיעון האלהים ואפשר שהיו שנים אם לא יהיה שם מכריע ביניהם אם יחלוקו ולא יגמר הדין על פיהם ולזה יחויב לכל הפחות שיהיו שלשה וכבר יתבאר מזה המקום שמודה מקצת הטענה ישבע שנאמר על שור על חמור על שה וגו':
@52 **וכי יפתה איש בתולה אשר לא אורסה.** קודם זה הפתוי ושכב עמה הנה יקשר עמה בקשר האישות ותהיה לו לאשה תחת אשר פתה אותה וזה הוא מה שענשה אותו התורה על זה ואם לא ירצה אביה לתתה לו לאשה הנה ישקול כסף כמוהר הבתולות כמו שנתבאר בפרשת כי תצא מלחמה בענין האונס שהוא חמשים כסף וראוי שתדע כי אמרו אשר לא אורסה. לא בא להוציא את הארוסה בעת הפתוי כי כבר נתבאר בתרוה משפט הארוסה שהיא בסקילה ואמנם בא להוציא מי שנתארסה ונתגרשה והוא מבואר שלא הוציא אותה מזה הדין לפטור המפתה אותה אבל הוציא אותה מענין היות הקנס לאביה. רצוני שאם לא אורסה יהיה הקנס לאביה כמו שנבאר ואם אורסה יהיה הקנס לעצמ' וראוי שתדע שלא יתחייב המפתה בזה הקנס אם לא בא אליה כדרכה שנאמר וכי יפתה איש בתולה שיפתה אותה וישכב עמה באופן אשר היא בתולה ולז"א כמוהר הבתולות כי הוא אבד אותה המוהר ההוא מפני שהשיב אותה בעולה. וראוי שתדע שזה הדין ינהג במי שהוא ברשות אביה כמו קטנה ונערה שנאמר ואם מאן ימאן אביה לתתה לו ואולם הבוגרת כבר יצאת מרשות אביה כמו שיתבאר בפרשת ראשי המטות ולזה אין לה קנס כי כנין הקנס הוא חדוש ולא ינהג אלא בנושא אשר זכרה אותו התורה. וראוי שתדע שאע"פ שאינה ראויה לו לאשה כרגון חייבי כריתת וחייבי לאוין שאין בהם מיתת ב"ד ולא התרו בו למלקו' ישלם קנס כי אמרו מהורי מהרנה לו לאשה אינו תנאי להקל עליו אבל הוא תנאי להחמיר עליו ולענשו בזה האופן ואין מן הראוי שכאשר לא יוכל להענש בזה האופן יהיה פטור. וראוי שתדע כי מי שהיא בחזקת בעולה אין לה קנס שנאמר בתולה וזו אינה בחזקת בתולה והוא מבואר שזה הקנס הוא לאביה כשהיה לה אב שנאמר ואם מאן ימאן אביה לתתה לו וכיון שהיא ברשותו לתת למי שירצה ראוי שיהיה הקנס הזה שלו ועוד שכבר ביארה התורה זה באונס שנאמר ונתן לאבי הנערה חמשים כסף. וראוי שתדע שאמרו מהורי מהרנה לו לאש' אינו מחויב שתהיה לו לאשה אם לא רצתה כי לא בא הצווי לה ולזה מבואר שאם לא רצתה היא נותן המפתה קנס לאביה וכ"ש אם לא רצה הוא כי אף על פי שרצה לנשאה ישלם קנס אם לא רצתה היא כ"ש כשלא רצה לכנסה שיחוייב לשלם לה קנס וראוי שתדע כי המפתה ישלם זולת הקנס הבושת והפגם וזה יתבאר ממה שאמר והוא שכבר נתבאר חיוב האדם בחמשה דברים במה שהזיק ברעה והוא מבואר שהאונס מביא צער באנוסה ואין הענין כן במפותה ואם היו החמשים כסף עונש זה הענין בכללו היה עושה האונס בבושת ופגם יותר כל מעונש המפתה כי המפתה ישלם חמשים כסף על הבושת והפגם והאונס יפטר בחמשים כסף והבושת והפגם והצער ולזה הוא מבואר שאין אלו החמשים כסף דמי הבושת והפגם אבל הם קנס והוא משלם אותם מפני מה שנהנה מזה ולזה אמר באונס ונתן האיש השוכב לאבי הנערה. רצוני שכבר נתן זה בעבור ששכב עמה ונהנה בשכיבתו זאת:
@54 **מכשפה לא תחיה.** ר"ל העושה מעשה מפעולות הכשוף. ואולם מה שהוא נעשה על צד אחיזת העינים אין בו חייב מיתה כי אין זה נכנס תחת גדר הכשוף וכבר יתבאר במה שיבא דין המכשף הוא בסקילה ואמר בזה המקום מכשפה לא תהיה להורות שאם לא המיתוה עוברים על לא תעשה והנה זכר בכאן האשה לפי שהנשים דעתן קלות ולה תמצאנה בהן פעולות הכשוף יותר ממה שימצאו באנשים. והנה זכר בכאן מכשפה כי הם יעשו פעולות על צד הכשוף להביא הבתולה אל שירצה המפתה:
@55 **כל שוכב עם בהמה מות יומת.** הנה הוצרך להזכיר זה בזה המקום כי מפני מה שנזכר מההבדל בין נזקי אדם לנזקי בהמה אולי יחשב חושב בראותו כי המפתה בתולה יפטר בממון שהשוכב עם בהמה יהיה פטור כי לא הזיק דבר לבעל הבהמה ולזה בארה התורה כי הוא חייב מיתה וזאת המיתה היא סקילה כמו שיתבאר במה שיבא ואין הבדל בשכיבת הבהמה בין כדרכה בין שלא כדרכה בין גדולה בין קטנה כי הוא ראויה לביאה בהולדה בין שאינה נרבעת או אובע' כמו שיתבאר בעניין העריות ועוד כי מי שימשך לפועל המשגל בזה האופן יקרה לו שאם לא ימצא אשה ישכב עם בהמה:
@56 **זובח לאלהים יחרם.** אע"פ שאין זה דרך עבודתם יחרם וימות וכבר נתבאר בפרשת שופטים שזאת המיתה היא סקילה והנה לא תעשה העבודה הזאת בלתי ליי' לבדו ולמדנו מזה שכן הענין בשאר העבודות הנעשות לשם יתע' שאם עשה אחת מהם לע"ז נסקל אע"פ שאין דרך עבודתה בכך ואין צריך לומר שאם עבד אותה דרך עבודתה שהוא חייב מיתה והנה בא זה בזה המקום לפי שהאנשים כאשר תרבה להם תאות המשגל יקחו להם מבנות הגוים לשכב עמם ויהיה זה סבה אל שיפותו לעבוד ע"ז כמו שאמר כי יסיר את בנך מאחרי ועד כי כבר ימשך מזה הפועל המגונה שיפותו לעשות תמונות יזבחו לפניהם או יקטרו לפניהם ויחשבו שיהיו בפועל הזה נעזרים בהשגת בעילת האשה אשר יחשקו בה כמו שהתפרסם משגעונות האומות הקדומות בזה הענין:
@57 **וגר.** הוא גר צדק שהוא גר בן ברית וכבר נלמד זה מהדברים הנלוים לו והם האלמנה והיתום והעני מישראל והנה הזהיר על אלו מפני שנפשם שפלה ואין להם כח והקדים דין הגר כי לא יחסר לו רק עזר המשפחה ואחר כך הזכיר האלמנה והיתום כי לא יחסר להם רק סדר ההנהגה והמשא והמתן כי אין להם מי שישא ויתן בעסקיהם כראוי ואח"כ העני והוא היותר שפל רוח מכלם:
@57 **לא תונה.** דבר ידוע הוא כי יש אונאה בדברים אונאה בממון ואולם האונאה אשר בממון אמרו וכי תמכרו ממכר וגו'. אל תונו איש את אחיו אשר ואולם האונאה אשר בדברים כאמרו והאכלתי את מוניך את בשרם והנה זאת ההונאה פירשו במכילת' אונאת דברים:
@57 **לא תלחצנו.** דבר ידוע שאין זאת האזהר' שלא נלחץ גופו ודחקהו מענין ותלחץ רגל בלעם כי כבר הקדימה התורה נזקי הגוף בזאת הפרשה ונעתקה אל נזקי הממון בהדרגה כמו שנבאר לסוף זאת הפרשה ולזה יהיה אמרו לא תחלצנו בממון כי כבר יפול שם הלחץ בממון ולפי שסמכו לאונאה הנה יהיה זה הלחץ אונאת ממון והנה הקדימה התורה אונאת דברים כי היא יותר קשה וכבר יורה שזה הלחץ הוא ממון כי כבר אמר אחר זה בענין הממון וגר לא תלחץ. ר"ל שלא תטה משפט כמו שיתבאר אחר זה וכבר אמרה זה התורה בביאור אמרה לא תטה משפט גר יתום ואלמנה:
@58 **לא תענון.** ר"ל שלא יכעיסם ויקניטם ולא יכאב לבם בדברים או יאבד ממונם כי זה הענוי הוא אשר ראוי שתזהיר התורה בזה המקום בענין האלמנות והיתומים כי רוב האנשים יקלו בהם לחלשתם:
@59 **כי אם צעוק יצעק.** הרצון בו הנה אם צעוק יצעק וכבר ימצאו בלשוננו רבים בזה האופן ר"ל שבאה מלת כי תמורת הנה לא תהיה לו כנושה לנוגשו בכח ולהצר לו בגביית חובו:
@61 **נשך.** הוא ריבית כמו שהמלוה ד' דינרין בה' והנה נקרא זה הענין נשך לפי שדרך המלוים כסף ברבית לקחת כסף וריבית לפי הזמן כאלו תאמר שידעו כמה יתנו בכל חדש והרי הכסף ההוא הוא כמו נושך ואוכל תמיד. ואולם בהלואת האוכל לא יפול שם נשך כי אין מנהגו זה המנהג ויהיה מענינו מבואר:
@68 **לא תשא שמע שוא.** וזאת האזהרה היא לדיין ויורה על זה האזהרות הנלוות לזה. ועוד כי אם ישמע איש אחר שמע שוא לא יזיק אבל האזהרה היא לדיין שלא ישמע דברי אחד מבעלי דין שלא בפני בעל דין אחר כדי שלא יקח בדמיונו מה שהוא שקר כי זה יהיה סבה אל שלא יוכל להאמין הפך הדברים ההם ויצא מפני זה המשפט מעוקל והנה קראה התורה זה הענין שמע שוא כי ברוב יהיו כמו אלו הדברים דברי שוא ולולי זה לא היה מקדים להקדים דבריו לדיין:
@68 **אל תשת ידך עם רשע להיות עד חמס.** ר"ל שלא ישית הדיין ידו עם רשע להיות עד מי שהוא איש חמס והנה חמס הוא שם תחת שם התואר. והו' מבואר שאין הרצון בזה שלא ישית ידו עם רשע באופן שיהיה עד חמס כי לא היה צריך לומר עם רשע כי אע"פ שלא היה רשע לא היה ראוי שישית ידו עמו להיות עד חמס ואולם הכונה בזה שלא ישית ידו עם רשע באופן שיהיה עד מי שהוא איש חמס והנה הרשע הוא מי שעבר עברה שיש בה מלקיות שנאמר והיה אם כן הכות הרשע וכן יקרא הרשע מי שעבר עבירה שיש בה מיתת ב"ד ואיש חמס הוא הלוקח ממון חבירו במס כמו הגזלנין והחמסנין וגנבים והמלוים ברבית וכן עד זומם הוא גם כן איש חמס ופסול לעדות. וראוי שתדע שהמחוייב מלקות כיון שלקה הוסר שם הרשע ממנו ויהיה כשר לעדות שנאמר ונקלה אחיך לעיניך כיון שלקה הרי הוא כאחיך ואולם מי שהוא איש חמס הוא פסול לעדות ואע"פ ששלם הממון שנקרא בעבורו איש חמס יהיה פסול לעדות כי לא הוסר שם איש החמס ממנו מפני מה ששלם מן הממון כי הכונתו הוא לעשות חמס כשיוכל אלא אם נתברר מענינו שעשה תשובה:
@69 **לא תהיה אחרי רבים לרעות.** ר"ל שבענין הרעות הגדולות כמו דיני נפשות אין ראוי להיות אחרי רבים המשל שאם היו המחייבין יותר מן המזכין אחר אין ראוי שנחייבהו מיתה על פיהם ומזה יתבאר שאם עברו זה הגבול רוצה לומר שיהיו המחייבין יותר מן המזכין יותר מאחד הנה יטו אחריהם כי התורה תדבר בזה האופן כמו שהתבאר בשרשים הכוללים והנה יתבאר כי אמרו לרעות הוא בדיני נפשות לבד כי בדיני ממונות יהיו הרעות לזה טובות לה וזה מבואר בנפשו:
@69 **ולא תענה על ריב לנטות.** ר"ל שלא יענה הדין על ריב כשישאלוהו מה דעתו בו לנטות אחד אחד משאר הדיינין ששמע דבריהם ויעלים מה שהיה דעותו בזדה הענין עד שיהיה מענהו בזה לנטות אחד אחד מי שקדמה לא להודיע מה שיראה בעיניו מזה הדין כי כשיעשה זה בזה התאר לא ילקח תועלת בדבר הדיינין. והנה לזאת הסבה לא היו מתחילין מהגדול שבסנהדרין בענין דיני נפשות שמא יטו האחרים לדבריו ולא יהיה בכאן זולת האחד מהסנהדרין:
@69 **אחרי רבים להטות.** הוא בהכרח בנושא זולת הנושא אשר אמר בו לא תהיה אחרי רבים לרעות והוא אם לזכות בדיני נפשות שהולכים בהם אחר הרוב אם לחובה אם לזכות בדיני ממונות:
@70 **ודל לא תהדר בריבו.** לזכותו בדיני ממונו למפני דלותו אע"פ שהיה כנגדו עשיר והיה ראוי לתת לו כמו זה הסך בתורת צדקה אבל ראוי שישפוט דין אמת לאמתו:
@71 **כי תפגע שור אויבך.** ר"ל שור ישראל בעל עברות כמו שביארו במכילתא כי אין ראוי לשנוא ישראל כשר שנאמר לא תשנא את אחיך בלבבך והנה יבארה התורה אע"פ שזה השור והחמור התועה בדרך הוא מאיש בעל עבירות כיון שהוא מחזיק בתורת משה ראוי להשיב לו אבידתו וכבר יוכיח העניין בעצמו אם אלו הב"ה הם תועים אם לא והנה ביאור דברי האבדה יהיו בכללן בפרשת כי תצא:
@72 **כי תראה חמור שונאך רובץ.** ר"ל ישראל בעל עברות שראוי לשנאתו ועם כל זה צותה התורה שאם ראית אותו רובץ תחת משאו והדלת מעזוב לו העלם הראוי שיעלימו בעניניו להניחם אובדים בעבור רוע מעשיו עזוב תעזוב עמו זה העניין עזרהו לפרק המשא מעל החמור באופן שלא ישאר רובץ ואפשר שיהיה הרצון בעזיבה עזיב' המשוא ר"ל שיוריד המשוא מעל החמור באופן שיוכל החמור לקום. והוא מבואר שאם היה שם בעל הבהמה הנה הוא קודם לכל אדם לתקן ענייניו כי לא צותה התור' זה אלא שלא נמנע מפני השנאה מלעזור לו כדי של ישאר חמורו רובץ שם ואם לא רצה בעל הבהמה לפרק אותה הנה לא יתחייב מוצאה לפרוק אותה וזה מעניינו מבוא' כי לחמלה עליו היה זה הצויי והוא ירצה באבדת הבהמה וכן הוא מבואר שאם לא היה מדרך מוצאו שיפרק הבהמה אם היתה שלו כמו שהיה זקן ואינו לפי כבודו או כהן והו' בבית הקברו' הנה הוא פטור מלפרוק כי לא החמירה התורה יותר על ממון חברו מממונו אבל הכונה בזה שיאהב ממון חברו במדרגת אהבתו ממונו והנה פירושו למדנו מעניין הנלוה שאמ' בו כי תפגע מכאן אמרו שזאת הראיה היא ראיה שהיא בפגיעה ושערו חכמים שהוא אחת משבעה ומחצה במיל שהוא אלפים אמה ואם היה רחוק ממנו יותר מזה השעור אינו מצוה ללכת אצלו ולפרוק בהמתו והוא מבואר שאם ראה שונאו שהוא רובץ תחת משאו שהוא מחוייב לפרק המשא מעליו והדברים ק"ו לא תטה משפט אביונך בריבו פירשו בו שהוא אזהרה לדיין שלא יטה משפט מי שהוא אביון מהשלמיות הטובות' והוא האיש החוטא שהוא אביון מן המצות שלא יאמר אדם כיון שזה הוא חוטא אין ראוי לעיין בדינו ולענוש שכנגדו אבל צותה התורה לדון לו דין אמת היה צדיק או רשע ולזאת הסבה הפסיקה התורה בעניין מצות הדיינין במצות השבת אבדה לחוטא ובמצות פריקת משאת בהמה החוטא מדבר שקר תרחק והאזהרה לדיין שיתרחק משמוע דבר שקר על האופן שהתבאר במה שאמר לא תשא שמע שוא ואפשר שאמר זה שאע"פ שיעידו עדים כנגד החוטא והדיין היה יודע שעדותם שקר והנה אין לדיין לומר כיון שהוא חוטא והעידו העדים כנגדו הנה אדון משפט אמת לפי מאמ' העדים ואענישנו אבל ראוי שיתרחק מז ונקי וצדיק אל תהרוג כי לא אצדיק רשע ראוי שתדע כי נקי הו מי שהו' נקי בעצמותו וצוה שלא להרגו אע"פ שנגמר דינו להריגה ומזה המקום נתבאר שאם מצאו לו זכות אפי' אחר שנגמר דינו מחזירין אותו כדי שלא יהרגו נקי ושכל מי שירצה להגיד לו זכו' מחזירין הדיינין לשמעו וצדיק הוא מי שהצדיקוהו ויצא צדיק בדין והנה אם ראו אחר זה חובה אין מחזירין דינן כי כל משפטי הדיינים מיי' כמו שאמר שלמת פלגי מים לב מלך ביד יי' אל כל אשר יחפוץ יטנו והנה לא הסכים השם ית' שיזכוהו הדיינים אם לא היה צדיק ולזה אמר כי לא אצדיק רשע ר"ל שלא אסכים שיצא צדיק בדין אם היה רשע. וראוי שתדע שהדין שאמרנו שאין מחזירין אותו לחובה הוא כשהיה ראוי שיקרא דין וזה אמנם יהיה כשלא טעו הדיינין בדבר שפשטי התורה מורים הפך דינם אבל אם טעו כו זה הטעות לא נכנס דינם בגדר הדין כלל ומחזירי' אותו אפי' לחובה:
@75 **ושחד לא תקח.** אפילו לדין דין אמת לאמתו:
@75 **כי השוחד יעור עיני חכמים.** וימנע מהם מראיית האמת כדין ההוא:
@75 **ויסלף דברי צדיקים.** אשר לא יסכימו לעשות עול בשום פנים לפי שדעתם קרובה למי שקבל שוחד ממנו ולא יוכלו לראו' לו חובה בשום פנים והוא מבואר שאם היה הדיין בעל מלאכה וקח מהבעלי דינים כשיעור מה שבטל ממלאכתו הנה אין זה נקרא שוחד. אבל הוא תשלומי מה שהפסיד בעבורם. וראוי כשהיה הענין כזה התירה שיקח הדיין שכר בטול מלאכתו משני הבעלי דין בשוה כדי שלא יהיה דעתו קרובה לאחד מהם יותר מהאחר. וראוי שתדע כי הדיין שלקח שוחד דינו בטל כי התורה העידה שהשוחד יעור עינו ויסלף דבריו ומזה. המקום יתבאר שהדיין שקרובה דעתו מאד מבעלי דינין אין ראוי שיראה להם:
@76 **וגר לא תלחץ.** אחשוב בזה אזהרה לדיין שלא ילחץ הגר בדינו כשיעלים עינו מלעיין כראוי בדינו מפני היות דעתו יותר קרובה אל העברי אשר יריב עמו ולזה נמשכה האזהרה הזאת לאזהרת לקיחת שוחד וזה כי עוו' הדין כבר יהיה לשתי סבו' אם מפני היות דעת הדיין קרובה לאחד מבעלי דינין אם מפני היו' דעת הדיין רחוקה מאחד מהם ולזה אמרו רבותינו שאין ראוי לאד' לדון לא לאוהבו ולא לשונאו ואמרה התור' שהו' ראוי שנחמול עליו לפי שנפשו שפלה ויכאב לבו מאד אם נלחצהו בזה האופן וכבר ידענו נפש הגר ושפלותו כי גרים היינו בארץ מצרים:
@77 **ושש שנים.** תוכל לזרוע את ארצך ולאסוף את תבואתה לעצמך ואולם השנה השביעית תשמטנה ר"ל שתסיר ידך וממשלתך מתבואתה וזה יהיה כשתפקיד מפירותיה לכל ישראל:
@78 **ונטשתה.** ר"ל שתעזוב התבואה ההיא ולא תשמרנה ותעכבה לעצמך כטעם אל מי נטשתה מעט הצאן. ויהיה זה סבה אל שיוכלו אביוני עמך לאכול מתבואתה ויתרם תשאר לחית השדה לאכלה ולמדנו מזה שלא הותר לאכול מתבואתה אלא בעת שנשאר ממונה בחוץ לחית השדה:
@78 **כן תעשה לכרמך ולזתיך.** ומה שידמה להם ר"ל שתפקיר פירותיהם בשה השביעי' ותעזבם בזולת שמירה. וראוי שתדע שמצוה זו אינה נוהגת אלא בארץ ישראל כמו שיתבאר בפרשת בהר סיני ומעת שנתחלקה הארץ וידע כל אחד מהם אי זה הוא ארצו או התחילו למנות שנאמר שש שנים תזרע את ארצך מן העת שהיא ארצך. וראוי שתדע שלא צותה התורה שלא יקחו הבעלים מתבואת ארצם אבל מותר להם לקחת ממנה כמו שנתבאר בפרשת בהר סיני אבל צותה שלא יקחה בכללות כאלו לא הקפידה כי כונת התורה שיוכלו לאכול ממנה העניים ולזאת הסבה לא התירה התורה פירות שביעית אלא בעת שנשאר ממינם בחוץ לחית השדה כי זה יהיה סבה שלא יעכב האדם הרבה מאותם הפירות לעצמו כי לא יועילו לו אחר שלא ישא ממינם בשדות ובכרמים ובאילנות לזאת הסבה בעינה נמנעה הסחורה בהם כמו שנאמר והיתה שבת הארץ לכם לאכלה שאם היתה הסחורה מותרת מהם הנה ילקוט האדם מאלו הפירות הרבה וילך למכרם לשאר האנשים בדרך שתשלם אכילתם קודם העת שלא ישאר ממינם בחוץ:
@79 **ששת ימים.** תוכל לעשות מעשיך וביום השביעי תחוייב לשבות מכל מלאכה באופן שלא יעשה לך הב"ח אשר הם ברשותך כמו שהתבאר בפרשת וישמע יתרו ויהיה זה סבה אל שינוח שורך וחמורך והעבד הכנעני הקטן שאינו עדין בגדר המצות והגר אשר בשער כשהיה שכירך כמו שביאר בפרשת וישמע יתרו. והנה סמך ענין השבת לענין השביעית להורות ששניהם משותפים בכונה אחת והמשל כי כמו שהותר לנו לעשות מלאכה בששת הימים ומנעה אותנו התורה מזה ביום השבת כן התירה לנו ענין עבודת האדמה בששת השנים ומנעה אותנו התורה מזה בשנה השביעית ואולם לא נמנעה במוחלט המלאכה בשנה השביעית כי אי אפשר שיהיה האד' בטל מכל מלאכה שנה אחת עם מה שיקרה בזה מההפסד כי הבטלה מביאה לידי זמה ולידי שעמום הלב ולא יתכן שישלם לאדם מה שיצרך לו בשנה אחת בזולת עשיית מלאכה בשנה ההיא והוא מבואר כי כל התועלות שמנינו בענין השבת תמצאנה בענין השביעית זולת מה שאמרנו כי יוחד היום ההוא לעבודת השם יתעלה מפני היותו תחת ממשלת כוכבים רעים כי זה לא יתכן שיהיה זה בשביעית וזה כי אע"פ שכבר יהיו השנים תחת ממשלת כוכב כוכב כמו הענין בימים הנה לשנת היובל יפסד זה הסדור. והמשל כי לשנת נ"ו שנה תשוב הממשלה לשבתאי ולא תהיה השביעית כי אם לשנת הנזכ' והנה תמצא בענין השמטה תועלת נוספת על תועלות מצות השבת והוא ההטבה לעניים:
@80 **ובכל אשר אמרתי אליכם תשמרו.** ירצה לפי מה שאחשוב ובעבור כל אשר אמרתי אליכם תשמרו ירצה לפי מה שאחשוב ובעבור כל אשר אמרתי אליכם להטיב אתכם לתת לכם את הארץ אשר נשבעתי לאבותיכם לשמרו שמירה נפלאה ולא תזכירו שם אלהים אחרים להשבע בהם כי זה יביא להאמין בהם ולא ישמע שם אלהים אחרים על פיך להביא האנשים לעבוד ע"ז כי זה כלו יהיה סבה אל שתעדר מכם הטובה אשר יעדתיה לכם. הלא תראה כי כאשר נשקעו ישראל בע"ז גלו מהארץ. וראוי שתדע שלא מנעה התורה זכירת שם ע"ז סתם כי כבר זכרה התורה וזכרו הנביאים קצת שמות ע"ז ולזאת הסכימו רז"ל שזאת האזהרה היא שלא לישבע בשם ע"ז והנה היא באופן מה תחת לא תשא כי התורה צותה שנשבע בשמו יתע' כשיביא ההכרה אל זה אמר ובשמו תשבע ואמר שבועת יי' תהיה בין שניהם. ולזה צוה גם כן שלא לישבע בשם ע"ז ואמרו ולא ישמע על פיך הוא תחת לא יהיה לך והוא אזהרה למסית ואפשר שיהיה הרצון באמרו ובכל אשר אמרתי אליכם תשמרו כי בכל אלו המצות שצויתי אתכם תהיו נשמרים כי הם כלם לתקון הקבוץ המדיני ולהסרת הנזקין מבין בני אדם או ירצה בזה שבכלל המצות שצויתי לכם תהיו נשמרים ותדבק השגחתי בכם כי הם כלם מכוונות להגעת השלמות הנפשי אשר הוא סבה דבקות ההשגחה האלהית באדם או ישוב זה לענין מצות השבת ויהיה הרצון בו וביום השביעית תשבות למען ינוח וגומ'. למען שתשמרו ותהיו מושגחים בכל אשר אמרתי אליכם כי מצות השבת תישירכם להשיג כי בכאן אלוה פועל בכל הנמצאות וזאת ההשגחה תהיה סבה אל שתדבק בכם ההשגחה האלהית והנה הביאור הראשון שעשינו בזה הוא היותר נאות לפי מה שאחשוב:
@81 **שלש רגלים תחוג לי בשנה.** נתבאר מצד הוראת הגדר כי זאת החגיגה הוא שיקריבו שלמים והם הנקראים שלמי חגיגה ואלו השלש רגלים ובאר אותם אחר זה והם חג המצות וחג השבועות וחג הסכות:
@82 **את חג המצות תשמור.** להקריב שלמי חגיגה שבעה ימים אשר תאכל מצות כאשר צויתיך למועד חדש האביב והוא סבוב תקופת ניסן כי אז התבואה באביה בארץ ישראל ולא יראו פני ריקם אבל תחוייב להקריב לי בבואך לראות פני עולה והיא נקראת עולה ראיה והנה הגיד לך הכתוב כי דין החגיגה והראיה אחד וכמו שהראיה יחוייב עליה בכניסתו כן הענין בחגיגה אם כן למה נאמר שבעת ימים להגיד שיש לחגיגת חג המצות תשלומין כל שבעה והנה אין לחגיגה ולראיה שיעור מן התורה אבל איש כמתנת ידו כמו שנתבאר בפרשת ראה אנכי. ואולם מדברי חכמים יהיה שעור הראיה מעת כסף לכל הפחות ושיעור החגיגה שתי כסף לפי שקצתם ליי' וקצתם לבעלים וחג הקציר הוא חג השבועות כי אז קציר חטים בארץ ישראל ועליה אמר הקציר סתם ואולם בחג המצות יהיה קציר שעורים ולזה קרב אז העומר משעורים להתיר החדש להדיוט והלא נקרא חג השבועות יום הבכורים כי אז יקריבו שתי הלחם שהם בכורי' כמו שנזכ' בפרשת אמור אל הכהנים ויותר אז החדש להקדש ואז גם כן יביאו הבכורים בירושלים על האופן שיתבאר בפרשת והיה כי תבא ולזה אמר בכללות שהוא זמן הבאת בכורי מעשיך אשר תזרע בשדה ולא אמר שהוא זמן הבאת בכורי החטים וחג האסיף בצאת השנה והוא חג הסוכות כי אז תשלם אסיפת הגורן והיקב ושאר הפירות אשר בשדה והנה למדו רז"ל שחג השבועות יש לחגיגתו תשלומין כל שבעה מחג המצות ולמדו שחג הסוכות יש לו תשלומין עד צאת י"ט האחרון שבו מחג המצו' והנה יספיק בזה כמו זה ההיקש לפי שאין בהקרבת שלמי חגיגה שלא בחיוב שום עיון:
@84 **שלש פעמים בשנה יראה כל זכורך את פני האדון יי'.** וזאת הראיה היא עם קרבן עולה כמו שאמר ולא יראו פני ריקם ואלו השלש פעמים הם בחג המצו' ובחג השבועות ובחג הסוכות. והנה התועלת בזאת הראייה היא לראות ענין בית המקדש שהוא מורה על מציאות השם יתע' ועל הגדולו' שבסודות הנמצאות כמו שנבאר במה שיבא בג"ה ולזאת הסבה באה המצוה להקריב לשם יתע' קרבן בעת הראייה ולזה ג"כ באה מצו' החגיגה אז להורות על שהוא ראוי שישמח האדם ויהיה חוגג בזכותו לעבוד האל ולהשיגו כפי כוחו כי זה הוא תכלית השלמות ותכלית השמחה כמו שהתבאר במקומותיו. וראוי שתדע כי לא יתחייבו באלו שתי המצו' כי אם הזכרים לא הנקבות והטומטום והאנדרוגינוס שנאמר כל זכורך וכבר יתחייבו עליהם בעת הראייה ביום הראשון של מועדים ויש להם תשלומי על האופן שביארנו בענין החגיגה והנה עכ"פ אם לא הביא עולת ראיה ביום הראשון עובר על לא תעשה שנאמר ולא יראו פני ריקם. והנה דין העבד ודין האשה הוא אחד בזה כמו שישתנה דינם בשאר מצות עשה שיש בהם זמן קבוע ועוד שכבר נאמר בפרשת הקהל בבוא כל ישראל לראות את פני יי' אלהיך למדנו משם שלא יחוייב בראייה כי אם ישראל לא עבד כי אינו ישראל גמור והנה החרש והשוטה והקטן אינם בני מצות כי אינם בני עדת ולה אינם מחוייבים בחגיגה וראיה והנה הסומא פטור מן הראייה שנאמר לראות את פני יי' אלהיך ולזה הענין מורה על הראות כל אחד מהם לאחד והנה ראות השם יתע' אותנו הוא ראייה שלמה בזולת חסרון ולזה יהיה הסומא באחד מעיניו פטור מן הראייה והנה אמר הכתוב לראות שהוא מבנין נפעל לראות להורות כי בראותנו אותו יראה אותנו וישגיח בנו ובכלל הנה הוא מבואר כי לא הוכרחנו בעצמות ללכת לבית המקדש כדי שיראה יי' אותנו כי עיניו משוטטות בכל הארץ ולזה יהיה עלותינו שם כדי שנראהו לפי מה שאפשר לנו וזה יהיה סבה אל שיראה אותנו וראוי שתדע כי מי שאינו יכול לעלות ברגליו המו הזקן והחולה ומה שידמה להם הוא פטור מן הראייה שנאמר בעלותך לראו' את פני יי' אלהיך והעליה שעולה האדם לפי הנהוג הוא ברגליו והנה הטמא והערל פטורין מן הראיה כי אינן רשאין להכנס למקדש ואולם הטמא הוא מבואר בתורה והערל השוהו לבן נכר שנאמר כל בן נכר ערל לב וערל בשר וראוי שתדע כי החרש שאינו שומע אע"פ שהו' מדבר או האלם שהוא שומע פטורין מן הראייה כי התועלת המכוון כראייה לא ישלם כי אם למי שישמע וידבר כי אז יתכן לו שישאל לחכמים אשר אצלו על מה הורה כל ענין וענין מבית המקדש וכבר יתבאר זה ממה שנאמר בפרשת הקהל לראות את פני יי' אלהיך וגומ'. ואמר שם בענין הקהל למען ישמעו ולמען ילמדו שכל הבאים לראות ראוי' לשמוע וללמד והלמידה השלימה לא תהיה כי אם למי שהוא מדבר כדי שישאל מה שהוא מסופק בו:
@85 **לא תזבח על חמץ דם זבחי.** ר"ל דם הפסח ולפי ששחיטת הפסח הוא אחר חצות הנה יחוייב שיהיה החמץ מבוער מבתינו קודם זמן שחיטתו והו' בחצי היום וזאת אזהרה לבני חבורה שלא יהיה חמץ ברשותם בעל שישח' הפסח לפי שהם זובחי' אותו אע"פ שאיש אחר יזבח בעבור' והו' ג"כ אזהרה שלא ישחטהו אדם ויש ברשותו חמץ כי הוא זובח אותו אע"פ שהו' זובח אותו לזולתו ואחד זביח' ואחד שאר עבודו' בו ולזה יהיה עובר בלא תעש' מי שזר' דמו או הקטיר אמוריו ויש ברשותו חמץ ואולם זכרה התורה הזביחה כי היא העבודה היותר קלה עד שהיא תהיה כשרה בזרים כמו שיתבאר בענין הקרבנות:
@85 **ולא ילין חלב חגי עד בקר.** אחשוב שיהיה הרמז במה שאמר חגי אל השלמים הבאים עם הפסח וכן במה שאמר בפרשת כי תשא ולא ילין לבקר זבח חג הפסח ר"ל אמורי זבח חגיגת הפסח וביאר בו שהוא יפסל בלינה וכל שכן בשאר הקרבנות וזה כי השלמים מותרי' באכילה עד היום הג' כמו שיתבאר בענין הקרבנות' והיה לחושב שיחשוב שיהיו מותרין למזבח גם כן עד היום השלישי ולזה הוצרך לבאר שהו נפסל בלינה ואולם באמורי הפסח בעצמו לא היה צריך לבאר זה כי בשר הפסח אינו מותר לאכול כי אם עד הבקר לפי משפטי התורה ומזה המקום נלמד שכל הקרב למזבח הוא נפסל בלינה ויעברו על הלנתו בלא תעשה:
@86 **ראשית** בכורי אדמתך תחוייב להביא בבית יי' אלהיך על האופן שיתבאר בפרשת כי תבא ושם יתבאר שלא יחוייב להביא בכורי' אלא מארץ ישראל ומשבעת המינין המיוחדים בתורה לארץ ישראל שנאמר ארץ חטה ושעורה וגפן ותאנה ורמון ארץ זית שמן ודבש וזה הדבש הוא דבש תמרים ויתחייב להביא מנבחר מהם שנאמר ראשית ושם ראשית יאמר על הקודם במעלה אמר קדש ישראל ליי' ראשית תבואתו והנה יתבאר שאם לא היו הפירות והקרקע שגדלו בו שלו אינו מביא שנאמר בכורי אדמתך והנה הבעלים חייבי' באחריותם עד שיהיו הפירות בבית המקדש שנא' תביא בית יי' אלהיך ואולם זמן הבאת הבכורים הוא בחג השבועות כמו שהתבאר במה שקדם לא קודם זה ואמנם שא דיני הבכורים יתבארו בג"ה בפרשת והיה כי תבא:
@86 **לא תבשל גדי בחלב אמו.** הוא הדין לשאר בהמות וחיות טהורות שיש להם חלב אם. ואולם העוף אין לו חלב אם ואין בבשולו בחלב אסור. וראוי שתדע כי אכילתו פסולה מן התורה ר"ל אכילת בשר בחלב וזה כי התורה מנעה בבישולו שהוא לתכלית האכילה וכל שכן שמנעה אכילתו ולזה תכלול האזהרות מהבשול שתי אזהרו' אזהרת הבשול והאזהרה מאכילה כמו שכללה האזהרה מלגלות ערות בת הבת שתי אזהרות והם ערות בת הבת וערות הבת. והנה יתבאר לך שהתורה מנעה אכילת בשר בחלב כי היא זכרה זאת האזהרה בפרשת ראה אנכי ואחר אזהרתה מאכילת הנבלה ושאר המאכלות האסורות להורות כי לא די שהזהירה מאכילת בשר בחלב אבל הזהירה גם כן מהבשול. וראוי שתדע שהמבשל בשר בהמה טהורה בחלב בהמה טמאה אינו לוקה שנאמר בחלב אמו שהיא טהורה ואין צריך לומר אם בשל בשר בהמה טמאה בחלב בהמה טהורה שאינו לוקה וכל מה שאינו חייב על בשולו אינו לוקה על אכילתו מפני בשר בחלב כי אנחנו למדנו האכילה מהבשול. ואולם בשר עוף בחלב אסור לאכול מדברי חכמים ואינו חייב על הבשול אם לא בשל לפי הנהוג בחום האש ואולם אם בשל בחמי טבריא ובמה שידמה להם אינו לוקה כי אין דרך בישול בכך וכן אם בשלו בחלב זכר פטור שנאמר בחלב אמו וכן אם בשלו בחלב מתה כי אינה אם אחר שמתה וכן אם בשלו במי חלב כי אין מי חלב חלב והתורה אמרה בחלב אמו והנה את אזהרה נזכרת בתורה בשלשה מקומות בזה המקום ובפרשת כי תשא ובפרשת ראה אנכי וידמה שהיא נזכרה באלה המקומות להודיע הכונה בזאת המצוה מצד הענינים הנלוים לה ולפי שבזה המקום היתה התורה זוכרת המצוה אשר יכונו לעבודת השם יתע' ולהשיגו בפי כחנו כמו חגיגה והראייה וקרבן הפסח והבכורים הנה ידמה שתהיה הכוונה בזאת המצוה אחד משני דברים אם להתקרב לעבודתו יתעלה אם התרחק מלכת בחקות שאר הגוים הרחוקים שעבודתו כי אולי היה מנהג האומות הקדומות לבשל בשר בחלב בבית עבודה זרה בבואם לחוג חגיהם ומנעה אותנו התורה מזה ואם לא מצאנו זה כתוב ממנהגיהם כי רושם נימוסי האומות ההם כבר אבד לאורך הזמן ולמחלוקת התורה עליהם ולזאת הסבה אחשוב שבאה האזהרה הזאת בפרשת כי תשא כי שם יראה שכוון במצות הנזכרות בו להרחיק מעבודה זרה מפני מעש' העגל ואפשר שהיא העירה בזה המקום להתקרב לעבודתו יתע' וזה כי כמו שצוה השם ית' שלא נעשה מלאכה ביום השבת למען נתבונן בענין זאת המצוה ויתבאר לנו שהיא להעיד כי ששת ימים עשה יי' את השמים ואת הארץ וביום השביעי שבת וינפש כן צוה שלא נבשל גדי בחלב אמו להעיד שלא נקח מחכמת השם יתעלה הנראת בנמצאות השופעות ממנו שהוא כלי אל שנשיג אמתת מציאותו הקדמות כוזבות יביאנו לספור בהתחלה הראשונה כמו שעשו קצת הקודמים שבטלו התנועות וההויה מפני קצת הקדמות כוזבות והביאם זה להאמין שתהיינה כל הנמצאות על מה שהם עליו מזולת סבה פועלת. ולזה צוה השם יתע' שנביא ראשית בכורי האדמה בית יי' לישב בנפשותינו שהכל מאתו וצונו שלא נבשל גדי בחלב אמו לישב בנפשותינו שנשמר שלא נשתמש בהשחתת נפשותינו בשפע השופע לנו מהשם יתע' אשר יגדלנו ויקנה לנפשנו מציאותה כמו שיגדל החלב הגדי היונק אותו כי זה ידמה למי שיבשל הגדי וישחיתהו בחלב אמו אשר היה מכוון לזונו ולגדלו או צוה זה להעיד שנזהר שלא תביאנו רוב הטובה שנתן לנו השם יתע' לבעוט בו כאמרו וישמן ישורון ויבעט. וכסף הרבתי לה וזהב עשו לבעל ולזה צוה גם כן שנביא ראשית בכורי האדמה לבית יי' לישב בנפשותינו שכל הטובות הבאות לנו הם מאתו ית' כי זה ירחיקנו מהבעיטה בו בסבת רבוי הטובות ואולם בפרשת ראה אנכי העיר אותנו מצד הנינים הנלוים לזאת האזהרה שם כי בזאת האזהרה תועלת לבריאו' הגוף ולזה המשיך האהרה בה שם אל האזהרה מאכילת הב"ח אשר הם בלתי נותי' לבריאו' גופנו כמו שנבא שם בג"ה ולא יקשה למצוא הסבה בזה למי שעיין בטבעיות ובחכמת הרפואה עיון מעט ובכלל הנה ערוב המזונות מתחלפים במהירות העכול וקשיו לא יאות כי המתעכל ראשונ' יפסיד האחר ואין הנה מקום ביאור אלו הדברים ולא יקשה בעיניך אין תהי' מצה אחת לתועלו' רבות כי אתה תראה מצות השבת שכרה בו התורה שתי תועלו'. ובכלל הנה התורה תדמה לטבע וכמו שיעשה הטבע הפעולה האחת לתועלות רבות כן הענין במה שתצוהו התורה.
@87 **מלאך.** הוא נביא. כי הנביא יקרא מלאך כמו שזכרנו כמה שקדם:
@88 **כי שמי בקרבו.** הנה קרא דברו שמו כי דבר השם יתע' לנביא הוא מה שהגיע לנו מהידיעה בנימוס הנמצאות והשם יתע' הוא נימוס הנמצאות וסדרם וישרם כמו שביארנו כל זה בספר מ"י ולזה יהיה הממרה בנביא ממרה בשם יתע':
@92 **ועבדתם את יי' אלהיכם.** ידוע כי אין זאת העבודה שיצטרך השם יתע' אל שנשרתהו כי הוא אינו צריך לזולתו ואינה מהעבודו' הנעשות לו במקדש כי הכהנים לבד יעשוה וזאת המצוה היא לכל ישראל ולזה הוא מבואר כי זאת העבודה הוא שנבקש ממנו מה שיצטרך לנו כמו שיבקש העבד מאדוניו מה שיצטרך לו ולזה ביארו ז"ל שזאת העבודה היא התפילה:
@101 **הנה** אחר שהודיע השם יתע' למשה אלו המשפטים והמצות והחקים והיה זה ביום שמוע ישראל ישרת הדברים אחר שעמדו העם מרחוק אמר אליו השם יתע' עלה אל יי' אתה ואהרן נדב ואביהוא ושבעים זקני ישראל כל אחד לפי מדרגתו אחר שהגיד לעם כל הדברים ואת כל המשפטים:
@101 **והשתחויתם.** לשם יתע' מרחוק אך משה לבדו יהיה נגש אל יי' והם לא יגשו ואחד מן העם לא יעלה עמו בהר סיני כי משה לבדו יעלה שם לזולתו עמו ויבא משה מן ההר אל העם ויספר לעם את כל דברי יי' אשר קדם זכרם ואת כל המשפטי' ויען כל העם קול אחד ויאמרו כל הדברים אשר דבר יי' לך נעשה כי כבר קבלו עליהם זה במה שאמרו דבר אתה עמנו ונשמעה ואל ידבר עמנו אלהי' פן נמות:
@103 **את כל דברי יי'.** אשר קבלו עליהם ישר'ובבקר בהשכמה השתדל להכניס ישראל בברית עם ה' ית' ולזה בנה מזבח שם תחת ההר והקים שם י"ב מצבות לי"ב שבטי ישראל:
@104 **ויכתב משה.** בספר:
@105 ושלח משה **נערי בני ישראל ויעלו עולות** במזבח **ויזבחו זבחים שלמים ליי' פרי'.** אחשוב כי העולות והשלמים הכל הים פרים וכבשים בעבור שהיו לכלל ישראל כי בדברים הכוללים לישראל כלו יביאו פר כי הוא הגדול שבמינים אשר יקריבו ממנו קרבן ליי' כמו שמצאנו בפר העלם של צבור והם עשו זה בשליחותו של משה כי לא היו שם כהנים עדין:
@106 והנה משה קבל **חצי הדם וישם באגנות וחצי הדם** העולה והשלמים זרק על המזבח לשם יתעלה.
@107 ולקחו **ספר ברית** אשר כתב בו את כל דברי יי' ויקרא באזני העם בעת רצותו לכרו' ברית עמהם לראות אם הם עתה נסכמי' בהסכמה שהסכימו לשמוע קול דברי יי' ויאמר כל אשר דבר יי' לך נעשה ונקבל היו מצות שיש בהם מעשה או מצות שאין בהם מעשה כמו מצות לא תעשה וקצת מצות עשה שאין בה מעשה:
@108 ואז לקח משה חצי הדם ששם באגנות וזרק **על העם** ר"ל שזרקו על קצתם לא על כל אחד מהם כי כמו שבזריקה אשר תהיה על איש אחד מצאנו שלא תצטרך להיו' על כל חלקיו אבל יספיק שתהיה על קצת חלקיו כן הענין בזריקה אשר תהיה על העם כלו ואולי זרק על מקום קבוץ העם והגיע הדם על קצם או זרק אותו על ראשי העם והביאור הראשון נראה לנו יותר ואולם לזרוק על כל אחד ואחד מהעם איננו נכון כי יקשה זה למשה לרבוי' ובזה נשלמה כריתת הברית כי דרך כורתי הברית לחלוק דבר אחד לב' חלקים נאמרו והמה כרתו אותו לשנים ויעברו בין בתריו והנה למדנו מזה שכבר טבלו קוד' זה כי לא מצאנו הזאה בזולת טבילה וזה יתבאר ממה שזכה התורה במצורע וטמא מת ועוד כבר נזכר בזה הענין כבוס בגדים קודם מעמד הר סיני ואין כבוס בגדים בזולת טבילה ומזה המקום למדו רז"ל שהגר כשיתגייר נכנס בברית בג' דברים במילה וטבילה והרצאת קרבן ואולם הטבילה והרצאת הקרבן התבאר ענינם מזה המקום ואמנם המילה לפי שקצת המצות התוריות לא יתכן שנחזיק בהם בזולת המילה כמו מצות קרבן הפסח ומה שידמה להם והנה נמולו ישראל בעת הצטוותם על אכילת הפסח ויצוו שכל ערל לא יאכל בו ולה נכנסו ישראל לברית באלו השלשה דברים:
@109 **ויעל משה ואהרן נדב ואביהוא ושבעים מזקני ישראל.** אל קצת ההר להשתחוות שם מרחוק כמו שצוו באופן שלא יתקרבו אל ראש ההר אשר שם הכבוד כי שם היה נגש משה לבדו.
@110 והתבוננו בענין מציאות השם יתע' והשיגוהו וראו שהוא אדון כל העולם לא אדון המציאות השפל לבדו כמו שיחשבו האומרים כי האלוה המנהיג הדברים ההווים הנפסדים הוא זולת האלוה המנהיג הדברים הנצחיים כמו הגרמים השמימיים והנה ראוהו ש **תחת רגליו הוא כמעשה לבנת הספיר וכעצם השמים לטוהר** והוא הגרם השמימיי ולה הוא אדון השמים עם היותו אדון כל הארץ:
@111 ואל אלו הזקנים שהיו **אצילי בני ישראל לא שלח ידו** השם יתע' להזיק להם מפני עלות השגתם בזה המושג היק שהיה מפורסם אז כי המשיג אותו ימות כמו שאמר מנוח מות נמות כי אלהים ראינו ואמ' יעקב כי ראיתי אלהים פנים אל פנים ותנצל נפשי ואמרה התורה השמע עם קול אלהים מדבר מתוך האש כמונו ויחי אבל התענגו תענוג נפלא במה שהשיגו כאלו היו אוכלים ושותים זהו הביאור הנאות בזה לפי דעתינו וכן הסכימו קצת רבותינו ז"ל כי זאת ההשגה היתה נאותה וצודקת וקצתם גנוה והנה הרב רבינו משה עליו השלום נמשך לסברתם והנה ראית המגנים זאת ההשגה ממה שאמר ואל אצילי בני ישראל לא שלח ידו מכאן שהיו ראוים לשליחות יד והנה הפירוש בזה לפי זה הדעת השני לפי מה שאחשוב הוא שהם טעו וחשבו שיהיה השם יתעלה אחד ממניעי הגרמים השמימיים ולזה אמר ראו שתחת רגליו כמעשה לבנת הספיר כי הגרם השמימיי הוא בזה התואר וכבר מה שיש בזה מהנטייה מהאמת בחמישי מספר מלחמות השם וכבר טעו בזה גדולי הפילוסופים כמו שביארנו שם. ואל אצילי בני ישראל לא שלח השם יתע' ידו להזיק אותם על טעות' ויחזו את האלהים בעת שהיו אוכלים ולא היו מתבודדים התבודדו' שלם מהשגת האמת בזה וכאלו זה סבה אל טעותם:
@112 **ויאמר יי' אל משה עלה אלי ההרה והיה שם.** ואחר אתנה לך את לחות האבן אשר יהיו בהם עשרת הדברים כתובים מכתב אלהים על דרך המופת. והתור' אתן לך והם ספורי התורה אשר יקובל בהם תועלת במדות ובדעות ואתם לך שם כלל המצות אשר הסכמתי לכתוב להורותם הדרך הישרה אשר בה תגיע להם ההצלחה:
@113 **ויקם משה ויהושע.** בן נון משרתו מבין הזקנים ויעל משה אל הר האלהים והוא הר סיני:
@114 **ואל הזקנים אמר שבו לנו בזה עד אשר נשוב אליכם.** להשתדל בהנהגת העם לשפוט ביניהם כראוי והנה אהרן וחור עמהם להודיע אתכם הדברים הקשים מי בעל דברים יגש אליהם לברר דינו והנה חור היה בן מרים אחותו של משה לפי הקבלה ומזה המקום ואילך לא נזכר בתורה וקבלו רבותינו שנהרג במעשה העגל על שהיה מוכיח ישראל:
@115 **ויעל משה אל ההר ויכס הענן את ההר.** להראות לישראל כי השם היה מדבר עמו:
@116 **וישכון כבוד יי' על הר סיני ויכסהו הענן ששת ימים.** ובסוף הששת ימים קרא השם יתע' למשה ביום השביעי מתוך הענן:
@117 **ומראה כבוד יי'.** לעיני בני ישראל כאש אוכלת בראש ההר:
@118 **ויבא משה בתוך הענן ויעל אל ההר ויהי משה בהר מ' יום ומ' לילה.** לחם לא אכל ומים לא שתה כמו שנזכר אחר זה אבל נתענג בהשגתו בהנתן לו התורה ונהנה מזיו שכינה ולא נצטרך למזון וזה כלו נוהג מנהג שאר המופתים אשר נעשו על ידי משה:

@1 **ואלה המשפטים עד מכה איש וגו'.**
@1 **באור הדברים:**
@1 **ואלה** המשפטים אשר תשים לפניהם לשפוט בין אדם לרעהו ע"פ המשפטים האלה. כי תקנה עבד עברי שש שנים יעבוד מיום המכרו ובתחלת השנה השביעית יצא לחפשי חנם בלא שטר שחרור ובלא כסף שיתן העבד לרבו. אם יכנס העבד בבית האדון בגופו לבד שאין לו אשה הנה יצא בגופו לבד שאי' בידו לקח' אשה בעודו בית אדוניו אם לא ירצה האדון כי הוא מחוייב במזונות אשתו ובניו כמו שיתבאר. ואם בעל אשה הוא בהכנסו בית אדוניו. ויצאה אשתו עמו כי היא תכנס ג"כ בבית האדון לחזון וכן העני' בבניו רצוני שהאדון חייב במזונותיהם כמו שאמ' בפרשת בהר סיני ויצא מעמך הוא ובניו עמו. ומזה המקום יתבאר שהאב חייב במזונות בניו הקטנים עד שש שנים לכל הפחות וזה כי ידמה שהאדון חייב במזונות אשת העבד להיות העבד חייב במזונותיה וראוי כשימכר בגנבתו לא תפסיד אשתו מזונותיה אשר נתחייב לה ובהיות העניין כן הנה יתבאר מזה שהוא חייב במזונות בניו ולזה יחוייב האדון לזונם ולפי שזה השעור שימכר העבד הוא שש שנים. הנה נלמד מזה שהאדם חייב במזונות בניו שש שנים לכל הפחות ואולם אחר זה הנה הוא ספק אם הו' חייב אם לא ולא נוכל להכריחו על זה מזה הצד אם לא מצד הצדקה כי מזה הצד נוכל לכופו על זה. אם היה ראוי לעשות כמו זאת הצדקה כמו שיתב' בדיני הצדקה. אם אדוניו יתן לו אשה וילדה לו בנים או הבנות. הנה בצאת העבד מיד אדוניו תשאר האשה וילדיה לאדוניה והו' יצא יחידי מחברתם והנה זאת האשה היא שפחה כנענית שבניה הם שלו ומזה המקו' הוא מבוא' שהאדון כופה עבדו לקחת שפחה כנענית כדי שיוליד לו עבדים. ואם אמור יאמר העבד אהבתי את אדוני ואת אשתי הכנענית ואת בני אשר לי ממנה לא רצה לצאת חפשי להפרד מאדוני ומאשתי ומבני. או ירצה בזה והוא יותר נכון אהבתי את אסוני עם אשתי ועם בני ר"ל שאני ואשתי ובני כלנו אוהבים אותו והיא אשתו העבריה ובניו העבריי ' כי הם בניו והיא אינו אשתו ואין הענין כן בשפחה כנענית והבנים שיש לו ממנה כי הם בניה לא בניו והיא אינה אשתו. והגישו אדוניו לפני ב"ד והגישו אל הדלת או אצל המזוזה באופן שיתכן לרצוע אזנו בדלת ורצע אדוניו את אזנו במרצע בדרך שיתן המרצע באזנו ובדלת. ועבדו לעולם ר"ל לזמן היותר ארוך שיהיה אפש' לעברי להיות עבד והוא עד היובל כי בשנת היובל חויבו לקרא דרור בארץ בדרך שישוב איש אל אחוזתו ואיש אל משפחתו כמו שהתבאר בפרשת בהר סיני ושם התבאר שההבדל יהיה בזה בין עבדים ישראלים ובין עבדים כנעניי' כי עבדים הכנעניים לא יצאו ביובל וזה לאות שהעבדים כלם יצאו מעבדות בבא היובל. וכי ימכור איש את בתו לאמה לא תצא מגדר ישראל להנשא לעבד כנעני בצאת העבדים שיוכלו אדוניהם להשיאם שפחה כענית אבל יעדה לו אדניה וישאנה או ירצה בזה לא תצא בשש שנים בצאת העבדים כי כבר יתכן שתשאר בבית לפי שהוא ראוי שיעדה לו אדוניה וישאנה. ואם היא רעה בעיני אדוניה באופן שלא רצה ליעד' הנה ישתדל שתפדה ר"ל שישיב לו אביה מכסף על פי השנים אש יש לה לעבוד עמו עד שלמות שש שנים כי איננה ישר שתעמוד בביתו לאמה בזולת אישות פן יקרב לגלו' ערותה אבל לא יוכל למכר' לבית אחר מישראל כאשר יבגוד בה שלא ירצה ליעדה לו כדי שיעדה מי שימכרה לו ואם רצה האדון ליעדה לבנו בנה יעשה לה כמשפט הבנות הנשואות לא יפול דבר ממשפטה מפני המכרה לו לאמה ואם אחרת יקח לו זולת האמה לא יגרע מפני זה מחק האמה דבר אבל ינהג בה כמנהג האיש את אשתו ר"ל שיתן לה מזונותיה וכסותה וחקה הראוי לה מהמשגל. ואם שלש אלה לא יעשה לה ר"ל שלא יעדה לו ולא לבנו ולא שישתד' עם קרוביה שיפדוה קודם הגעת השש שנים הנה תצא חנם בלא נתינת כסף וזה אמנם יקרה אם כשתשלים עבודת השש שני כי אז תצא חנם כמו הענין בעבד עברי אם כשתביא סימנים תוך שש שנים ומפני זה האופן השני אמר אין כסף ר"ל כי אע"פ שכבר חורה באמרו והפדה כי בצאתה תוך זמנה תשיב כסף הנה יתכן שתצא קודם זמנה בזולת נתינת כסף וזה אמנם יהיה כשהביאה סימנין וזה יתבא' ממה שאומ'. וזה כי בן ובת הם שמות יפלו על הקטנים כשיאמרו סתם כאמרו אם בן נגח או בת יגח שהוא מורה על קטן וקטנ' כמו שיתבאר בזאת הפרשה ולא תמצא שקרא בראשי המטו' הנערה אשר ולענין הפרת נדריה היא ברשותה אפילו בהיותה נערה כמו שיתבאר שם. ואולם לענין מכירה לא השליטה אותו התורה כי אם בהיותה קטנה ולזה אמר את בתו ובהיות הענין כן הנה הוא מבואר שאין האב רשאי למכור את בתו כי אם בעוד' קטנה ולזה אין ראוי ימשול למכרה כי אם לעת אשר היא ברשותו למכרה. והמשל כי מי שהיו לו פירו' שזה אחד לשתי שנים לא יוכל למכור פירות השדה ליותר משתי שנים וזה מבואר בנפשו ולזה הוא מבואר שכאשר תשוב זאת הקטנה נערה וזה יהיה כשהביאה סימנין אז תצא מרשות האדון. וראוי שתדע שקנין עבד עברי האמור בכאן הוא שמכרוהו בית דין כי כבר ימכרוהו בגנבתו כמו שיתבאר במה שיבא. וכבר התבאר שזה העניין הוא כשלא מכר עצמו מעניין הנמשך לו בדין האמה שהוא כאמה שמכרה זולתה אשר הוא שליט במכירתה ולה יהיה קניין עבד עברי כשמכרוהו זולתו מהשליטים על מכירתו ועוד שכבר נתבאר בפרשת הר סיני במוכר עצמו שאינו יוצא כי אם ביובל לא בשש שנים כמו העניין בזה העבד הנזכר ולזה יחוייב שיהי' זה הרי' במי שמכרוהו זולתו והנה דין זה העבד שיעבוד שש שנים אם לא פגע בהם היובל כי בבא היובל יצאו כל העבדים העבריים חפשי' ואם מת האדון עובד את הבן כי דינו כדין האדון בזה העניי' כמו שביאר' התורה בעניין האמה שבן האדון קם תחתיו ליעדה והנה היה זה כן כי לפי הנהוג תבא הירושה מן האב לבן והוא מה שהוא ראוי אם לא ימנע זה מונע ולפי שמשפטי התורה יהיו בענינים לפי הנהוג הנה לא יעתק ענין עבדו' העבד העברי או האמה העבריה כי אם לבן לא לאח ולא לבת ומזה יתבאר שאם ברח העבד תוך זמנו שהוא חייב להשלים מה שיחסר מן הזמן שנ' שש שני' יעבוד ואמנם אם חלה תוך הזמן לא יחוייב להשלים אם לא היה מה שחסר מן הזמן שלא היה יכול לעבוד בו כלל יותר מחציו ר"ל ארבע שנים כי הוא המספר הראשון מהשנים שיוסיף על חצי השש שנים. וזה שכבר אמרה התורה בענין עבד עברי בפרשת בהר סיני כשכיר כתושב יהיה עמך ר"ל שענינו ממוצע בין השכיר והתושב והנה התושב לא יגרע מחוקו מהאדון דבר מפני חליו והשכיר לא יקח דבר כשיחלה באופן שלא יוכל לעשות דבר מעבודתו. ולזאת הסבה אם חלה שלש שנים אינו חייב לשלם כי היה קצת הזמן כשכיר וקצתו כתושב ואולם אם חלה ארבע שנים באופן שלא יוכל לעבוד כלל הנה הוא חייב לשלם והנה אין האדון רשאי להכריחו לעשות מלאכה שאין מדרכה לעשותה כאלו תאמר שילמדנו מלאכה שלא היה יודע אבל עושה המלאכ' שיהיה דרכו לעשות' שנ' יעבוד ר"ל העבודה אשר מדרכו שיעשה אותה. והנה בבא השנה השביעית מיום המכרו יוצא לחפשי בזולת כסף יקנה עצמו בו מהאדון ובזולת שטר יקנה האדון לו גופו בו שנ' ובשנה השביעית יצא לחפשי הנם והנה יתבאר מזה שקדם השנה השביעית לא יצא העבד חנם אבל יצטרך לכסף או לשטר שחרור וזה מבוא בנפשו לפי השרשים הכוללים והנה כשלא היתה לו אשר בהכנסתו בית האדון אין לו רשות לקחתה להעמיס על האדון מעמס מזונותיה אל אם היה זה מדעת האדון שנ' אם בגפו יבא בגפו יצא והנה אם היתה לו אשה ובנים או בני או אשה האדון חייב במזונותיהם שנ' ויצאה אשתו עמו והוא הדין לבניו וכן תמצ' שביארה התורה זה במוכר עצמו לישראל או לגוי אמ' במוכר עצמו לישר' בפרשת בהר סיני ויצא מעמך הוא ובניו עמו והנה יתבאר שמעש' ידי אשתו ובניו הם לעבד לא לאדון כי לא קנה אותם לו לעבדים בקנותו העבד ואם היתה ארוסה או שומרת יבם הנה אינה אשתו ולא יתחייב האדון במזונותיה וכן אם היתה פסולה לו לפי שאינה ראויה להיות אשתו והתורה אמר' ויצאה אשתו עמו והנה לא יוכל האדון לתת לעבד שפחה כנענית אם לא היו לו אשה ובני' בהכנסו ברשותו שנאמר אהבתי את אדוני את אשתי ואת בני כשם שהיה הוא נמצא בהכנסו כן יהיו אשתו ובניו נמצאים אז ועוד כי בזה האופן יתכן שיאמר שאהבו אותו אשתו ובניו וזה שאם לא היו בניו נולדי' קודם הכנסו שם לא יתברר להם הטבת האדון להם יותר מחוק הנהוג שיאהבוהו והנה אין האדון או בנו מוסר לו כי אם שפחה כנענית אחת שנא' יתן לו אשה ולא שתי נשים ואינו נותן שפחה אחת לשני עבדים שנ' יתן לו ולא לזולתו והנה אינו נרצע העבד עד שיאמר כשהו' עבד אהבתי את אדוני את אשתי ואת בני שנ' ואם אמור יאמר העבד אהבתי את אדוני ואינו נרצע מפני פעם אחת שיאמ זה המאמר שנ' ואם אמור יאמר ר"ל שיהיה רגיל לומר זה המאמר והרגילות הוא בהשנות והמעט שיהיה בהשנות הוא שנים כי הוא הרבוי הראשון ולזה אינו נרצע עד שיאמר זה המאמר וישנה אותו כשהוא עבד ולפי שפחות משוה פרוטה אינו דבר לפי השרשי' התוריים הנה יחוייב שישאר מזמן עבדותו כשיאמר זה שוה פרוטה או יותר וראוי שתדע שכהן אע"פ שלוקח שפחה כנענית אינו נרצע כי ביובל ישוב איש למשפחתו כמו שהתבאר בפרש' בהר סיני ולזה יחוייב שיוכל לשוב בחזק' שהיה בה ואם היה נרצע הנה ישוב בעל מום ויהיה פוסל לעבודה כמו שיתבאר במה שיבא ולא ישוב לחזקה שהיה בה ולפי שאמ' אהבתי את אדני את אשי ואת בני אפשר שיובן שישוב לאשתו הכנענית וילדיה הנה נלמד מזה שאם לא נשא שפחה כנענית והיו לו בנים ממנה אינו נרצע וזה יתבאר באופן אחר והוא כי אחר שאמר האשה וילדיה תהיה לאדוניה והוא יצא בגפו ביאר שכבר אפשר שלא יצא אז והוא אם יאמר אהבתי את אדוני את אשתי וגו' ולזה לא יהיה נרצע כי אם מי שנשא שפחה כנענית והנה יחוייב שיהיה הדלת אשר ירצע בו עומד כדרכו אצל המזוזה לא שתהיה הדלת עקורה שנא' והגישו אל הדלת או אל המזוזה. וזה מורה שהדלת היא סמוכה למזוזה כמשפטה. ולפי שהאלהים הוא לשון רבים הנה הם שנים, ולפי שאם היו שנים לא יהיה בכאן מכריע אם יחלקו בדבר הנה יחויב שיהיו שלשה. והנה הרציעה היא בכלי של מתכת שנא' במרצע של מתכת ואדוניו בעצמו הוא רוצע שנאמר ורצע אדוניו והיא באזנו הימנית כמו שהתבאר בשרשים הכוללים והנה אינו עובד בו כי אם האדון לבד לא לבנו אם מת האדון שנאמר ועבדו וסבת זה כי אהבת האדון הניעתהו להשאר שם ובסוד הדבר יסור הדבר המסובב ממנה והנה אין עבד עברי נוהג כי אם בשעה שהיובל נוהג בו יציאתו תלויה ביובל ומזה יתבאר גם כן שכן הענין באמה העבריה שנאמר כי ימכר לך אחיך העברי או העבריה בשעה שזה נוהג זה נוהג. והנה האיש הוא שמוכר בתו ואין האשה מוכרת בתה ואחיה גם כן אינם מוכרין אותה אלא כשהיא קטנה שנאמר וכי ימכור איש את בתו איש ולא אשה בתו ולא אחותו ואינו מוכר אותו אלא כשהיא קטנה שנ' בתו ואינו מוכר אותה אלא כשהיא ברשותו ואולם אם השיאה ונתארמלה או נתגרשה והרי היא קטנה אינו רשאי למכרה שהרי יצאה מרשותו ולה אמרה התורה ונדר אלמנה וגרושה וגומר יקום עליה כמו שיתבאר בפרשת ראשי המטות ואינו מוכר אותה אלא למי שיש לו לקוחי' בה או לבנו כדי שתהא ראויה ליעוד שנאמ' אשר לא יעדה ואם לבנו יעדנה ולזה אינו מוכר אותה לבנו ואין האדון מיעד אותה לו או לבנו אלא מדעתה שנאמר אשר לא יעדה והנה היא יוצאה קודם שש בגרעון כסף לפי השנים שנאמ' והפדה ומזה יתבאר שאין האמה העברייה נקנית בפרוטה כי לא יתכן לה גרעון כסף והתורה אמרה והפדה. ומזה המקום נלמד שהבעל חייב אל אשתו בשאר כסות ועונה. וראוי שתדע שאין האמה העבריה נרצעת כי לא יתכן הנשאה לעבד ולא יהיו גם כן בניה עבדים ולא אמרה התורה משפט הרציעה כי אם בעבד ולא ינהג זה הדין כי לא נזכר זה הדין כי אם בעבד שמכרוהו ב"ד כי בו נזכר ואולם במוכר עצמו לא ינהג זה הדין כי לא נזכר זה הדין בו בפרשת בהר סיני וראוי היה להיות כן שאם היה המוכר עצמו מותר בשפחה כנענית הנה לפעמים ימכר האדם עצמו לאיש אחד מפני תאותו לשכב עם שפחתו ואולם התועלות המגיעות מזאת הפרשה:
@1 **השרש** הראשון הוא שאינו נמכר בגנבתו ליותר משש שנים עם שהיה רב כמות הגנבה ובזה הקל מה לגנב כמו שיתבאר אצל דין הנמכר בגנבתו וזה עם שהוא מבואר כבר נזכר זה בראשון מקדושין:
@1 **השרש** השני הוא להודיע שאין העבד עובד אלא העבודה שהוא יודע בה לא שיכריחהו האדון ללמוד מלאכה כדי שיעבדהו בה שנאמר שש שנים יעבוד וזה יכלול העבודה אשר מדרכו שיעבוד בה וכשנמכר גם כן היה ערכו לפי המלאכה שהוא יודע בה וכבר אמר גם כן לא תעבוד בו עבודת עבד וכבר נתבאר זה השרש במכילתא ובספרי':
@1 **השרש** השלישי הוא שהעבד יצא לחירות כשעבד שש שנים באופן ממוצע בין השכיר והתושב כי עבודתו הוא כן וזה כי גופו קנוי לו באופן זה עד שכבר יוכל האדון להכריחו להוליד ממנו לו עבדים ובזה הצד הוא כתושב ומצד שיצא לחפשי בשביעית הוא כשכיר הלא תראה כי גם במוכר עצמו שאין רבו כופהו לישא שפחה כנענית אמרה התורה כשכיר כתושב יהיה עמך לפי שהוא יוצא ביובל והוא מבואר שהשכיר יחוייב לשלם אם חלה בזמן שכירותו והתושב לא יחוייב מה ולזה הוא מבואר שאם חלה העבד שלשה שנים ועבד שלש שנים יוצא לחפשי בשביעית כי הוא נקרא עובד באופן מה כיון שהוא מוכן עבוד אם יוכל כמו שנקרא הישן עובד כאמרו מתוקה שנת העובד אבל אם חלה ארבעה שנים ולא עבד כי אם שתי שנים לא יפטר בשעבוד השנה השלישית שהרי השנה הבאה אחריה אינה שביעית לא למכירה ולא לעבודה אם ישלים שני העבודה ויצא בשביעית ולזה יתבאר שאם ברח בקצת ימי הששה שני' יחוייב להשלים ימי הבריחה כי לא יכנס בגדר העובד כבר נתבאר זה השרש בראשו' מקדושין:
@1 **השרש** הרביעי הוא שהעבד העברי יגרע בפדיונו ויוצא וכבר נלמד זה הדין מאמה העבריה זה הדין ג"כ מבואר כי לא נמכר אלא מפני שאין לו שנ' ואם אין לו ונמכר בגנבתו ועוד שנ' ובשביעי' יצא לחפשי חנם למדנו מזה שקודם השביעית לא יצא לחפשי חנם ומזה למדנו שצריך לתן כסף לאדוניו אם יצא קדם השביעי' וכבר נתבאר זה השרש בראשון מקדושין:
@1 **השרש** החמישי הוא שאם מחל הרב על העבודה אין העבד יוצא לחרות אם לא כתב לו גט שחרור שנ' ובשביעית יצא לחפשי חנם לא קודם זה והנה יצא לחפשי בגט שחרור מק"ו מעבד כנעני שיוצא בגט שחרור שנ' או חפשה לא נתן לה למדנו ששפחה כנענית יוצאת לחפשי בגט שחרור וכן קונה האשה עצמה בגט שנאמר וכתב לה ספר בריתות כבר נתבאר זה השרש בראשון מקדושין:
@1 **השרש** הששי שאם מת האדון ולא הניח בן הנה העבד יוצא לחפשי ואינו עובד שאר יורשי האדון וזה כי מה שנהוג מהירושה הוא לבן ולא לשאר הקרובים ולזה הוא מבואר כי כשנמכר נמכר לזה התכלית ועו' שהבן לבדו מצאנו שהו' קם תחת אביו בזה הענין לא שאר קרוביו ולזה אמ' באמה העברייה ואם לבנו יעדנה לא לאחר מאחיו לא לשאר קרוביו ולזה גם כן יתבאר שאין האדון שליט למכור אבדו או לתתו לאחר וכבר נתבאר זה השרש בראשון מקדושין:
@1 **השרש** השביעי הוא שהאדון חייב במזונות אשת העבד וכמו שנ' ויצאה אשתו עמו והוא הדין בניו כמו שביארנו כי גם במוכר עצמו חייבה התורה האדון במזונות בני העבד ומעש' ירידן הוא לעצמם לא לאדון כי לא נקנו לו אשתו ובניו לעבדים ומזה יתבאר שאם אין לעבד אשר כשנמכר ולקחה אחר כן הנה לא יתחייב האדון במזונותיו ומזונות הבנים שיהיו לו ממנה אם לקחה כשנכנס ברשותו וכבר נתבאר זה עוד ממה שאמר אם בגפו יבא בגפו יצא ר"ל אם נכנס בלא אשה יצא בלא אשה אך אם בעל אשה הוא תצא אשתו עמו וכבר נתבאר זה השרש בספרא ובראשון מקדושין:
@1 **השרש** השמיני הוא שאם לא היתה ראויה לו כגון שהיתה אדורה לו מן התורה או מדברי סופרים אין האדון חייב במזונותיה שנאמר ויצאה אשתו עמו מי שראויה להיות עמו כבר נתבאר זה השרש בראשון מקדושין:
@1 **השרש** התשיעי הוא שכבר נלמד מזה המקום שהאב חייב במזונות בניו הקטנים עד שש שנים כמו שביארנו וכבר נזכר זה השרש בחמישי מכתובות:
@1 **השרש** העשירי הוא שהעבד שיש לו שאשה ובני ישלוט לו רבו לתת לו שפחה כנענית כמו שביארנו בביאור דברי זאת הפרשה וכבר נתבאר זה השרש בראשון מקדושין וראוי שתדע שאין האדון יכול להפריש העבד מאשתו הישראלית כי העבד כבר נתחייב בעונתה כמו שנתחייב במזונותיה ואין שעבודה נפקע מפני זאת המכירה והוא מבואר שאינו מותר כי אם בשפחה אחת שנ' אם אדוניו יתן לו אשה לא נשים ואינו נותנה לשני עבדים שהרי לא תהיה לו אבל תהיה לו ולזולתו והתור' אמר' יתן לו אשה ואמרה וילדה לו בנים או בנות:
@1 **השרש** הי"א הוא הטומטום והאנדרוגינוס אינו נמכר לעבד עברי שהרי אינו ראוי לתת לו אשה ואין מינו ראוי להוליד בנים או בנו' כבר נתבאר זה השרש בא' מקדושין:
@1 **השרש** הי"ב הוא שהעבד שנשא שפחה כנענית והגיע שם ששנים כשנשאר מהם זמן יתכן שישאר מי שהוא עבד ר"ל שיש בעבודה הנשארה שוה פרוטה אמר ושנה אהבתי את אדוני אשי ואת בני לא אצא חפשי הרי הוא נרצע ועובד את רבו עד שנת היובל אך אם מת רבו אינו עובד יורשיו שנאמר ועבדו הוא ולא הבן ועוד שהרי בסבת אהבתו אותו אדוניו נרצע וכבר תסור זאת הסבה במות אדוניו וכבר נתבאר זה השרש בראשון מקדושין:
@1 **השרש** הי"ג הוא שאם היה העבד כהן אינו נרצע שנ' ושב אל משפחתו לחזקת ולשררה שהיה בו וכהן הנרצע לא יוכל לשוב לחזקה שהיה בה שהרי נעשה בעל מום ברציעה ופסול לעבודה כבר נתבאר זה בראשון מקדושין ומה יתבאר שאין הגוי נקנה כעבד עברי כי לא ישוב אל משפחתו ביובל לפי שאין לו משפחה כבר נתבאר זה בה' ממציעא:
@1 **השרש** הי"ד הוא שאין עבד עברי נוהג אלא בזמן שהיובל נוהג כי יש ליציאת העבד עברי רושם מה ביובל וזה מבואר במוכר עצמו שהו' עובד עד שנת היובל והעבד שמכרוהו ב"ד אפשר ג"כ בו שיהיה ליציאתו רושם מה ביובל כבר נתבאר זה השרש בשלישי מקדושין:
@1 **השרש** הט"ו הוא כי האדון רוצע ולא בנו ולא שלוחו ואינו רוצה שני עבדים כאחד שנ' אדוניו ולא אחר את אזנו ולא אזנו עם אזן זולתו כבר נתב' זה השרש בירו' ובב' מקדושין:
@1 **השרש** הי"ו הוא שמתנאי הרציעה הוא שיגישהו אדוניו לפני הדיינים כדי שישמעו הדברים ואחר זה ירצעהו במרצע של מתכת בדלת אם היה הדלת עומד ורוצע אזנו עד שיגיע אל הדלת שנ' ונתת באזנו ובדלת כבר נתבאר זה השרש בראשון מקדושין:
@1 **השרש** הא' הוא שאין האדם מוכר את בתו אלא כשהיא קטנה שנ' וכי ימכור איש את בתו לאמה והיא לא תתואר בזה התואר אלא כשהיא קטנה כנאמר על קטן וקטנה או בן יגח או בת יגח כבר נתבאר זה השרש בשלישי מכתובות:
@1 **השרש** הב' הוא שאיש מוכר את בתו ואינו מוכר את בנו ולא האשה מוכרת את בתה כי אינה ראויה בזה הדין כמו האב שנאמר וכי ימכור איש את בתו ולא אמר בתה ולא בנו וכבר נתבאר זה השרש במכילתא:
@1 **השרש** הג' הוא שאין האדם מוכר בתו אלא א"כ מטה ידו ואין לו דבר שיתפרנס ממנו וזה נלמד ממה שסומך דין אמה העבריה למכירת העבד העברי. שאינו נמכר בגנבתו אלא א"כ אין לו דבר לשלם הגנבה שנאמר ואם אין לו ונמכר בגנבתו כבר נתבאר זה השרש בראשון מקדושין.,
@1 **השרש** הד' הוא שאין טומטום ואנדרוגינוס נמכר כמו אמה העבריה כי אינו ראוי להיות לאשה לאדון או לבנו כבר נתבאר זה בראשון מקדושין.
@1 **השרש** החמישי הוא שאמה העבריה יוצאת בשש שנים מיום המכרה כו הענין בעבד עברי שנאמ' בפרשת ראה אכי כי ימכר לך אחיך העברי או העבריה ועבדך שש שנים מקיש עברי לעבריה בענין זה וראוי היה להיות בן וזה כי באמה הקל יותר ממה שהקל בעבד עברי עד שכבר דקדקה התורה שתהיה שם במדרגת אישות ולא במדרגת שפחות ולזה הוא מבואר שאין ראוי שיכביד בה שתהיה עובדת יותר משש שנים וזה גם כן יתבאר מפני הקשת דינה לדין עבד עברי עם שהיא יותר ראויה בזה הדין מן העבד כי היותה עובדת שם שש שנים בזולת יעוד או גרעון כסף הוא מגונה אצל התורה כ"ש שיהיה מגונה היותר עובדת יותר משש שנים וזה גם כן אפשר שנלמוד ממה שנאמר ואם שלש אלה לא יעשה לה ויצאה חנם אין כסף. ר"ל בלא גרעון פדיונה וזה אמנם יהיה בעת שראוי שתצא חנם בזולת כסף והוא בהשלמת ו' שנים. ועדיין היא קטנה כמו העניין בעבד עברי שנאמ' בו לחפשי יצא חנם ואולם אמרנו ועדין היא קטנה כי הוא ראוי שיהיה אמרו יעדה והפדה ויצאה חנם בנושא אחד בעינו והוא הקטנה שנ' ואם שלש אלה לא יעשה לה ויצאה חנם כמו שנתבאר זה השרש בראשון מקדושין:
@1 **השרש** הששי הוא הוא שהאמר העבריה ועבד עברי יוצאים ביובל אם נפגע בהם קודם שש שנים כי הכל שוים ביציאה ביובל כמו שנתבאר בפרש' בהר סיני וכבר נתבאר זה השרש בראשון מקדושין:
@1 **השרש** השביעי הוא שאין האדון שליט למכור אותה או ליתנה לזולתו שנ' לעם נכרי לא ימשול למכרה והוא הדין לנתינ' כי הטעם אחד וכבר נתבאר זה השרש בראשון מקדושין. ומזה השרש נתבאר שאם מת האדון תצא האמה לחפשי ואינה עובדת אפילו לבן וכ"ש שאר הקרובים וראוי היה להיות כן כי הקבוץ ההוא יהיה קבוץ נכרי כשמת האב כי אולי נתרצה אב האמה למכור בתו לזה האיש מפני ידיעתו בטוב תכונותיו ומוסרו ליסר בני ביתו ולשמרם מכל דבר רע כבר נתבאר זה השרש בראשון מקדושין:
@1 **השרש** השמיני הוא שהבת שהביאה סימני נערות או שבגרה יוצאה לחרות לפי שאינה קטנה וכמו שאינה נמכרת אלא כשהיא קטנה כן לא ישלוט האב למכרה ליותר מימי הקטנות כי צריך שיהיה כסף קנינה ראוי לגרעון שנאמר והפדה וזה דבר בלתי אפשר וכבר נתבאר זה השרש בא' מקדושין:
@1 **השרש** העשירי הוא שאין המיעד צריך לתת לו קדושין לאמה אלא יעוד לבד כי הקנין הראשון מתישר לקדושין אם היה שם יעוד כי זה הוא קנין הגוף היותר שלם להיות בה ולזה לא יחסר אלא שיאמר לה בפני עדים כשיעדה שתהיה מאורסה לו בכסף שקבל אביה כשמכרה. ואולם אמרנו בפני עדים כי בזולת זה לא ישלם קשר האישות אשר יענשו עליו מיתה שנ' על פי שנים עדים או שלשה עדים יקום דבר כבר נתבאר זה בא' מקדושין:
@1 **השרש** הי"א הוא שאמה העבריה יוצאה בגרעון כסף שנאמר והפדה והוא מבואר שמצות יעוד קודמת למצות פדיה שנ' אשר לו יעדה והפדה וראוי היה להיות כן כי אולי תחשד זאת הבת מפני שלא רצה האדון ליעדה או מפני השתדלותם לפדות' כי זה יביא אולי לחשוב שנתעללו בה בבית האדון כבר נתבאר זה השרש בא' מקדושין ובא' מכתובות:
@1 **השרש** הי"ב הוא שאין אמה העבריה נמכרת אלא למי שאין לו בה קדושין כי ראוי שיהיה כסף הקניה ראוי לזה כבר נתבאר זה בא' מקדושין:
@1 **השרש** הי"ג הוא שיש לאב למכור בתו לשפחות אר שפחות וזה יתבאר ממה שאמ' אם רעה בעיני אדוניה אשר לו יעדה והפדה וגו' מגיד שאם רעה בעיני אדוניה אין האדון רשאי למכרה ומזה יתבאר שהאב מושל למכרה לעם נכרי כי הו' יותר ראוי שיהיה שליט בה אך אינה מוכרה לשפחות אחר אישות לפי שכיון שקנתה הבעל נקנה גופה לה עולמית וסר קנין גופה מהאב לגמרי אמנם מצד בתו לשפחות לא סר קנין גופה ממנו אם לא היה שם יעוד כבר נתבאר זה השרש בא' מקדושין:
@1 **השרש** הי"ד הוא שאין אמה העבריה ולא עבד עברי יוצאים בשן ועין כעבד כנעני כי אין גופו קנוי. וכבר נתבאר זה השרש בא' מקדושין:
@1 **השרש** הט"ו שאין הבעל רשאי לגרוע מאשתו שארה כסותה ועונתה הראויה לה ממנו וזה שאלו הענינים יתחלף שעורם לחלוף יכלת הבעל אך עכ"פ צריך שיתן לה ההכרחי לאכול וללבוש ואע"פ שהוא עני אך אם היה עשיר יתן לה לפי עשרו וכן העני' בעונ' כי היא תתחלף בהכרח כחלוף עניני האיש אשר נשאת לו והמשל כי הגמל מפני שהוא הולך בדרכי' רחוקים לא יתכן שיתן לאשתו עונתה בכל יום וכ"ש שיהיה רחוק יותר באיש הספן ולזה יהיה הרצון בעונתה הראויה לה ממנו ולזה יחויב שיהיה הרצון באמרו שארה כסותה השאר והכסות הראויה לה ממנו כבר נתבאר זה השרש בחמשי מכתובות:
@12 **מכה איש ומת וגו' עד וכי יפתח איש בור.**
@12 **באור דברי הפרשה:**
@12 **מכה** איש ומת מפני ההכאה ההיא מות יומת ואם לא הזיד להרגו אבל הרג אותו בשגגה כאלו תאמ' שיבא ביער לחטוב עצים ונשל הברזל מן העץ ומצא את רעהו ומת הנה אשים לך מקו' אשר ינוס שמה והם ערי המקלט אשר זכרה התורה במה שאחר זה. וכי יזיד איש על רעהו להרגו בערמה הנה לא ינצל באחת מערי המקלט אבל תקחנו למות אפי' מעם מזבחי שהוא היותר ראוי שיהיה קולט וזה כי ערי הלוי' קולטים. כמו שיתבאר ואם מחנה לויה קולט כ"ש מחנה שכינה והנה למדנו מזה המקום שאין לוקחים למות מעם מזבחי אלא מי שנתחייב מיתת ב"ד לפי המשפט האמתי ולפי שאמר מעם מזבחי ולא אמ' מעל מזבחי למדנו שאינו קולט אלא מה שהוא עמו והוא כהן העובד עבודה שם ולפי שאמר להרגו בערמה למדנו שראוי שיהיה הורג בן דעת שיוכל להערים יצאו חרש שוטה וקטן שאינם מערימים ויצא מי שאינו מערים להרוג כמו הרופא והמיסר. וראוי שתדע שאיזה שיהיה המומת מישראל יתחייב ההורגו מיתה היה איש או אשה או קטן שנאמר ואיש כי יכה כל נפש אדם וראוי שתדע שאיזה שיהיה ההורג שיהיה בן דעת יתחייב מיתה ולא אמר הכתוב איש אלא שדבר בהווה ולזה תתחייב האשה החורגת הטומטום והאנדרוגינוס וזה מבואר בנפשו מענין זאת האזהרה כי התורה צותה לסלק ההיזקי' מבין בני אדם כדי שישלם הקבוץ המדיני ולזה גם כן תמצ' שהתורה בארה בקצת המקומות שהאשה תענש בהזיקה לזולתה אמר וקצותה את כפה וכן ראוי שיתברר לך שדין האשה ודין האיש אחד בשאר העונשין הנוהגים זה המנהג ואולם שאר משפטי ענין הרציחה יתבארו ממקומות אחרי' מהתורה ומכה אביו ומכה אמו הוא חייב מיתה ולפי שלא נתבאר בתורה תאר זאת המיתה נברור לו הקלה שבמיתו' והו' חנק כי אין ראוי שנטול מהעונשין כי אם מהראוי לא יותר ולפי שההכאה מצאנוה נופלת על ההכאה שיש בה מיתה כאמרו ויך את המצרי לכל מכה נפש ועל הכאה שאין בה מיתה נאמר ארבעים יכנו והיא הכאה שאין בה חבורה וכי יכה איש את עין עבדו והיא הכאה שיש בה חבורה והיה בלתי אפשר שתהיה זאת האזהרה בהכאה שיש בה מיתה כי לא יצטרך להזהיר על זה הוא בהכאה שאין בה מיתה ולפי שההכאה שאין בה מיתה תהיה אם הכאה שיש בה חבורה הנה אין ראוי שנטיל זה העונש הנפלא כי אם בהכאה שיש בה חבורה כי זה אולי היתה הכונה בזאת ההכאה ועוד שאנחנו נלמד זה הדבר מענינו רצוני שזה ההכאה היא ממין הכאת ההריגה שהזהיר עליה קודם זה אין הבדל ביניהם אלא שאין זאת ההכאה מיתה ולפי שהכאת ההריגה שיש בה חבורה לפי הנהוג מזה הפועל הנה תהיה בזאת ההכאה חבורה. וראוי שתדע שלא יקרא מכה מה שיעשה ע"ד הרפואה וכן אם הכה אותם אחר מיתה כי המכה היא פעל מכוון להזיק יצטער בו המוכה וגונב איש ומכרו ונמצא זה הנגנב ברשות הגונב הנה ימות הגנב והנה נתבאר בפרשת כי תצא שאחד האיש ואחד האשה או קטן או זולתם ממי שהוא נכלל בתורת ישראל ינהג בו זה הדין אם גנבוהו שנאמר כי ימצא איש גונב נפש מאחיו מבני ישראל כל נפש במשמע. וראוי שתדע שלא יקרא גונב אם גנב נפש מהנפשות שהם ברשותו כמו בנו ותלמידו ואחיו הקטן ומה שידמה לזה ויתבאר זה עוד ממה שאמרה התורה ונמצא בידו ר"ל שיהיה נמצא בידו אחר הגנבה פרט לאלו שם מצויין בידו ואינו חייב עד שיכניסנו ברשותו שנאמר ונמצא בידו ואינו חייב עד שימכר הנגנב בעצמו פרט למוכר האשה לולדותיה או מה שידמה לזה שנאמר ומכרו שימכר אותו בעצמו והנה זאת המיתה היא בחנק כי לא נתבאר תארה בתורה ואולם שאר דיני גונב נפש יתבארו בפרשת כי תצא ומקלל אביו ואמו מות יומת בסקילה שנאמר אביו ואמו קלל דמיו בו וכבר יתבאר שזה מורה על הסקילה ממה שאמרה תורה באבן ירגמו אות' דמיהם בם והנה זאת הקללה היא בשם מהשמות המיוחדים לשם יתעלה לא בכינוי וזה נתבאר מענין הקללות הכתובות בפרשת סוטה שהם בשם המפורש. וראוי שתדע שכבר יתחייב על הקללה אע"פ שקללם של בפניהם ולא נצטערו בקללה ההיא כי הקללה תאמר על זה האופן כמו שאמרה התורה לא תקלל חרש ולזאת הסבה יתחייב בקללה אפי' לאחר מיתת אביו ואמו וזה מבואר מאד וראוי שתדע שלא יתחייב על הכאת אביו ואמו ועל קללתם אם לא היו ישראלים וזה כבר נלמד מענינו כי כל אלו הדינים הם בישראל לבד כמו שיתבאר ברוצח שנ' וכי יזיד איש על רעהו וגונב נפשות נתבאר זה גם כן כמו שקדם ואולם מדברי סופרים הנה הגר אסור להכות אביו ואמו ולקללם. וכי יריבון אנשים והכה איש את רעהו באבן או באגרוף באופן שלא ימות במכה ההיא ונפל המוכה למשכב אם יקום המוכה והתהלך בחוץ על משענת טבעיו ר"ל שישוב לבריאותו ונקה המכה מהמיתה אבל יתן לו מהממון בשיעור מה שנתבטל מהמלאכה בסבת המכה ההיא ויפרע שכר הרופא לרפאתו ממה שיקרה מהחולי בסבת המכה ההיא והנה למדנו ממה שיאמר באבן או באגרוף שאינו חייב בניזקין אם לא היה במה שהכהו בו כדי להזיק כמו הענין באבן או באגרוף וזה הענין ג"כ אפשר שנלמדהו על צד ההיקש ממה שזכרה התורה במיתה או באבן יד אשר ימות בה הכהן ר"ל שהיה בו כדי להמית וראוי שתדע שהוא מן היושר שיהיו אומדים אותו אחר שהכה אם יש במכה ההיא כדי להמית ואם אין בה כדי להמית יפטר המכה מהמיתה וזה האדם שלא הוכה אפשר שיקרו לו מקרים ימות בהם ובהיות ענין כן הנה אם חייבנו המכה מיתה במות המוכה קודם שירפא מהמכה הנה ימות המכה בלא משפט כשמת המוכה בסבת מקרים אחרים לא בסבת המכה והתורה אמרה וכי יזיד איש על רעהו להרגו שיהיה הוא ההורג אות ולזה יחוייב שיהיו אומדין המכה אם שיתכן שימות בה המוכה ואם היא באופן שיאמרו אותו שכבר יוכל לקום ולהתהלך בחוץ על משענת טבעיו יהיה המכה פטור מהמיתה ואף על פי שימות המוכה והנה ענין השבת הוא שיתן לו מה שבטלו ממלאכתו אשר הוא יכול לעשותה ואינו דומה שבת מי שהוא נוקב מרגליות לשבת מי שהוא עושה מעשה מחט ולזה אמר שבתו והנה אם היתה מלאכת המוכה מהאיש המכה אותו כמו שהיה עבד עברי הנה יפטר המכה מהשבת וענין הרפוי שיתן שכר הרופא לרפא אותו עד שיבריא מהמכה ההיא ומהמקרים הבאין בסבתה כאלו תאמר שהעלתה המכה צמחין או שנתסרה אחר שהיתה ולא יתחייב המכה לרפאת מה שיהיה למוכה מהחלי בסבת רוע הנהגתו כי הוא לא נתחייב כי אם על רפואת מה בא לו מההיזק בסבתו וכן הענין בזבת וזה מבואר בנפשו מלשון התורה ומענין זאת המצוה כי זה אמנם היה מהתורה על צד היושר שישלם לו מה שהיזקו לא שישלם לו מה שהגיע לו מהנזק לא בסבתו. וכי יכה איש את עבדו הכנעני או את אמתו הכנענית בשבט ומת תחת ידו רוצה לומ' שימות תכף קודם שיעברו עשרים וארבעה שעות הנה יהרג אדוניו בחרב אך אם יחיה יום שלם שהוא משקיעת השמש עד שובו לשקוע שנית או יחיה משני ימים כשיעור היום השלם הנה לא ימות אדוניו כי כספו הוא. וראוי שתדע כי האדם יהרג על הריגתו העבד והאמה הכנענית כי הם בעלי תורה זולת מצות מעטות יהיו פטורים עליה כמו הענין באשה ישראלית ולזה היה העבד נכלל במה שאמר וכי יזיד איש על רעהו כי העבד הוא רע לנו בענין התורה ואמנם הקלה התורה במפשט מפני היותו כספו כמו שאמר לא יוקם כי כספו הוא ומפני זה יהיה לו רשות ליסרו אך לא ימשול להכותו מכה אכזרית שימות בו. וראוי שתדע שאם לא היה זה העבד כלו שלו או זאת האמה לא ינהג בו דין יום או יומים אך יהיה האדון נהרג עליו אם מת בסבת המכה אפילו אחר זמן מרובה כמו הענין בהריגת שאר האנשים ולמדנו זה ממה שאמר את עבדו ואת אמתו כי כספו הוא ואם לא היה עבדו בעת שהכהו וקנה אותו קודם שימו' או הפך רצו' שכבר היה עבדו בעת שהכהו ואינו עבדו בעת שמת לא ינהג בו דין יום או יומים שנאמר וכי יכה איש עבדו שיהיה עבדו בעת שהכהו ומת תחת ידו שיהיה ברשותו בעת שמת. וכבר נלמד זה ג"כ ממה שאמר לא יוקם כי כספו הוא שכבר יתבאר מזה שהו' כספו בעת מותו וזה מבואר בנפשו וכבר כתב הר"ם ז"ל כי לזה אמר' תור' בשבט מפני שיש לו רשו' ליסרו אבל אם הנהו בחרב אינו בדין יום או יומים כי אין לו רשות להכותו בזה האופן ודברים של טעם הם. וכי ינצו אנשים והכו אשה הרה ולא יהיה אסון באשה. הנה יענש המכה כאשר ישית עליו בעל האשה לתת בדמי הולדות ויתן דמי הולדות על פי הדיינין ר"ל שאם היה בעל האשה מקשה לשאול הנה הדיינין ישפטו ביניהם על צד השומא והאומד. והמשל שאם יפטרהו בעל האשה במנה אף על פי שלפי השומא יהיה ערך מזה יותר ממנה יפטר המזיק במנה כי דמי ולדות לבעל ולזה יש לו למחול וראוי היה שיהיה ערך הולדות לבעל לפי שהבני' הם שלו ולו הם מתיחסים וזאת השומא הוא שיראו במה תמכר אשה הרה כזו וכמה תמכר בהיותה בלתי הרה ומה שתמכר יותר בהיותה הרה הוא לבעל ואם אסון יהיה באשה הנה יהרג הורגה ולא יענש בממון וזה אמנם יהיה כשנתכון לאשה אבל אם נתכון לחברו והרג את האשה פטור המו שביארנו במה שקדם ואז לא יפטר מדמי ולדות כי התורה לא פטרה אותו מדמי ולדות אם הרג את האשה אלא מפני שיתנו נפש תחת נפש ואין ראוי שיהיה מת ומשלם וכן מצאנו במכה רעהו באבן או באגרוף שלא נתחייב ממון אלא כשלא ימות המכה. עין תחת עין. ר"ל אם לא יהיה אסון שם שאם היה שם אסון יהיה העונש נפש תחת נפש אמנם כשלא היה שם אסון יענש בממון. וזה כי בולדות אף על פי שהיה סופם להיות נפש מפני שאינם עתה שלימי הבריאה לא יענש כי אם בממון ואותו הממון יהיה לבעל כמו שקדם ואם היה הנזק באופן אחר כאלו תאמר שחסרו עינה או שינה או אבר מאיבריה יהיו אומדין עין תחת עין בממון כאלו תאמר כשיראו כמה יהיה ערך הנזק בעין וכמה יהיה ערכו אחר שחסר עינו ואותו הפחת ישלם המזיק וכבר יתבאר לך שזה העונש הוא ממון ממה שאומר וזה שכבר מצאנו בנזקין שיש בהם עונש ממון כמו שקדם באמרו רק שבתו יתן ורפא ירפא. וכן הענין בולדות שהם כאבר מאיברי האש' ולזה ראוי שיהיה הענין כן באלו הנזקין ואין לאומ' שיאמר שכבר יעשו לו מכה במכה ההיא ויתן עם זה השבת והרפוי כי אין זה מיושר התורה שיענה יותר ממה שהזיק ולזה הוא מבואר שהוא יפטר בממון ועוד כי היזק הולדות הוא יותר עצום מהיזק האיברי' ואין ראוי שיהיה עונש על ההיזק היותר עצם יותר קל ואם היה אומרו עין תחת עין כפשוטו יהיה העונש עליו יותר מהעונש על הולדות כי עונש הגוף הוא יותר קשה לאין שעור מעונש הממון ועוד כי כמו שבהיזק המיתה אין הבדל כמין בין העונש שיגיע על המתת עבדו והעונש אשר יגיע על המתת זולתו כן ראוי שיהיה הענין בנזקין והנה מצאנו העונש על נזקי העבד ממון כי הוא ישולח לחפשי תחת עינו או תחת שנו ואם היה אמרו עין תחת עין כפשוטו היה ראוי שיהיה כן בעונש אשר יגיע לאדון בשחתו עין עבדו לא יהיה הבדל ביניהם במין אבל יהיה ההבדל ביניהם באופן אחר כאלו תאמר שאם יעמוד זמן מה אחר ההכאה קודם שתשחת עינו יפטר האדון ועוד כי התורה הזכירה כאילו החבלות החמור תחלה כמו שנבאר במה שיבא וכבר דתחילה לבאר שהעונש בניזקין הוא ממון במה שחחיב לתת שבת ורפוי במה שאמר כי כבר ינקה המכה מעונש אחר ואחר זה רצתה לבאר אופן הטלת זה העונש שלא תחשב שיפטר בשבת ורפוי אבל אם היתה החבלה בוולדות יתן גם כן דמי ההולדות ואם היתה החבלה באיברים אחרים יתן דמי האברים ההם ועוד כי התורה אמרה במאמר כולל כי כשלא יהיה אסון יענש בממון ולזה יהיה שב אמרו עין תחת עין אל מה שאמר ענוש יענש ר"ל שהוא יענש בממון עין תחת עין ועוד כי עונש הגוף ועונש הממון הם עונשים אין התיחסות ביניהם וראוי שיהיה העונש לפי המרי ובהיות הענין כן ראוי כי הדברים אשר יהיה עונשם בגוף אין להם יחס אל הדברים אשר ענשם ממון כי ההקש הוא אחד וכאשר היה זה כן הנה מן השקר שישתתף בדבר אחד בעינו עונש הגוף ועונש הממון ולפי שכבר התבאר שבכמו אלו ההיזקים יהיו שם עונש בממון שנ' רק שבתו יתן ורפא ירפא הנה הוא בלתי אפשר שיהיה שם עונש גוף ג"כ ולא יקשה בעיני' איך יתכן שיובן אמרו עין תחת עין ממו' כי כמו זה הלשון אמרה התורה במה שהוא ממון אמר בפרשת אמור אל הכהנים ומכה נפש בהמה ישלמנה נפש תחת נפש ויותר זה ממה שאמר אחר זה השור יסקל וגם בעליו יומת שהוא בלי ספק ממון כמו שנבאר בהגיענו שם בג"ה. הנה קראה התורה מיתה תתו דמי נפשו באמרו אם כופר יושת עליו ונתן פדיון נפשו ועוד כי התורה אמרה ולא תקחו כופר לנפש רוצח וגו' למדנו מזה לפי מה שנתבאר בשרשים הכוללים שכמה שהוא למטה מזה יקחו כופר ולזה יתבאר שבכמו אלו החבלות יהיה העונש ממון ואחר שהתישב לנו זה נשלים ביאור הענין אמר שאם לא יהיה שם אסון הנה יענש במה שהכל בממון עין תחת עין ר"ל שישומו דמי עין הנזק וישלם לו וזאת השומא תהיה כשישומו כמה יהיו דמיו אם ימכר קודם שנשחת עינו וכמה יהיו דמיו אם ימכר אחר השחתו וכבר נתבאר במה שקדם שהוא יתן לו ג"כ השבת והרפוי. וכבר יתבאר לך גם כן שהוא ישלים דמי צערו אשר נצטער בזאת ההכאה מן הענין בעצמו וממה שנזכר מזה בתורה וזה שהוא ראוי שישלם לו זה הצער כי אתה תמצא האנשים שיעשו מלאכה שכל מה שיגיע במלאכה ההיא מהצער יותר יותן להם שכירות רב והנה נזכר זה גם כן בתורה באמרו כויה תחת כויה והנה אפשר בכויה שלא יגיע בו נזק זולת הצער כאלו תאמר שבואו בשפוד על צפורנו ואמר גם כן בקנס האונס תחת אשר עינה ר"ל שהוא ישלם זה בעבור שציער אותה וכבר יתבאר לך שהוא ישלם דמי הבשת כי אתה תמצא באנשים שיקחו שכירות בעשיית המלאכות שכל מה שיהיה הבשת בעשיית המלאכה ההיא יותר עצום ינתן להם שכירות יותר רב וכבר נלמד זה ג"כ ממה שאמר' התורה ושלחה את ידה והחזיקה במבושיו וקצותה את כפה וזה כי התורה לקחה הפרט אשר יהיו בו בושת להורות שכבר תקפיד' התורה בענין הבושת ולזה תמצא גם כן שיענה מוציא שם רע מפני הבושת כי הוא לא הזיק באופן אחר ועם כל זה ענשה אותו התורה מאה כסף ומזה המקו' יתבאר לך כי בושת הוא ממון לא קנס כמו שחשבו רבי' ולזה אמרו ז"ל משלם בושת ופגם על פי עצמו ואינו משלם קנס כבר בארו לך כי הבושת הוא ממון ועוד כי הם אמרו במאמר כולל כל מי שאינו משלם במה שהזיק אינו משלם על פי עצמו ולפי שהבשת הוא דבר שמשלם בו במה שהזיק כי הוא משוער לפי המביש והמתבייש הנה הוא יהיה משתלם על פי עצמו ומה שזה דרכו הוא ממון ולא יטעך מה שאמרו בראש החובל על ענין הבשת חסדא חסדא קנסו הוא מגבת בכבל. שירה שהבשת הוא קנס כי הבשת הנזכר שם הוא קצוב ולא ישוער לפי המביש והמתבייש ומה שזה דרכו הוא קנס ולזאת הסבה קראנו שלשים של עבד קנס ואף על פי שעיקרו ממון לפי שהתורה השוה בזה עבד לעבד וכבר יתבאר זה לך גם כן ממקומות רבים מהתלמוד שהבשת הוא ממון ואין הנה מקום זאת החקירה כי הוא יותר ראוי בחבורים התלמודיים. וראוי שתדע כי דמי הולדות הם לבעל כשהיה חי בשעת נגיפה כי התורה זכתה לו אמנם אם נגפוה אחר מיתה הבעל יהיו דמי ולדו' לאשה לא ליורשי הבעל וכן הענין במי שהיתה מעוברת ואין לה בעל שדמי הולדות הם שלה וזה מבואר בנפשו לפי לשון משפטי התורה עם מה שהתבאר מהשרשים הכוללי' ומזה יתבאר שאם היה בעלה גר ואין לו יורשין וחבל בה בחיי הגר ומת הנה יפטר מדמי ולדות כי נכסיו הם הפקר וכל הקודם בהם זכה ובכאן התבאר שהחובל בחברו חייב בחמשה דברים בנזק אם חבל בו באופן שלא ישוב לענינו הראשון כמו ששחת עינו או קטע ידו ובשבת וברפוי ובצער ובבשת וכבר תהיה החבלה באופן שיתחייב בקצת אלו הדברים זולת קצת כאלו תאמר שאם לא היה שם כי אם צער לא ישלם כי אם צער ואם לא היה שם כי בושת לא ישלם כ"א בשת והקש על זה ולמדנו ממה שאמרנוהו ולא יהיה אסון ענוש יענש שהדבר שיש בעינו מיתת ב"ד לא יתכן שיהי' בו עונש ממון כי עונש הגוף ועונש הממון הם עניני' מתחלפי' חלוף רב ולא יתכן שיהיו בנושא אחד ולזה מה שיהיה בו מיתה אם היה מזיד לא יפול בו עונש ממון אפי' אם היה שוגג כי ההבדל שיש בין שוגג למזיד אינו אלא לחייבו מית' או לפטרו. וכי יכה איש את עין עבדו הכנעני או עין אמתו הכנעני' באופן שישחית אותה שלא ישוב לענינה הנה יוכרח האדון לשלחו לחפשי תחת עינו וענין שלוחו לחפשי הוא שיכתוב לו גט שחרור יהיה ענינו שהוא בן חורין ויתננו לו ואם שן עבדו או שן אמתו יפיל הנה יחוייב שיש לשחנו לחפשי תחת שנו וזה השן איננה שן של חלב שהיא חוזרת אבל השן שאיננה חזורת כמו העני' בעין כי הוא דבר בשן הדומה בענינה לעין ואחד שן ואחד עין ואחד שאר איברים הדומים להם שיהיו מומין שבגלוי ואינן חוזרין כמו שיתבאר מהשרשים הכוללים. וראוי שתדע שזה הדין ינהג בעבדו ואמתו אבל אם היה עבד או אמה של אחרים יתחייב בחבלו בו כי הוא ראוי בחיובו חבלו בחברו אולם כאש' הכל בעבדו ואמתו אם חסרו אבר דומה בענינו לשן ועין כמו ראש החוטם וראשי האזנים וראשי אצבעות הידים והרגלים וראש הגויה וראשי הדדים של אשה הנה ישלחנו לחפש ואם חבל בו באופן אחר פטור כי התורה לא חייבה אותו בחבלו בו אם לא בזה האופן וראוי שתדע שהשחתת העין יהיה בשני הצדדים אם כשישחית הראות אם כשישחית כלי העין והנה בכל אחד מאלו הפני' יצא העבד לחפשי אם ישחית עינו האדון שנאמר ושחתה והמשל שאם היה מרגיש קצת הרגש בחוש הראות ועוד אותו האדון באופן שאינו רואה כלל ולא יחזור לו ראותו אע"פ שנשאר לו עינו הנה כבר נשחת העין וישולח העבד לחפשי וכן אם לא היה רואה העבד ונקר האדון עינו כי קודם זה היה העין חלק מב"ח ואחר כך נשחת ושב באופן שאינו חלק מב"ח וכן ההיקש בשאר ראשי האיברים כי ההשחתה תהיה בהם בשני אלו הצדדים וראוי שתדע כי כבר יצא העבד לחירות בזה אף על פי שלא הכהו האדון אבל הפיל שנו או יסמא עינו בזולת הכאה שנאמר אם שן עבדו או שן אמתו יפיל איך שיהיה שיפילנו אע"פ שנתכון לרפואתו והוא שיתכוין לעינו או לשנו שנאמר ואם שן עבדו או שן אמתו יפיל וכי יכה איש את עין עבדו או את עין אמתו אבל אם הכהו בלא מתכוין אין העבד יוצא לחירות כאלו תאמר שזרק אבן לכותל ונגע בעבדו והפיל שנו וכן אם נתכוון להזיק ולא היתה ההכאה על העין או על האזן אבל אצלה על דבר אחר כאלו תאמר שיכה בפטיש על האבן אצל עינו או אצל אזנו ונתחדש לו ממנה העורון או חרשות אינו יוצא לחירות שנאמר וכי יכה איש את עין עבדו כשתהיה ההכאה בעין בדרך שיתחדש ממנה בעצמות העורון ולפי שחייבה התורה לשלחו חפשי אחר זה הנה נסתפק לחכמי התלמוד אם דינו כדין משוחרר כיון שהוא מחוסר שחרור ולזה אם חבל בו איש אחר תוך זה הזמן אין העבד ולא רבו יכולין להוציא ממנו לא העבד לפי שאינו משוחרר ולא רבו לפי שאין לו בו קנין ואם חבל בו רבו אחר זה קודם שישוחרר פטור ואם תפש העבד אין מוציאי' מידו לפי שהוא ספק וראוי שתדע שאם הפיל אחר שינו יהיה הנזק לעבד כי התורה זכתה לו בזה עד שישולח בו חפשי ולזה יהיה זה הנזק לעבד וילקח בו קרקע ורבו אוכל פירות ויהיה הקרקע של עבד כשיצא לחירות. וכי יגח שור את איש או את אשה בקרניו ומת סקול יסקל השור על יד ב"ד כמו הענין בשאר העונשים הנלוים לזה עם שבזה יגיע תועלת מזאת הסקילה שישמרו האנשים הב"ח אשר ברשותם באופן שלא יזיקו ולא יאכל את בשרו ולא יהנו ממנו כי האכילה הוא מין ממיני ההנאה ולא היה צריך לומר בכאן שלא יאכל את בשרו אם היתה כונתו למנוע אכלתה לבד כי מפני שהוא נסקל אין ספק שהוא אסור באכילה לפי מה שיתבאר במה שיבא ולפי שהוא ראוי שיהיה משפט בשרו בזה ומשפט שאר חלקיו משפט אחר לפי שלא הזיק בבשרו יותר ממה שהזיק בחלבו או בעורו או בקרניו והדומה לזה ממה שהוא חלק מהשור הנה יהיה השור כלו אסור בהנאה כמו שיתבאר מהשרשי' הכוללים ובעל השור יהיה נקי מלשלם ממון כלל וראוי שתדע שאחד שור ואחד שאר ב"ח שיש ברשותו של אדם ואולם דבר הכתוב בהווה וזה מבואר כי הכונ' בזה היא לשמר שלא ימית האנשים הב"ח שהוא ברשותו של אדם וכן הוא מבואר שאחד נגיחה או נשיכה או רביצה או בעיטה או נגיפה כיון שכוונתו להזיק כמו הענין בנגיחה וזה מבואר בנפשו מהשרשים הכוללים ואין השור חייב מיתה עד שיתכוין להזיק לנפש אדם שנאמר אחר זה ואם שור נגח הוא מתמול שלשום והועד בבעליו וזה אמנם ישלם כשיכוון להזיק לאדם אמנם אם נתכון להזיק לבהמה והזיק לאדם הנה יהיה היזקו לו במקרה ומה שזה דרכו לא יתכן שתשלם בו העדה כי הוא לא יגיע כי אם על המעט וזה מבואר מאד. וראוי שתדע כי לא יתחייב מיתה השור שלא נגע מעצמו אבל הקניטוהו אנשים והניחוהו שנאמ' כי יגח שיהיה נגח מעצמו ולא שיניחוהו וכן הענין אם נגח שור אחר שאם הגיחוהו הנה הבעלים פטורים והוא מבואר שאין גומרין דינו של שור אלא בפניו כי אז יתברר שזהו השור שהמית וראוי גם כן שיהיה גמר דינו בפני בעליו כי אליו מגיע הנזק והוא יטען מה שאפשר לו מהזכות על שורו ואם לא היו שם הבעלים אולי יסקל השור ולא במשפט ועוד כי התורה אמרה והועד בבעליו הנה כבר הקפידה התורה שתהיה ההערה בפני בעליו כדי שיטעון על זה מה שאפשר עליו וכן ראוי שיהיה הענין בגמר דינו ולזאת הסבה יתבאר שאם קדם האדם ושחטו קודם שיגמר דינו שהשור הוא מותר באכילה לפי שלא יתכן שיגמר דינו אחר זה ועוד כי התורה אמרה סקול יסקל השור שיהיה שור בעת שיגמר דינו לסקלו וזה איננו שור ואמנם אם שחטו אחר שנגמר דינו הרי הוא אסור בהנאה ומי שיאכל מבשרו כזית לוקה כי גמר דינו אסרו בהנא' לא סקילתו וזה מבואר מאד והוא מבואר שהשור שאין לו בעלים יסקל ג"כ כשהמית את האדם כי הכוונה היתה בזאת המצוה לסלק ההיזקים הממיתים האנשים ולא יצטרך לגמור דינו בפני בעליו כי אין לו בעלים ואם היה השור טרפה אינו נסקל שנאמר השור יסקל וגם בעליו יומת ר"ל שהשור יומת והשור הטרפה הוא חשוב כמת ואם היה בעל השור טרפה הנה השור אינו נסקל שהרי בעל השור אם המית פטור מפני שהוא חשוב כמת. והתורה אמרה מכה איש ומת מות יומת ועוד שהוא עדות שאי אתה יכול להזימה וכל עדות שאתה יכול להזימה אינה עדות כמו שיתבאר במה שיבא. ואם שור נגח והוא מתמול שלשום והועד בב"ד כי שם לבד יהיה העדות בפני בעליו שהוא נגח היום ותמול ושלשום הנה אם לא ישמרנו בעליו אחר זה והמית איש או אשה השור יסקל על יד ב"ד וגם בעליו יומת. וראוי שתדע שאין זאת המיתה בב"ד כי כבר הקפידה התורה ברוצח הנהרג שיזיד על רעהו ויערים בהריגתו. ועוד כי כבר בארה התורה שלא יעתק דין מה שיש בענינו עונש מיתה אצל עונש ממון באמרה ולא תקחו כופר לנפש רוצח לנוס אל עיר מקלטו ולפי שבזה המקום נעתק עונש אל הממון הוא מבואר שאין זאת המיתה על יד ב"ד ולזה הסכימו במכילת' שזאת המיתה היא בידי שמים והופר הוא כפרה לה ויתכן גם כן שיהיה אמרו וגם בעליו יומת כאלו אמר שישלם נפש תחת נפש וה אמנם יהיה כשיתן דמי הנהרג אם ישימו יורשי הנהרג כופר עליו ואז יתן פדיון נפשו ככל אשר יושת עליו לפי ערך הנהרג ואמנם אמ' אם כופר יושת עליו שאם רצו היורשים למחול הכופר הרשות בידם ולפי שהוא חוטא בזה הענין מפני שלא שמר שורו המועד כראוי הנה יהיה הכופר כפרה על זה החטא ולזה יהיה דינו דין הכפרה לכל הדברים ר"ל שאם מת בעל השור קודם שיתן הכופר הנה היורשים פטורים ממנו לפי שאין כפרה לאחר מיתה וכן אם לא היה בעל השור ראוי לכפרה כמו שהיה קטן או שוטה. וכבר מצאנו שהכופר הוא לכפר על הנפש אמר בפרשת כי תשא ונתנו איש כופר נפשו ליי' וסוף העני' לכפר על נפשותיכם ולזה הוא מבואר שדין הכופר אשר נזכר בכאן הוא דין הכפרה לא דין הממון כי לא יתכן לקחת ממון תמורת נפש אם לא על צד הכפרה ואם יגח השור קטן או קטנה מישראל כמשפט הזה יעשה לו ר"ל שיסקל השור וישלם בעליו כופר אם היה מועד ואם היה הנגוח עבד כנעני או אמה כנענית הנה יהיה הכופר שלשים שקלים של כסף כל שקל מהם משקל שפ"ד שעורות והם יהיו לאדוניו והשור יסקל וזה לך ראיה כי מה שאמר או בן ינג או בת יגח הוא בבני ישראל. ועוד כי כל הענין כלו מדבר כשהיה הנזק לאנשי התורה אבל הבדיל בין קצת לקצת וזה כי העבד והאמה מפני שאינם בשלמות בגדרי ישראל הבדיל ביניהם ובין ישראל. וראוי שתדע כי שור של שני שותפין שהועד והמית יתחייב כל אחד מהם בכופר שלם כי הכופר הוא לכפרה על הנפש ולכל אחד מהם תצטרך כפרה שלמה כי נפש יש לו והנה מי שלא ירצה לתת את הכפר כופין אותו ב"ד לתת ליורשי הנהרג ואולם זאת ההעדה היא לפי שפוטי הפסוק שתהיה נגיחתו בשלשה ימים שנאמ' ואם שור נגח הוא מתמול שלשום ואולם העדתו אפשר שתהיה יחד רוצה לומר שיעידו העדים בב"ד שנגח שלשה ימים שנאמר והועד בבעליו אחר נגיחתו שלשה פעמים וידמה שלא אמרה תורה מתמול שלשום אלא כדי שתהיה הריגתו האנשים בשלשה פעמים זה אחר זה כי אז יהיה מועד אם הרג שלשה יחד בהכאה אחת במספר כי אין ראוי שנחשוב אותו למועד כשהיה הענין בזה התואר ומזה המקום יסור הספק איך יתכן שיהיה מועד אחר הוא נסקל בהריגה אחת לבד וזה שזה אפשר כשהרג שלשה אנשים ובאו אחר כן עדים והעידו זה בב"ד וקודם שנגמר דינו הרג הרביעי כי אז יסקל השור וישלמו הבעלים כופר או אם הרג שלשה גוים כי אז הוא מועד לאדם או שהרג שלשה בני אדם טרפה הי הוא אינו נסקל עליהם שנאמר והמית איש או אשה יצאו אלו שהם כמו מתים ולפי שהכופר לכפרה נפשט בו להחמיר הוא בהפך מה שהיינו שופטים בו אם היה ממון ר"ל שאז היינו שופטים בו להקל בספק שיפול בחיובו ולפי שנאמר השור יסקל וגם בעליו יומת למדנו שאין הבעלים משלמין כופר עד שיסקל השור ונאמר שזה אמנם יהיה כשהיה מחוייב השור סקילה אמנם כשלא היה חייב השור סקילה וזה אמנם יהיה כשלא היתה כוונתו להזיק כי אז לא יתחייב השור סקילה כמו שיתבאר הנה אז ישלמו הבעלים כופר מפני שלא שמרו אותו כי חייב הכפר יבא מזה הצד כי האדם מוזהר שלא ישים דמי' בביתו ולזה יביא הכופר לכפרה על זה העון וזה אמנם יהיה כשהיה מועד ליפול על בני אדם בבורות לאכול ירק שם או שהיה מועד להתחכך להנאתו בכותלים להפילם על בני אדם כי מפני שהוא מועד להרוג האנשים בזה האופן הנה יתחייבו הבעלים כופר כשלא שמרוהו ולא נאמר כיון שאין השור נסקל אין הבעלים משלמין סופר כי מפני שהכופר היא לכפרה נחמיר בזה ונאמר כי אולי לא הקפידה התורה בזה אלא כשהיה השור ראוי לסקילה וכן אם העידו העדים שיש לו שור נגח בבקרו ולא ידעו אי זהו הנה ישלחמו הבעלי' כופר אף על פי שאין השור נסקל כי הוא מוכרח לשמר כל בקרו לשמרם מן זה ההיזק הנפלא כי זאת היתה כוונת התורה בזה הענין בלי ספק. ואולם אם חבל השור באדם זה ממה של נזכר דינו בתורה ואולם נלמד זה הדין מנזקי שור בשור ומה שנזכר בענין הכופר התורה וזה כי במקום שאין לאדם חיוב ממון כשהזיק בידיו יתחייב ממון כשהזיק שורו ומפני זה יחוייב כי במקום שיהיה לאדם חיוב ממון כשהזיק בידיו יתחייב ממון כשהזיק שורו ומזה יתבאר כי השור לא יתחייב בחמשה דברים. ואולם יתחייב בנזק לבד כי הכופר הוא נזק ומזה יתבאר כי השור לא יתחייב בדמי ולדות כי לא חייבהו התורה רק בדמי נפש שהוא כן קיימא כמו איש ואשה ובן או בת ועבד ואמה וזה מבואר משרשי הכוללים וכבר יתבאר גם כן שאם היה השור מועד ושמרו בעליו השמירה הנהוגה לכמו הב"ח ההוא הנה הוא פטור מן הכופר שהרי שמרו וכתיב ולא ישמרנו בעליו וכן יתבאר שאין הבדל בין תם למועד אלא בשור ומה שידמה לו שאינו מועד לזה מתחלת ענינו ואולם אם היה שם מי שהוא מועד מתחלתו לזה כמון הארי והדוב והזאב ומה שידמה להם במקומות אשר ימצאו מועדים להריגת האדם הנה יתחייב עליה' לפי מה שאחשב כזולת העד' אם לא שמרם כראוי וזה מבואר מהשרשים הכוללים והנה התועלות המגיעות מאלו הפרשיות הם במצות והכונה בכללם סלוק החבלו' והיזיקי' בין בני האדם באופן שלא ימיתו קצתם קצת ולא יחבלו קצתם קבצת ולא ימותו הב"ח אשר ברשות האדם האנשים והתועלת בזה מבואר בתקון הקבוץ המדיני. והנה היה ההורג חייב מיתה מדה כנגד מדה והיא מכה אביו במיתה למה שיש בזה מהעזות כנגד הוריו אשר היה מחוייב לכבדם ולירא מהם ולזאת הסבה היה המקלל במיתה והיה מיתת המקלל יותר חמורה לפי שכבר שיקל אותו ולאנשים לקלל מלהכות והיה שכבר גונב נפש חייב מיתה כשנשתעבד בו ומכרו לפי שהוא יוציאהו מגדר התורה באופן מה כי הוא ימכר אותו בחזקת עבד כנעני עם מה שימשך מזה מההפסד שלא יודע מאי זו משפחה הוא. ויקרה לו שיקח אחותו או אחד משאר העריות. ולזאת הסבה לא יתחייב אם לא גנבו מאחיו ר"ל שאם מכרו לאחד ממשפחתו פטור כמו שיתבאר בפרשת כי תצא והנה היה עונש החבלות ממון לפי שבזה יש תשלומין מה לנחבל והוא מן היושר שתשתדל התורה שישולם לו מה שחסרו אותו לפי מה שאפשר ואם היה העונש בזה מדה כנגד מדה לא יהיה בזה שום תועלת לנחבל. ועוד כי לפעמים לא יהיה לנחבל מה שירפא בו בעצמו וימות ויגיע מזה היזק לו וגנות לחובל בו ועוד כי אי אפשר לעשות בכל החבלות מדה כנגד מדה וזה מבואר בנפשו ולה ראוי שיהיה העונש ממון והנה הקלה התורה בהריגת האדם בעברו ואמתו כי כספו הוא והיה עונש הפלת הולדו' ממון לפי שאינם בריאה שלימה והנה ישולח העבד חפשי בהשחתת עינו או שנו ומה שידמה להם מהאיברים לפי שכבר היה ראוי שיתן לו האדון דמי האבר ההוא כי אינו ברשותו באופן שיוכל להשחית איבריו אבל הוא לו לעבדו לעולם בהם תעבודו ולפי שלא יתכן שיתן האדון כסף לעבדו רצצה התורה שיהיה הכסף ההוא פדיון העבד ההוא מיד רבו ובזה תועלת גם כן שישמר האדון מהכות עבדו ואמתו באכזריות פן ישחית אחת מאבריהם אשר יחוייב לו שישלחם לחפשי עליהם והנה היה עונש הב"ח ההורג את האדם מיתה כדי שלא יוזק בו אדם ולהזהיר בעליו לשמרו והנה היה בעליו פטור אם לא היה זה הב"ח מועד כי לא היה לו להעלות זה על דעתו ואולם כשהיה מועד ולא שמרו כראוי אז יתחייב כופר ואם היה הנהרג עבד או אמה יתן שלשים שקלי' אשר היה דמי העבד הבינוני תמורת מה שהפסיד האדון בזה הנזק. ואולם שרשי זאת המצוה הם נ"ב שרשים:
@12 **השרש** הא' הוא שיהיה שאי זה שיהיה בן עונשין היה איש או אשה או טומטום או אנדרוגינוס שהרג נפש מישראל זכר או נקבה גדול או קטן חייב מיתה וזאת המיתה היא בסייף שנאמ' מכה איש ומת מות יומת אי זה שיהיה המכה ואחד איש או אשה גדולים או קטנים אלא שדבר הכתוב בהווה ותדע שכן הוא שהרי אמר במקום אחר ואיש כי יכה כל נפש אדם ויתבאר שבישראל מדבר שכבר זכר דינו אלו החבלות דין ההורג עבדו שהוא בן תורה והקל בדינו מעט מפני היותו כספו ועוד שכבר תמצא במה שאמ' וגונב איש גונב נפש מאחיו מבני ישראל ויתבאר שזאת המיתה היא בסייף שהרי אמ' בהורג עבדו נקום ינקם וזה אמנם יאמר על ההריגה כחרב שנ' חרב נוקמת נקם ברית ובביאור אמרו שופך דם האדם באדם דמו ישפך כבר נתבאר זה השרש בשני מסנהדרין:
@12 **השרש** הב' הוא שלא יתחייב מיתה ההורג אם לא עשה זה בזדון ויכוין לזה הנהרג שנ' וכי יזיד איש על רעהו להרגו בערמה אבל אם נתכוון להרוג את זה והרג את זה פטור כבר נתבאר זה ברביעי מסנהדרין:
@12 **השרש** הג' הוא שההורג בשוגג גולה שנ' ואשר לא צדה כבר נתבאר זה השרש בי"ג מסנהדרין:
@12 **השרש** הד' הוא שהמזבח קולט ההורג בשגגה שנ' בהורג במזיד מעם מזבחי תקחנו למות ולה הוא קולט מי שהוא המזבח לפי הנהוג כמו כהן ועבודה בידו כבר נתבאר זה השרש בי"ג מסנהדרין:
@12 **השרש** הה' הוא שהמכה עבדו או אמתו הכנעני ומת תחת ידו הרי זה נהרג עליו אם לא עמד אחר זה כ"ד שעות קודם שמת ואם עמד כ"ד שעות פטו שנ' לא יוקם כי כספו הוא ולזה הוא מבואר שאם היה העבד של אחרים או היה לאחר שותפות בו או ממלאכתו אינו בדין יום או יומים אבל נהרג עליו כהורג ישראל שהרי אינו כספו ואינו עדו בשלמות כבד נתבאר זה השרש מי"ג מסנהדרין ובח' מבבא קמא ובג' מבבא בתרא וידמה שלכך אמרה התור וכי יכה איש את עבדו או את אמתו בשבט לפי שיש לאדון ליסר עבדו על דרך המוסר הבאות בשבט או במה שידמה לו שמיסר האדם בו את בנו כאמרו חושך שבטו שונא בנו וכאשר היתה המכה בזה התואר רגלים לדבר שלא נתכוון להגו מפני שהו' כספו ויורה על זה שכבר חיה אחר זה יום שלם ואולם אם הכהו בסייף או באבן או בחץ הדבר מעיד שאין זה ליסרו אבל להרגו ולא יהיה בדין יום או יומים וכן כתב הרב המורה ודברי' של טעם הם ואולם שאר השרשי' אשר בדיני ההורג במזיד או בשגגה יתבארו בג"ה בפרשת ואלה מסעי:
@12 **השרש** הו' הוא שהמכה אביו או אמו היה איש או אשה או טומטום או אנדרוגינוס חייב מיתה והוא חנק שהיא קלה שבמיתות כי לא פורש וראוי שלא נטיל מהעונשים יותר מהראוי ולפי שסמכה התורה סמיכת זאת ההכאה אחר ההכאה שיש בה מיתה וההרצה למדנו שזאת ההכאה שיש בה מיתה וההרצה היא מעין ההכאות ההם אלא שאין בה מיתה אם לא היה בהכאה ההיא חבורה ולזה יתבאר שאם הכה אות' לאחר מיתה אינו חייב מיתה. או אם עשה בהם חבורה לרפואה כבר נתבאר זה השרש בי"א מסנהדרין:
@12 **השרש** הז' הוא שאם היו אביו ואמו רשעים. הרי הוא פטור על הכאתם ועל קללתם שהרי אינם נוהגים כמנהג ישראל והתורה לא זכרה באלו המקומות כי אם בהיזק שיגיע מהאדם לזולתו מישראל או מן האנשים הנוהגין מנהג ישראל באופן מה כמו העבד הכנעני כבר נתבאר זה השרש בי"א מסנהדרין. והנה זה השרש הוא כולל בקללת הדיין והנשיא לזאת הסבה בעינה וכבר נתבאר זה במכילתא:
@12 **השרש** הח' הוא שהגונב נפש מישראל והדומה להם מן אנשי התורה כמו גר ועבד משוחרר ויביאנו לרשותו וישתמש בו ומכרו לאחרים חייב מיתה שנ' וגונב איש ומכרו ונמצא בידו מות יומת ואמר בפרשת כי תצא כי ימצא איש גונב נפש מאחיו מבני ישראל והתעמר בו ומכרו למדנו מזה שאין הבדל בין גונב קטן ובין גונב גדול שהרי הוא גונב נפש ושאינו חייב עד שיביאהו לרשותו שנ' ונמצא בידו ואינו חייב עד שישתעבד בו שנ' והתעמר בו ואל זה ג"כ רמז באמרו ונמצא בידו ר"ל שהיה נמצא תחת ידו לעבדו ואינו חייב עד שימכרנו לאחרים כי זהו גדר המכור ובביאורה אמר וגונב נפש מאחיו ר"ל שגנבו מאחיו ומקרוביו ולזה הוא מבואר שאם מכרו לאחד מהם הוא גנוב מאחיו. ואם חסר אחד מאלו התארים אינו חייב מיתה כבר נתבאר זה השרש בי"א מסנהדרין:
@12 **השרש** הט' הוא שהעומר הזה לא נדקדק בו שיהיה בו שוה פרוטה כי התורה לא דקדקה בזה מפני ההנאה שהגיע לגונב מפני העמוד אבל מפני ההשתמשות שנשתמש בו כאלו הוא עבדו לזה גם כן מכרו בחזקה הוא עבדו. ולה אמר בזה המקום ונמצא בידו תמורת העמוד להורות שאיך שיהיה שישתמש דרך עבדות ינהג בו זה הדין כבר נתבא זה בי"א בסנהדרין:
@12 **השרש** הי' הוא שלא יקרא גונב נפש מאחיו מי שהיה הנפש ההוא ברשותו וקודם זה כמו בו ותלמידו או מי שהוא סמוך על שלחנו ועוד שהתורה אמרה ונמצא בידו שתהיה הגנבה סבת היותו נמצא הידו יצאו אלו שהם נמצאי' בידו בזולת גנבה כבר נתבאר זה בי"א מסנהדרין. וממה שיפול בו ספק הוא אם נתעמר בו כשהנגנב ישן אם יקרא עמוד לחייבו מיתה אם לאו. והנה זה העמוד יתכן שיורה כשנשען עליו וזה שכבר אפשר שנ' כי מפני שלא דקדקה התורה בזה העמוד היה מעט או הרבה יתחייב על זה העמוד וכבר אפשר כי אין העמוד בכך כי נדר העמוד הוא לפי הנהוג העבוד' אשר תהיה בהקיץ ועל זה לא יתחייב מיתה על כמו זה העמוד כי הוא ספק ויראה לי שכבר יתחייב על הגנבה ועל המכירה אע"פ שהנגנב ישן כי דרך הגבה והמכיר' בזה האופן היא יותר בישן ממה שהיא בנעור וזה מבואר בנפשו ואולם מה שנסתפק לחכמי התלמוד הוא מהעמוד וזה הוא באמרם בי"א מסנהדרין בעי רבי ירמיה גנבו ומכרו כשהוא ישן מהו וכו' דרך עמוד בכך או אין דרך עמוד בכך ואמרו שם ותפוק לי דליכא עמוד כלל ואמרו לא צריכא ישן רגזא עליה כבר נתבאר לך זה שלא נסתפק לשואל זולת העמוד שיהיה כשהוא ישן אם דרך עמוד בכך או אין דרך עמוד בכך ואולם הרב המורה יסבור בזה סברא מקובלת לסברתנו ומה שידמה הוא מה שכתבנו ואין ספק שאם מכר שפחה לעובריה שאין זו הכירה שיתחייב עליה שנאמר וגונב איש ומכרו שיהיה המוכר איש או האשה שגנב':
@12 **השרש** הי"א הוא שהמקלל אביו ואמו נסקל שנ' ומקלל אביו ואמו מות יומת וזאת המצוה במיתה שרש שהיא בסקילה שנ' אביו ואמו קלל דמיו בו כבר נתבא' וזה בששי בסנהדרין.
@12 **השרש** הי"ב הוא שאינו חייב עד שיקללם בשם מן שמות המיוחדים לשם יתע' כמו יי' אל אלהים יה שדי צבאות וזה מבואר מהקללות בתורה בפרשת סוטה שהם בשם מן השמו' המיוחדים כבר נתבאר זה השרש בשביעי מסנהדרין:
@12 **השרש** הי"ג הו' שאם קללם אפי' לאחר מיתה חייב כי הנפש ששבה אליה הקללה היא קיימת לאח מיתה ובה ג"כ יותר מרוע התכונה והעזו. וכבר תמצא שנקרא אב לאחר מיתה כאמרו כי התענית בכל אשר התענה אבי כבר נתבאר זה השרש בי"א מסנהדרין:
@12 **השרש** הי"ד הו' שיתחייב החובל בחברו לשלם ממן והם ה' דברים. נזק. שבת. רפוי. צער. בשת. בנזק נאמר ענוש יענש כאשר ישית עליו בעל האשה והו' דמי הולדו' אשר העדירם ממנו ואמר יד תחת יד רגל תחת רגל והוא ממון כמו שביארנו בזאת הפרשה ואמר בשבת ורפוי רק שבתו יתן ורפא ירפא ואמ' בבשת וקצותה את כפה והו' ממון כמו שביארנו כבר נתבאר זה השרש בח' מקמא והוא מבואר כי במקום שיקרו כל אלו החמשה דברי' ישלם כלם וכאשר לא יקרו כי אם קצתם ישלם מה שיקרה מזה. כבר נתבאר זה השרש בח' מקמא ובירושלמי:
@12 **השרש** הט"ו הוא שד' דברי' מאלו יהיה בהם דין השגגה ברצון כיון שיש לו פשיעה מה בזה הבשת כבשת שלא יתחייב עד שיתכוין להזיק או לבייש שנאמ' וקרבה אשת האחת להציל את אישה מיד מכהו ושלחה ידה והחזיקה במבושיו וזה שלא חלקה התורה בין שוגג למזיד כי אם במכה נפש שנ' ואשר לא צדה וגו' וכי יזיד איש על רעהו אבל בחבלות יתחייב לשלם אע"פ שהו' שוגג כיון שהו' פושע פשיעה מה כבר נתבא' זה השרש בב' מקדושין.
@12 **השרש** הי"ו הוא שלא יתחזק המזיק בשגגה אם היה הנזק הוא הפושע יותר בהגעת הנזק לו כאו תאמר שזרק את האבן והוציא ראשו וקבלה או שנכנס לרשות המזיק שלא ברשותו והזיקו בשגגה וכן הענין אם היו שניהם במדרגה אחת מהפשיעה. וזה מבואר בנפשו חיובו כבר נתבאר זה השרש בשמיני מקמא ובי"ג מסנהדרין:
@12 **השרש** הי"ז הוא שהשגגה שהיא למט' מהשגגה שיתחייב עליה גלות כאלו תאמ' שהיא קרובה לאנוס כגון שנפל מן הגג ברוח שאינה מצויה והזיק' והכה לו כזה שגגה מה והיא עלייתו לראש הגג במקום שיתכן שיפילהו הרוח שאינה מצויה ואע"פ שלא תקרה רק על המעט וכן אם היתה אבן מונחת בחיקו והכיר בה ושכחה או שלא הכיר בה מעולם ועמד ונפלה והזיק הנה באלו לא ישלם כי אם הנזק לבד כי התורה אמרה יד תחת יד רגל תחת רגל. מ"מ ישלם הנזק ונתבאר עוד מזה ממה שחייבה התורה בדמי הולדות ולא יתחייב בד' דברים הנשארים כגון שנתכוון לזרוק שתים. וזרק ד' והזיק האשה שהיא שגגה קרובים לאנוס וראוי להיות כן וזה כי השוגג והמזיד חייבין באלו הדברים וזולת הבשת של יתחייב בו כי אם המזיד והאנוס פטו' מכלם כמו שהתבאר בשרשי' הכוללי'. ולה ראוי שיהיה השוגג קרוב לאנוס חייב בקצת' ובקצתם לא וראוי שיהיה מה שיתחייב בו הוא הנזק כי הוא הדבר היותר ראוי לשלם כי ההיזק בו הוא יותר נגלה עם שהוא נוהג גם בממונו שהזיק. ורואי שלא יעלם ממנו שאם היה בזה הנזק יד אחר הוא פושע בו הנה יתחייב השני כאלו תאמר שהפילו חברו מראש הגג והזיק או ששם כלי' או אדם אצלו בעת שהו' ישן והזיקם הישן בתנועתו בעת השינה וזה מבואר חיובו מאד. כבר נתבאר זה השרש בחמישי מקמא ובירושלמי בשני מקמא:
@12 **השרש** הי"ח הוא שאלו הה' דברים שמין לי מקבל הנזק והמזיק. והמשל שאם הסרו אבר כגון שקטע ידו או רגלו שמין כמה נפחת ערך איש בזה אם ימכר לעבד מפני חסרון האבר ההוא וזהו הנזק ואחר זה משלם והצער בשמין כמה היה אדם כזה נותן שלא יחוסר ממנו זה האבר בזה האופן המצער אך הוא יחוסר ממנו בסם שלא יצטער בו כי אם צער מעט והוא מבואר שכל מה שהיה הנזק יותר מעונג ויותר עשיר יהיה ערך הצער יותר רב. והשבת שמין לפי מה שבטלו ממלאכתו כל ימי חליו לפי המלאכה שהוא יודע בה אם לא חסרו אבר משערי' לפי מה שבטלו מהמלאכה שיוכל לעשותה בזולת האבר ההוא כל ימי חליו אך דמי מלאכת האבר ההוא נכללו בדמי האבר הההוא וכן ידמה שהרפוי יהיה מתחלף גם כן לפי מעלת הנחבל כי כבר יתחלפו הרפואות הלקוחות אם דרך הפה אם מחוץ לפי מנהג המקבל הרפואה והיותו ענוג או הפך והבשת משערין אותו לפי המביש והמתבייש וזה שאם היה המביש פחות ונבזה יהיה הבשת יותר גדול ממה שיהיה אם היה נכבד וכן אם היה המתביש נכבד הנה בושתו יותר גדול ממה שהיה אם היה נבזה כבר נתבאר זה השרש בשמיני מקמא:
@12 **השרש** הי"ט הוא שאומדין מה שהזיק בו אם יש בו כדי להזיק כבר נתבאר זה השרש בשמיני מקמא:
@12 **השרש** הכ' הוא שלא יתחייב בדיני אדם אם הזיק בחברו כשהעיתו או שצעק באזנו וחרשו כיון שלא נגע בו בדבר נרגש ואינו דומה לאבן או לאגרוף שאמר' התורה וכן אם בישו בדברים פטור שאינו דומה למה שאמרה תורה ושלחה ידה והחזיקה במבושיו כבר נתבאר זה הזרז בשמיני בקמא:
@12 **השרש** הכ"א הוא שהנוגף את אשה בכוונה ויצאו ילדיה ולא מתה משלם דמי הולדות זולת מה שיתחייב מפני מה שהזיק בגוף האשה לפי מה שקדם שנאמר ולא יהיה אסון ענש יענש וגו' ואם מתה פטור מדמי ולדו' שהרי הוא חייב מיתה אם היה מזיד ולא יתכן שיתקבצו בפועל אחד בעינו ענש המיתה והממון יחד כמו שהתבאר בשרשים הכוללים ולה אמ' ואם אסון יהיה ונתת נפש תחת נפש ולזה הוא מבואר שאע"פ שהמיתה בשגגה פטור מדמי הולדות לפי שהעונש הפועל הזה הוא אם חיוב מיתה אם פטור ולא יוכל להגיע אל עונש הממון כבר נתבאר זה השרש בשמיני מבבא קמא:
@12 **השרש** הכ"ב הוא שאם לא נתכוון לאשה אע"פ שמתה חייב בדמי הולדות לפי שאין בזה הפועל עונש המיתה כלל כמו שקדם כבר נתבאר זה השרש בד' מבבא קמא:
@12 **השרש** הכ"ג הוא שהעובר הוא אבר מאברי האשה ולזה היה עונש נוגף האשה ויצאו ילדיה ממון שאם היו חשובים לנפש היה ראוי שיהיה בהם חיוב מיתה והיה זה כן לפי שהעובר הוא נזון בהדם ההוה בכבד אמו כמו הענין בשאר אברי אמו. כבר נזכר זה בחמישי מקמא ובתשיעי מסנהדרין ובמקומות רבים מהתלמוד והוא מהשרשים הכוללים:
@12 **השרש** הכ"ד הוא שהנזק והצער הוא לאשה ודמי הולדות לבעל כשהיה לה בעל כי התורה זכתה לו בהם. ואולם אם מת הבעל יהיו דמי הולדות ג"כ לאשה. והיה זה כן כי לא זכתה התורה בדמי הולדות כי אם לבעל לא ליורשיו וזה כי אין האשה נקנית להם. ולפי שהולדות הם כמו אבר מאבריה הנה יהיו דמי הולדות שלה. והנה יתבאר כי הנזק והצער לה לפי שלא זכתה התורה לבעל אלא בדמי ולדות שיש לו צער וטרח בהויתם ולא יחסר בהפקדם מגוף האשה. ואולם מה שיחסר מגוף האשה בהפקדו ראוי שיהיה לאש' וכן הצער ההוא יהיה לאשה לזאת הסב' ואולם השבת הוא לבעל אם היו מעשה ידיה שלו וכן הענין בעבד עברי כי מלאכתו היא לרבו וכבר נתבאר זה בשלישי מקמא. ומזה יתבאר שכופר האשה הוא ליורשי האשה אם הרג אותה שור מועד ולא לבעל ונתבאר זה ברביעי מקמא. והנה התבאר מאלו הדברים שהבושת הוא שלה וכן יראה מהתוספתא בפרק י"ג מאבות נזיקין ומהמשנה בששי מכתובות. כי החולק על זה הדעת שם הוא יחיד וכן הענין בתוספת'. ואולם הרב המורה נמשך לדברי היחיד לפי שנשאו ונתנו המאוראים להקשות ולתרץ על דעתו. והנראה בעיני שאין כח במשא ומתן ההוא לדחות הדעת הנזכר בזה במקומו והוא מה שנתבאר מזה בחמישי מקמא אשר יחויב שיהיה הבושה לכל בני המשפחה ואמרו התם לא גופיה מאשתו גופיה היה מחויב שיהיה הנזק שלו כיון שאשתו הי' גופו או שיהיה לו חלק בנזק וזה דוחה מה שנזכר מזה בשמיני מקמא ובשביעי מכתובות ולזה הנראה בעיני שאין הלכה כדברי אותו היחיד כי לא נדחה תלמוד ערו' מפני שנויי דחיקי כמו שכתב רבינו האיי ז"ל ואם היה לא יהיה זה מן התורה אלא מתקנות חכמים:
@12 **השרש** הכ"ה הוא שהמכה עין עבדו או עין אמתו הכנני' ושחתה או שיפיל שן עבדו או אמתו הדומה לעין שאינו חוזר והוא השן שאינו שן של חלב חייב לשלחם לחפשי. וכן הענין בשאר האברים הדומים לשן ועין שהם ראשי אברים וגלויין כמו ראש החוטם וראשי האזנים וראשי האצבעות מן הידים והרגלים וראש הערוה באדם וראשי הדדים באשה ולפי שלא אמר בהם לחפשי יצא למדנו שהם חסרים שלוח וענין השלוח הוא שיכתוב להם שטר שחרור כמו שאמר בשפחה חרופה או הפשה לא נתן לה ומשם למדנו שאין דנין דין המשוחרר עד שיגיע גט שחרור לידם והוא מבואר שענין השחתת האבר יאמר על שני פנים האחד שישחיתנו מעשות הדבר הטבעי המיוחד לו כאלו תאמר שסמא את עין עבדו אלא שהעין עודנו קיים והואר נזוק והוא חלק מהב"ח והשני שישחיתנו מהיות חלק ב"ה כאלו תאמר שתמק עינו בחבורה ואי זה חלק שיהיה מאלו הוא קרוי השחתה כבר נתבאר זה השרש בראשון מקדושין:
@12 **השרש** הכ"ו הוא שאינו חייב לשלחם חפשי אם לא היו מיוחדים לו ויתכוין ויכה בגופם שנ' וכי יכה איש את עין עבדו וזה שיהיה כלו שלו ויכה עינו שהיא הכאה בגופו ויתכוין לזה אבל אם זרק אבן ונתכוון לזרוק בכותל והנה עין עבדו או שחרש אזנו בזולת הכאה בגופ' כמו שהכה באויר מנגד עינו וסמאה כנגד אזנו וחרשה או שלא היה העבד בכללו שלו לא יתחייב לשלחם אותו חפשי וכבר נתבאר זה השרש בראשון מקדושין ובשני מבבא קמא:
@12 **השרש** הכ"ז הוא שהחובל בעבד כנעני שלו בזולת זה האופן פטור אפילו אם המיתו בשבט ומת תחת ידו ועמד יום או יומים פטור שהרי הוא קנינו ולזה הוא מבואר שאם חבלו בו אחרים משלמין חמשה דברים לרבו כבר נתבאר זה השרש בשמיני מבבא קמא:
@12 **השרש** הכ"ח הוא שהמפיל שן עבדו ואח"כ סמא עינו או חבל בו יפול ספק אם נתחייב לו דמי עינו לפי שאינו עבדו בעת ההיא כיון שהוא חייב לשלחו או לא יתחייב לו דמי עינו כיון שהוא מחוסר גט שחרור ידמה שכבר יקרא עבדו שאם אינו במדרגת העבד לא יצטרך לו ממנו גט שחרור כיון שהוא ספק המוציא מחבירו עליו הראיה וכבר נזכר זה השרש ברביעי מסנהדרין:
@12 **השרש** הכ"ט הוא שלא ינהג דין היציאה בשן ועין בעבד ואמה עבריה כי אין גופם קנוי לאדון אבל יתחייב להם ה' דברים לבד מה שישבתו מן המלאכה בעת אשר מלאכת' שלו ולזה יהיה חלק מה לאדון בנזק אם היה הנזק בחסרון אבר שיבטלו בסבת חסרונו מהמלאכה כמו היד או העין ומה שידמ' להם ודרך החלוק' בזה שילקה במה שישולם לעבד העברי מאלו הה' דברים קרקע ויהיה רבו אוכל פירותיו כל הזמן שתהי' מלאכתו שלו וכן הדי' בבת הקטנה. ואם חבל בת האב או זולתו כי מפני ששולט במכירתה הו' מבואר שמעשה ידיה שלה ולא יהיה לאב חלק בנזק הפוחת אותו מכספת והוא הנזק אשר יחוסר בו אבר ושבית' ממלאכה כבר נתבאר זה השרש בא' מקדושין ובא' מקמ':
@12 **השרש** הל' הוא שאשת האדם או בניו שחבל בהם הוא או אחר זוכין בה' דברים זולת השבת שלא תזכה בו האשה אם היו מעשה ידיה לבעל וזה מבואר בנפשו כי אינו שליט למכור את בתו כמו שביארנו כבר נתבאר זה השרש בראשון מבבא קמא:
@12 **השרש** הל"א הוא ששור איש או אשה שנגח איש או אשה בישראל גדולים או קטנים או עבד או אמה ומת. והיה זה בדרך כונה להזיק לאדם או שהזיק בצד אחר דומ' לה כמו הדחיפה והנגיפה והבעיטה והרביצה כי הכונה בהם להזיק והמית את האדם הרי הבהמה נסקלת בב"ד ובעלים פטורים מן הכופר שנ' סקול יסקל השור ואולם שאין הבדל בזה בין שהמית גדול או קטון או עבד כנעני הרי הו' מבואר ואולם שצריך שיהי' מתכוין להזיק לאדם הוא מבואר ממה שנ' כי יגח שור את איש או את אשה שיהיה מתכוין לנגח איש או אשה ולזה יתבאר שאם נתכוון להרוג את הבהמה והרג את האדם פטור מהמיתה וראוי היה להיות כן כי לא נסקל אלא לשמירה שלא ימית אחרים ואין לירא מזה שלא ימית אחרים שהרי לא נתכון אלא לבהמה כבר נתבאר זה בראשון וברביעי מבבא קמא:
@12 **השרש** הל"ב הוא שהשור שהרג את האדם שהו' טרפה אינו נסקל שנ' איש או אשה יצא הטרפה שכבר היה מת קודם זה כי הטרפה אי אפשר שיחיה כבר נתבאר זה השרש בד' מקמא:
@12 **השרש** הל"ג הוא שהשור שהרג ג' בני אדם באופן שיהיה מועד להריגת האנשים והועד בבעליו בפני ב"ד באופן שידעו כי שור נגח הו' ולא שמרוהו בעליו כראוי השור נסקל והבעלים משלמין כופר ליורשיו אם היה ישראל ול' שקלים לאדון אם היה עבד כנעני שנ' אם שור נגח הוא מתמול שלשום הועד כבעליו ולא ישמרנו השור יסקל וגם בעליו יומת והנה דין השור המועד ודין החיות המועדות מתחלתן הוא אחד כמו הדוב והארי והנמר והדומ' להם שהם מועדים בתחלת' להריגת האנשים. כבר נתבאר זה השרש בא' ובד' מקמא:
@12 **השרש** הל"ד הוא שהשור שאין לו בעלים שהרג את האדם נסקל וזה כי הוא מבואר כי דעת התורה היתה בזה לסלק ההיזקי' ולזה לא התנה בשור הנסקל שיהיו לו בעלים אבל אמר כי יגח שור ולזה אמר כי יגח שור איש כמו שאמר בשור שהזיק שור ואולם במועד לחייב את הכפר הזכיר שיהיו לו בעלים כי בזולת זה לא יהיה חייב שם כפר כבר נתבאר זה השרש בד' מקמא. ובזה הבאור יתבאר שהשור שנגמר דינו לסקילה שנתערב באחרים כלם נסקלים כי התורה חייבה לסלק ההיזקי' מבין האנשים וספק של תורה הדין בו להחמיר כמו שנתבאר זה השרש בשרשי' הכוללי' אך אם לא נגמר דינו פטור כי אין דרך לגמר דינו מה שלא יוכר השור כבר נתבאר זה השרש בתשיעי מסנהדרין:
@12 **השרש** הל"ה הוא שהכפר הוא כפרה למה שהיו הבעלים חייבין מיתה בידי שמים מפני שלא שמרו בהמתן שאם היתה בידי אדם לא היה ראוי שיעתק דינו אל הממון והרי אמרה התורה אם כפר יושת עליו וגו' וזה כי דין ענש הגוף ודין עונש הממון מתחלפין תכלית החלוף הלא תראה כי גם לפטור מהגלות הרוצח בשגגה דקדקה התורה שלא יקחו כפר לפטרו לנוס אל עיר מקלטו כ"ש שלא יקח כפר לפטרו ממיתה בין דין כבר נתבאר זה בראשון מסנהדרין ובהיות הענין כן הוא מבואר שזאת המיתה בידי שמים והכפר הוא בא לכפרה עליה ולזה לא יהיה דין זה הממון כדין שאר הממון שהולכים בממון להקל על המשלם אותו אבל נלך להחמיר כדי שתהיה כפרה לבעלי' ומזה יתבאר שמי שאינו ראוי לכפרה פטור מלשלם את הכפר כמו החרש והשוטה והקטן כבר נתבאר זה השרש בד' מקמא. ומזה המקום יתבאר שמי שהוא גורם למיתת חבירו אע"פ שלא יעשה זה בידים חייב מיתה בידי שמים כאלו תאמר אם שסה בו את הכלב או שהשיך בו את הנחש או שכפתו והניחו ומת ברעב ומצמא אינה משלם כפר כי גדול עונו מנשא בכפר. וזה כי השיעור מהשפיעה אשר כופר בו הדם לבעלים בכפר הוא למטה מזה. כבר נתבאר זה השרש בתשיעי מסנהדרין:
@12 **השרש** הל"ו הוא שהשור המועד שמכרוהו בעליו חזר לתמותו שנ' הועד בבעליו וזה לא הועד בבעלי'. ולזה אינם פושעי' בזה פשיעה יתחייבו עליה כפר. כבר נתבאר זה השרש בשני מבבא קמא:
@12 **השרש** הל"ז הוא שהשור המועד להמית בני אדם בלי כונה להזיק באופן שאינו חייב מיתה לפי מה שביארנו. הנה הבעלים חייבין בכפר או בשלשים של עבד אם המית את האדם ולא שמרוהו כראוי. כי הבעלים פושעים על שלא שמרוהו וכיון שהוא מועד לזה והמשל שהיה מועד להרוג את האדם בהיותו מתכוין להרוג הבהמה. ר"ל שכבר קרה לו זה המקרה שלשה פעמים או שהיה מועד להתחכך בכותלי' להנאתו ומדי התחככו בהם יפילם על בני אדם וקרה לו זה ג' פעמים ואע"פ שיש למספק שיספק בזה ויאמר שזאת פשיעה היא למטה מהפשיעה אשר לבעלי' בשור המועד למזיק בכונה ועוד שהתור' לא זכרה נתינת הכפר אם לא כשהשור יסקל הנה מפני שהכפר הו' כפר' נשפוט בספקו להחמיר כדי שיהיו הבעלי' נקיים מעון כבר נתבאר זה השרש בד' ובה' מקמא. ומזה המקום יתבאר שאם נכנסה הבהמה לרשות הניזק או שלא ברשו' הניזק ודרסה בדרך הלוכה על גבי תינוק והרגתו הנה הבעלים משלמין את הכפר. לפי שהרגל מועדת להזיק דרך הליכה וברשות הניזק יתחייב על נזקי הרגל כמו שיתבאר והנה היו הבעלים פושעים בזה לפי מה שיתבאר מפני שלא שמרו בהמתם מלהכנס ברשו' הניזק יתחייב על נזקי הרגל כי הדבר ידוע שהאדם משים בביתו טפו וכליו והם מוכנים להנזק ברגלי הבהמה הנכנסה שם בזולת ידיעתם כבר נתבאר זה השרש בשלישי מבבא קמא:
@12 **השרש** הל"ח הוא שהשור המועד שהמית האדם ברשות המזיק יהיו בעליו פטורים מן הכפר שהרי לא היו לו לכנס שם ולזה לא היתה בזה פשיעה לבעלי' אך הוא פושע בעצמו כי אין לבעלים להעלות על דעתם שתזיק לאדם שאינו מביתם בביתם אך אם נתנו לו רשו' להכנס שם הנה הם פושעים שלא שמרוהו שלא תזיקהו כבר נתבאר זה השרש בשני מקמא:
@12 **השרש** הל"ט הוא שהכופר הו' דמי הנהרג לפי מה שישפטו הדיינין שנ' ונתן פדיון נפשו ככל אשר יושת עליו וזאת השיחה יתחייב שתהיה בב"ד כי הם אשר יש להם כח בזה הלא תראה כי גם בדמי הולדו' שתלה העניין בבעל האשה אמר ונתן בפלילים. ויתבאר שהם דמי הנהרג לא דמי בעל השור שאם היה הענין כן לא היה מתחלף הערך בין שהמית ישראל בין שהמית עבד עברי. כבר נתבאר זה השרש בד' מקמא ובשלישי מתוספת קמא:
@12 **השרש** המ' הוא שהשור המועד שהמית והיה שור של שותפין הנה כל אחד מהשותפין יתחייב בכפר שלם כי לכל אחד יש נפש ויצטרך לכפרה שתהיה פדיון נפשו ולא נתבא' מלשון התורה שישלם פדיון נפש המזיק בפחו' מנזק שלם ולזה ישלם כל אחד כפר שלם מפני שהכפר היא לכפר' הנה נלך בספקו להחמיר כבר נתבא' זה השרש בד' מקמא:
@12 **השרש** המ"א הוא שכבר יראה מלשון התורה שיהיו בענין העדת השור תנאי' בצד הזמן ומצד הדבר הניזק ומצד זמני ההעדה בבעליו בב"ד והנה מה שהוא מצד הזמן הוא שכבר יראה ממה שדקדקה התורה בנגיחות השור שיהיו ב' ימים רצופים כי שור שהוא מועד להזיק בזמן מה אינו מועד להזיק בזולתו והמשל שאם נגח ג' ימים זה אחר זה הוא מועד לכל הימים וכן אם נגח שלש שבתות זה אחר זה הרי הוא מעוד ליום השבת לבד וכן אם נגח מעשרה ימים לעשרה ימי'. ידמה שכבר משלה בשור ההוא לחה מה שתביאהו להזיק שתתעורר בזמן ההוא לבד ואולם מה שהו' מצד הנושא הוא שכבר ידמה מלשון התורה ג"כ שמועד למין מה אינו מועד לזולת המין ההוא כאלו תאמר שהמועד לאדם אינו מועד לבהמ' ומועד לשור אינו מועד לחמור ולא זכרה התור' במועד ובתם נגיחה במין אחר ר"ל בשור שהמית האדם זכרה נגיחה האדם במועד ובתם וכן העני' בשור שהזיק שור ולזה ידמה שהמועד מין אחד אינו מועד למין אחר ואולם אם נגח שור חמור וגמל הרי הוא מועד לכל המינין כמו שהמועד לג' ימים רצופי' הוא מועד לכל אחר מימי השבוע ובזה האופן יתבאר ג"כ שמועד לנזקין אינו מועד למיתה ושהמועד ליגח אינו מועד לגוף או לנשוך או לרבץ או לבעוט ומזה יתבאר שמועד לקרן ימין אינו מועד לקרן שמאל כבר נתבאר זה בד' מקמא. ואולם מה שהוא מצד זמני ההערה בבעלים כי יראה מלשון התורה באופן מה שיצטרך שתהיה ההעדה בבעלים בג' ימים שנ' או נודע כי שור נגח הוא מתמול שלשום והוא אפשר ששב מתמול שלשום אל ההודעה והוא אפשר ג"כ שיהיה שב אל הנגיחות לבד ולזה יהיה בזה התנאי ספק ובממון נשפוט בו להקל כבר נתבאר זה השרש בב' מקמ'. ובכפ' בשפוט בו להחמיר ר"ל שכב' נפשטהו למועד אע"פ שהעידו העדים ג' העדויות ביום אחד לפי מה שיראה לי בד' מקמא. וידמה ג"כ שבמה שדקדקנו בתנאי הזמן והבוש' נשפט להחמיר בעניין הכפר כי יש לאומ' שיאמר שלא אמרה התורה מתמול שלשום אלא לתנאי שלא תהיינה הנגיחות יחד כי לא יהיה מועד ולזה אמר בתמול שלשום להורו' שצריך שתהיינה הנגיחות זו אחר זו כי הג' ימים לא יתכן שתהיינה יחד ובזה יתבאר שנ' בשור המועד להריגת הב' מועד להריגת האדם שנ' ואם שור נגח הוא מתמול שלשום ושור נגח קרינא כזה. וכן אם הוא מועד לחבול באנשים חבל של סכנה אפשר שיקרא ג"כ שור נגח ויתחייבו בכל זה הבעלי' כופר מספק שהרי הם פושעי' כשלא שמרוהו כראוי אחר שכבר ידעו בו שהו' נגח באחד מאלו הפנים. וכב' נתב' זה השרש בד' מקמ'. ומזה המקום יסור הספק איך יתכן שיבא לתשלומי כפר שור שהרג את האדם כיון שהוא נסקל בהריגה הראשונה שהרי כבר יקרה זה ג"כ כשהרג בני אדם טרפה שהרי אני קורא בו שור נגח כשהיו העדים מכירי' בעל השור ואינם מכירים את השור אך הם מכירים מתנועותיו ומראהו ותארו בראותם זה מרחוק ששור אחד הוא שנגח ג' הגניחו' וזה יביא בעל השור אל שיחויב לשמר כל השורי' אשר לו שם וכשלא שמרם כלם הוא פושע כבר נתבאר זה בד' מקמא. ואין ספק שאם חזר בו השור מגניחה מה שהוא מועד לו הרי הואר תם שלא יאמר בו שור נגח הוא אבל יאמר בו שכבר היה שור נגח וזה יתבאר כשיהיו התינוקות ממשמשים בו ואינו מזיק הדבר שהוא מעוד לו בעת שהוא מעוד לו כבר נתב' זה השרש בב' מקמא:
@12 **השרש** המ"ב הוא שהשור הטרפת אינו נסקל וכן אם היה של אדם טרפה וזה כי הסקילה היא להמית החי וזה הוא חשוב כמת וכבר נאמ' בבעליו יומת יצא זה שהוא חשוב כמת כבר נתב' זה השרש בט' מסנהדרין ויראה לי שאין ראוי לבעלי' לגדלו בתוך ביתם שנ' ולא תשים דמים בביתך אך ישחטוהו או ישמרוהו שמירה מעולה מאד באופן שלא יוכל להזיק:
@12 **השרש** המ"ג הוא שאין גומרין דינו של שור אלא בפני בעליו אם היו לו בעלים וזה כי התורה אראה כי ההעדה בב"ד תהיה בפני בעליו שכ' והועד בבעליו ועוד שהוא ראוי שיהיה בעל השור עומד על שורו לטעון מה שאפש' לו לזכו' להציל ממונו שלא יענש בלא משפט כבר נתבאר זה השרש ברביעי מקמא:
@12 **השרש** המ"ד הוא שהאוכל מהשור שנגמר דינו לסקילה אע"פ ששחטו לוקה שנאמ' ולא יאכל את בשרו כבר נתבאר זה השרש בשני מפסחי' ומזה יתבאר שהוא אסור באכילה כי האכילה היא אחת ממיני ההנאה ואין הבדל בזה בין בשרו ועורו וקרניו ושאר חלקיו כי לא הזיק בבשר יותר ממה שהזיק באלו:
@12 **השרש** המ"ה הוא שהשור שגנח את האשה ויצאו ילדיה פטור מדמי ולדו' וזה כי התור' ביארה בענין הכפר שהוא יהיה בקטני' ובגדולי' שהם שלמי ההויה ולזה לא ימשך זה הדין בעוברים כי לא הגיע להם שלמותם בחויה עדיין כבר נתבאר זה בשמיני מקמא. ובזה יתבאר ששור שחבל באדם משלם נזק של האבר שהזיק ממנו הוא שלם ההויה וזה יתבאר ג"כ מצד אחר וזה כי במקום שהוא יותר בלתי ראוי שיערך בממון חייבה התורה לשלם כפר כשיזיק באבר אחד מאברי האדם יחוייב לו מהתורה שישלם ממון והוא מבואר שמה שיתואר מזה מחיוב נזקי שור באדם והוא שלום הנזק לא הד' דברים הנשארים שיתחייב בהם אדם שהזיק באדם לא יהיה דינו כי אם דין הממון וג"כ הנה בין בכוונה בין שלא בכוונה כי לא הבדיל בין אדם לשור כי אם במית' כמו ששור שהזיק לא יתחלף בו דין החבל ר"ל כי בכל אחד מהם ישלם נזק כמו שיתבאר כן הענין בשור שחבל באדם אבל ביארה התורה שלומי נזק בהמתת האדם וממנו נלמד זה הדין בחבלו בו מקל וחומר. ואולם לא נתחייבתם בחצי נזק לפי שהו' נסקל ואי אפשר להשתלם חצי נזק מגופו. אך בחבלת האדם כמו שזכרה זה באדם שהזיק לאדם כי אין הבדל בו בין המיתה לנזקין בחיוב שלום הנזק והוא מבואר שאי' הבדל בחבלו' השור בין שהזיק בכונה ובין שהזיק בלא כונה שהרי האדם בנזקי בורו חייב אע"פ שאי אפשר בו כונה להזיק ואולם בהמתת האדם חוייב שתהיה בכונה לפי שהשור נסקל וזה גם כן נלמד מאדם שהזיק באדם שלא זכרה בו התורה כוונה כי אם בהמתה לא בנזקין כבר נתבא' זה בשלישי מקמ'. וראוי שתדע שאם נגח השור המועד שפחה כנענית ויצאו ילדיה משלם דמי ולדו' לאדון כי כספו הם וכאלו הזיק ממונו למה זה דומ' לשורו שנגח פרו של חבירו ויצאו עוברין שבמעיה. כבר נתבאר זה בחמישי מקמא:
@12 **השרש** המ"ו הוא שהשור אינו מועד לנזיקין שהביאוהו האנשים להזיק כמו הענין בשור האצטרין רוצה לומר שלמדוהו לשחק עם שור אחר שנ' כי יגח כי יגוף שיעשה זה מעצמו לא שיגיחוהו או שיגיפוהו ולזה הו' מבואר שאם הרג את האד' בזה האופן אינו נסקל כבר נתב' זה השר' בד' מקמ'. ואם היו לו ב"ח אשר הוא מוכן להזיק במעט הערה יעירוהו האנשים שאינם נמלטי' ממנה כמו הענין בכלבי' אשר ישובו בשמעם אותיות השריקה אע"פ שאין כונת מוצאי האותיו' מפיהם שיעוררו אותו להזיק הנה אין דינו דין שור האצטרין כבר נתבאר זה השרש בשני מבבא קמא:
@12 **השרש** המ"ז הוא שהשור שבעלי' פטורין אם הזיקו כמו הענין בשור של חרש שוטה וקטן אם הזיק פטור מלשלם לאיש יהיה ממונם חמור מגופם וזה כי לא יתחייב האדם בנזקי ממונו שהזיק אלא מפני שהוא פושע בשמירתו כבר נתבאר זה השרש בד' מקמא:
@12 **השרש** המ"ח הוא ששור תם של איש או של אשה שהמית שור רעהו או הזיקו בנגיפה או נגיחה או רביצה או בעיטה או נשיכה הנה הבעלים משלמין חצי מה שהוזק בסבת ההמתה או החבלה מגו השור המזיק היה שוה מעט או הרבה שנ' כי יגוף שור איש את שור רעהו וגו' ואחד שור ואחד שאר בעלי חיים שיזיקו באופן שדרכם להזיק ואחר שהמיתו או חבלו כי הכונה כלה היא להסיר הנזקים מבין האנשים והוא מבואר כי בכלל מה שפיחתו המיתה יהיה בכלל שכר הוצאת הנבלה מהמקום שהפילה שם כי אם היתה במקום עמוק ויצטרך לשבור הנשים להוציאה משם ובכלל הנה שכר הטורח בהבאת' למקו' אפשר שתמכר בו ראוי שיגרע מדמי הגבלה כבר נתבאר זה השרש בא' מקמא. וממה שזכרנו שהתם משלם חצי נזק מגופו יתבא' לנו שיש לאיש הניזק שהוזק שותפות בשור ההוא ויתחייב בנזקי' שיזיק אחר זה לפי החלק שהיה לו בו כבר נתבאר זה השרש בד' מקמא:
@12 **השרש** המ"ט הוא שהשור לא יתחייב בנזיקין ברשות המזיק כי אין לבעלים פשיעה בזה כיון שהכניס הניזק שורו או כליו שם שלא ברשות הבעלים. וכבר יתבאר לך אמתת זה הענין כי התורה דקדקה בנזקי שן ורגל שיהיה היזקם ברשות הניזק כי אז בעל הפחת הוא בלתי פושע כזה. ואולם ברשות הרבים יהיה פטור כי דרך הבהמו' ללכת ברשות הרבים ואין דרך האנשים להניח כליהם או פירותיהם בר"ה ולזה יהיה הניזק הוא הפושע כזה לא המזיק ומזה יתבא' שעל נזקי קרן והדומה לו יתחייב בר"ה וכ"ש אם הזיק ברשות הניזק כבר נתבאר זה והשרש בא' מבבא קמא:
@12 **השרש** הנ' הוא שהשור המועד ששמרוהו בעליו כראוי ויצא והזיק הבעלים פטורים שנ' ולא ישמרנו בעליו והרי שמרו ואם לא שמרו כראוי הבעלים משלמים נזק שלם מן המטלטלים או מן העדית שבקרקע כמו שהתבאר בשרשים הכוללים שנ' שלם ישלם שור תחת שור והנה השמירה תהיה אם קשרו במוסרה ונעל בפניו בדלת שיכול לעמוד ברוח מצויה כי כשהיה הענין בזה התואר הנה יתבאר שאין בו אפשרות לפי הנהוג לצאת ולהזיק אם לא לשהיתה שם סבה שתחייבהו לצאת כמו שהניחו שם בהמה או שהניחו בזולת מאכל ומשקה והיה רעב וצמא או שמסרה לחרש שוטה וקטן שאינם בני דעת כי אז הבעלים פושעים כאלו לא שמרוהו כבר נתבאר זה השרש בד' ובששי מקמא. והנה יתבאר שאלו התשלומין הם קסף או שוה כסף מהמטלטלין או ממיטב הקרקעות שהרי התורה ביארה כבור שהבעלים משלימין כסף בשווי הדבר הנזק שנ' כסף ישיב לבעליו וכ"ש שיתחייב בזה בנזק השור שדרכו לילך ולהזיק וכוונתו להזיק ולזה הוא מבואר שמה שאמרה תורה בשור מועד שלם ישלם שור תחת שור הרצון בו השווי מה שהזיק לא שיפטר בשור שהזיק אם הזיק יותר מכדי דמיו ולא שיתן שור שהיה שוה מנה אם הזיק טשו רשוה עשרים דינרין הנה יתבא' במה שנ' בכור שכסף היא כשוה כסף וכ"ש שיהיה שוה כסף בכסף כי אין ערך הכסף מצד עצמו כי אם מצד הסכמת האנשים והנה השוה כסף שהוא ככסף הם המטלטלים שאפשר לו להעתיקם בכל מקום שירצה או למכרם לא הקרקעות אלא אם היו עדית שיקפצו עליהם האנשים לקנותם לחשיבותם כי אי אפשר לו להעתיקם וזה השרש כולל לכל התשלומין הנזכרי' בתורה זולת תשלומי המלוה שהתורה נתנה הבחירה בזה ללוה שנ' בחוץ תעמוד והאיש אשר אתה נושה בו יוציא אליך את העבוט החוצה כבר נתבאר זה השרש בראשון מבבא קמא:
@33 **וכי יפתח איש בור עד כי יתן איש אל רעהו.**
@33 **ביאור דברי הפרשה:**
@33 **השרש** הראשון הוא שהממציא תקלה ברשות הרבים ויש בה כדי להמית שור או חמור הנופל שם ונפל שם בעל חי ומת בעל הבור חייב לשלם מה שפיחתה המיתה ערך הבעל חי הנופל שם אם לא כסהו כראוי וכן הפותח את הבור ולא כסהו כראוי והיה זה כן לפי שהוא גורם זה הנזק לבהמות אשר מדרכם שילכו שם והנה יתבאר שצריך שיהיה בה כדי להמית מן הפרט שזכרה התורה והוא הבור לפי מה שירה עליו הגדר עמוק עשרה טפחים והו' עם זה בלתי רחב ולזה יהיה בו חבל יתכן שימו' הבעל חי הנופל שם וכל שכן אם היה בו עם זה קשי שיתחבט בו הנופל שם כי החבט לבדו כלי להמית אע"פ שלא יהיה שם חבל ובזה יתבאר שהחפירה שלא יהיה חבל ולא חבט כמו שהיו גיזי צמר בקרקעיתו והיה רחבו יותר מעמקו ונפל בו בעל חי ומת בעל הבור פטור אך אם היה שם חבל למיתה או חבט חייב ומזה יתבאר שבור עמוק שמונה טפחים ומהם שני טפחים מים חייב בו על מיתת הב"ח הנופלים שם שהרי יש בו הכל למיתה כבר נתבאר זה השרש בשמנה מבבא קמא:
@33 **השרש** הב' שאע"פ שלא היה לאדם פשיעה בחפירת הבור לפי שכבר חפרו בתוך רשותו אם הפקיר אחר כן רשותו לרבים ולא הפקיר בורו הרי הוא כפותח בור ברשות הרבים בעת שהפקיר רשותו כי אז נתן פתח לבהמו' לפול בבור ההוא והרי הוא בעל הבור ולזה הוא מבוא' שממונו הוא מזיק אך אם הפקיר ג"כ בורו אינו חייב בנזקו שהרי אינו בעל הבור ר"ל שאינו ממונו ואין לו פשיעה בחפירתו כבר נתבאר זה השרש בחמשי מבבא קמא ומזה יתבאר שכל תקלה שאין לו פשיעה בהמצאתו אותה אם הפקירה לא יתחייב בנזקיה כבר נתבאר זה בשלישי מבבא קמא:
@33 **השרש** הג' הוא שלא יתחייב בעל הבור אם נפל אדם לבור ומת ולא יתחייב ג"כ על הכלים אפ נפלו שם ונשברו וזה כי מפני שהיתה התורה מדברת בנזקי שור שהמית אדם והפסיקה המאמר במיתת שור וחמור בבור קודם השלמתה המאמר בהשלמת נזקי שור בשור ולא זכרה בו המתת האדם למדנו שלא יתחייב בבור על המתת האדם הנופל שם וזה יתבאר גם כן מן הפרטים הנזכרים בנזקי הבור והם שור וחמור שהם יותר ראוים לפול מן האדם לפי שאינם בעלי שכל והנה הבור אין לו התחלה מעצמו להמית האד' כמו הענין בשור כי השור ילך אל האדם ויזיקהו וזה בלתי אפשר בבור שלא יתחייב בעל הבור על הכלים אם נפלו שם כי אין להם מעצמם התחלה לילך ולפול בבור כמו הענין בשור וחמור ואין לבור גם כן התחלה לילך אליהם כבר נתבאר זה בחמישי מבבא קמא:
@33 **השרש** הד' הוא שהכורה או חבור או הפותח אותו וכסהו כסוי בלתי ראוי באופן מה הרי הוא חייב בנזקי הבור שהרי לא כסהו והמשל שכסהו כסוי חלוש יתקלקל ברגלי הבהמות ההולכות שם או שכסהו בכליו של חברו שלא ברשותו שהרי יבא בעל הכלים ויטול את כלים שכסה בורו או מסרהו לחרש שוטה וקטן שאין להם דעת ולזה יקרה שיגלוהו ולא יכסוהו אחר זה וכן אם כסה בורו וידע שנתגלה ולא השתדל לשוב לכסותו והיה לו פנאי בזה מהעת שידע שנתגלה כבר נתבאר זה השרש בשלישי ובחמישי מבבא קמא:
@33 **השרש** הה' הוא שאע"פ שאין בבור כדי להמית כיון שיש בו כדי להזיק והוזק בו הב"ח הנופל שם או שהוזק בו אדם בעל הבור חייב כי התורה שתקה מלבאר דיני נזקי שור ובור בחבלות להשענה על מה שנזכר מזה באדם שהזיק אדם אך לא יתחייב בחבלות האדם כי אם בנזק כמו שביארנו בשור שחבל אדם כבר נתבארו זה השרש בחמישי מקמא ומזה יתבאר שהחופר בור שאין בו כדי להמית ובא אחר והשלימו לשעור ההמתה השני חייב לפי שכבר שנה צורת הבור כי בהתחלה לא היה בו כדי להמית ולזה נסתלקו מעשי הראשון לגמרי ואולם אם חפר הראשון כשעור הבור והשלימו לעשרים שניהם חייבין בנזקיו כי כל אחד מהם כרה בור ולא נסתלקו מעשי ראשון שהרי היה בו כדי להמית ולזה לא נשתנה צורתו ולזה מחלקין ביניהם שלום הנזקין כבר נתבאר זה השרש בה' מקמא:
@33 **השרש** הששי הוא שלא יתחייב בעל הבור במיתת שור וחמור הנופלים שם אם לא היתה נפילתם ראוי לפי הנהוג ולזה הוא מבואר שאם נפל שם שור שהוא פקח ביום בעל הבור פטור כי אין דרך שור פקח ליפול בבור ביום או אם היה סומא או שוטה או קטן או שנפל שם בלילה או שדחפו שם ב"ח אחר הרי כל אחד מאלו ראוי לפול בבור ואם היה ראוי הב"ח הדוחה אותו לשלם קצת הנזק ישתלם ממנו הנזק מה שאפשר לו והשאר ישלם בעל הבור כי לולי הבור לא היה ניזק השור הנופל מפני זאת הדחיפה בזה האופן ואם אי אפשר להשתלט מהב"ח הדוחף כלל הנה בעל הבור ישלם הנזק כלו כי אליו יתכן שייוחס ההיזק וזה מבואר מאד וכן הענין אם הוחלקה במים ונפלה שם כבר נתבאר זה השרש בשמיני מקמא ומזה המקום יתבאר שאם נפל בבור באופן בלתי ראוי שיפול בו בעל הבור פטור כאלו תאמר שנפל לאחוריו תוך הבור מפני שחרד מקול הברה המתחדש שם כי זה אינו דרך נפילה אך אם נפל לפניו בסבת זאת החרדה חייב כי זהו דרך נפילה ואולם אם נפל מקול הברה לפניו חוץ לבור הנה הדבר בספק אם יתחייב בזה בעל הבור שנאמר ונפל שם שור או חמור וזה אפשר שיובן שיפול בבוראו שיפול אצל המקום ההוא כי שם יאמר על המקום והמקום יאמר על המקום הרחב או על המקום שמיוחד ולזה הוא מבואר שכבר אפשר שיובן שמפני בריתו יפול שמה שור או חמור וזה יהיה אם יהיה מפני שיפול תוך הבור או חוץ ממנו כיון שבריתו תסבב זה כבר נתבאר זה בה' מקמא:
@33 **השרש** הז' הוא שאם נפל לתוכו ב"ח ומת והיה בלתי אפשר בו שיהיה המת שלו הנה בעל הבור פטור מלשלם שנאמר והמת יהיה לו יצא זה שאין המת שלו כמו הענין בשו' של פסולי המוקדשין שנבלתו היתה אסורה בהנאה כמו שיתבאר במה שיבא בג"ה:
@33 **השרש** הח' הוא שאין הבדל בחבלו' הבו' בין שיפול הנופל בתוך הבור בדרך נפילה כי מה שדקדקה התורה הוא במיתה לא בחבלות והוא מבואר ממה שנזכר בנזקי אדם באדם כי בחבלות לא ידוקדק באופן מה שידוקדק במיתה שם נלמד זה הדין כבר נתבא' זה בה' בבא קמא:
@33 **השרש** הט' הוא שאי זו תקלה שימציא האדם ברשות הרבים דינם דין הבור כאלו תאמר ששפך מימיו ברשות הרבים או הניח שם זבלו אז אבנו או משאו או כדו שנשברה ברה"ר בפשיעה ולא סלקה או שנתקל אדם ונפל והיה לו מקום לעמוד ולא עמד והיה למכשול להולכים שם דינו גם כן דין הבור. כבר נתבאר זה בשלישי מקמא. והוא מבואר ממה שקדם שהמניח כדו בר"ה ונתקל בה האדם ושברה פטור על שבירת' כי בעל הכד פושע בזה לא האד' כי אין דרך בני אדם להתבונן בדרכים הידועים לו כבר נתבאר זה השרש בשלישי מבתרא:
@33 **השרש** הי' הוא שמה שהיה עניינו מוכן לתקלה והיה חדושו ברשותו כמו הענין בכותל רע והאילן כי אין חדושם לתקלה ויש לאדם לבנות כותל בתוך רשותו או אם נטה אילן אם נפלו ברשות הרבים והיה למכשול להולכים שם הנה בעל הכותל או בעל האילן פטור מלשלם כי אין לו פשיעה בחדושם ואינו בעל חבור כי הוא לא חדש זה הבור כי מה שחדש לא היה לתקלה ואין זה דומה לכורה בור ברשותו שהרי הוא המציאו לתקלה אך זה ואם הוא בעל האבנים והעץ אינו מצד מה שהם בעל הבור כבר נתבאר זה השרש בעשירי מבבא מציעא:
@33 **השרש** הי"א הוא שהגונב שור או שה ואחר שנשחט ברשותו טבח אותו או מכרו משלם תשלומי ד' או ה' ואם לא טבחו או מכרו שגנב אי זה דבר שיהיה משלם תשלומי כפל שנא' כי יגנוב איש שור או שה והנה התנינו שיהיה הדבר ברשותו קודם טביחה ומכירה לפי שהדבר אינו נגנב עד שהתמיד להיות ברשות הבעלים כבר נתבאר זה השרש בששי מבבא קמא:
@33 **השרש** הי"ב הוא שהגונב ממי שאינו רעהו כמו הענין בהקדש ומה שידמה לו בזה אינו משלם אלא הקרן שנאמר ישלם שנים לרעהו ובזה הדין שוה דין קדשים קלים לקדשי הקדשים כי הבעלים אינם זוכין בחלקם מקדשים קלים אם לא משל גבוה כמו שיתבאר בג"ה ובזה יתבאר שאם היה משל הקדש בשעת מכירה או טביחה אינו משלם ד' או ה' כבר נתבאר זה השרש מבבא קמא:
@33 **השרש** הי"ג הוא שהמוכר הגנבה אפילו לפני בעלים שאין מכירתו מכירה משלם תשלומי ד' וה' אם היה הנמכר שור או שה שנאמר וטבחו או מכרו בעת שיתחייב על הטביחה יתחייב על המכירה והוא מבואר שפועל הטביחה שלם באי זה שהיתה הטביחה וכ"ש אם טבח ומכר אחר יאוש בעלים שהרי מכירתו מכירה כי כבר קנאה הגנב ביאוש הבעלים כמו שיתבאר בשרשים הכוללים ואע"פ שכבר אפשר שיאמר אומר כי שלו היה טובח ושלו היה מוכר ואין ראוי שישל' תשלומי ד' וה' כי לזה הועילו שני הפרטים שזכרה התורה בזה ללמד שכבר יתחייב בזה בין לפני יאוש בין לאחר יאוש כי המכירה לא תהיה באופן שלם כי אם אחר יאוש הבעלים והטביחה תהיה אפילו לפני יאוש ובעת שיתחייב על הטביחה יתחייב על המכיר' ולזה יתחייב באלו התשלומין בין לפני יאוש בין לאחר יאוש ולה הוא מבואר כי שלו הוא טובח ושלו הוא מוכר אם הוא משלם תשלומי כפל כבר נתבאר זה השרש בשביעי מבבא קמא:
@33 **השרש** הי"ד הוא שאם היה מה שטבח ומכר מתחלף במינו באופן מה ממה שנגנב כאלו תאמר שגנב טלה ונעשהו איל עגל ונעשה שור אינו משלם תשלומי ד' וה' שנאמר וטבחו או מכרו רצה בזה שיהיה מה שגנב הוא מה שטבח או מכר אבל משלם תשלומי כפל בשעת הגנבה וכן הענין אם קנה הגנבה בשנוי מעשה כגון שגנב כסף ועשה ממנו כלים ר"ל שהוא משלם כפל בשעת הגנבה לא בשעת העמידה כדין שנאמ' אם המצא תמצא בידו הגנבה ר"ל שתהיה הגנבה בעינה לא אחר שנשתנית כבר נתבאר זה השרש בשביעי מבבא קמא:
@33 **השרש** הט"ו הוא שהטובח שחיטה בלתי ראויה לאכול לישראל כאלו תאמר שנתכלה בידו אינו משלם תשלומי ד' וה' וזה כי לא יכנס בגדר הטביחה לפי שאינו ראוי לתכלית מה שכיון בו בטביחה אלא אם היתה זאת הפעולה לרפואה או לכלבים כי זה הוא מועיל למה שכיון בו כבר נתבאר זה השרש בשביעי מבבא קמא:
@33 **השרש** הי"ו הוא שלא יתחייב לתשלומי ד' וה' מפני המכירה אם לא מכרה כלה שנאמר וטבחו או מכרו כשם שהטביחה היא לכללות גופה מן הנמכר במכירה ולזה אם שייר בה ממכירתו אותה דבר הנתר עמה בשחיטה לא יתחייב בזה הקנס ואם קטע ממנה אבר ואח"כ מכרה הנה זה הדבר בספק לפי שיש לאומר שיאמר שכיון שלא שייר לו דבר הנתר עמה בשחיטה כשמכרה אחר שקטע ממנה אבר הרי זאת המכירה דומה לטביחה ויש לומר שיאמר שכיון שלא מכר כל הגוף שגנב והוא הראוי לטביחה אין אני קורא בו וטבחו או מכרו ר"ל שאין מה שמכר הוא הדבר שנגנב וכן כשמכרה שייר לו במלאכה דבר מה ר"ל שהתנה שיהיה לו חלק מה במלאכתה ל' יום הרי הדבר בזה בספק וזה כי מפני שלא שייר לו בגופה שום דבר יש לאומר שיאמ' שאין זה שיור ישי' זאת הטביחה דומה למכירה ויש לאומר שיאמר שאין זה דומה לטביחה כי הטביחה תסיר ממנו הנאת תועלת ההנאה במלאכתה אחר שטבחה מה שאין כן בזאת המכירה ולזה יהיה באלו הדבר בספק והמוצא מחברו עליו הראיה כבר נתבאר השרש בששי מבבא קמא:
@33 **השרש** הי"ז הוא שלא יתחייב בד' או ה' אם טבח או מכר אם לא גנב תחלה שנאמר כי יגנוב איש שהוטבחו או מכרו כבר נתבאר זה השרש בשביעי מבבא קמא:
@33 **השרש** הי"ח הוא שמה שהיה ראוי שתשביח הגניבה בעצמותה כמו גזותיה ולדותיה הוא לבעלים לפני היאוש אך לאחר יאוש הוא לגנב וזה מבואר מהשרשים הכוללים ואם השביחה הגנב כאלו תאמר שהוציא הוצאת מה מפני מה אפילו לפני היאו' השבח לגנב וכן אם הכחישה הגנבה הפחת על הגנב ומשלם כשעת הגנבה תשלומי כפל ותשלומי ד' וה' כאלו תאמר שהשבח והפחת לגנב אך במה שהשביח לבעלים משלם לפי מה שהיא עם השבח תשלומי כפל ותשלומי ד' וה' וכן אם דרך הדבר הנגנב שיתיקר בעת מוגבל מהשגה דרך מזל וטבחו או מכרו משלם הכל כשעת העמדת בדין כי זה הפרי היה לבעלי' בזה הדבר הנגנב כי הם כבר ימתינו למכור אל העת שימכר יותר ומזה יתחייב שאם נפסדה הגנבה מעצמ' זה קודם העת לא ישלם הגנב אלא כשעת הגניבה תשלומי כפל או תשלומי ד' וה' וההפך אם החלה הגנבה כי אין דרך האדם להמתין מכירת קניניו אל העת שימכרו בו פחות ולזה משלם הכל בשעת הגנבה כבר נתבאר זה השרש בשביעי מבבא קמא:
@33 **השרש** הי"ט הוא שתשלומי כפל אינם נוהגים כי אם במטלטלין שגופם ממון כי לא נזכר בתורה זה העונש כי אם בכסף ובכלים ובעלי חיים שגופן ממון ולזה לאינהג זה הדין בקרקעות ולא בעבדים ושטרות כמו שהתבאר בשרשים הכוללים ושתלומי ד' וה' אינן נוהגין בשור וזה וזה מבואר בעצמו מלשון התורה כבר נתבאר זה השרש בשביעי מבבא קמא:
@33 **השרש** הכ' הוא שאין הגונב אחר הגנב משלם תשלומי כפל ותשלומי ד' וה' שנאמר וגונב או ביאוש הבעלים או בשנוי מעשה כי אז הוא אדון לזאת הגנבה כבר נתבאר זה השרש בשביעי מבבא קמא:
@33 **השרש** הכ"א הוא שלא יתחייב הגנב תשלומי כפל ותשלומי ד' וה' אלא כשהוצרך הבעל דין שיבא הגנב לפני ב"ד לחייב אותו על פי עדים בב"ד שנאמר אשר ירשיעון אלהים ישלם שנים לרעהו אך אם היה הוא המרשיע עצמו כאלו תאמר שהודה מעצמו שטבח ומכר אינו משלם קנס וזה השרש כולל לכל הקנסות ר"ל שהמודה בהם פטור כבר נתבאר זה השרש בשביעי מבבא קמא ובמקומות רבים מהתלמוד:
@33 **השרש** הכ"ב הוא שהאיש שגנב לרעהו או שנמכר בגנבתו אם אין לו דבר לשלם הגנבה אך האשה אינה נמכרת בגנבתה שנאמר כי יגנוב איש שור או וגומ'. ואם אין לו ונמכר בגנבתו וכבר יתבאר לך שלא נלמד מזה שיהיה זה הדין באשה לפי שלא מצאה התורה צד לאשה שימכרוה אחרים זולת האב מכירת בתו ומשם נלמד בזה האופן מהאב שהאב מוכר את בתו לא את בנו ושב"ד מוכרין את האיש בגנבתו לא האשה כי אין צד יתכן שימכרוהו ב"ד אם לא בגנבתו וזה מבואר בחפוש במשפטי התורה כבר נתבאר זה השרש בראשון מקדושין:
@33 **השרש** הכ"ג הוא שהגנב אינו נשכר כי אם בגנבתו לא בכפלו ולא בתשלומי ד' וה' ולזה אם היו דמי מכירתו לשש שנים יותר מערך הגנבה אינו נמכר כי דמיו ראויין שיהיו נכללין בגנבתו שנאמ' ונמכר בגנבתו שזה הענין אם גנב דבר אחד או גנב דברים רבים לאיש אחד או לאנשים רבים והשאר ישאר עליו חוב עד שיעשיר וזה מבואר בנפשו חי ובו כי מלת גנבה תאמר על דברים רבים. כמו שתאמר על דבר אחד עם שכבר יראה כי כוונת התורה שלא להעמיס עליו אם אין לו לשלם להמכר ליותר משש שנים ואע"פ שהיתה הגנבה יותר שוה אלף דנרי זהב ולזה יתבאר גם כן שאם גנב לאנשים רבים אינו נמכר על כל אחת מהגנבות שש שנים אך נמכר לשש שנים ומחלקין ביניהם לפי הראוי ואם חזר וגנב למי שנמכר בעבור גנבתו הנה יראה לזאת הסבה שאינו נמכר שנית ועוד שהתורה אמרה ונמכר בגנבתו והוא מצורף אל בעל הגנבה מורה הוראה כי בעבור גנבתו שגנב לזה או לאלו הוא נמכר וזה יהיה פעם א' לא יותר אך אם גנב לאיש אחר או לאנשים אחרים אחר שנמכר חוזר להמכר אפילו כמה פעמים כבר נתבאר זה השר' בראשון מקדושין:
@33 **השרש** הכ"ד הוא שהעד הזומם אינו נמכר בזממו ר"ל בב"ד אם העיד שגנב ראובן גנבה מה והוזם שנאמר ונמכר בגנבתו. בגנבתו לבד הוא נמכר לא בסבת דבר אחר וכבר יתבאר זה ביאור שלם יותר ממה שאומר וזה שהמכירה הזאת אינה מתחייבת בעצמות מזה העדות אבל תתחייב ממנו במקרה מפני שאין לו לשלם ולזה אין אני קורא בו כאשר זמם לעשות לאחיו ואולם יתחייב לו ממון והוא מה שהיה מחייבו מהממון בזה העדות ואם אין לו יהיה עליו חוב עד שיעשיר כבר נתבאר זה השרש בראשון מקדושין:
@33 **השרש** הכ"ה הוא שהכא במחתרת אין לו דמים אם הרגו בעל הבית או אחר שנאמר אם המחתרת ימצא הגנב וגומר לפי שהוא כמו רודף להרוג נפש ואע"פ שבא על עסקי ממון כי דעתו היה שאם יעמוד אחד מבני הבית למנעו מלקיחת הממון יהרגהו ומזה יתבאר שאין הבדל בזדה בין נמצא במחתרת גדול או קטון זכר או נקבה ואע"פ שהקטן אינו בן עונשין כי אין הכונה בזאת המיתה כי אם להציל הנפש או הנפשות הבא להרגן ולזאת לא תהיה זאת ההמתה ע"י ב"ד ובהיות הענין כן הנה לא תיקר בזה נפש הנקבה או הקטן מנפש הגדול. וזה מבואר מאד כבר נתבאר זה השרש בראשון ובשמיני מסנהדרין:
@33 **השרש** הכ"ו הוא שאם היה ברור שלא בא להרוג אסור להרגו שנאמר אם זרחה השמש עליו דמים לו כאלו תאמר שהיה יושב מהמחתרת בין שגנב בין שלא גנב וכן אם בא במקום לגנוב שחזקתו שאין הבעלים שם כגון שבא לתוך גנו או לתוך הדיר שהדבר מוכיח שלא בא אלא על עסקי ממון וכן האב הבא במחתרת של בנו שחזקתו שלא בא להרוג כי רחמי האב על הבן הלא תראה כי דוד היה מצוה לעבדיו שלא להרוג לאבשלום ואע"פ שהיה צודה את נפשו כבר נתבאר זה השרש בשמיני מסנהדרין:
@33 **השרש** הכ"ז הוא שהבהמה מועדת מתחלתה דרך הלוכה כאלו תאמר לדרוס ברגליה הירקות והפירות והכלים הקטנים ולאכול הדבר הראוי לה אפילו על ידי דחק' ולזה תמצא שלא זכרה התורה תמות והעדה באלו ההיזקים והוא מבואר שמה שיתכן שתזיק דרך הלוכה יכלול שיהיה ההיזק הזה ברגליה או בשאר חלקי גופה כאלו תאמר בשערה בזנבה או בדבר הדבק לגופה כמו פרומיא שבפיה ועגלה המושכת בקרן ומה שידמה לזה ומה שיתכן שתזיק באכילה יכלול מה שידמה לזה ממה שיתכוין בו להנאתה ותזיק כאלו תאמר שנתחככה בכותל להנאתה כי כבר תמצא בנזקי הבור שיתחייב האדם בהם. ואין בנזקין ההן שום הנאה לבעל הבור ובזה יתבאר שהוא יתחייב על נזקי הרגל ואם אין בהם תועלת לבעל הבהמה וג"כ אלו לא היה חייב בנזקי השן אלא מפני ההנאה המגעת לבעל הבהמה לא הה ראוי שישלם כי אם בשעור מה שנהנה לא כשעור מה שתזיק וזהו הפך מה שאמרה התורה מיטב שדהו ומיטב כרמו ישלם כבר נתבא' זה השרש בראשון ובשני מבבא קמא:
@33 **השרש** הכ"ח הוא שלא יתחייב על נזקי שן ורגל אלא כשהזיקו ברשות הניזק שנאמר ובער בשדה לא ברשות בעלים. והיה זה כן כי בעל הפירות הוא פושע אם הניח שם פירותיו כי יותר מיוחד רשות הרבים להניח שם הבהמות מלהניח שם הפירות או הכלי' ולזה הוא מבואר שאם היתה רשות מיוחדת לזה ולזה בעל מבהמה חייב בנזקי שן ורגל שאני קורא בו ובער בשד' אחר והנה הוא פושע על שלא שמר בהמתו שם כיון שהוא יודע שאם ימצאו שם פירות או כלים יתכן שיוזקו בסבתה ומזה יתבאר שאם אכלה הבהמה מתוך הרחבה פירות שבצדי הרחבה פטורה מלשלם מה שהזיקה כי יש לה רושת ללכת שם יותר ממה שיש רשות לבעל הפירות להניחם בצדי הרחבה ואולם אם עמדה הבהמה כלה בצדי הרחבה ומשם אכלה הפירות שמצדי הרחבה משלמת מה הזיקה כי יותר יש רשות לבעל הפירות להניחם שם ממש שיש רשות לבהמה ללכת שם וכן אם קפצה על גבי חברתה ברשו' הרבי' ואכלה פירות שעליה משלמת מה שהזיקה שהרי אני קורא בה ובער בשדה אחר אבל אם אכלה ברשות הרבים פירות שעל גבי חברתה פטורה שאין אני קורא בזה וביער בשדה אחר וזה מבואר מאד והוא מבואר שגם במקומו' שהיא פטורה מלשלם מה שהזיקה משלמת מה שנהנות והוא מה שנהנו הבעלים בזאת האכילה כבר נתבאר זה השרש בשני מבבא קמא:
@33 **השרש** הכ"ט הוא שלא יתחייב האדם בנזקי שן ורגל אם שמר בהמה כראוי כאלו תאמר שנעל בפניה כראוי וזה אמנם היה אם נעל בפני' בדלת שיכולה לעמוד ברוח מצויה אבל אם היה פושע בשמירתה חייב לשלם שנאמר ושלח את בעירה ובער בשדה אחר שיהיה הוא המשלח או המבעיר או שפשע בשמירתה שהיה אנוס בזה כאלו תאמר שהוחלק ונפלה לגנה או שנתקלה באונס לגנה כי אין בזה פשיעה לבעלים כבר נתבאר זה השרש בראשון מבבא קמא:
@33 **השרש** ה"ל הוא שהבהמה מועדת לאכול הראוי לה וכן היא מועדת למה שנלוה לה מהיזק הכלים אשר האוכלין בהם כמו התרנגולין שהיו מחטטין בחבל שבו עיסה ופסקוהו או גדי שראה אוכל על החבית וקפ שם לאכול האוכל ושבר הכלי זה הוא מנהג הב"ח אך אם שנה בזה הפועל ר"ל שלא עשהו באופן הנהוג הרי הוא תם לזה ההיזק כמו שקדם בנזקי הנגיחה ותולדותיה וכן אם אכלה דבר שאינו ראוי לה אפילו ע"י הדחק כאלו תאמר שאכלה כסות או כלים או חתול שאכל תרנגולין גדולים. כבר נתבאר זה השרש בשני מבבא קמא:
@33 **השרש** הל"א הוא שהבהמה שלקחה כלים ברשות הנזק והוציאה כלים ואכלתן ברשות הניזק כאלו תאמר שהוציאתם מביתו ואכלתן בשדהו משלמת מה שהזיקה וכן אם היתה מהלכת ברשות הרבים ואכלה משם פרות ברשות הנזק שהרי אני קורא בו ובער בשדה אחר ואולם אם היתה הבהמה ברשות הנזק ופרותיו ברשות הרבים ואכלה משם אלו הפרות הנה זה הענין ספק אם משלמת מה שהזיקה אם לא וזה כי יש לאומר שיאמר שאין אני קורא בה ובער בשדה אחר כי כוונת זה המאמר הוא שיהיו הפירות ברשות הניזק כמו הענין בשדה שהפירו' נמצאים בו ובהיות הענין כן והנה זה הדבר בספק והמוציא מחברו עליו הראיה כבר נתבאר זה השרש שני מבבא קמא:
@33 **השרש** הל"ב הוא שמי ששמר בהמתו כראוי. ובא אחר והעמידה על קומתו של חברו ואכלה שם פירו' או שפרץ גדר המקום שהיא משתמרת שם כראוי הבעלים פטורי' וזה הגורם לנזק הוא חייב לשלם כי הוא לבדו הפושע בזה ואם היו הבעלים פושעים גם כן כאלו תאמר שלא נעלו בפניה כראוי או שהיו כותלי המקום ההוא רעועות הרי הבעלים חייבים לפי שהם פושעים וזה האחד פטור מדיני אדם אך הוא חייב בדיני שמים כי אולי לא הזיקה הבהמה אם לא הביא אותה לזה כבר נתבאר זה השרש בששי מבא קמא:
@33 **השרש** הל"ג הוא שאם הכניס אדם פירותיו או כליו ברשו' המזיק שלא ברשותו והזיקה בהם בהמתו של בעל הבית באלו תאמר שנתקלת בם ונפלה בעל הפירות או בעל הכלים חייב בנזקי הבהמה ואם שברתן הבהמה או אכלתן המזיק פטור מלשלם מה שהזיקה ואם אכלתן והוזקה באכילתן בעל הפירות פטור לפי שאין דרך הבהמה להנזק באכילתן ולזאת הסבה בעינה יהיה פטור אדם הנותן סם המות לפני בהמת חברו ואכלה ומלתה אך הוא חייב בידי שמים כי הוא גרם זה הנזק כבר נתבאר זה השרש בששי מבבא קמא:
@33 **השרש** הל"ד הוא שהבהמה שהזיקה פירות המחוברין שהן צריכין לקרקע אין משערין מה שהזיקה בפני עצמו כי אם על גב הקרקעות שנאמר מיטב שדהו ומיטב כרמו ישלם ר"ל מה שהיה שדהו יותר שוה עם אלו הפירות מה שהוא פחות מאחד מששים הוא בטל במעוטו ולזה הוא מבואר שלא ישערו זה על שדה הוא יותר מששי' בזה הדבר הנאכל או הנשחת מפירות השדה לא יאכל בכמו זה מיטב שדהו לפי שהשדה לא תמכר בפחות דבר מורגש מפני זה החלק הקטן ממנה הנאכל ולפי שכל בהמה שישערו זה הנזק על גבי השדה יותר קטנה יהיה ערך הנזק יותר גדול והוא מבואר מהשרשים הכוללים שאין מוצאין ממון מיד המחזיק בו אלא מפני דבר שאין בו ספק שהוא חייב בזה הממון הנה לא ישערו הנזק כי אם בששי' מדבר הנאכל פחו' דבר בלתי מורגש ולזה ישערו זה הנזק בששים כאלו תאמר שאם אכלה פירות ערוגה אחת או השחיתה אותם משערים זה בשדה שהיא ששי' ערוגות ואולם אם היו הפירות גמורין משערין אותם בפני עצמן כבר נתבאר זה השרש בששי מבבא קמא:
@33 **השרש** הל"ה הוא שהמוסר בהמתו לשומר פטור מנזקיה והשומר חייב כי הוא הפושע בזה אך אם לא קבל עליו השומר לשמור השמירה שיפטרו בה הבעלים חייבים וזה מבואר בנפשו כבר נתבאר זה בראשון וברביעי מבבא קמא:
@33 **השרש** הל"ו הוא ששור שהזיק והמית האדם דנין אותו דיני ממונות ואחר כך דנין אותו דיני נפשות שאם דנוהו תחלה דיני נפשות לא יוכלו לדונם אחר זה דיני ממונות כי מפני שנגמר דינו בסקילה הרי אין לו בעלים כי הוא אסור בהנאה ולא יהיה להם דרך לדונו אחר זה בדיני ממונות כי אין לו בעלים שיעמדו על שורם ולזה לא יתחייבו הבעלים לשלם הממון ההוא ואם דנוהו אחר זה דיני ממונו' לא ישתלם זה הממון כי אם מהשבח שהשביח בדדיה משגימר דינו עד שיסקל כי הבעלים אינם חייבים בו לפי שאינם בעליו בעת שדניהו דיני ממונות ולזה לא היה להם דרך להפך בזכותו מה שאפשר ואולם אם היה מת לא יתכן לדונו כי אם בדיני נפשות כי מפני שהוא נסקל אם שם צד יוכל להשתלם מגופו חצי הנזק ההו' כבר נתבא' זה השרש בח' מבבא קמא ומזה המקום יתבאר ששור שנגמר דינו לסקילה ואחר כך הוזמו עדיו כל הקודם בו זכה לפי שמהעת שנגמר דינו לסקילה השמיטו הבעלי' ידם ממנו והפקירוהו וכבר נתבאר זה בששי מכריתות:
@33 **השרש** הל"ז הוא מה שתזיק בו הבהמה לפי דרכה שאינו מחובר לה כמו הצרורות המנודין מתחת רגליה בהליכתה או תרנגולין ששברו כלי' ברוח שבכנפיהם היה היזקן ברשות הניזק הנה דינם לשלם חצי נזק. וזה כי לא נוכל לבאר מדברי התורה שיהיה דינם דין הרגל כי לא חייבה התורה בתשלומי הנזק הזה כי אם ששלח בעירה לא הדבר הבא מכח בעירה אך זכר זה באדם שנאמר באבן או באגרוף וגם משם לא נאכל ללמוד זה הדין כי האדם יעשה זה כדי להזיק אן הדבר המוכה באבן ההוא מה שלא יקרה זה בצרורות ולפי שדרך הבהמה להזיק בכך אי אפשר לפוטרו כי כונת התורה להסיר ההיזקים מבני אדם ולזה חייבה התם לשלם חצי נזק ואע"פ שאין לבעלי' להעלות על לבם שיגיע היזק מבהמתם בזה האופן וכ"ש שראוי לחשבם בזה המקום שדרך הבהמה להזיק בזה האופן ולזה הוא ראוי שלא לחייבם יותר מחצי נזק כי אינם בתשלומי הנזק בזה האופן כמו שהם ראויים מתשלומי הנזק במה שהזיקו מגופם או במחובר לגופם ואינו ראוי שיהיה משתלם מגופם חצי הנזק הזה כי ידמה שלא נתנה התורה זה הדין כי אם כמה שהיה לבעלים להעלות על לב ולזה די אם יעשו שווי גוף הבהמה המזקת ואמנם בזה המקום לפי שדרכה בכך היה לבעלי' להעלות זה על לבם ולזה ראוי שישלמו זה מביתם כבר נתבאר זה השרש בראשון ובשמיני מבבא קמא:
@33 **השרש** הל"ח הוא שהבהמה שביעטה והתיזה תרורו' מחמת הבעיטה והזיק ברשות הניזק הנה יפול בזה ספק אם יש שנוי לצרורות לרביע נזק אם יהיה דינם כמו דין נזק הבעיטה כיון שכוונתו להזיק והתורה לא הבדילה בזה בין שיהיה ההיזק במה שבא מכח המזיק ובין שיהיה במה שיבא מגוף המזיק או המחובר לו שנאמר באבן או באגרוף והמוציא מחברו עליו הראיה כדין כל הספקו' ואמנם אם זיקה בזה האופן ברשות הרבים יהיה בזה ספק עוד אם דינם דין הרגל שפטור עליה ברשות הרבים או דינם דין בקרן שחייב עליה ברשות הרבים וישלם רביע נזק מגופה והמוציא מחבירו עליו הראיה כבר נתבאר זה השרש בשני מקמא והוא מבואר שאם הכניס תרנגול ראשו לאויר כלי זכוכית ותק בו ושברו בקולו אין בה שנוי בצרורות אם היה בכלי אוכל או משקה כי כמו שדרכו להכניס ראשו שם לקחת המאכל או המשקה כן דרכו לתקוע שם וכן הענין בסוס שצנף וחמור שגער והזיקו בקולם בזה האופן ואולם לא היה שם אוכל או משקה הרי זה שנוי בצרורות ודיני דין הצרורות הנזכרים כבר נתבאר זה בשני מבבא קמא:
@33 **השרש** הל"ט הוא שהבהמה שכבשה בזנבה או באמתה כשכוש רב ברשות הרבים והזיקה בזה האופן הנה יפול ספק אם דינה דין הרגל כיון שדרכה לכשכש בזנבה או באמתה או יהיה דינה דין השנוי כיון שאין דרכה לכשכש כשכוש רב והמוציא מחברו עליו הראיה כבר נתבאר זה השרש בראשון ובזני מבבא קמא:
@33 **השרש** המ' הוא שהמדליק בתוך שלו אם היה אפשר להבערה ההיא שתבער רשותו בעת הדלקה או שנפלה אחר זה הגדר אשר בחצרו והיה לו פנאי לגדרה קודם שתעבור האעש רשותו ולא גדרה והזיקה דבר גלוי במקום שאפשר לה חייב לשלם זק שלם. ואפי' על הניר והאבנים אם לחכה הניר וסכסכה האבנים לפי שדרך האש לאכול דבר הראוי לו לאכול ואפי' ללחך נירו ולסכסך אבניו שנאמר ומצאה קוצים ונאכל גדיש או הקמה או השדה אלא אינו חייב על הדבר הטמון כי התורה לא זכרה אלא הדברים הגלוים ולזה אם הניחו בגדיש אפילו הכלים שדרכן להטמין בגדיש כגון מוריגין וכלי הבקר לא יתחיב בעל האש אלא כאלו היה הכל גדיש אבל הזיקה במקום שאינו ראוי לעבור בו הדלקה ההיא פטור שנאמר כי תצא אש ומצאה קוצים וזהו כדרכה תתלקח בהם כבר נתבאר זה השרש בשני מבבא קמא:
@33 **השרש** המ"א הוא שמדליק בתוך רשות חברו והיזק או מת האדם חייב כאלו הזיק או הניח בידו ולזה הוא מבואר שהמדליק בזה האופן יתחייב על הטמון שנשרף בסבת הדלקה ויתחייב על המתת האדם כשלא היה לאיש ההוא דרך להמלט מהשרפה ויתחייב גם כן על חמשת דברים אם הזיק באדם כאלו הזיק בידי' כבר נתבאר זה השרש בשני מבבא קמא:
@33 **השרש** המ"ב הוא שתולדות האש דינם כדין האש כלומר אם הניח אבנו סכינו ומשאו בראש גגו ונפלו ברוח מצויה והזיקו כי כמו שהאיש דרכו לילך ולהזיק באמצע העצים שימצא בדרכו כן דרך האבן הראוי ליפול ברוח מצויה כבר נתבאר זה השרש בשני מבבא קמא:
@33 **השרש** המ"ג הוא שאם היה הנזק באש פושע שאם לא פשע לא היה נזק בא על האש פטור ויתחייב גם כן זה שפשע בנזקי האש אשר הוא סבתם כאלו תאמר שהיה גמל טעון פשתן עובר ברשות הרבים ונכנס פשתנו לתוך החנות והודלק בנרו של חנוני והדליק את הבירה בעל הגמל חייב כי הוא הפושע בזה מפני שהרבה במשאו באופן שיכנס לחנות ולא יכילהו המבוי אשר שם כבר נתבאר זה בשביעי מבבא קמא:
@33 **השרש** המ"ד הוא שהמבעיר הוא אשר יתחייב לא מי שהוא סבה רחוקה והמשל שמי שמסר נחלת לחרש שוטה וקטן והדליקו בה אש והזיקה פטור כי הוא אינו המבעיר לזה האיש כי דרך הגחלת להכבו' לא להתפשט ולאכול סביב לכל סביבותיה וכן אם הביא אש ולא היו שם עצים ובא אחר והביא שם עצים והודלק האש הנה השני הוא המבעיר ואם בא השלישי וליבה האש הנה השלישי הוא המבעיר לא הראשוני' כי כבר היה האש כבה לולי לבוי השלישי. ואם לבתו רוח שאינה מצויה כלם פטורים כי לא היה האש ראוי להתפשט לולי הרוח שאינ' מצויה שלבתו כבר נתבאר זה השרש בשביעי מבבא קמא:
@43 **וכן יתן איש עד כי יפתה איש בתולה:**
@43 **ביאור דברי הפרשה:**
@43 **השרש** הראשון הוא שאין השומרים משועבדין בדבר עד שיגיע לאדם ושיקבלו עליהם לשמור שנאמר בשומר חנם כי יתן איש אל רעהו כסף או כלים לשמור ובשומר שכר נאמר כי יתן איש אל רעהו חמור או שור או שה וכל בהמה לשמור ובשואל נאמר וכי ישאל איש מעם רעהו והנה ענין השאלה מעם רעהו מורה שיגיע לידו מיד רעהו ויורה עם זה שהוא מקבל לשמרו ולהשיבו כבר נתבאר זה השרש בראשון וברביעי ובששי ובשמיני ממציעא ומזה המקום יתבאר שמי שהפקידה בידו מעות לחלק לעניים בלתי ידועים או לפדיון שבויים בלתי ידועים ונאנסו בפשיעה פטור מלשלם שהרי לא נהנו בידו לשמור כי אם לבזבז לחלק ואין גם כן בכאן איש ידוע או אנשים ידועים שיהיה זה הפקדון שלהם והרי הוא מפני זה ממון שאין לו תובעים ואולם אם היה מוכן לחלק לאנשי' ידועים הנה הפקדון בידו לשמור לכל אחד מהם חלק ולה יהיה דינו כדין שומר כבר נבתאר זה השרש בשמיני מבבא קמא:
@43 **השרש** השני הוא שאין דין השומרים נוהג אלא בדברים שנתנום מתחלתן מאיש לרעהו לא ממי שאינו רעהו כמו ההקדש ומה שידמה לו שנאמר כי יתן איש אל רעהו חמור או שור או שה וכל בהמה לשמור כי ישאל איש מעם רעהו ולזה הוא מבואר שאם היה הדבר שנתן לו משל הקדש או ממי שאינו רעהו ואחר כן שב להיות רעהו טרם שיצא הפקדון או השמלה מידו הנה דינו דין הפקדון שלא נתנו לו רעהו כבר נתבאר זה השרש בשמיני מבבא מציעא:
@43 **השרש** השלישי הוא שאין דין השומר נוהג אלא במטלטלין שגופן ממון כמו כסף או כלים או חמור או שור או שה או שלמה שהם הפרטים שזכרה התורה כזה כבר נתבאר זה השרש בחמישי מבבא מציעא:
@43 **השרש** הרביעי הוא שהשולח ידו להשתמש בפקדון כאלו היה שלו הנה קנאו מהעת ההוא ולזה יתחייב לשלמו לבעלים אפילו נאנס באונס גדל אפילו מת מעצמו ואפילו היה שומר חנם שנאמר אם לא שלח ידו במלאכת רעהו הא אם שלח לא יפטרהו שום אונס שהרי ביד של שומר נאנס לא של בעלים כבר נתבאר זה השרש בשני ושלישי ממציעא:
@43 **השרש** הו' הוא שהשואל שהיו בעליו עמו במלאכתו בשעת מלאכה פטור מהכל ואפילו מהפשיעה שנאמר ואם בעליו עמו לא ישלם כ"ש אם יהיה זה הדין בשאר השומרים וראוי שתדע שאם היו עמו בשעת שאלה אעפ"י שינם עמו במלאכתו בשעת האונס דינו דין שאלה כבעלי' שהרי בעת השאלה לא נשתעבדו הבעלים בשמירה כלל ואם לא היו עמו בשעת שאלה אע"פ שהיו עמו במלאכתו בשעה שנאנסה אינו דינו דין שאלה בבעלים כי כבר נשתעבד בשמירה בעת השאלה וכן ענין בשאר השומרים משל השאלה בבעלים כגון שהיה זה ששאל ממנו מלמד בנו או המקיז לו דם או הסופר שלו או אמר לו השקני מים והשאילני בהמתך והשקהו מים והשאילתו בהמתו או שאמר לו שמור לי היום ואשמור לך היום וכן אם שאל מאשתו או שותפין ששאלו זה מזה וכ"ש אם השאיל בהמתו או השכירה לשאת משא ויצא עמה לעזור לשואל או לשוכר לטעון הבהמה אך אם יצא עמה לראות המשא שלא יטעון עליה יותר מדאי אין זו שאלה בבעלים כי אינו עמו במלאכה השואל או השוכר ואם אמר לו שמור לי היום ואשמור לך מחר נעשו שומרי שכר זה לזה וכן אם אמר השותף השאילני היום ואני אשאילך מחר ואם נשאל מהאשה ונשאל לו לבעלה אינו שאלה בבעלים כי אע"פ שהפרות לבעל אינו בעל הדבר ההוא כבר נתבאר זה השרש בשמיני מבבא מציעא:
@43 **השרש** השביעי הוא שהשאלה בשליח הבעלים אינה שאלה בבעלים שנאמר אם בעליו עמו הוא ולא שלוחו וזה מבואר מהסבה שנתננו בענין השמיר' בבעלים בביאור לזאת הפרשה אך אם השאיל עבדו הכנעני עם פרתו הרי זו שאלה בבעלים כי לזה השאיל לו עבדו שיזהר בשמירת הפרה ובכלל הנה יד העבד הכנעני היא כיד רבו כשעשה זה מדעת רבו אך אם נשאל העבד מעצמו אינה שאלה בבעלים. וזה מבואר מאד כי אין לו רשות להשאל מעצמו ולהזיק בזה לרבו כבר נתבאר זה השרש בשמיני מבבא מציעא:
@43 **השרש** השמיני הוא שהשאלה היא לפי השרשי' הכוללים לעשות בו שזה פרוטה כי פחות מזה אינו נחשב למאומה אלא כי מפני שכבר יקרה לפעמים שישאל האדם למה שאין בו שוה פרוטה בהמה או כלים הנה יפול ספק אם שאל בהמה בבעלים לעשות בה פחות משוה פרוטה או אם שאל שתי פרות בבעלים לעשות בהם שוה פרוטה יהיה בכל מה שיעשה בכל אחת מהם פחות משוה פרוטה הנה הדבר בספק אם היה זה שאלה בבעלים אם לא והמוציא מחברו עליו הראיה כבר נתבאר השרש בשמיני ממציעא:
@43 **השרש** התשיעי הוא ששואל מהשותפין ונשאל לו אחד מהם הוא בספק אם יקרא זה שאלה בבעלים שהן בעלים באופן מה ואינם בעלים בשלמות והמוציא מחברו עליו הראיה כבר נתבאר זה השרש בשמיני מבבא מציעא:
@43 **השרש** העשירי הוא שהשומרים הם בגדרם לשמור עד שיגיע הדבר ההוא לידי הבעלים וזה מבואר בנפשו אך השואל שהחזיר דבר אחר זמן השאלה שאין לו להשתמש בו ואין לו רשות להשתמש בו ואין דינו דין שומר שכר שהרי קדמו חסד הבעלים כשהשאילו לו הדבר מה שחייבהו לשמור הדבר ההוא כבר נתבאר זה השרש בשמיני מבבא מציעא:
@43 **השרש** הי"א הוא שהמשאיל אינו יכול לחזור בו ממה שהשאיל עד שישלמו ימי השאלה כמו הענין במתנ' ושכירות וזה מבואר בנפשו ולזה אם השאילו כלי להשתמש בו משתמש בו השואל עד שלא יהיה ראוי להשתמש בו השמוש ההו' אשר שאלו עליו כבר נתבאר זה השרש בשמיני מבבא מציעא:
@43 **השרש** הי"ב הוא שמי ששאל שאלה בבעלים וחזר ושאלה שלא בבעלי' הנה הדבר בספק אם יקרא זה שאלה בבעלים כי יש לאומ' שיאמר כי זאת שאלה אחת נמשכת כל זמן ב' השאלות לפי שהתחלת השאלה הוא לבעלים הנה תקרא כלה שאלה בבעלים ואפשר שנאמר שלא היתה השאלה השנית שתשאר בידו על התואר שהיתה קודם משעבוד השמירה אבל היא שאלה בפני עצמה ולזה יהיה המוציא מחבירו עליו הראיה וכן הענין אם שאלה שלא בבעלים וחזר ושכרה בבעלי' כי לאומר שיאמר כי זה הוא כמו המסר שני והוא בבעלים ולזה יהיה הענין שמירה בבעלים ולזה יהיה המוציא מחבירו עליו הראיה ואולם אם שאל הבהמה בבעלים ואח"כ שכרה שלא בבעלים הנה הדבר מבואר כי על ההמסר הראשון המשיך השכירות ולה יהיה זה הענן שמירה בבעלים. כבר נתבאר זה בחמישי מבבא מציעא:
@43 **השרש** הי"ג הוא שבכלל הפשיעה יהיה נכלל האונס אשר השומר הוא סבה מה בהגעתו או שיהיה אפשר לו שישמור שלא יפול וזה מבואר בנפשו. והמשל שיאמר הרועה לאונס להראותו שאינו ירא ממנו במקום פלוני אנו רועים וכך וכך רועים אנחנו וכך וכך כלי מלחמה יש לנו ובא שם האונס ונתחזק כנגדם ואנסם הרי הוא פושע בזה וכן אם שכר האדם להעתיק יינו ממקום למקום והעביר חבית גדולה שאין דרך כל נושאי המשאים האלו להעבירה ונשברה או שהעמים על הבהמה יותר מהחוק הנהוג או שהוליכה בהר והוחלקה כל זה יהיה בכלל בגדר הפשיעה אם לא עשה זה ברצון הבעלים וכן אם היה יכול להציל כשיקרא רועים ויביא מקלות ולא קרא ולא הביא הנה הוא פושע אלא בשומר חנם לא תהיה פשיעה אם לא היה יכול להביא הרועים והמקלות בזולת שכר כי כבר הורה הקנין ההוא מאומה ואולם בשומר שכר יהיה פשיעה אם לא הביאם אפילו בשכר כי כבר הורה בעל הקנין שהוא רוצה לתת שכר לשמור זה הקנין. ולזה שכר מי שישמרהו וכן יקרא אונס מה שהתחלתו אונס יביא אל שימכרה קנין ההוא בידים כגון שהיו לסטים באים בבית השומר לאנסו כדי שיקחו הפקדון שבידו וקד' ונתן להם הפקדון קודם שהזיקוהו הרי זה אונס כבר נתבאר זה השרש בששי ובשביעי מבבא מציעא:
@43 **השרש** הי"ד הוא שאם היה הדבר הנפקד בידו נפסד מעצמו כאלו תאמר שהיה חמץ והיה קרוב לזמן אסורו ואין הבעלים במקום שיוכלו להשיבו להם תוך זה הזמן מהיתרו הנה מוכרו ברשות ב"ד בשום השב אבדה לבעלים עם שכבר נתנוהו בידו לשמור ולא לבוד והנה יהיה פושע באופן מה אם לא יציל מה שיוכל להציל לבעלי' ואולם יעשה זה ברשות ב"ד כי לא היה לו רשות מהבעלי' למכור מה שנתנו לו לשמור וזה גם כן ראוי להציל עצמו מן החשד ומן התרעומת וכן הדין במה שידמה לזה שיראה השומר שיפסידו יותר מן ההפסד שעלה בלב הבעלי' בעת שנתנו לו הפקדון לשמור כבר נתב' זה בג' ממציעא:
@43 **השרש** הט"ו הוא שהשומר שיטען טענה שיפטר בה מלשלם כמו שטוען שומר חנם שנגנב או טען שומר שכר שנאנס באנסין גדולים נשבע שהדבר כן ויפטר אם לא היה האונס במקום שדרכן שיהיו שם עדים להעיד עליו כי אז אומרים לו הבא ראיה והפטר שנאמר אין רואה שבועת תהיה בין שניהם. כבר נתבאר זה בג' ובו' מבבא מציעא. ובזה המקום יתבאר שלא יחוייב שיאמן האדם בשבועתו אלא במקומות שאי אפשר בזולת זה כי אז יתחייב שיאמן כאמרו ולקח בעליו וגו':
@43 **השרש** הי"ו שהשומר שמסר לשומר אחר שלא ברשות ובדעת הבעלים לא יתחייבו הבעלים להאמין זה השומר השני בשבועה כי כבר יאמרו לשומר הראשון אתה נאמן לי בשבועה וזה אינו נאמן לי בשבועה ולזה יפסיד השומר ראשון זה וישלם לבעלים אם לא ראינום מפקידים לזה השומר השני כי אז לא יוכלו לומר שלא יאמינוהו בשבועה והוא מבואר שאם היה הראשון שומר שכר והשני שומר חנם ויגנב הפקדון השני פטור והראשון חייב לבעלים ואם היה הראשון שומר חנם והשני שומר שכר ונגנב הנה השני משלם לבעלים לא לשומ' הראשון כי התורה לא פטרה שומר חנם בגנבה ואבדה לתכלית שירויח בזה אלא לתכלית שיפטר מלשלם וזה מבואר מאד ולזה אמר ולקח בעליו ולא ישלם כבר נתבאר זה השרש בג' מבבא מציעא ובז' מבבא קמא:
@43 **השרש** הי"ז הוא שהמלוה על המשכון דינו דין שומר שכר שהרי הוא עושה מצוה שנאמר ולך תהיה צדקה ופוטרתו מצדקה אחרת שהוא מחוייב בה ולזה פטר באונסין גדולים והלוה יתחייב להשיב לו מה שהלוהו אם נאנס המשכון באונסין גדולים כבר נתבאר זה בששי מבבא מציעא:
@43 **השרש** הי"ח הוא שהשומר חנם שטען שנגנב פקדונו ונשבע ואח"כ באו עדים והעידו בפני ב"ד שנשבע לשקר הרי זה משלם שנים ואולם אם הודה מעצמו פטור מהכפל שנאמר אשר ירשיעון האלהים ישלם שנים והוא הכפל אך אם הודה הוא בעצמו ולא יצטרך שירשיעוהו פטור מלשלם הלא תראה שהמכחש בפקדון ונשבע על שקר ואח"כ הודה משלם קרן וחומש כמו שיתבאר במה שיבא והוא שרש כולל לכל מודה בקנס שהוא פטור. והנה יקרא קנס מה שלא ישלם בשיעור מה שהזיק אבל ישלם יותר או פחות מלבד חצי נזק צרורות שהוא ממון כבר נתבאר זה השרש בב' ובט' מבבא קמא:
@43 **השרש** הי"ט הוא שמודה מקצת הטענה בכסף או כלים והדומה להם מהמטלטלים שגופם ממון חייב שבועה. שנאמר אשר יאמר כי הוא זה וכבר אמר קודם זה ונקרב בעל הבית אל האלהים אם לא שלח ידו וגומ' וכשומר שכר נאמר שבועת יי' תהיה בין שניהם אם לא שלח ידו וגומ' ומזה המקום יתבאר שאם לא היתה ההודאה חלק מהטענה לא יתחייב שבועה והמשל שאם תבע לו שור גדול והודה לו שור קטן אינו חייב שבועה כי אין השור קטן חלק מגוף השור הגדול אבל אם היתה הטביעה בשור וחטין והודה באחד מהמינים הרי הוא חייב שבועה כי כבר יתכן שיאמר בכמו זה אשר יאמר כי הוא זה. ומזה המקום יתבאר שלא יקרא מודה בקצת הטענה בטענת כסף אם הודה בפחות מפרוטה כי אינו נחשב למאומה כבר נתבאר זה בששי משבועות:
@43 **השרש** הכ' הוא שלא ישבע השומר על טענה אם היא פחותה משתי מעות כסף או על טענת כלי אפילו היה פחות משוה פרוטה כרי התורה אמרה כסף או כלים ולפי שהכסף הקטן שיהיה בתורה או הקשיטה אן הגרה שהיא מעה והכסף נאמר על הדבר והיה הרבוי הראון שנים הנה יתבאר שהשומר אינו נשבע על כפירת הכסף אם היה פחות משני מעין שהן משקל שנים ושלשה גרגירי שעורה בינונים מכסף צרוף ואולם על הכלים ישבע אפילו היה אחד שהרי נאמר על שלמה שהוא כלי והיה זה כן לפי שהכלי הוא מועיל בעצמותו ואולם הכסף אינו מועיל כי אם מצד מה שנקנה בו והקנין יהיה לפי הנהוג במספר מה מהמעות ומזה המקום ילמד זה הדין במודה במקצת כבר נתבאר זה השרש בב' משבועות. והפלא מהרב המורה שהסכים שיהיה השומר נשבע אפילו על טענת פרוטה. וזה שמה שהותנה בטענה שתהיה שתי כסף למדנו ממה שאמר בשומר חנם עם שזה גם כן הוא ממה שיתכן שיפול בין בעל הפקדון ובין השומר ר"ל שבעל הפקדון יאמר שמה שהפקיד בידו הוא כך והשומר לא יודה לו אלא בקצת ומזה נלמד זה הדין לכל מודה מקצת:
@43 **השרש** הכ"א הוא שאם לא היתה לה הטענה מוגבלת לא יהיה לה קצת יתחייב עליו שבועה בהודאתו כי לא יוכר בו הקצת מן הכל והמשל אם אמר לו כיס מלא דינרים מסרתי לך והוא אומר לא מסרת לי אלא צרור של דינרים ולא ידעתי כמה היו בו מהדינרים אינו חייב שבועה כי לא יתברר שיהיה מה שהודה פחות ממה שטענו כבר נתבאר זה בו' משבועות:
@43 **השרש** הכ"ב הוא שהמודה בדבר שאי אפשר לכפור כי אין הודאתו הודאה כגון שתבעו מאה דינר חמשים בשטר ונ' על פה והודה לו מה שבשטר שנאמר אשר יאמר כי הוא זה מה שיודע כי הוא זה ומצד מאמרו יצא זה שלא היה רושם במאמרו שאפילו כפר יתחייב בו כבר נתבאר זה השרש בראשון ממציעא:
@43 **השרש** הכ"ג הוא שהמודה מקצת הטענה ואמר הא לך פטור בשבועה שהרי אין זה מאמר לבד אבל מעשה והתורה אמרה אשר יאמר כי הוא זה שיהיה המאמר לבד יצא זה שהוא מעשה. כבר נתבאר זה השרש בראשון ממציעא:
@43 **השרש** הארבעה ועשרים הוא שהטוען טענת גנב בפקדון אינו משלם כפל אם לא היה בעל הפקדון גדול כשנתן לו הפקדון שנאמר כי יתן איש אל רעהו והיה זה כן לפי שנתינת הקטן אינה כלום כבר נתבאר זה השרש בט' מבבא קמא:
@52 **וכי יפתה איש בתולה עד וגר לא תונה:**
@52 **ביאור דברי הפרשה:**
@52 **השרש** הראשון הוא שהמפתה נערה בתולה שאינה מאורשה ובא עליה משלם חמשי' שקלים כס לאבי הנערה מפני הנאת שהשכיבה אם לא רצה אביה לתתה לו לאשה למדנו שהיא נערה ושהם חמשים כסף מדין אונס הנזכר בפרשת כי תצא והיה זה כן כי מפני שהבוגרת אינה בתולה בשלמות כי פתחה הוא כמו פתוח ולמדנו שזה יהיה מפני תאות השכיבה שנאמר בפרשת כי תצא ונתן האיש השוכב עמה וגומ'. והנ המפתה חייב עוד לתת לאביה בושת ופגם יותר על חמשים כסף כמו שביארנו והפגם ששמין אותה כאלו היא שפחה הנמכרת בשוק כמה תמכר קודם זה וכמה תמכר לאחר זה ואולם צער אינו משלם כי המפותה אין לה צער וברצונה גם כן נעשה והנה יתבאר ששאר הדברים הם גם כן לאביה כי התורה ביארה שהנזק הוא לאביה בענין בתולה וכ"ש בושת ופגם ואולם אם לא עמדה בדין עד שבגרה הנה הכל שלה שנאמר באונס ונתן לאבי הנערה ואין זה אב הנערה כבר נתבאר זה השרש בג' מכתובות. ומזה המקום יתבאר שהאשה שאינה בחזקת בתולה כגון המגורשת מן הנשואים והשוטה והחרשת והגיורת והשבויה ומי שיצא עליה שם רע אין לה חמשים כסף שנאמר וכי יפתה איש בתולה ואלו אינה בחזקת בתולה. והאילונית גם כן אין לה חמשים כסף לפי שאינה נקראת נערב בעת מהעתים אבל היה אם קטנה אם גדולה. ואולם יתחייב באלו בושת ופגם מלבד החרשת והשוטה כבר נתבאר זה השרש בג' מכתובות:
@52 **השרש** הב' הוא שאינו משלם כסף אם לא בא עליה בדרכה שנאמר וכי יפתה איש בתולה מן המקום שהיא בו בתולה ולא אמר כסף ישקול כמוהר הבתולות ומזה המקום יתבאר שהקטנה שאינה ראויה לביאה והיא הפחותה משלש שנים ויום אחד שהרי היא הנשארת בתולה עם שאין ביאתה נכנסת בגדר השכיבה כבר נתבאר זה השרש בג' מכתובות:
@52 **השרש** הג' הוא שאם אין הנערה ראויה להיות לו לאשה כאלו תאמר שהיתה אסורה לו אינו פטור מפני זה מהקנס כי התורה לא אמרה מהורי מהרנה לו לאשה להקל מעליו אך יהיה פטור מהקנס בה אם היה חייב מלקות על בעילתה או אם היתה מהעריות שיש בהם מיתת ב"ד כמו שנבאר בשרשים הכוללים כבר נתבאר זה השרש בשלישי מכתובות:
@52 **השרש** הד' הוא שהמפתה אינו חייב עכ"פ לשאת את המפותה שאם היה הדבר כן היה התורה אמרת שלא יוכל לשלחה כל ימיו כמו שאמר באונס אך ישלם חמשים כסף אם לא רצה לכנוס כמו שביארנו כבר נתבאר זה בג' מכתובות:
@52 **השר'ש** הה' הוא שאם בא עליה ומתה קודם שעמדה בדין פטור מלשלם קנס שנאמר ונתן לאבי הנערה חמשים כסף והרי אינו אבי הנערה בשעת הנתינה כבר נתבאר זה השרש בשלישי מכתובות:
@52 **השרש** הששי הוא שהנבעלת בעיר חזקתה שהיא מפותה אם לא נתבאר שהיא אנוסה וזה מבואר ממה שאמרה התורה בנערה המאורסה בפרשת כי תצא כבר נתבאר זה השרש בספרי':
@52 **השרש** הראשון הוא שהשוכב עם בהמה בין קטנה בין גדולה חייב מיתה ואע"פ שהבהמה היא טרפה בין שהיא חיה עתה הנה יש לו הנאה והנה גדר השכיבה הוא שיהיה בה קושי באבר הזכר כי בזולת זה לא תקרא שכיבה או ביאה כמו שהתבאר בשרשים הכוללים ואין הבדל בזה בין איש ואשה אם היתה נרבעת כמו שהתבאר בפרשת עריות והוא מבואר שמה שאמר שם ואת הבהמה תהרוגו אינו להקל על הרובע או הנרבע שאם אינה ראויה להריגה לא יתחייבו עליה מיתה וזה כי הפועל המגונה הזה הוא שאם היתה טרפה או בריאה ולא כוונה התורה גם כן לענוש הבהמה כי אינה בת עונש אבל הכונה היא למחות זכר הפועל המגונה הזה שלא ילמדו בני אדם לעשותו כבר נתבאר זה בט' מסנהדרין:
@52 **השרש** השני היא שזאת המיתה היא סקילה כמו שנתבא' בפרשת קדושים כבר נתבאר זה בז' מסנהדרין. והוא מבואר מהשרשים הכוללים שאם האיש או האשה ראוים לביאה אע"פ שהם קטנים הבהמה נהרגת ושאין הבדל בזאת השכיבה בין שתהיה כדרכה בין שלא כדרכה:
@57 **וגר לא תונה וגו' עד לא תשא שמע שוא:**
@57 **ביאור הדברים:**
@57 **אמר** וגר לא תונה בדברים ולא תלחצנו בממון להנותו במקח וממכר מפני חולשתו כי אין בשער עזרתו כי אתם הייתם גרים בארץ מצרים וידעתם צער הגר כאשר יצרו לו וילחצוהו או ירצה בזה שאם תבזוהו מפני שהוא גר גם הוא יכול להשיב לכם כי גרים הייתם בארץ מצרים וכן פירשו זה במכילתא. והנה אונאת דברים היא כמו שיקראוהו גר או שיאמרו לו זכור מעשיך ושאר מה שידמה לזה ואולם שאר דיני אונאת ממון במקח וממכר יתבארו בג"ה בפרשת בהר סיני. כל אלמנה ויתום לא תענון אפילו בדברים או לגרום להם הפסד בממונם ואע"פ שהיתה האלמנה עשירה ביותר או שהיה היתום עשיר ביותר הנה הוזהרנו מלענות אותם. אם ענה תענה אותו. ר"ל שתהיה תכונתך פחותה שתהיה רגיל לענותו הנה אם צעוק יצעק אלי ר"ל שירגיל לצעק באופן שתבא הצעקה אלי שמוע אשמע צעקתו ר"ל צעקת היתום והוא הדין לאלמנה ואולם לקחה התורה היתום בזה הענין כי האיש הוא יותר ראוי שתשמע צעקתו מצעקת האשה לחולשת דעתה בטבע והנה אקום נקמתם וחרה אפי והרגתי אתכם בחרב לשלם מדה כנגד מדה באופן שתהיינה נשיכם אלמנות ובניכם יתומים ורז"ל פירשו במכילתא שזה הענין הוא הקללה השנית והוא שכבר ישים נשיכם במדרגת אלמנות שתהיינה צרורות באלמנות חיות כמו שילכו בעליהן מדינת הים ולא נודע אם מתו ויהיו הבנים יתומים שלא יניחום ב"ד לירד בנכסי אביהם כי לא נודע אם מתו והנה הבנים נקראו יתומים בכל עת שתתמיד הסבה אשר בעבורה באה זאת האזהרה והו' הזמן אשר יצטרכו בו לאד' גדול להטפל בעניניהם ולהנהיגם ואמנם אחר זה אין דינם דין היתומים וראוי שתדע כי לא יקרא ענוי מה שתכליתו לטוב אבל הוא ראוי שיקרא הטבה וחנינה כי הפעולות יקראו בשם תכליתם ולזה אם ענה אותם אדם ליסרם באופן ראוי וללמדם מצות ואומנות ואומר להם בזה האופן דברים מכאיבים לבם או שהכה אותם אין זה עובר בלא תעשה. אם כסף תלוה את עמי את העני שהוא עמך במקומך שאתה חייב להלוותו כמו שאמרה העבט תעביטנו לא תהיה לו כנושה לנוגשו באכזריות והנה לא צותה התורה להניח לו חיובו אם לא ירצה לפרוע אבל באה זאת האזהרה שלא לנגזדו באופן שלא יגיע תועלת למלוה ויגיע צער ללוה כמו שישאל לו חיובו בב"ד והוא יודע שאין לו לפרוע ולא עשה זה אלא לצערו או לביישו כדי שיתפרסם בפני רבים ענינו. לא לתשימון עליו נשך וזאת היא אזהרה למלוה וכן היא אזהרה לכל מי שתשלם זאת ההשמה על ידו כמו הסופר והעדים כי הם משימים עליו נשך במה שכתבו והעידו בו עד שכבר יגלה המלוה זה חיוב וכן יעבור הערב על זה הלאו כי הוא כמו משים עליו נשך שאם לא היה זה ערב לא הניח לו המלוה מעותיו אם תמשכן חבריך בב"ד לגבות חובך ותקח שמלתו המכסה בה ביום הנה תתחייב להשיבו לו באופן שיהיה בידו בכל יום עד שיבא השמש כי הוא כסותו לבדה ואין לו זולתה שיתכסה בה היא שמלתו לכסות עורו וכן הענין אם תקח ממנו כסות הלילה ואין לו זולתו שישכב בו בלילה הנה תחוייב להשיבו לו בערב וישאר בידו עד הבקר כי במה ישכב אם לא תשיבהו לא והיה אם יצעק אלי ושמעתי צעקתו כי חנון אני. ולזה ראוי שתהיה נזהר להשיב לו כסות יום ביו וכסות לילה בלילה כשלא היה לו זולתו להתכסות בו וראוי שתדע שה אמנם יהיה כשלא היה לו זולתו להתכסות בו וראוי שתדע שזה אמנם יהיה כשלא היה לעני כסות זולתו להתכסות בו שנאמר כי הוא כסותו לבדה במה ישכב וזה הדין גם כן יהיה כשמשכנו שלא בשעת הלואה שנאמר אם חבל תחבול שלמת רעך אבל המלוה על משכון לא יתחייב בזה וכן הוא מבואר שאם מת העני לא יתחייב להחזיר המשכון ליורשיו על האופן שהוא חייב להחזירו לו שנאמר עד בא השמש תשיבנו לו כי הוא כסותו היא שמלתו. לא תקלל השופטים והדיינים כי עם שזה הוא מהמדות הפחותות כבר יגיע בו הפסד מבואר בתיקון המדינה וכן הענין במי שיקלל הנשיא שהוא נשיא לישר' בכללו וזה יכלול והשיא והמלך וראש סנהדרין כי נשיאות אלו מקיף בכלל ישראל וראוי שתדע שלא יתחייבו בזאת הקללות אם לא קללו בשם מהשמות המיוחדים לשם יתעלה או בכנוי מן הכנוים אשר יתארו בהם השם יתעלה וזה בנלמד אופן מה מענין הקללה אשר נהגו האנשים בה אשר בעבורה באה האזהרה בזה המקום וזה כי ההפסד שיגיע ממנה שוה באיזה לשון שתהיה הקללה ולה יהיה בזה המקום דין הכנויים כדין השמות ואולם במקלל אביו ואמו לקושי העונש אשר בו לא יסקל אם לא היתה קללה בשם מהשמות המיוחדים להשם ית' כמו הענין בקללת סוטה בשוה ושאר הקללו' הכתובות בתורה וראוי שתדע שכבר נכלל האזהרה מלקלל השם יתעלה במה שאמר אלהים לא תקלל כי אם נזהרנו מלקלל הדיינין אשר אצלנו כ"ש שאנו מוזהרין מלקלל הדיין האמיתי שהוא השם יתע' והנה זה הענין הוא כמו הענין בערות הבת ששתקה התורה ממנו ומפני שהזהירה מלגלות ערות בת הבת ובת הבן ולזה יהיה מקיף אלהים לא תקלל על שתי אזהרות אלו כמו שיקיף אומרו ערות בת בתך לא תגלה על אזהרת גלוי ערות הבת. מלאתך ודעמך לא תאחר הנה קרא מתנת הבכורי' מלאה כי כאשר ישלם בשול הפרי וימלא יתחייבו אף אז זאת המתנה וקרא התרומה דמע לפי שלא יתחייבו עליה עד גמר מלאכת הפירות ההם כמו שאמרה התורה ראשית דגנך ותירושך ויצהרך והנה התירוש והיצהר הם דמע הזתים והענבים והכונה בזה שלא יקדים האדם המתנות המאוחרות ויאחר המוקדמות אבל ראוי שיפריש תחלה הבכורים ואחר כן התרומה ואחר כן מעשר ראשון ואחר כן מעשר שני על האופן שיתבא' בכור בניך תתן לי ר"ל שתתן פדיון הבכור לכהן כמו שיתבאר במה שיבא כן תעשה לשורך לצאנך שתתן הבכור לי אך לא תתנהו תכף שנולד כי בזה יהיה מגיע הפסד לכהן ועוד שאינו ראוי לקרבן עד היום השמיני כמו שיתבאר בענין הקרבנות ולזה יהיה עכ"פ שבעת ימים עם אמו וביום השמיני תוכל לתתו לי כי אז הוא ראוי לקרבן ומתקנת חכמים שיטפלו בו בעלי' לגדלו בבהמה דקה עד שלשים יום ובגסה עד חמשים יום כי בזה כבוד לשם יתעלה. ואני קדש תהיון לי לנהוג קדושה בקדשים ובמזונותיהם ובשר שיצא חוץ למחיצתו כמו הבכור שיצא חוץ לחומת ירושלם וכמו הפסח שיצא חוץ מהחבורה ומה שידמה להם והבשר שהוא טרפה לא תאכלו אכן לכלב תשליכו אותו בבשר שאפשר בו זה והוא בשר הטרפה ואולם בשר הקדשים לא יתכן להאכילם כמו שיתבאר במה שיבא. וראוי שלא יעלם ממנו כי אמרו ובשר בשדה טרפה לא יתכן שיהיה שב אל הטרפה כי הטרפה שנטרפה בבית היא אסורה כמו הטרפה שנטרפה בשדה ולזה בארנו כי אמרו ובשר בשדה טרפה הוא כאלו אמר ובשר בשדה טרפה לא תאכלו והנה הבשר בשדה הוא הבשר שיצא חוץ למחיצתו או שחשבו עליו לאכלו חוץ למחיצתו. כי הבשר ההיא טרפה פסולה כמו שיתבאר בענין הקרבנות ואפשר שירצה באמרו ובשר בשדה טרפה הבשר שנפרדה מהבהמה קודם שנשחטה היא טרפה ואינה נתרת בשחיטת הבהמה. ואולם הביאור הראשון הוא יותר נאות לפי הענין. והנה התועלת המגיע מאלו האזהרות אשר כללנום יחד בזה הוא מבואר. והוא שלא נכאיב לב הגר והיתום והאלמנה והעני לא בדברים ולא במה שיגיע להם הפסד ממון אשר יחשב שאין אשם בו כמו ההונאה במקח וממכר והרבית ואחר זה הזהיר גם כן מלחטא לגדולי' באלו הפנים שלא נחשב שתהיה אזהר' בזה באלו השפלים לבד ולזה הזהיר מקללת הדיין והנשיא והזהיר מלאחר המתנות אשר נצטוינו לתתם לכהנים וללוים כי לא יחשוב האדם שיהיה בהם אשם כי הוא לקח ממון הכהנים והלוים בידים והזהיר עם זה מלהקדים נתינת בכור הבהמה לכהן יותר מן הראוי כי בזה יגיע הפסד לכהן כשלא יהיה לבכור ההוא חלב שיהיה ניזון ממנו ואי אפשר להקריבו עדיין עד שמנת ימים ויהיה זה סבה שימות הבכור ביד הכהן ואחר כן הזהיר שלא נזיק לעצמנו באחד מהפנים האלה והזהיר ראשונה במה שאין בו נזק לגוף כי אם לנפש והוא אכילת הבשר שיצא חוץ למחיצתו וזה דומה אל מה שקדמה האזרה בו מהזיק בדברים כי ההפעלות המגיע מהם הוא מצד הנפש ואח"כ הזהיר במה שיגיע בו נזק לגוף והוא אכילת הטרפה כי בשדה אינו נאות על דרך הבריאות והנה הטרפה היא לפי מה שיורה עליו גדרה שנטרפה באופן שאי אפשר בה שתחיה אבל היא חיה עדין שאם היתה מתה הנה תקר' נבלה ודין זה דין הנבלה בשוה וענינה האמתי הוא שיטרוף אותה ב"ח אחר באופ' שיהיה בלתי אפשר לה שתחייה י"ב חדש כי המצוה יתבאר מענינם אם הם ממיתות אם לא תוך הזמן וידמה שהחמירה התורה בטרפה יותר משאר המכות והחליים הנופלים בה שאי אפשר לה להחיו' בסבתם י"ב חדש לפי שרוב הטורפים הם בעלי אדם והדבר יבא לידי סכנה ואולם חכמים השוו בין הטרפה האמיתית ובין הבהמה שאי אפשר לה להחיות מפני מכותיה וכבר מנו רז"ל על צד החפוש הדברים שתהיה בהם הבהמה טרפה מנפי מכותיה והנה ההבדל בין הטרפה האמתית ובין הטרפות שמנו חכמים כי האוכל כזית מהטרפה האמתית לוקה ואין הענין כן בטרפות אשר הם מדרכנו ובכל ספק בטרפה האמתית נשפוט בו להחמיר ואין הענין כן בספק שיקרה בשאר הטרפות:
@57 ואולם שרשי המצות אלו הם:
@57 **השרש** הראשון הוא שאסור להלוות ברבית לישראל שא' לא תשימון עליו נשך ובזאת האזהרה נכללים כל המשימים יד בין הלוה והנלוה להסכים ביניהם הרבית ולזה שנתה התורה לשונה שהיתה מדברת בו בלשון יחיד והעתיקה הענין בלשון רבים להזהיר כל המשתדלים בזה כמו הערב והסופר והעדים כבר נתבאר זה השרש בחמישי מבבא מציעא:
@57 **השרש** הב' הוא שגדר הנשך הוא שיתן לו רבית קצוצה. ר"ל שיתן רבית כך וכך לחדש או לשנה או שידור בחצרו בחנם כ"ש שתהיה המלוה אצלו או שתהיה השדה אצלו בתורת מכר ויאכל פירותיה עד שישיב לו המלוה וישיב לו השדה והוא מבואר שהדיינין יכריחוהו להשיב כמו זה הרבית ללוה כי זה הוא כמו גזל בידו לפי שהתורה מנעתו ממנו וכ"ש שאם לא גבה אותו שאין הדיינים מגבין אותו את הרבית מן הלוה כבר נתבאר זה בה' ממציעא. ויראה לי שלא יועיל ברבית קצוצה אם קבל הלוה לתת הרבית בתורת מתנה וזה כי מפני שיביאהו להסכים לתת הרבית והוא החסרון הוא בעינו יביאהו לתת לו זה בתורת מתנה וזה ממה שאין ספק בו אמנם אחר שקבלו ממנו אם רצה הלוה למחול לו מחול ולא יצטרך להחזירו לו ומזה המקום יתבאר שהמשכיר דינריו כאו הם כלים הרי זה אינו רבית שהרי שכרם לו לחזור לו בעינם וישתמש בהם אם להראו' שהוא עשיר אם לשקול בהם אם לשאר הדברים שאפשר שישתמש בהם וישיב' לו בעינ' ואולם מדברי' אסור שהרי הוא אבק רבית כי השוכר יערים בזה ויוציאם בעסקיו. ואחר זה ישיב לו דין אחרים ונמצא זה כמו רבית וכן הנותן מתנה לחברו קודם שישאל ממנו שילונו או שהלוהו והשיב לו המלוה ואח"כ שלח לו דורון אין בזה אסור רבית מן התורה אבל הוא אסור מדבריהם כיון שהו' נותן לזה המלוה שהלוה או שילונו. אבל נותן מתנה למלוה כדי שילוה לחברו או נותן מתנה לחברו שיאמר למלוה שילונו אין בכך כלום כיון שאין זה מגיע ממלו הללוה וכן יתבאר מזה שמי ששאל מחברו שילונו מנה ואמר לו שאין לו אלא חטים במנה ושעבד לו עצמו במנה ואחר כן חזר ולקחם ממנו בעשרים וארבע סלע שאין בזה דין רבית אבל הוא אסור מדבריהם מפני ערמת רבית ואולם מי שמכר חובותיו קודם זמן הפרעון בפחות אין זה רבית אפילו מדבריהם שהרי אין דין המלוה כדין המעות כמו שהתבאר בשרשים הכוללים כבר נתבאר זה כלו בחמישי ממציעא:
@57 **השרש** הג' הוא שהממשכן את העני על מלוותו שהוא חייב לו ולקח לו הכר שהוא ישן בו ושדימה לזה ממה שאי אפשר לעני לעמוד מזולת זה הכלי בשעה הזאת הנה אם היה שמושו שמוש יום חייב להשיבו לו בכל יום ואם היה כסות לילה חייב להשיבו בכל לילה עד זריחת השמש והנה בפרשת כי תצא בא בזה הענין לאו שנאמר לא תשכב בעבוטו השב תשיב לו את העבוט ר"ל לא תשכב ועבוטו הוא אצלך והוא הדין שהוא חייב להשיב לו כלי שעושה בו מלאכתו ביום כי מה ילבש או ישכב או במה יעשה מלאכתו שהוא מתפרנס בה והוא מבואר שזה לא ינהג אלא כשימשכננו על הלואתו כמו שביארה התורה לא כשהלוהו על המשכון כי אין ראוי בו זה הדין כמו שהוא ראוי כשימשכננו על הלואתו וזה כי כבר גלה העני דעתו כשילוה לו על המשכון הזה שכבר אפשר לו לעמוד מזולת כסות הזה או הכלי הזה כבר נתבאר זה השרש בתשיעי מבבא מציעא:
@57 **השרש** הד' הוא שלא יתחייב על קללת הדיין והנשיא אם היו רשעים גמורים שנאמר ונשיא בעמך לא תאור והוא הדין בשאר כל אדם כי התורה הזהירה על קללתם ואמרה לא תקלל חרש וזה יתבאר מזה המקום כי אפילו הנשיא דקדקה התורה בזה ובכלל הנה לא הקפידה התורה על קללת הדיין והנשיא אלא מפני התועלת המגיע מהם והישרת האנשים אל השלמות וזה לא יתכן כשיהיו רשעים כבר נתבאר זה השרש במכילתא:
@57 **השרש** הה' הוא שאי לוקין על קללתם אם לא היה קללתם בשם מן השמות המיוחדים לשם יתעלה כמו אל אלהים יה שדי צבאות או בכנוי מן הכנוים המיוחדים לו כמו חנון וקנא ואם קלל בזה האופן בכל לשון הרי זה קללה והקללה היא שיאמר ארור או קללה אחרת ולא שישלול ממנו הברכה כמו שאמר אל יחי ברוך כי שלילת הברכה אינה קללה כמו שנתבאר זה בשביעי משבועות:
@57 **השרש** הו' הוא שאף על פי שמחל על קללתו הנשיא או הדיין או אחד מישראל אין מחילתו מחילה לפטור המקלל מהמלקות והיה זה כן כי התורה לא תתלה זה הענין בקפידת המקולל אבל הזכירה מזה אם הקפיד המתקלל אם לא יקפיד כבר נתבאר זה בשני מסנהדין והוא מבואר מהשרשים הכוללים שכבר יקרה שיתחייב בזה ג' מלקיות אם קרא לנשיא שיהי הדיין כי הוא גם כן מישראל כבר נתבאר זה ברביעי משבועות:
@57 **לא תשא שמע שוא וגומ' עד שש שנים תזרע ארצך:**
@57 **ביאור דברי הפרשה:**
@68 **ביאור דברי הפרשה:**
@87 הנה אנכי שולח מלאך וגו' עד ואל משה אמר
@87 **ביאור הפרשה:**
@87 **אמר** הנה אנכי שולח מלאך נביאי לפניך ולהנהיג אותך לשמרך בדרך אשר אתה הולך על ידי העתידות אשר יגידו לך בשמי ועל ידי הנפלאות שאעשה לך על ידו והנה יהיה כאלו הנביאים מי שיביאך אל המקדש אשר הכינותי להיות ביתי שם כי הוא ינחילך את הארץ:
@88 **השמר**. מפני הנביא ושמע בקולו במה שיגיד לך בשמי כמו שאמר בפרשה שופטי' ושוטרים נביא בקרבך מאחיך כמוני יקים לך יי' אלהיך אליו תשמעון אל תמר בו לבלתי שמוע אל דבריו אשר ידבר בשמי כי לא יוכל לשאת אל פשעיכם כי שמי הוא בקרבו ומאתי יצאו הדברים והממרה בו הוא ממרה בי והממרה בדברי הנביא חייב מיתה בידי שמים שנאמר בפרשת שופטים אנכי אדרוש מעמו.
@89 הנה **אם שמוע תשמע בקולי** באופן שתעשה כל אשר אדבר על ידו הנה אשנא שונאך ואלחם מלחמותיך:
@90 **כי ילך מלאכי לפניך**. ונביאי והביאך אל הארץ אשר נשבעתי לאבותיך ואכחיד כל אחד מהאומות אשר בה השמר לך שלא תשתחוה לאלהיהם וה"ה לזביחה ונסוך וקטור אע"פ שאין עבודתה בכך כמו שקדם ולא תעבדם דרך עבודה כמו הפוער עצמו לפעור והזורק אבן למרקולים:
@91 **ולא תעשה כמעשיהם**. ר"ל שלא תעבדני באופן שהם עובדים אלהיהם כמו שאמר בפרשת ראה אנכי איכה יעבדו הגוים האלה את אלהיהם ואעשה כן גם אני כי הרס תהרסם האלילים ההם ושבר תשבר מצבותיהם באופן שתאבד הע"ז וכל הנעשה בשבילה כמו שהתבאר בפרשת ראה אנכי כי זאת המצוה לא היתה כי אם באלילים אשר נמצאים בארצנו כי בהם אנחנו מחוייבים שנשתדל לאבדם בה האופן לא בשאר המקומות וזה נלמד מזה הפסוק כי הוא מדבר בארץ ישראל. וכבר נתבאר זה גם כן בפרשת ראה אנכי ויחוייב לכם שתבקשו ההכרחי לכם מאתו יתע' כשתתפללו לפניו על זה והוא ישמע תפלתכם ויברך לחמך ומימיך באופן שיהיה לחמך נתן ומימיך נאמנים ויסיר מחלה מקרבך ולא תהיה משכלה ועקרה בארצך את מספר ימיך אמלא באופן שלא תמות בלא עתך:
@94 **את אימתי אשלח לפניך**. על כל הגוים והמותי את כל העם אשר תבא בהם ויברחו ממך מרב פחדם ויראתם ושלחתי את הצרעה לפניך להזיק לאומות אשר תלחם בהם והנה אמר זה על דרך משל על העזר האלהי שיהיה נלוה לישראל בהכנעת האומו' ההם לא אגרש האומות מפניך בשנה אחת כי זה יהיה סבה שלא יהיה מתיישב מהארץ כי אם מעט והוא המקום אשר תשב בו והשאר יהיה מדבר ותגדל בו חית השדה ותזיק אותך מאד לרבויה מעט מעט אגרש האומות מפניך עד אשר תפרה ואז תנחל את הארץ:
@98 **ושתי את גבולך מים סוף ועד ים פלשתים וממדבר עד הנהר**. ובזה נכללה כל ארץ ישראל באורך וברוחב והוא מה שאמר וירד מים עד ים ומנהר עד אפסי ארץ כי אתן בידכם את יושיב הארץ בכללם וגרשתמו מפניך ואז אשית גבולך השעור הנזכר בתורה:
@99 **לא תכרות להם ולאלהיהם ברית**. ר"ל שלא תכרות ברית לעובדי ע"ז כדי שתעשה עמהם שלום כי זה יהיה סבה שתכרות ברית לאלהיהם ותעבוד ע"ז אבל יהרגו או יחזרו מעבודתם לא ישבו בארץ אלו הגוי' העובדים ע"ז פן יחטיאו אותך לי בשיפתוך לעבוד ע"ז ומזה יתבאר שאסור לישראל להניחה שישבו עמהם אפילו לפי שעה כי אולי בזן המעט ההוא יחטיאו אותם לש' יתע' כי יהיה לך למוקש מגיד שאפילו אחד מהם לא נניח לשבת בארצנו כי יהיה לנו למוקש במה שיפותונו לע"ז והנה גר שעד הכתוב בתורה הוא המקבל של לעבוד ע"ז וכבר יתבאר שהוא ראוי גם כן שיקבל שאר המצות שנצטוו בני נח היה בה השלמות ביחס אל מה שיהיו מוכנים לקבל ממנו האומות ההם וכמו שלא יתכן לישראל לעזוב קצת תורתנו ולהחזיק בקצת כן לא יותר זה לבני נח ולזה היה ראוי שיקבל עליו הגר היושב בארצנו שלא לעבוד ע"ז עם שאר המצות שנצטוו בני נח ואז נניח אותו לשבת עמנו. והנה התועלת המגיע מזאת הפרשה במצו' שנזכרו בה הוא מבואר וזה כי בשמיעה לדברי הנביא תשלם לישראל ההשגחה האלהית אשר בעבורה שולח הנביא להם. והנה מה שהזהיר שלא נעבדהו באופן שיעבדו שאר האומות אלהיהם הוא נגלה התועלת כי ראוי שלא נלמד ממעשיהם כדי שלא נתפתה לעבוד ע"ז ועוד כשכבר בארה התורה התועלת בזה וספרה כי גם את בניהם ואת בנותיהם ישרפו באש לאלהיהם ומה שצוה שנתפלל אליו ונשאל ממנו מה שיצטרך הוא מבואר התועלת לישב בדעותינו כי כל הטובות שופעות מאתו עם שבזה תדבק בנו ההשגחה האלהית כי ענין התפלה ומהותה הוא לפי מה שנבאר בתורה שנספר שבחי השם יתע' ואח"כ נתפלל כמו שמצאנו במשה בהתפללו לשם יתע' בראש פרשת ואתחנן והנה וסור שבחי השם יתע' הוא מה שנוכל להשיג מאמתת מציאותו ווזאת ההשגה היא סבה דבקות השגחתו בנו כמו שביארנו ברביעי ממ"י ומה שצוה שלא לכרות ברית לעובדי ע"ז ושלא ישבו בארצנו כבר נתבאר בתורה התועלת באלו המצות והוא שלא יחטיאו אותנו. והנה בזאת הפרשה עם זה תועלת בדעות והוא להודיע כי השם יתעלה ישלח לישראל נביאו על דרך ההשגחה לשמרם ממה שיתכן שיזוקו בו ולהקנותם הטובות וההשגחות הבאות אליהם והנה הקדים לזכור השמירה כי ההשגחה האלהית והיא מיוחדת בזה לדבקים בו יותר ממה שהוא בהקנאת הטובות כי היא תהיה בהודעת הדעות אשר יתכן שיקרו וזאת היתה הכונה בענין אלו ההודעות אשר תהיינה לנביא בעתידות כמו שהתבאר בשני ממ"י והיא תהיה בשעת להקנות הטובות באמצעות ההודעה כשתהיה בטובות ובאמצעות הנפלאות אשר תהיינה על יד הנביא והנה הוסיף להזהירם בכאן מענין ע"ז לפי שגלוי וידוע לפני השם יתע' שסופן היה לעבוד אלהי נכר הארץ כמו שהתבאר בספר שופטים ומלכים ורצה להתחכם להצילם מזה. וראוי שתדע כי כמה שזכר שיעשה להם אם יעבדו השם יכללו בו כל הטובות וההשמר מהרעות וזה כי באמרו וברך את לחמך ואת מימיך כלל שימצאו להם המזונות ברבוי ושלא יזיקו להם בהיותם נזונים מהם אבל יולידו להם דם טוב ובאמרו שיסיר כל מחלה מביניהם כלל שירפאם מהמחלה שתהיה להם ושיצילם מכל עפוש מחוץ ומכל דבר מזיק כמו הפכת הארצות ואש נופל מן השמים ומה שידמה לזה וזה כולל שיהיה להם בגד ללבוש ובית להיו' להם למחסה למסתור ואחר שיעדם בשמירתם באיש לפי מה שאפשר שב ליעד בשמירתם במין ולזה אמר לא תהיה משכלה ועקרה בארצך כי בזה כלל קיומם במין ורבוי' וזהו אמרו את מספר ימיך אמלא ר"ל שלא ימותו בלא עתם ולזה לא תהיה משכלה בארצך ואחר זה יעדם על נצחם האומו' אשר יבואו בהם באופן שיברחו כלם מהם ולזה תמצא להם ארץ ישבו בה עם רבוים:
@101 **ואל משה אמר עלה אל יי' וגו' עד סוף הפרשה:**
@101 **ביאור דברי הפרשה:**

@1 **התועלת** הראשון הוא במצות והוא לבאר דין עבד עברי ביציאת רשות האדון לחפשי. ואולם התועלת בזאת המצוה ובמה שדמה לה הוא מבואר והוא לסבב שלא ישאר איש או אשה מישראל בשפלות ודלות מתמיד אבל יתנחמו משפלותם וענים בזכרם כי עוד מעט יצאו חפשים מעבודתם וישובו להם קרקעותיהן אשר מכרום וזה כי בבא השנה השביעית יצאו לחפשי או ביובל לכל הפחות וביובל ישובו להם קרקעותיהם והנה בזאת קצת נחמה לדלים האמללים והכריחה התורה העבדים הנמכרים בגנבתם לישא שפחה כנענית אם ירצה אדוניו להדחיקו יות' מהגנב' כי יקשה להם להיות זרעו לא לו ולזאת הסבה לא יוכרח לישא שפחה כנענית אם לא היה לו אשר ובני' כי מי שאין לו אשה לא יקשה לו נשיאת השפחה ומי שיאן לו בנים לא יקשה לו הולדת הבני' לא לו כי לא שער עניין זה הקניין שישער אותו מי שיש לו בנים ורצתה התורה לבזותו כאשר תביאהו תאותו אל השפחה הכנענית אל שיבחר להיו' עבד יותר משיהיה בן חורין להרחיק ממנו זאת הבחירה המגונה כי יקשה לו לפרסם חסרונו לפני השופטים ולהרצע אנו במקום רואים בזה האופן המגונה. ואולם שרשי זאת המצוה הם ששה עשר:
@1 **התועלת** השני הוא במצו'. והוא לבאר דין אמה העברייה ביציאת מרשות האדון לחפשי. והנה התועלת בזאת המצוה הוא בעינו התועלת אשר במצות שלוח עבד עברי והנה כוונה התורה שיהיה כח האדון ליעדה לו או לבנו אף על פי שלא ירצה זה אביה להרחיק מכירת הבת בזה האופן כי האנשים אשר יסכים האדם לתת להם בתו לאשה אינם רבים מאד וזה יהיה סבה שלא יסכים למוכרה אלא לכמו אלו האנשים ר"ל האנשים אשר ייסכים לתת להם בתו לאשה ולזאת הסבה לא השליט' התורה האדם למכר' לאיש אחר שיעדנה כי לא נתרצה אביה בזה במכירתו בתו עם שבזה ג"כ מהיושר כי כבר יתרצה האדון לשרת איש מה עם שבענין היעוד תועלת אחר והוא כי האדם לרוב תשוקתו למשגל אולי ישתדל לפתות זאת האמה ויקרה בזה מההפסד והגנות מה שלא יעלם ולה רצתה התורה שיעדה הוא או בנו או ישתדל שתפדה ותצא מרשותו כי איננו ישר שתעמוד ברשותו מזולת זה האופן והנה השליטה התורה לאדם למכור בתו בהיותה קטנה לא למכור בנו לפי שהאשה נבראת לעבודת האדם כמו שנתבאר בפרשת בראשית ולה ישלוט האב למכור בתו ולא למכור בנו כי היא נבראת לשרת ולפי שראויה להיותה לאיש בהיותה נערה הנה תסור ממשלת האב ממנה בהיותה נערה:
@1 **התועלת** הג' הוא במצות. והוא מה שצותה התורה שלא יגרע האדם מאשתו שאר כסות ועונה והנה התועלת בזאת המצוה הוא מבואר וזה שאם לא היה הבעל מלביש אשתו וזן אותה היתה האשה טרודה תמיד באסיפת הקניינים להיות לה לחם לאכול ובגד ללבוש ולא יגיע לבעלה ממנה השרות אשר יצטרך ותפסד הבונה אשר בעבודה היתה בריאת האשה לפי מה שהתבאר בפרשת בראשית ואם היה שולט הבעל במניעת עונתה הנה יהיה זה מביא אותה לזנות כאשר ירבה כח המותר הזרעי ויגיע בזה מההפסד בקבוץ המדיני מה שלא יעלם ואולם שרשי המצוה הזאת הם חמש עשרה:
@33 והנה התועלת המגיע מאלו הדינים הוא במצות והתועלת בהם הוא מבואר בסלוק ההיזקים מבין האנשים באופן שלא יזיק מה שהוא ממון האדם לזולתו והנה הזכיר תחלה דין הבור לפי שאין דרכו לילך ולהזיק והיה לחושב שיחשוב שיהיה בעל הבור פטור מנזקין לפי שהתחלת זה ההיזק הוא בבעל חי ההולך שם כי הוא הולך מפני הטבע אשר בו וזה גרם לו להנזק בבור והנה חייבתהו התורה באלו ההיזקים לפי שהוא דרך שתלכנה הבהמות ברשות הרבים וזה שהמוציא להם תקלה הוא כאלו הזיקם בידי' ולזה פטור על הבור ברשות המזיק ופטור גם כן על הכלים ואחר כן זכר נזקי השור לפי שאין דרכו להזיק בכמו זה האופן כאש' היה תם והיה לחושב שיחשוב שלא יהיה אשם לבעלים בזה הנזק ויהיו פטורים ולפי שנזקי השן יחשב בהן שיהיו כמו הגניבה הקדימה התורה לזכור מן הגניבה שלא יחשוב חושב שיהיה שוה עונש הגניבה לעונש נזקי השן ואחר כן זכר דין נזקי השן והרגל וחייב בהם ברשות הנזק לבד כי ברשות הרבים יש לבהמה רשות להלוך ואין לבעל הפירות רשות להניח שם פירותיו ולזה לא יתחייב בעל הבהמה אלא כשהלכה הבהמה במקום שאין לה רשות להלוך והיה רשות לבעל הפירות להניח שם פירותיו שלא שמר הבהמה ההיא כראוי לפי שיש לבהמה התחלה בעצמה ללכ' באשר תמצא הפירו' לאכלן ולהזיק הדברים בהליכה כשלא ימנעוה מזה ואחר זה זכר דין נזקי האש שהם כאלו הזיק בעל האש בידים כי כשבער האש יש לו התחלה בטבע שיתפשט בכל המקומות אשר אפשר שיאחז בהם ואי אפש' לו מזולת שימשך בהם אם לא ימנעהו מונע ואין הענין כן בנזקי השן כי אין חיוב הליכת הבהמה למקום הפירות כשלא ישמרנה כחיוב הליכת האש כאשר אפשר שימשך בו וזה מבואר בנפשו ולזה יתחייב על האש בחמשה דברים אם הזיק אדם מה שאין כן אם הזיק בו ממונו כמו שור ובור והדומה להם ואולם שרשי אלו המצות הם מ"ד:
@43 ואולם התועלת המגיע מאלו הדינים:
@43 **התועלת** הוא לדון בדין שומר חנם ובדין שומר שכר והשוכר ובדין שואל ובדין כל טוען וכופר. ואולם שרשי אלו המצות על מדרגתם ועל ביאורם הם ל"ד:
@43 **התועלת** הה' הוא שהשומר חנם פטור מכל אונס ולא יתחייב לשלם אלא אם פשע בשמירתו שנאמ' על כל דבר פשע והפשיעה תהיה אם לא שמר השמירה הראויה לדבר ההוא ולזה יפטר שומר חנם בגנבה ואבידה כ"ש באונסים הגדולים ומפני זה נשבע אם לא ימצא הגנב שנגנב או שמכר ולא פשע בשמירה פטור ונקרב בעל הבית אל האלהים והרצון בו להשבע כמו שביארנו והשומר שכר והשוכר חייבין באונסין קטנים כמו גנבה ואבדה ופטורים מאונסין גדולים כמו שבורה שבויה ומתה כשהיה זה בזולת פשיעה והשואל חייב בכל האונסין ולזה אם מתה מחמת המלאכה שאל אותה עליה או כחשה מחמת המלאכה ההיא או שנשבר הכלי מחמת המלאכה ששאל אותה עליה בזולת פשיעה שהרי עשה זה ברשות הבעלים כבר נתבאר זה השרש בשביעי מבבא מציעא:
@52 ואולם התועלות המגיעות הם שנים:
@52 **התועלת** הראשון הוא במצות. והוא מה שצותה התורה בענין המפתה את בתולה שיקחנה לו לאשה או שישלם חמשים שקלים כסף לאבי הנערה והנה שרשי זאת המצוה הם ששה:
@52 **התועלת** השני הוא במצות והוא מה שצותה התורה להמית כל שוכב עם בהמה שנאמר כל שוכב עם בהמה מות יומת ואולם שרשי זאת המצוה הם שנים:
@68 והנה התועלת המגיע באלו האזהרות הוא במצות והתועלת בהם מבואר לשפוט בצדק בין האנשים והנה באה האזהרה שלא לקבל עדות איש רשע ואיש חמס לי שהדבר קרוב שיעידו שקר ובאה האזהרה לסנהדרי' שלא יגמרו הדין בדיני נפשות לחובה אם לא היו המחייבים יותר מהמזכין שנים או יותר לפי שראוי שנתרחק מהריגת האנשים אם לא יביאהו ההכרח והנ' אם היינו הולכי' אחר הרוב בזה הענין הנה ימצא שיהרג הנהר' על פי אחד והו' האחד שיוסיפו בו המחייבין על המזכין ואין ראוי שנעשה דבר גדול כזה על פי אחד. והנה באה האזהרה שלא לענות על ריב לנטות לפי שהכוונה ברבוי הדיינין שיתבארו דעותיהן בזה הענין בדרך שיצא דין אמת לאמתו ואם ענה אחד מהם לנטות לא יתבאר לנו דעתו בזה הענין ולא יקובל תועלת בו לברר אמתת הדין והנה באה המצוה להטות אחרי רבים בדיני ממונות כי שם יספיק אחד לדין אמר בצדק תשפוט עמיתך וכן הענין לזכור בדיני נפשות כי סבה חלושה תספיק להציל האנשים מההריגה לקשי ענינה ובאה המצוה לדיין שלא יטה אחרי הדל כשיריב עם זולתו לחמלה עליו כי אין מן הראוי לו לעזור לדל בזה האופן אבל היא מצוה הבאה בעבירה ולפי שרצתה התורה להזהיר הדיין מהטות משפט האיש החוטא והקדימה לזה שראוי שנשיב אבדת החוטא ונפרק המשא מעליו ומעל בהמתו אחר שהוא מחזיק בתורת משה ובאה המצוה לדיין שלא יהרוג הנקי שנתחייב בדין כי לא נוכל לומר שזה הדין הסכים עליו ה' יתעלה כי לא יבאו לו הרעות מאת השם יתע' בעצמות כל שכן על צד העול ואולם מי שנצדק בדין בז האופן יתכן שנאמר שזה הדין הסכים עליו השם יתע' כי הטובות הם באות מאתו ואולי שהשגיחה בזה שנצטדק בדין בזה האופן ובאה האזהרה לדיין שלא יקח שוחד כדי שלא יביאהו להטות הדין ושלא ילחץ זה הגר כי אם ירגיל עצמו בזה אולי לא ישגיח כראוי בדינו ויטה משפטו. ואולם שרשי אלו האזהרות הם שנים עשר:
@68 השרש הראשון הוא שאין ראוי שיקובל עדות שקר ולא עדות חמס והנה הרשע הוא מי שעבר עברה שיש בה מלקות או מיתת בית דין כי כבר קראה התורה אלו האנשים רשעים שנאמר והיה אם כן הכות הרשע אשר הוא רשע למות ואיש חמס הוא שלוקח ממון שאינו שלו בחמס כמו גנב וגזלן ומלוה ברבית והיה זה כן כי כבר נחשדו כמו אלו שיעידו עדות שקר מפני הממון למעוט יראתם מהשם יתעלה ומזה המקום יתבאר מקל וחמור שאין מקבלים עדות עד זומם שהרי הוא חשוד לזאת העברה כבר נתבאר זה השרש בשלישי מסנהדרין:
@68 השרש השני הוא שהנוגע בעדות פסול להעיד שנאמר העד שקר ענה באחיו לא תענה ברעך למדנו מזה שהעדות הוא שיעיד האדם בענייני איש זולתו לא במה שהוא כמו בעל דבר יקרא טענה לא עדות ובכלל הנה כל אדם הוא חשוד לטעון שקר בענייניו כבר נתבאר זה השרש בשלישי מבבא בתרא:
@68 השרש הג' הוא שאין מקבלין עדות ממי שאינו מישראל כגון עבד כנעני או נכרי שנאמר העד שקר ענה באחיו כאשר זמם לעשות לאחיו למדנו מזה שהמעיד ראוי שיהיה מישראל וזה מבואר גם כן מהפרטים שזכרה התורה בזה המקום כי כמו אלו האנשים שאין יראת השם יתע' על פניהם ולא יראו מהעיד עדות שקר כבר נתבאר זה השרש בראשון מבבא קמא:
@68 השרש הד' הוא שמי שלא יוכל לעמוד על בוריו של דבר פסול לעדות זה מבואר מאלו הפרטים שזכרה התורה בזה המקום וזה שאם נפסלו לעדות מי שיכולין לעמוד על בוריו של דבר מפני חשדנו אותם על אהבת הממון לא יעיד מה שידעו מאמתת הדבר כל שכן שיהיו פסולין האנשים אשר מצד קצורם וחסרון דעתם לא יוכלו לעמוד על אמתת הדבר כי איך יעיד מי שלא ידע אמתו' הדבר ובכלל הנה התור' זכר' בפרטי העדו' ודרשת וחקרת היטיב ולא תתכן הדרישה והחקירה בחסרי הדעת כמו החרש והשוטה והקטן וכן השומע ואינו מדבר פסול לעדות כי אינו יכול להעיד אלא ברמזיות. ואין הרמיזה דבר מובן בבירור. ועוד שהתורה אמרה בענין העדות אם לא יגיד ונשא עונו מגיד שהעד הוא שיכול להגיד ושעדותו תהיה בהגדה ולזאת הסבה גם כן יהיה הסומא פסול לעדות כי לא יוכל לראות ולעמוד על אמתת הדבר וכבר אמרה התורה בענין העדות והוא עד או ראה או ידע כבר נתבאר זה בח' ובט' מערכין. ולזאת הסבה יתבאר שהנשים פסולות לעדות לחסרון ולחלשת שכלם ולקלות התפתותם לדברים. והנה אמרה התורה בענין העדות ועמדו שני האנשים ולא הנשים ולזה יהיו הטומטום והאנדרוגינוס פסולים לעדות כי כל אחד מהם הוא בספק אשה והוא ספק של תורה כבר נתבאר זה השרש בסוף תוספת בכורים:
@68 השרש הה' הוא שהקרובים פסולים לעדות מן התורה לפי שהם כמו בשר אחד והם ג"כ כמו נוגעים בדבר לפני שהם ראויים לירש קצתם קצת ולזה לא ינהג זה הדין כי אם במשפחת האב והמשל שהאב פסול לעדות הבן והבנים זה לזה וכן הענין בבני בנים שנקראו בנים והם ראויים לירש קצתם את קצת כמו שיתבאר בדיני הירושה ובכלל הנה יתבאר מן התורה שבני בנים הרי הם שאר בשר לא בני בניהם. ולזה מנה גלוי עריות מבת אשתו או מבת בן אשתו כי הם שאר אחד וכן הענין בבת בנו ובת בתו ומזה המקום יתבא' שהאב עם בת בן בנו אינו שאר אחד מן התורה וכ"ש בן האב עם בת בן בנו וכל שכן בן בן האב עם בת בן בנו והנה האחי' שהם בני איש אחד נקראי' ראשונ' כי הם הענפי' הראשוני' לשרש שהוא האב ובניהם הם שניים ובני בניהם הם שלשיים ומזה המקום יתבאר ששלישי בשני הוא כשר להעיד ואולם שני בשני הם שאר אחד ואע"פ שהם מותרים לישא זה את זה ולא יהיה זה כן כשיהיה הראשון נקבה כי אז הם אסורים זה בזה אמרה תורה ערות דודתך לא תגלה ולפי שהאשה היא שאר בעלה למדנו מזה המקום שבעל כאשתו ולפי שאין נאמנים לזכות לפי היותם כמו נוגעים בעדות או אין נאמנים לחובה כי העד הוא מי שהוא יכריע בין טענת החולקים לאי זה שיהיה מהצדדים וזה מבואר מאד כבר נתבאר זה השרש בשלישי מסנהדרין ואחשוב כי כל אלו הפסולין כלל הפסוק באמרו לא תשא שמע שוא:
@68 השרש הו' הוא שהרואה בהמת חבירו רובצת תחת משאה אפילו היה בעל עברו' הנה הוא מחוייב לפרוק עמו המשא שנאמר עזוב תעזוב עמו וכן חייב לטעון עמו על הבהמה אחר זה שנאמר הקם תקים עמו. ואין ראוי שיובן שיהיה חייב לפרוק אפילו בעל בהמה היה בעל עברות מפני החמלה על צער ב"ח ולא יחוייב לטעון אלא כשלא היה בעל עברות כי כבר תראה שכבר חמלה התורה על מי שהוא בעל עברות להשיב אבדתו באופן שחמלה בזה במי שהוא בלתי בעל עברות וזה אמנם יהיה לחמלה על הבעלים לא לחמלה על הב"ח ובהיות הנין כן הנה יחוייב שיהיה מקים עמו וגם אם היה בעל עברה כבר נתבאר זה השרש בשני מבבא מציעא:
@68 השרש הז' הוא שאם פרק וטען וחזר ורבץ חייב לפרוק ולטעון עמו אפילו מאה פעמים שנאמר הקם תקים עמו ולא תשלם ההקמה בזולת זה ומזה יתבאר שהוא ראוי שילך עמו עד שיראה שיתקיים המשא על הבהמה כבר נתבאר זה השרש בשני מבבא מציעא. ויראה לי שאם לא תוכל הבהמה לשאת המשא אפילו על ידי הדחק אינו חייב לחזור ולטעון אלא המשא שיכולה לשאת על ידי הדחק כי לא יקרא הקמה טעינה שתרבץ בעבורה הבהמה תכף וזה מבואר בנפשו:
@68 השרש הח' הוא שאם היה שם בעל הבהמה הנה הוא פורק וטוען עמו שנאמר עזוב תעזוב עמו ואם לא רצה בעל הבהמה לטרוח אין זקוק מוצאו לפרוק ולטעון ואע"פ שיכול בזה אם לא היה בעל הבהמה בלתי יכול לעזור בזה וזה מבואר בנפשו ולזה הוא מבואר שאם לא היה שם בעל הבהמה חייב המוצא לטעון ולפרוק אם יוכל כבר נתבאר זה השרש בשני ממציעא:
@68 השרש הט' הוא שמי שיאן דרכו לטעון ולפרוק ואע"פ שהיתה הבהמה שלו כגון זקן ואינו לפי כבודו או כהן והוא בבית הקברות פטור מלפרוק ולטעון שנאמר וחדלת מעזוב לו ר"ל שיחדל מלעזוב מפני שהיא של שונאו יצא זה שחדל לעזוב לכל האנשים אפילו לעצמו כבר נתבאר זה השרש בתוספת מציעא פרק ר' שמעון:
@68 השרש העשירי הוא שלא יתחייב האדם לפרוק לטעון אם היה הבהמה רחוקה ממנו ואע"פ שהוא רואה אותה שאם היה הענין כן היו רבים טורחים בזה לבטלה כי אפשר שתראה הבהמה מרחוק לאנשים רבים במקומות רבים וקודם היותם תשלם הפריקה והטעינה לבהמה ויהיה טרחם לריק ולזה סמך הכתוב באמרו כי תראה חמור שונאך לאמרו כי תפגע שור אויבך להורות שזאת הראיה יתחייב שתהיה בפגיעה ושערו חכמים שהמרחק הזה הוא עד ריס אחד שהוא אחד משבעה ומחצה במיל והוא רס"ו אמות ושתי שלישי אמה כבר נתבאר זה השרש בשני מבבא מציעא:
@68 השרש הי"א הוא שהפריקה יתחייב בה בזולת שכר ואולם הטוען נוטל שכרו וכן הענין במה שילך עמו עד שיראה שיתקיים המשא על הבהמה כי לא הכריחה התורה לעשות מלאכתו של זה בחנם אך הכונה היא לחייבו לטעון עמו שם שלא ימצאו לו אנשים אחרים לשכור אותם על זאת המלאכה כבר נתבאר זה השרש בשני מבבא מציעא:
@68 השרש הי"ב הוא שאם מצא ב' בדרך לפרוק ולטעון חייב לפרק תחלה מפני הפסד הבהמה וצערא והתורה גם כן הקדימה הפריקה לטעינה אך אם היתה הטעינה של שונאי והפריקה מאוהבו הטעינה קודמת כי התורה דקדקה מאד במה שהוא משונאו כדי שלא יחדל מעזוב לו מפני שהוא שונאו והוא מבוא שהמוצא אדם רובץ תחת משאו חייב לפרוק ולטעון עמו כי הדברים ק"ו כבר נתבאר זה השרש בשני ממציעא:
@68 שש שנים תזרע ארצך וגו'. עד הנה אנכי שולח מלאך:
@73 והנה התועלת במה שכללה אותו זאת הפרשה היא במצות כבר זכרנו כל תועלותיהם אצל זכירתינו אחת אחת מהם והנה שרשי אלו המצות הם תשעה:
@73 השרש הא' הוא שהמצוה להביא שלמי חגיגה ברגלים והא באים מהבהמה כמו שיתבאר בעניני הקרבנות והנה באה ביום הראשון כי התורה אמרה ולא יראו פני רקם ולזה יחוייב שתהיה הראיה ביום הראשון וביאה התורה בזה הספור כי דין החגיגה והראיה הוא אחד ולזה יתבאר כי כמו שהחגיגה יש לה תשלומין כל שבעה ושכל מי שהוא פטור מן הראיה הוא פטור מן החגיגה ומזה יתבאר שהפטור ביום הראשון מהם אינו מחוייב בשתלומין וזה מבואר בנפשו כבר נתבאר זה השרש בראשון מחגיג:
@73 השרש הב' הוא שהראיה אינה נוהגת אלא בזכרים מן ישראל שנאמר יראה כל זכורך והם הזכרים שהם מישראל לא העבדים כי אינם זכורך וכבר אמרה ג"כ בפרשת נצבים בבא כל ישראל לראות את פני השם אלהיך יצאו העבדים שאינם מבני ישר' והנה היו הנשים מפטרות מאלו המצות לחסרון דעתן מלעמוד בסבת הראיה על הכונו' הראויו' בראית בית המקד' ועניניו ולה הוא שהחרש והשוטה והקטן פטורין מהם לחסרון דעתם ועוד כי אינם בני מצות כמו שהתבאר בשרשי' הכוללי' וכן ראוי שנבין מזה שהמדבר ואינו שומע ושומע ואינו מדבר פטורים מאלו המצות כי חסר דעת בהכרה בכמו אלו העמוקות כי לא יתכן לאדם להשיגם אם לא בשמיעה ודבור כי בהם ישלם לו הלמד כדי שיתישר לעמוד על אלו הסודות וכבר תמצא שאמר בפרשת הקהל שהוא בעת הראיה למען ישמעון ולמען ילמדון הנה דקדק שיהיו שומעין ואף על פי הקל שם להביא הנשים והטף וכל שכן בשאר הראיות ולזאת הסבה בעינה יחוייב שיהיה מדבר כי בזולת זה לא תשלם בהם הלמידה ומזה המקו' יתבאר שהטומטום האנדרוגינוס אינה בני ראיה וחגיגה כי כל אחד מהם הוא ספק אשה כבר נתבאר זה השרש בראשון מחגיגה:
@73 השרש הג' הוא שמי שאינו יכול לעלות ברגליו בירושלם להר הבית הוא פטור מן הראיה שנאמר בעלתוך לראות את פני יי' אלהיך והנה לפי הנהוג שהיה העליה ברגליו וזה מבואר מאד ובזה גם כן יתבאר שמי שאינו יכול לכנס למקדש כמו הערל והטמא פטור מהראיה כבר נתבאר זה השרש בראשון מחגיגה:
@73 השרש הד' הוא שהסומא באחד מעיניו פטור מן הראיה וזה כי אם דקדקה התורה בקרבנות שיהיה שיהו תמימים וזה להעיד על שלמות השם יתע' אשר הקרבנות מישירים להשגתו כמו שנבאר כל שכן שראוי שידוקדק שתהיה הראיה שלמה להורות על שלמות הנראה וזה כי כונת התורה בזאת הראיה היא לראות המקדש ומעניניו מההישרה להשיג השם יתע' לפי מה שאפשר ולזה דקדקה התורה שלא יראו פני השם יתב' רקם להעיד על שאלו הענינים אינם דבר רק ובכלל הנה הראיה היא לפי הנהוג בשתי עינים ואלו הפעולות אשר זכרה התורה בכמו אלו הענינים ראוי שיהיו על השלמות לפי מה שאפשר כבר נתבאר זה השרש בראשון מחגיגה:
@73 השרש הה' הוא שהראיה בא מחולין לא ממעשר שני ולא ממעשר בהמה אשר דינה להאכל בירושלם כמו העניין במעשה שני וזה כי היא חובה ואין אדם פורע חובו משל הקדש אשר הוא מיוחד להאכיל לבעלי' להקרבה לשם ית' אלא אם עשו מהם שלמים כי הבעלים אוכלי' אותם אחר הקרבת האמורין לשם יתע' אך לא יתכן שיעשו מהם עולה שהיא כלה כליל כמו שמחוייב זה כעולת ראיה ולזה גם כן יתבאר שאין עושין שלמי חגיגה שהיא חובה במעות מעשר שני כי התורה הגבילה אותם לעניינים שהם רשות או לשלמי שמחה אמר בפרשת ראה אנכי ונתת הכסף בכל אשר תאוה נפשך בבקר ובצאן וגו' ושמחת אתה וביתך מגיד לך הכתוב שהוא משתמש בהם במה שהוא רשות והוא אשר תשאלהו נפשו לא מה שתחייבהו התורה זולת שלמי שמחה שנאמר ושמחת אתה וביתך ואולם במעשר בהמה מפני שלא מנעה התורה ממנו זה יהיה מחוייב בו שיאכל בתורת שלמים בירושלם כמו שיתבאר הנה יתכן שיפרש ממנו חובה בשלמי חגיגה כבר נתבאר זה השרש בראשון מחגיגה:
@73 השרש הו' הוא שהאדם חייב להביא בכורים מן הפירות כי המיוחדים לארץ כנען והם ז' המינין כאמר ארץ חטה ושעורה וגפן ותאנה ורמון ארץ זית שמן ודבש והוא דבש תמרים ויתבאר זה ממה שאמר בכורי אדמתך תביא רוצה לומר בכורי הפירות המיוחדים לארצך ולזה אמר תמורת זה בפרשת והיה כי תבא מראשית פרי האדמה אשר נתת לי השם וחייב ליתן מן המשובחין שבהם כי הם קרואים ראשית כאמרו קדש ישראל ליי' ראשית תבואתו. וכבר נתבאר זה השרש בראשון מבכורים:
@73 השרש הז' הוא שצריך שיהיו כל הגידולים מאדמתו ר"ל שיהיה שרש האילן וענפיו ברשותו אבל אם היה שרש האילן ברשות אחד או ברשות הרבים והבריכו לתוך שדהו או שיהיה הענין הפך זה אינו בכורים שנ' ראשית בכורי אדמתך שיהיו כל הגידולים מאדמתך כבר נתבאר זה השרש בראשון מבכורים:
@73 השרש הח' הוא שאין מביאים בכורים קודם עצרת שנא' וחג הקציר בכורי מעשיך אשר תזרע בשדה והיה זה כן כי אז יביאו בכורים מן החטה במקדש והם שתי הלחם והחטה היא קודמת לשאר המינין שנאמר ארץ חטה ושעורה וגומ' ולזה נקרא חג שבועות יום הבכורים ואמנם חייב להקריב קודם זה בכורי השעורים להתיר החדש לישראל ואם הביא משא בכורים קודם עצרת אין מקבלים ממנו כי התורה נתנה כבוד לבכורי חטה יות' ממה שנתנה לבכורים האחרים וזה מבואר מהקרבנות הבאים עם שתי הלחם כבר נתבאר זה השרש בד' מחלה ובג' מבכורים:
@73 השרש הט' הוא שהמוציא בכורים ונאנסו קודם שיביאם בבית השם יתע' חייב להפריש אחרים תחתיהם שנאמר תביא בית ה' אלהיך. למדנו מזה שהוא חייב באחריותם עד שיביאם להר הבית כבר נתבאר זה השרש בראשון מבכורים. ואולם שאר שרשי זאת המצוה יתבארו בג"ה בפרשת והיה כי תבא:
@101 והנה התועלות המגיעים מזה הספור הם ששה:
@101 **התועלת** הראשון הוא בדעות והוא שמה שישיג האיש הנכבד מהשם יתע' הוא זולת מה שישיג מי שהוא שפל ממנו ולזה אמר שזקני ישראל ישתחוו מרחוק ונגש משה לבדו אל יי' ואע"פ שכל אחד מהם ישיג השם יתע' באופן מה וזה עיון עמוק מאד וכבר ביארנו אמתתו בראשון ממלחמו' יי':
@101 **התועלת** השני הוא להודיע כי ההכנה בברית הש"י יהיה בהוצאת קרבן וטבילה כי לא יתכן שיהיה האדם קונה זה הקנין הנפלא בזולת רושם כי לא יאות שיהיה בלי בעל דת ואח"כ בזולת פעולה גדולה ישוב בעל דת ויענש באלו העונשין הגדולים והנפלאים אם יעבור על מצותיה:
@101 **התועלת** השלישי הוא להודיע שראוי למי שיתגייר שיודיעו לו מצות התורה ודיניה כדי שידע אם יסכים לקבל כמו זה הנימוס כי אין ראוי שיקובל זה הנימוס השלם על צד האונס וההכרח. ולזאת הסבה לא סמך משה על מה שהודיע לישראל בערב מאלו המצות והמשפטים אבל רצה להשיב להם זכרונם בעת הכנסם בבריתו לראות אם יסכימו ברצונם לקבל באלו המצות:
@101 **התועלת** הד' הוא בדעות והוא להודיע כי אלהי השמים הוא אלהי הארץ ושכל מניעי הגרמים השממיי' הם עלולים ממנו על משל אחד וזה עיון נפלא מאד כבר רמז עליו באמרו ותחת רגליו במעשה לבנת הספיר כמו שבארנו:
@101 **התועלת** החמישי הוא במצו' והוא להודיע כי הדייני' יהיה מהם מה שיצטרך לשבעי' איש ועוד נוסף עליה' ראש ב"ד ולה הגביל משה שיש בו ע' זקני' לדון דין אמת עמהם במקום משה ואהרן וחור להביא להם הדבר הקשה והנה מספר אלו הדיינין לא יצטרך בדיני ממונות כי אפי' דיין אחר דן שנ' בצדק תשפוט עמיתך ואמנם יצטרך בדיני נפשות הגדולים כמו שיתבאר במה שיבא:
@101 **התועלת** הששי הוא להודיע שכבר היה שם בהר רושם הכירו ממנו הגעת הנבואה למשה אותם המ' יום שעמד משה בהר לקבול התורה בשלמות כי זה ממה שיוסיף להם התאמתות בענין התורה וזה הרושם הוא האש שהיה בראש ההר וכל ישראל רואים:
@101 **וראוי** שתדע שמה שבא מהאזהרות והמצות בזאת הפרשה בא בתכלית הסדור מטוב הסדור והנה הקדים לזכור המצות אשר תהיינה במדות כי זה השלמות הוא קודם בסדר והתחיל בו ממה שכללה אותו מצות כבוד ההורים והוא עשיית הטוב במדו' כי הוא התכלית המכוון במדות ולזה זכר דין שלוח העבד והאמה חפשי' בשנה השביעית ומצו' יעוד האמה ושלא לגרוע ממנה שאר כסות ועונה כי בזה מהטוב במדות מה שלא יעלם. וכאלו באר שלא נחשוב שיגיע לנו השלמות במדות כאשר נגיע לכל בעל חק חקו ממה שהיתה לו ממשלה ושררה עלינו אבל נחוייב לנהוג זה המנהג גם בשפלים ממנו והנה הקדי' דין העבד לדין האמה להיות הזכר יותר נכבד מהנקבה ואחר כך החל באזהרות אשר יקיף בהם דבור לא תרצח והחל מהרציחה בישראל להיותה היותר קשה שבזה הסוד וביאר שאם לא ימות המוכה יהיה העונש ממון ולפי שבזה הענין יהיה העונש מיתה אם ימו' המוכה המשיך לזה מה שיזיק האדם לזולתו שיהיה ענשו מיתה ולזה זכר דין מכה אביו ואמו ואחר זה זכר דין גונב נפש כי הוא תחת דבור לא תגנוב הבא אחר לא תרצח ואחר כך זכר דין מקלל אביו ואמו כי הוא תחת דבור לא תענה ברעך עד שקר כמו שביארנו במה שקדם. ואחר כך שב להשלים דיני מה שיוכלל תחת דבור לא תרצח ולזה הודיע דין רציחת עבד כנעני להיותו למטה מישראל כי אינו בן תורה בשלימות ואחר כך הודיע דין הפלת הולדות שהם בלתי שלמי הבריאה ולזה יהיה דינם דין ההיזק אשר יהיה באברי הגוף כי הם כמו אבר מאברי אמם ואחר זה ביאר דין ההיזק אשר יהיה באברי הגוף לישראל כי הם למטה מתולדות כי תולדות הם בחיים להיות בריאה שלמה ואין הענין כן באברי הגוף ואח"כ ביאר דין ההיזק שיהיה באברי הגוף בעבד כנעני להיותו למטה מישראל כמו שזכרנו במה שקדם ואחר שהשלים לזכור דיני ממונות החבלות שיעשה האדם בזולתו שב לזכור דיני מיני החבלות שיעשה ממין האדם בזולתו והחל מהיותר קשה שבה הסוג והוא שימית שורו איש או אשה מישראל ואחר כך הודיע איך יהיה דינו אם המית שורו עבד כנעני להיותו למטה מישראל כמו שקדם ואחר כן ביאר דיני ההיזק שיגיע מממון האדם לממון חבירו וזכר בזה דיני הבור והשור וההבער והאש שהגיע היזק מהם וכבר ביארנו למה סדרה התורה אותם בזה הסדור ולמה הפסיק אותם בענין הגנבה ואחר שהשלים לזכור מה שיגיע בו נזק מהאדם או מממונו לזולתו בידים בא להזכיר הנזקים שיגיע מהאדם לזולתו בממונו לא בידים אבל בעבור שלא שמר כראוי וזכר בזה דיני השומרים ארבעה על מדרגותיהם באופן הנהוג והשלמות וסבת הסדור הבא בזכירתם הוא מבואר מדברינו במה שקדם. ואחר שהשלים זה בא לזכור היזק שיגיע מהאדם לזולתו שיהיה בו הנאה לכל אחד מהחלקי' ולזה באר דיני המפתה כי הוא הזיק לאבי הנערה והיה בזה הנאה לפועל ולמקבל והמשיך לזאת המצוה ענין הכשוף וגלוי ערות הבהמה ועבודת ע"ז לסבה שזכרנו במה שקדם ואחר זה בא לזכור ההיו' שיגי' מהאד' לחבירו במה שלא יוכר היותו נזק כמו שיכאיב לבו בדבריו או יזיקהו בממון באופן שיחשוב שכבר נעשה כרצונו ושאין בה פשע כמו האונאה במקח וממכר והרבית שישתעבד בו הלוה והנה זכר הגר תחלה ואח"כ האלמנה והיות ואח"כ העני לסבה שזכרנו במה שקדם ואחר כך זכר במה שיעשה האדם כנגד זולתו בדבריו או בממון והוא לא ירגיש בו כמו שיקלל האדם המנהיגים וראשי העם בזולת ידיעתם או שיאחר המתנות אשר ראוי שיתנם לכהני' או למי שידמה להם וכלל בזה שלא יקדימם יותר מן הראוי באופן שלא יזיק לכהן ולזה חוייב להטפל בבכור ז' ימים ואחר כך זכר דיני מה שיעשה האדם כנגד עצמו במה שלא ירגיש שיגיעהו נזק בו כמו אכילת הבשר חוץ למחיצתו או אכילת הטרפה ואלו הנזיקין הם מתיחסים לנזקים שיהיו בממון ובדבור שלא יורגש בהם אבל יחשב באלו שיגיע בהם תועלת והנאה והנה הנזק שיגיע מאכילת הבשר חוץ למחיצתו הוא שזה יהיה סבה אל שתעלם ממנו הסבה אשר בעבורה צוה ה' שלא תאכל זה הבשר כי אם תוך זה הגבול ואח"כ זכר דיני מה שיעשו הדינין שלא יחשבו להם פשע בזה אשר אולי יהיה סבת להגעת ההיזקים באנשים בגוף או בממון ולזה הזהיר שלא ישמעו דברי בעל דין אחד שלא בפני חבירו ושלא יניחו הרשע ואיש החמס להעיד כי אולי יעיד שקר ושלא לדון להריגה אם לא היו המחייבי' יותר על המזכין שנים או יותר ושיגיד כל אחד מהדינין דעתו ולא יעלימהו ושיטו אחרי רבים לממון או לזכות בדיני נפשות וצוה שלא יהדר דל בריבו כי בזה הענין יעשה הדיין עול ויחשוב לעשות לעשות מצוה וכן אם יטה משפט האיש הרשע וכבר הפסיק בזה בזכירת השבת אבידת הרשע ופריקת המשא מעל בהמתו כי גם בזה יחשב לעשות טוב ויעשה הרע אם ימנע מזה ואחר זכר שמי שנצטדק בדין בדיני נפשות לא נשיב דינו לחייבו כי בזה יחשוב לעשות יושר והרחיקתהו התורה מזה כי ראוי שנתרחק מהריגת הנפשות אם לא יביאה ההכרח אל זה ואחר שיש בכאן סבה יתכן שנפטרהו בה אין ראוי שנשיב דינו אחור לחייבו ואחר זה הזהיר שלא יקח הדיין שוחד אפילו שלא להטות הדין ושלא ילחץ הנר למאסו אותו כי זה כולו יהיה סבה שיעות הדין והוא לא ישער ואחר שהשלים לזכור דיני מיני ההיזקים שיגיעו מהאד' לחבירו בכל אופניהם שב להזכיר מה שיוכלל בדבור זכור כמו השביעית ובשבת וביאר שבזה תועלת במדות להטיב לעניים ולהיות המנוחה לבעלי העמל ובזה תועלת גם כן בהשגת השם יתע' כמו שביארנו במה שקדם ולזה הזהיר בזה המקום מההשבע בע"ז ומקריאת האנשים לעבדה להעיד כי יש כאלו המצות הערה להרחיק האדם מע"ז ולזאת הסבה היתה גם כן מצות החגיגה ברגלים והראייה כי בזה הישרה להשיג השם יתע' כמו שזכרנו ולזכירת יציאת מצרים אשר בה מההישרה להשיג השם יתעלה מה שלא יעלם צוה שלא נזבח על חמץ דם הפסח וצוה שלא נלין אמורי שלמי חגיגה עד הבקר לכבוד השם יתע' כי זה קרב אליו. וראוי שיקרבהו לו בעת יותר נבחר וצוה להביא ראשית בכורי האדמה בית יי' ושלא נבשל גדי בחלב אמו כי כל אלו תחת דבור זכור באופן מה כי יש בהם תועלת במדות ובדעות וצוה ג"כ אחר זה שלא נמרה על פי הנביא כי בשמיעה אל דבריו תועלת במדות ובדעות וכאלו היתה זאת המצוה תחת דבור זכר אחר כן הזהיר מעבוד ע"ז וצוה לאבד הע"ז ומשמשיה והוא תחת לא יהיה לך ואחר כן צוה לעבוד ה' ית' והוא תחת דבור אנכי:
